-- =============================================================================
-- 0135 — Thirteen more courses for the academy
--
-- The founder's second batch of lecture files: Java, Database Fundamentals,
-- SQL Server, Design Patterns, Clean Code, Data Structures, Operating Systems,
-- Red Hat administration, WordPress, LINQ, ADO.NET, ASP.NET Core MVC (two
-- series) and ASP.NET Core Web API (two recordings). Each file is a list of
-- recorded lectures, one video and its summary each. Every lecture becomes one
-- lesson in the TechMood anatomy (0034): the video, its summary, what you will
-- learn (from the summary's points, without the class logistics), the review
-- sources, a practical assignment with its deliverables, a case study with its
-- question and a challenge — the assignment, case and challenge written for
-- each lesson.
--
-- Where a path already announced a matching course, the lectures fill it
-- (java-basics, db-foundations, sql-server, design-patterns, clean-code, linux,
-- aspnet-core); the rest are new courses placed in their paths:
--   linq-adonet, aspnet-mvc        → C# & .NET (required, after the C# bootcamp)
--   aspnet-mvc-3tier               → C# & .NET (optional, advanced)
--   aspnet-mvc                     → Back-End (optional)
--   data-structures                → Software Engineering (optional)
--   operating-systems              → Software Engineering, System Administration (optional)
--   wordpress                      → Web, Freelancing (optional)
-- The two Web API recordings teach the same eight topics, so each lesson carries
-- both videos rather than appearing twice.
--
-- Loaded with public.import_course() (0112), which never touches a course that
-- already has content: running this twice changes nothing.
-- =============================================================================

select public.import_course($course${"slug":"java-basics","title_ar":"Java من الأساسيات إلى JavaFX","title_en":"Java SE: From Basics to JavaFX","description_ar":"لغة Java من أول برنامج: أنواع البيانات والتحكم والبرمجة الكائنية والمُعدِّلات، ثم الاستثناءات والواجهات وتعدد المسارات، والملفات والشبكات وJDBC والمجموعات، وواجهات JavaFX، وصولاً إلى Lambda وStreams في Java الحديثة.","level":"beginner","estimated_hours":60,"paths":[],"modules":[{"title_ar":"أساسيات اللغة","lessons":[{"title_ar":"مقدمة Java وJDK وJRE وأول برنامج","title_en":"Introduction to Java, JDK, JRE & Your First Program","kind":"video","summary_ar":"هذا الفيديو هو الجزء الأول من سلسلة تعليمية لتعلم لغة جافا (Java)، يقدمها المهندس أحمد لطفي.","outcomes_ar":["لماذا لغة جافا؟ — يوضح الفيديو تاريخ نشأة اللغة كبديل للغات مثل C و C++، مع التركيز على ميزة كونها مستقلة عن منصة التشغيل (Platform Independent) بفضل تقنية Java Virtual Machine (JVM)","شرح الفرق بين JDK و JRE","مفاهيم البرمجة الكائنية (OOP) مثل الكلاسات (Classes)، الأترييوتس (Attributes)، والميثودز (Methods)","استخدام مُعامل new لإنشاء الكائنات في الذاكرة (Heap)","أول برنامج — كتابة وتشغيل برنامج \"Hello World\" وكيفية التعامل مع الكومبايلر (javac) والمفسر (java)","يختتم الجزء بفقرة أسئلة وأجوبة وتحديد موعد لاستكمال المحاضرة بعد الاستراحة"],"case_study_ar":"زميلك ثبّت JRE فقط ويحاول ترجمة برنامجه فيظهر له أن javac غير معروف.","case_question_ar":"ما سبب المشكلة؟ وما الذي يحتاج تثبيته ولماذا؟","challenge_ar":"شغّل البرنامج نفسه على نظامين مختلفين (أو جهاز وزميل) ووثّق أن الـ bytecode نفسه يعمل على الاثنين.","videos":[{"title_ar":"المحاضرة — مقدمة Java وJDK وJRE وأول برنامج","url":"https://youtu.be/LeZuvfE2x34","description_ar":null}],"resources":[{"label":"Learn Java — dev.java","url":"https://dev.java/learn/","kind":"website"},{"label":"The Java Tutorials — Oracle","url":"https://docs.oracle.com/javase/tutorial/","kind":"website"}],"assignment":{"title_ar":"تكليف: مقدمة Java وJDK وJRE وأول برنامج","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_JAVA_L01_IntroductionToJava\n\nالمطلوب:\n1️⃣ ثبّت JDK وتأكد من الإصدار بالأمر java -version.\n2️⃣ اكتب برنامج HelloTechMood يطبع اسمك وتخصصك، وشغّله من سطر الأوامر بـ javac ثم java.\n3️⃣ أنشئ كائناً بـ new من كلاس Student فيه الاسم والعمر واطبع بياناته.\n4️⃣ اكتب في README الفرق بين JDK وJRE وJVM بجملتين لكل واحد.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"الحزم والوراثة وكلاس Object","title_en":"Packages, Inheritance & the Object Class","kind":"video","summary_ar":"يقدم هذا الفيديو الجزء الثاني من سلسلة تعليم لغة الجافا (Java) للمبتدئين.","outcomes_ar":["الحزم (Packages) — يشرح المحاضر أهمية الحزم في تنظيم الكلاسات (Classes)، وكيفية عمل Import للمكتبات، مع الإشارة إلى أن حزمة `java.lang` يتم استدعاؤها تلقائياً","الوراثة وكلاس Object — يوضح أن جميع الكلاسات في جافا ترث تلقائياً من كلاس أب رئيسي يسمى Object","تطبيقات الجافا (Java Applets) — يستعرض مفهوم Applets كبرامج جافا تعمل داخل المتصفح، ويشرح دورة حياة الأبلت (Lifecycle) التي تتضمن ميثودات مثل `init`, `start`, `paint`, `stop`, و `destroy`","الرسم في الجافا — يتناول كيفية الرسم داخل الأبلت باستخدام كلاس Graphics وميثود `paint`","التشغيل والكومبايل — يشرح كيفية استخدام `javac` لترجمة الكود، وكيفية تشغيل الأبلت باستخدام أداة `appletviewer` و"],"case_study_ar":"مشروع فيه 40 كلاساً كلها في مجلد واحد بلا حزم، وصار فيه كلاسان بالاسم نفسه.","case_question_ar":"كيف تنظّم الحزم هذا المشروع؟ وكيف تحلّ تعارض الأسماء؟","challenge_ar":"أنشئ ملف JAR قابلاً للتشغيل من المشروع وشغّله بـ java -jar.","videos":[{"title_ar":"المحاضرة — الحزم والوراثة وكلاس Object","url":"https://youtu.be/TNT0TpoNIEM","description_ar":null}],"resources":[{"label":"Learn Java — dev.java","url":"https://dev.java/learn/","kind":"website"},{"label":"The Java Tutorials — Oracle","url":"https://docs.oracle.com/javase/tutorial/","kind":"website"}],"assignment":{"title_ar":"تكليف: الحزم والوراثة وكلاس Object","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_JAVA_L02_PackagesInheritanceThe\n\nالمطلوب:\n1️⃣ أنشئ حزمتين: tm.models وtm.app، وضع كلاس Person في الأولى وMain في الثانية.\n2️⃣ ورّث Student وMentor من Person وأعد تعريف toString وequals.\n3️⃣ استدعِ دوال Object (getClass وhashCode وtoString) واطبع النتائج.\n4️⃣ ترجم المشروع وشغّله من سطر الأوامر مع مسار الحزم الصحيح.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"أنواع البيانات والمؤثرات والمصفوفات وString","title_en":"Data Types, Operators, Arrays & Strings","kind":"video","summary_ar":"يقدم هذا الفيديو الجزء الثالث من دورة تعلم لغة Java، حيث يركز على شرح مفاهيم برمجية أساسية بأسلوب مبسط ومقارن للغة C/C++.","outcomes_ar":["قواعد التسمية (Identifiers) — توضيح القواعد التي يفرضها مترجم (Compiler) جافا عند تسمية المتغيرات والفئات","أنواع البيانات (Data Types) — ينقسم التعامل مع البيانات إلى نوعين: الأنواع الأولية (Primitive types) مثل البوليان والأرقام، والأنواع المرجعية (Reference types) مثل المصفوفات والكائنات","فئات التغليف (Wrapper Classes) — شرح لأهمية هذه الفئات التي تقابل الأنواع الأولية وكيفية استخدامها","المؤثرات (Operators) — استعراض شامل لأنواع المؤثرات الحسابية والمنطقية والترنري (Ternary operator) ومقارنتها بما هو موجود في لغات أخرى","المصفوفات (Arrays) — شرح مفهوم المصفوفات في جافا وكيفية التعامل مع مصفوفات الأنواع الأولية ومصفوفات المراجع للكائنات","فئة النصوص (String Class) — التعمق في كيفية التعامل مع النصوص في جافا، ومفهوم String Pool لتوفير الذاكرة","يتميز الفيديو بتقديم أمثلة توضيحية ونقاشات حول الفرق بين جافا واللغات التي تعتمد على الإدارة اليدوية للذاكرة، مع التركيز على تجنب الأخطاء الشائعة مثل `NullPointerException` و `ArrayIndexOutOfBoundsException`"],"case_study_ar":"برنامج يقارن كلمة المرور المدخلة بـ == فيرفض كلمات صحيحة أحياناً.","case_question_ar":"لماذا يحدث ذلك؟ وما الطريقة الصحيحة للمقارنة؟","challenge_ar":"اكتب دالة تعكس جملة كلمةً كلمة باستخدام StringBuilder وقارن سرعتها مع جمع النصوص بـ +.","videos":[{"title_ar":"المحاضرة — أنواع البيانات والمؤثرات والمصفوفات وString","url":"https://youtu.be/LesIB0JCAYU","description_ar":null}],"resources":[{"label":"Learn Java — dev.java","url":"https://dev.java/learn/","kind":"website"},{"label":"The Java Tutorials — Oracle","url":"https://docs.oracle.com/javase/tutorial/","kind":"website"}],"assignment":{"title_ar":"تكليف: أنواع البيانات والمؤثرات والمصفوفات وString","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_JAVA_L03_DataTypesOperators\n\nالمطلوب:\n1️⃣ اكتب برنامجاً يقرأ درجات 10 طلاب في مصفوفة ويحسب المجموع والمتوسط وأعلى وأقل درجة.\n2️⃣ استخدم Wrapper Classes لتحويل نصوص إلى أرقام (Integer.parseInt).\n3️⃣ طبّق عمليات String: الطول، التقطيع، البحث، التحويل لحروف كبيرة، والمقارنة بـ equals.\n4️⃣ اشرح بتعليق في الكود لماذا لا نقارن النصوص بـ ==.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"جمل التحكم والحلقات","title_en":"Control Flow & Loops","kind":"video","summary_ar":"يقدم هذا الفيديو الجزء الرابع من كورس لغة Java الموجه للمبتدئين، حيث يركز على مفاهيم التحكم في تدفق البرنامج (Control Program Flow).","outcomes_ar":["جمل التحكم والبرمجة (Branching Statements) — شرح مفصل لاستخدام `if` و `switch` لاتخاذ القرارات في الكود. تم توضيح كيفية استخدام `switch` مع النصوص (Strings) بدءاً من إصدارات Java الحديثة","`while` و `do-while` — للتحكم في التكرار بناءً على شرط معين","`for` loop — الاستخدام التقليدي","`enhanced for loop` — وهي الطريقة الأمثل للتعامل مع المصفوفات (Arrays) والمجموعات","أدوات التحكم في الحلقات — شرح الفرق بين `break` لإنهاء الحلقة تماماً، و `continue` لتخطي التكرار الحالي فقط","التوثيق (Comments) — أهمية كتابة التعليقات وكيفية استخدام أداة JavaDoc لإنشاء توثيق تلقائي للكود","شهد الفيديو أيضاً نقاشاً تقنياً حول الفرق بين اللغات البرمجية واللغات النصية (Scripting Languages)، وتأكيداً على أهمية تحديد أنواع المتغيرات في Java"],"case_study_ar":"حلقة while في برنامج تسجيل دخول لا تتوقف أبداً حتى بعد إدخال كلمة المرور الصحيحة.","case_question_ar":"ما الأسباب المحتملة؟ وكيف تكتب شرط الخروج بشكل آمن مع حد أقصى للمحاولات؟","challenge_ar":"اكتب لعبة تخمين رقم عشوائي بعدد محاولات محدود وتلميح أكبر/أصغر.","videos":[{"title_ar":"المحاضرة — جمل التحكم والحلقات","url":"https://youtu.be/QUT1cN7O0nA","description_ar":null}],"resources":[{"label":"Learn Java — dev.java","url":"https://dev.java/learn/","kind":"website"},{"label":"The Java Tutorials — Oracle","url":"https://docs.oracle.com/javase/tutorial/","kind":"website"}],"assignment":{"title_ar":"تكليف: جمل التحكم والحلقات","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_JAVA_L04_ControlFlowLoops\n\nالمطلوب:\n1️⃣ اكتب آلة حاسبة نصية بقائمة خيارات تعمل بـ switch داخل حلقة while حتى يختار المستخدم الخروج.\n2️⃣ اطبع جدول الضرب من 1 إلى 10 بحلقتين for متداخلتين.\n3️⃣ استخدم enhanced for للمرور على مصفوفة أسماء، وbreak وcontinue في مثال واضح.\n4️⃣ وثّق كودك بتعليقات Javadoc لدالة واحدة على الأقل.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}}]},{"title_ar":"المُعدِّلات والاستثناءات والواجهات","lessons":[{"title_ar":"مُعدِّلات الوصول وstatic وfinal وabstract","title_en":"Access Specifiers & Modifiers","kind":"video","summary_ar":"يقدم هذا الفيديو شرحًا تعليميًا مكثفًا لمفاهيم مُعدلات الوصول (Access Specifiers) و المُعدلات (Modifiers) في لغة البرمجة Java.","outcomes_ar":["مُعدلات الوصول (Access Specifiers) — شرح الفرق بين Public، Private، Protected، والنوع الافتراضي (Friendly/Default) وكيفية تأثير كل منها على مستوى رؤية الكلاسات أو المتغيرات داخل وخارج الحزمة (Package)","Final — لمنع التوريث أو التعديل على القيم والميثودات","Static — لشرح المتغيرات والميثودات المرتبطة بالكلاس","الفواصل الاستاتيكية (Static/Free-floating blocks) — كيفية استخدام هذه البلوكات لتنفيذ أكواد تلقائية عند تحميل الكلاس أو عند استدعاء الكونستراكتور","Abstract — شرح الكلاسات والميثودات المجردة (Abstract Classes/Methods) ودورها في التصميم البرمجي","Native — لاستدعاء كود بلغة غير Java (مثل C)","Transient — لمنع انتقال بيانات معينة أثناء عمليات الإرسال عبر الشبكة (Serialization)","Volatile & Synchronized — شرح أساسيات التعامل مع تعدد الخيوط (Multithreading)"],"case_study_ar":"كل حقول كلاس الحساب البنكي public، وصار أي جزء من البرنامج يعدّل الرصيد مباشرة.","case_question_ar":"ما الخطر هنا؟ وكيف يحميه التغليف (Encapsulation)؟","challenge_ar":"أضف static block يطبع رسالة عند تحميل الكلاس، ووضّح بالتجربة متى يُنفَّذ.","videos":[{"title_ar":"المحاضرة — مُعدِّلات الوصول وstatic وfinal وabstract","url":"https://youtu.be/1FCnTTJ6glQ","description_ar":null}],"resources":[{"label":"Learn Java — dev.java","url":"https://dev.java/learn/","kind":"website"},{"label":"The Java Tutorials — Oracle","url":"https://docs.oracle.com/javase/tutorial/","kind":"website"}],"assignment":{"title_ar":"تكليف: مُعدِّلات الوصول وstatic وfinal وabstract","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_JAVA_L05_AccessSpecifiersModifiers\n\nالمطلوب:\n1️⃣ صمّم كلاس BankAccount بحقول private ودوال public للإيداع والسحب مع تحقق من الرصيد.\n2️⃣ أضف عداداً static لعدد الحسابات المنشأة وثابتاً final لنسبة الفائدة.\n3️⃣ أنشئ كلاساً abstract باسم Shape ودالة abstract area وورّث منه Circle وRectangle.\n4️⃣ اشرح في README متى تختار protected بدل private.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"المُعدِّلات المتقدمة: synchronized وfinal","title_en":"Advanced Modifiers: synchronized & final","kind":"video","summary_ar":"يركز هذا الدرس بشكل أساسي على شرح مفاهيم متقدمة في البرمجة.","outcomes_ar":["الكلمة المفتاحية `synchronized` — يشرح المحاضر أهمية استخدام `synchronized` عند التعامل مع تعدد الخيوط (Multithreading) لتجنب تضارب البيانات (Data Corruption) وضمان أن خيطاً واحداً فقط يمكنه الوصول إلى البيانات المشتركة ","النقاش حول قواعد البيانات — دار نقاش مع أحد الطلاب حول دور قواعد البيانات (DBMS) في حماية البيانات، حيث أوضح المحاضر أن `synchronized` هي آلية برمجية داخلية تستخدم في تطوير التطبيقات (بما فيها أنظمة قواعد البيانات نفسها)","الكلمة المفتاحية `final` — تم توضيح أن الكلمة المفتاحية `final` عند استخدامها مع المتغيرات تجعلها ثوابت (Constants) لا يمكن تغيير قيمتها بعد تعيينها لأول مرة","نصيحة حول الموديفايرز — حذر المحاضر من استخدام عدة Modifiers مع بعضها بشكل خاطئ لتجنب أخطاء التصريف (Compiler Errors)"],"case_study_ar":"عدّاد زيارات موقع يُحدَّث من أكثر من خيط فيظهر رقم أقل من الحقيقي.","case_question_ar":"لماذا يضيع جزء من الزيادات؟ وكيف يمنع synchronized ذلك؟","challenge_ar":"جرّب AtomicInteger بدلاً من synchronized وقارن البساطة والنتيجة.","videos":[{"title_ar":"المحاضرة — المُعدِّلات المتقدمة: synchronized وfinal","url":"https://youtu.be/gYrSmwrcCf4","description_ar":null}],"resources":[{"label":"Learn Java — dev.java","url":"https://dev.java/learn/","kind":"website"},{"label":"The Java Tutorials — Oracle","url":"https://docs.oracle.com/javase/tutorial/","kind":"website"}],"assignment":{"title_ar":"تكليف: المُعدِّلات المتقدمة: synchronized وfinal","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_JAVA_L06_AdvancedModifiersSynchronized\n\nالمطلوب:\n1️⃣ اكتب كلاساً final لا يمكن الوراثة منه ودالة final لا يمكن إعادة تعريفها، وجرّب كسرهما ولاحظ أخطاء الترجمة.\n2️⃣ أنشئ عدّاداً مشتركاً يزيده خيطان معاً بدون synchronized ثم معه، وقارن النتيجة.\n3️⃣ لخّص في جدول: المعدّل، أين يُستخدم، ومثال.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"معالجة الاستثناءات","title_en":"Exception Handling","kind":"video","summary_ar":"يقدم هذا الفيديو شرحًا تفصيليًا لمفهوم معالجة الاستثناءات (Exception Handling) في لغة البرمجة Java.","outcomes_ar":["مفهوم الاستثناءات — تعريف الاستثناءات بأنها أخطاء تحدث أثناء تشغيل البرنامج (Runtime) وتؤدي إلى توقفه","تصنيف الأخطاء — تقسيم الأخطاء إلى ثلاثة أنواع: أخطاء لا يمكن التحكم بها (Errors)، أخطاء منطقية يمكن تجنبها، وأخطاء متوقعة يجب التعامل معها (Checked Exceptions)","طرق معالجة الاستثناءات — مناقشة ثلاث استراتيجيات للتعامل مع الأخطاء: تجاهلها (وهو خيار سيء)، معالجتها في مكان وقوعها، أو تفويض المعالجة لمكان آخر","آلية المعالجة — شرح استخدام بلوك `try-catch` لالتقاط الاستثناءات، وأهمية بلوك `finally` لضمان تنفيذ كود معين بغض النظر عن حدوث خطأ","التعامل مع الاستثناءات المخصصة — توضيح كيفية إنشاء فئة استثناء خاصة بك (Custom Exception) واستخدامها داخل الدوال","الفرق بين Checked و Unchecked Exceptions — توضيح الفرق الجوهري بين الاستثناءات التي يجبرك المترجم (Compiler) على معالجتها وتلك التي لا يشترط ذلك","تقنية Try-with-resources — ميزة ظهرت في Java 7 لضمان إغلاق الموارد (مثل الملفات) تلقائيًا بعد الانتهاء منها"],"case_study_ar":"تطبيق يغلق فجأة عند إدخال حرف بدل رقم، ولا يعرف المستخدم ماذا حدث.","case_question_ar":"أين تضع try/catch؟ وما الرسالة المناسبة للمستخدم؟","challenge_ar":"أضف finally يسجّل كل خطأ في ملف log.txt مع الوقت.","videos":[{"title_ar":"المحاضرة — معالجة الاستثناءات","url":"https://youtu.be/ANiBlQrSUNk","description_ar":null}],"resources":[{"label":"Learn Java — dev.java","url":"https://dev.java/learn/","kind":"website"},{"label":"The Java Tutorials — Oracle","url":"https://docs.oracle.com/javase/tutorial/","kind":"website"}],"assignment":{"title_ar":"تكليف: معالجة الاستثناءات","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_JAVA_L07_ExceptionHandling\n\nالمطلوب:\n1️⃣ اكتب برنامج قسمة يقرأ رقمين ويعالج ArithmeticException وNumberFormatException برسائل واضحة.\n2️⃣ أنشئ استثناءً مخصصاً InsufficientBalanceException واستخدمه في كلاس الحساب البنكي.\n3️⃣ اقرأ ملفاً نصياً باستخدام try-with-resources.\n4️⃣ اشرح في README الفرق بين Checked وUnchecked بمثال لكل منهما.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"الواجهات وتعدد المسارات","title_en":"Interfaces & Multithreading","kind":"video","summary_ar":"يركز هذا الدرس بشكل أساسي على موضوعين متقدمين في البرمجة الكائنية التوجه (OOP).","outcomes_ar":["شرح مفهوم الواجهات كبديل لتعدد الوراثة (Multiple Inheritance) في Java","توضيح الفرق بين الكلاس المجرد (Abstract Class) والواجهة، وكيفية استخدام الكلمة المحجوزة `implements`","استعراض التحديثات التي أدخلتها Java 8 على الواجهات، مثل الطرق الافتراضية (Default Methods) والطرق الساكنة (Static Methods)","تعدد المسارات (Multithreading) — (38:10 - نهاية الفيديو)","تعريف مفهوم تعدد المسارات وكيفية عملها في Java، بما في ذلك دور Garbage Collector كمهمة خلفية","وراثة كلاس `Thread`","تنفيذ واجهة `Runnable`","مناقشة دورة حياة المسار، أهمية الميثود `run()`، وطرق التحكم في المسارات مثل `start()`، `sleep()`، و `yield()`","توضيح كيفية التعامل مع الاستثناءات مثل `InterruptedException` عند استخدام المسارات"],"case_study_ar":"تطبيق سطح مكتب يتجمد أثناء تحميل ملف كبير.","case_question_ar":"كيف يحل تشغيل التحميل في خيط منفصل المشكلة؟","challenge_ar":"استخدم ExecutorService لتشغيل خمس مهام بمجموعة خيوط ثابتة.","videos":[{"title_ar":"المحاضرة — الواجهات وتعدد المسارات","url":"https://youtu.be/ySBtTso1kI0","description_ar":null}],"resources":[{"label":"Learn Java — dev.java","url":"https://dev.java/learn/","kind":"website"},{"label":"The Java Tutorials — Oracle","url":"https://docs.oracle.com/javase/tutorial/","kind":"website"}],"assignment":{"title_ar":"تكليف: الواجهات وتعدد المسارات","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_JAVA_L08_InterfacesMultithreading\n\nالمطلوب:\n1️⃣ عرّف واجهة Payable ونفّذها في Employee وFreelancer، واحسب الرواتب عبر مصفوفة من النوع Payable.\n2️⃣ أنشئ خيطين بطريقتين: الوراثة من Thread وتنفيذ Runnable.\n3️⃣ اجعل خيطاً يطبع الأرقام وآخر يطبع الحروف في الوقت نفسه ولاحظ التداخل.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}}]},{"title_ar":"الرسوم والأحداث والتزامن","lessons":[{"title_ar":"فئات الواجهات الرسومية: Graphics وColor وFont","title_en":"Essential GUI Classes: Graphics, Color & Font","kind":"video","summary_ar":"يركز هذا الدرس على شرح مفاهيم برمجية متقدمة وأساسيات التعامل مع الواجهات الرسومية.","outcomes_ar":["ناقش الفيديو كيفية استخدام أكثر من Modifier في وقت واحد مع الكلاسات والميثودز، مع التأكيد على ضرورة تجنب التعارض بينها (مثل محاولة دمج `final` و `abstract`)، وكيف يتعامل المترجم (Compiler) مع هذه الحالات","كلاس Graphics — يُستخدم كـ \"قلم\" للرسم والكتابة على المكونات الرسومية، ويدعم عمليات مثل `drawRect`, `fillRect`, `drawOval`, و `drawArc`","كلاس Color — يتيح تمثيل الألوان باستخدام نظام RGB (الأحمر، الأخضر، الأزرق)، مع وجود 13 لونًا جاهزًا للاستخدام المباشر","كلاس Font — يتحكم في شكل وحجم وستايل الخطوط المستخدمة في التطبيق","شرح الفيديو كيفية الحصول على قائمة الخطوط المدعومة في النظام الحالي باستخدام `Toolkit`","ناقش أهمية التعامل مع الميثودز التي تحمل وسم `Deprecated` في الوثائق الرسمية، وضرورة البحث عن البدائل الحديثة لتجنب مشاكل التوافق في إصدارات Java المستقبلية"],"case_study_ar":"تصميم الواجهة يظهر بشكل مختلف على شاشتين بدقتين مختلفتين.","case_question_ar":"كيف تستخدم أبعاد النافذة بدل الأرقام الثابتة لتبقى الرسوم متناسقة؟","challenge_ar":"ارسم رسماً بيانياً عمودياً بسيطاً لدرجات خمسة طلاب.","videos":[{"title_ar":"المحاضرة — فئات الواجهات الرسومية: Graphics وColor وFont","url":"https://youtu.be/3DiBm37PMPU","description_ar":null}],"resources":[{"label":"Learn Java — dev.java","url":"https://dev.java/learn/","kind":"website"},{"label":"The Java Tutorials — Oracle","url":"https://docs.oracle.com/javase/tutorial/","kind":"website"}],"assignment":{"title_ar":"تكليف: فئات الواجهات الرسومية: Graphics وColor وFont","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_JAVA_L09_EssentialGUIClasses\n\nالمطلوب:\n1️⃣ ارسم بطاقة تعريفية في نافذة: مستطيل ملوّن، اسمك بخط مخصص، ودائرة كشعار.\n2️⃣ استخدم Color بقيم RGB مخصصة وFont بأحجام مختلفة.\n3️⃣ اعرض أبعاد الشاشة باستخدام Toolkit.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"دورة حياة Thread والتزامن","title_en":"Thread Lifecycle & Synchronization","kind":"video","summary_ar":"هذا الفيديو هو الجزء العاشر من كورس تعلم Java، ويركز بشكل أساسي على دورة حياة الثريد (Thread Lifecycle) ومفهوم التزامن (Synchronization).","outcomes_ar":["دورة حياة الثريد — شرح الحالات التي تمر بها الثريد (مثل New، Ready، Running، Sleeping، Blocked) وكيفية الانتقال بينها، بالإضافة إلى توضيح تأثير استخدام `yield()` و `sleep()`","مفهوم التزامن Synchronization — تم شرح أهمية استخدام `synchronized` عند تعامل عدة ثريدز مع بيانات مشتركة لمنع حدوث تضارب أو تلف في البيانات (Data Corruption). وأكد المحاضر أن التزامن ضروري للحفاظ على سلامة البيانات لكنه ","أمثلة برمجية — استعرض المحاضر مثالاً عملياً يوضح كيف يمكن أن يتداخل خروج البيانات عند استخدام أكثر من ثريد للطباعة، وكيف تعالج كلمة `synchronized` هذه المشكلة","عمل بانر متحرك (Marquee)","برمجة كرة تتحرك وتصطدم بحواف النافذة"],"case_study_ar":"الحركة في نافذتك تتقطع وتسرّع وتبطئ عشوائياً.","case_question_ar":"ما دور sleep ومعدّل التحديث؟ وكيف تجعل الحركة ثابتة؟","challenge_ar":"أضف أكثر من كرة، كل واحدة بخيط ولون وسرعة مختلفة.","videos":[{"title_ar":"المحاضرة — دورة حياة Thread والتزامن","url":"https://youtu.be/aBHRjud0HT0","description_ar":null}],"resources":[{"label":"Learn Java — dev.java","url":"https://dev.java/learn/","kind":"website"},{"label":"The Java Tutorials — Oracle","url":"https://docs.oracle.com/javase/tutorial/","kind":"website"}],"assignment":{"title_ar":"تكليف: دورة حياة Thread والتزامن","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_JAVA_L10_ThreadLifecycleSynchronization\n\nالمطلوب:\n1️⃣ نفّذ بانراً متحركاً (Marquee) لنص يتحرك أفقياً في نافذة باستخدام خيط.\n2️⃣ نفّذ كرة تتحرك وترتد عن حواف النافذة.\n3️⃣ ارسم مخطط حالات Thread (New, Runnable, Blocked, Waiting, Terminated) وأرفقه.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"الكلاسات المتداخلة ومعالجة الأحداث","title_en":"Nested Classes & Event Handling","kind":"video","summary_ar":"يقدم هذا الفيديو محاضرة تعليمية ضمن كورس جافا (Java)، وتتناول موضوعين رئيسيين.","outcomes_ar":["يوضح المحاضر مفهوم تعريف كلاس داخل كلاس آخر، وأهمية ذلك في التنظيم المنطقي (Logical Grouping) للكود","يشرح الفوائد البرمجية مثل تعزيز التغليف (Encapsulation)، حيث يمكن للكلاس المتداخل الوصول إلى المكونات الخاصة (private members) للكلاس الخارجي","يستعرض الأنواع الأربعة للكلاسات المتداخلة — العادية (Member)، الساكنة (Static)، المحلية (Local)، والمجهولة (Anonymous)، مع أمثلة عملية","يشرح المفهوم الأساسي لمعالجة الأحداث في لغة جافا، والذي يعتمد على ثلاثة عناصر: مصدر الحدث (Event Source)، الحدث نفسه (Event Object)، والمستمع (Listener)","يوضح دور Event Dispatch Thread في إدارة الأحداث وتوجيهها للمستمعين المناسبين","Action Event — عند الضغط على زر","Adjustment Event — عند استخدام أشرطة التمرير","Component Event — عند تغيير حجم أو مكان المكون","Item Event — عند اختيار عناصر (مثل Checkbox)","Text Event — عند تغيير النصوص"],"case_study_ar":"كل أزرار النافذة تستخدم مستمعاً واحداً ضخماً بشروط كثيرة.","case_question_ar":"كيف تنظّم الأحداث بمستمعات أصغر وأوضح؟","challenge_ar":"نفّذ المستمع نفسه بـ Lambda وقارن طول الكود.","videos":[{"title_ar":"المحاضرة — الكلاسات المتداخلة ومعالجة الأحداث","url":"https://youtu.be/HV9ThAF_Eq8","description_ar":null}],"resources":[{"label":"Learn Java — dev.java","url":"https://dev.java/learn/","kind":"website"},{"label":"The Java Tutorials — Oracle","url":"https://docs.oracle.com/javase/tutorial/","kind":"website"}],"assignment":{"title_ar":"تكليف: الكلاسات المتداخلة ومعالجة الأحداث","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_JAVA_L11_NestedClassesEvent\n\nالمطلوب:\n1️⃣ اكتب مثالاً لكل نوع من الكلاسات المتداخلة الأربعة مع تعليق يشرح متى يُستخدم.\n2️⃣ أنشئ نافذة فيها زر يغيّر لون الخلفية عند الضغط باستخدام ActionListener.\n3️⃣ نفّذ المستمع مرة ككلاس داخلي ومرة كـ anonymous class.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"المستمعات والفأرة وAdapters وSwing","title_en":"Listeners, Mouse Events, Adapters & Swing","kind":"video","summary_ar":"يقدم هذا الفيديو جزءًا من كورس تعلم لغة Java، ويركز بشكل أساسي على مفاهيم التعامل مع الأحداث (Event Handling) في واجهات المستخدم الرسومية (GUI).","outcomes_ar":["أنواع الـ Listeners — استعرض المحاضر مختلف الـ Listeners المقابلة للأحداث (Events)، مثل `ActionListener` و`ItemListener` و`KeyListener` و`MouseListener`، موضحًا أن كل نوع يحتوي على ميثودز محددة للاستجابة للأحداث المختلفة","التعامل مع الفأرة (Mouse Events) — شرح كيف تم تقسيم التعامل مع الفأرة إلى `MouseListener` (للضغط، التحرير، والنقر) و`MouseMotionListener` (للحركة والسحب)","استخدام الـ Adapters — أوضح المحاضر كيفية استخدام الـ Adapters كبديل لتنفيذ الـ Listeners التي تحتوي على ميثودز متعددة، مما يسهل كتابة الكود عبر عمل Override للميثود المطلوبة فقط","مكتبة Swing — انتقل الحديث إلى استخدام مكونات Swing (مثل `JFrame` و`JTextArea`) لإنشاء واجهات المستخدم، مشيرًا إلى أهمية `JScrollPane` وخصائص الفريم مثل `setResizable` و`setVisible`","إنشاء تطبيق يحتوي على أزرار للتحكم (زيادة/نقصان)","تحريك نص باستخدام لوحة المفاتيح","التحكم في حركة كورة باستخدام الأزرار (Start/Pause) باستخدام متغير من نوع `volatile`","رسم خطوط باستخدام الفأرة"],"case_study_ar":"كلاس يحتاج حدثاً واحداً من الفأرة لكنه مضطر لكتابة خمس دوال فارغة.","case_question_ar":"كيف يحل Adapter هذه المشكلة؟","challenge_ar":"حوّل برنامج الرسم إلى لوحة رسم بألوان قابلة للاختيار وزر مسح.","videos":[{"title_ar":"المحاضرة — المستمعات والفأرة وAdapters وSwing","url":"https://youtu.be/Lrpu0mHPVNQ","description_ar":null}],"resources":[{"label":"Learn Java — dev.java","url":"https://dev.java/learn/","kind":"website"},{"label":"The Java Tutorials — Oracle","url":"https://docs.oracle.com/javase/tutorial/","kind":"website"}],"assignment":{"title_ar":"تكليف: المستمعات والفأرة وAdapters وSwing","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_JAVA_L12_ListenersMouseEvents\n\nالمطلوب:\n1️⃣ تطبيق Swing فيه زرّا زيادة ونقصان لعدّاد ظاهر.\n2️⃣ حرّك نصاً بأسهم لوحة المفاتيح.\n3️⃣ ارسم خطوطاً بسحب الفأرة باستخدام MouseAdapter.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}}]},{"title_ar":"الملفات والشبكات وقواعد البيانات","lessons":[{"title_ar":"تدفقات الإدخال والإخراج والشبكات","title_en":"I/O Streams & Networking","kind":"video","summary_ar":"يركز هذا الدرس بشكل أساسي على التعامل مع ملفات الإدخال والإخراج (I/O Streams) وتقنيات الشبكات (Networking) في Java.","outcomes_ar":["شرح تدفق البيانات (Data Flow) من المصدر إلى الوجهة، وكيف يتعامل برنامج Java مع هذه التدفقات","التمييز بين أنواع الـ Streams (مثل الـ Input والـ Output)","مناقشة الفرق بين الملفات (Files) والمجلدات (Directories)، وكيفية استخدام كلاس `File` في Java لإدارة الملفات والتحقق من وجودها ومعلوماتها","الفرق بين Low-level streams (التي تتعامل مع البايتات أو الكاركترات مباشرة) و High-level streams التي توفر وظائف أكثر تعقيداً","أمثلة على كلاسات مثل `FileInputStream` و `FileOutputStream` و `RandomAccessFile`","شرح كيفية عمل الخادم والعميل (Client-Server communication)","توضيح مفهوم الـ Sockets وكيفية استخدام كلاسات `ServerSocket` و `Socket` في حزمة `java.net` لإنشاء تطبيقات شبكية بسيطة","تقديم مثال عملي لكتابة تطبيق بسيط يقوم بتبادل الرسائل بين عميل وخادم عبر الشبكة","يؤكد المحاضر على أهمية فهم كيفية إغلاق الـ Streams بعد الانتهاء منها واستخدام الـ `try-catch` للتعامل مع الاستثناءات (IOExceptions)"],"case_study_ar":"برنامج يقرأ ملفاً كبيراً بايتاً بايتاً ويأخذ دقائق.","case_question_ar":"كيف تحسّن الـ Buffered Streams الأداء؟","challenge_ar":"احفظ قائمة كائنات في ملف بالـ Serialization ثم أعد قراءتها.","videos":[{"title_ar":"المحاضرة — تدفقات الإدخال والإخراج والشبكات","url":"https://youtu.be/vqIqsUWf5dg","description_ar":null}],"resources":[{"label":"Learn Java — dev.java","url":"https://dev.java/learn/","kind":"website"},{"label":"The Java Tutorials — Oracle","url":"https://docs.oracle.com/javase/tutorial/","kind":"website"}],"assignment":{"title_ar":"تكليف: تدفقات الإدخال والإخراج والشبكات","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_JAVA_L13_IOStreams\n\nالمطلوب:\n1️⃣ اكتب برنامجاً ينسخ ملفاً نصياً سطراً سطراً باستخدام BufferedReader وBufferedWriter.\n2️⃣ اعرض محتويات مجلد مع حجم كل ملف باستخدام File.\n3️⃣ اكتب Server وClient بسيطين يتبادلان رسالة عبر Socket.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"تطبيق غرفة دردشة Client/Server","title_en":"Building a Chat Room (Client/Server)","kind":"video","summary_ar":"يشرح هذا الفيديو كيفية بناء تطبيق دردشة (Chat Room) باستخدام لغة Java، مع التركيز على مفاهيم الربط بين الخادم (Server) والعميل (Client).","outcomes_ar":["يعتمد النظام على خادم يستمع لطلبات الاتصال من عدة عملاء (Clients) في نفس الوقت","عند انضمام عميل، يقوم الخادم بإنشاء خيط معالجة (Thread) خاص به للتعامل مع رسائله وإعادة إرسالها لجميع المتصلين في الغرفة","يتكون من فئتين رئيسيتين — `ChatServer` لإدارة الاتصال عبر Sockets و `ChatHandler` للتعامل مع كل عميل كـ Thread مستقل","استخدام مصفوفة من نوع Vector (تكون Static) لتخزين جميع اتصالات العملاء المفتوحة لضمان وصول الرسائل للجميع","يتم تعديل واجهة المستخدم الرسومية (GUI) لتتضمن اتصالاً عبر Socket","إضافة خيط قارئ (Reader Thread) لاستقبال الرسائل من الخادم وتحديث نافذة المحادثة فوراً","إمكانية استخدام JOptionPane لإجبار المستخدم على إدخال اسم مستخدم (Username) عند بدء التطبيق لتمييز الرسائل","استعراض سريع لكيفية التعامل مع الروابط عبر الإنترنت باستخدام فئة URL في Java، وكيفية استخدام `openStream` لقراءة بيانات من صفحات الويب","ختم المحاضر الفيديو بالتشجيع على التجربة العملية في المختبر وتجهيز قاعدة بيانات MySQL للمحاضرة القادمة"],"case_study_ar":"عند خروج أحد العملاء فجأة يتوقف الخادم عن العمل للجميع.","case_question_ar":"كيف تعالج انقطاع عميل دون أن يسقط الخادم؟","challenge_ar":"أضف رسائل خاصة بين عميلين بصيغة ‎@الاسم.","videos":[{"title_ar":"المحاضرة — تطبيق غرفة دردشة Client/Server","url":"https://youtu.be/OXBQm2bn3N4","description_ar":null}],"resources":[{"label":"Learn Java — dev.java","url":"https://dev.java/learn/","kind":"website"},{"label":"The Java Tutorials — Oracle","url":"https://docs.oracle.com/javase/tutorial/","kind":"website"}],"assignment":{"title_ar":"تكليف: تطبيق غرفة دردشة Client/Server","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_JAVA_L14_BuildingAChat\n\nالمطلوب:\n1️⃣ ابنِ غرفة دردشة: خادم يقبل عدة عملاء، كل عميل في خيط، ويعيد بث كل رسالة للجميع.\n2️⃣ أضف اسم المرسل والوقت لكل رسالة.\n3️⃣ اعرض الاتصال بثلاثة عملاء على الأقل في لقطات شاشة.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"ربط Java بقواعد البيانات JDBC","title_en":"Java Database Connectivity (JDBC)","kind":"video","summary_ar":"يقدم هذا الفيديو شرحًا تعليميًا حول كيفية ربط لغة البرمجة Java بقواعد البيانات. يغطي هذا الدرس الفيديو المفاهيم الأساسية لتقنية JDBC (Java Database Connectivity) وكيفية التعامل مع قواعد البيانات بشكل عام.","outcomes_ar":["مقدمة عن JDBC — شرح الهدف من استخدام JDBC كواجهة برمجية تسمح لبرامج Java بالاتصال بأنظمة إدارة قواعد البيانات المختلفة بشكل موحد","أنواع تعريفات الربط (Drivers) — استعراض الأنواع الأربعة لمشغلات قواعد البيانات (Drivers)، مع توضيح الفروق بينها من حيث الأداء وقابلية النقل، مع التركيز على النوع الرابع (Type 4) كأكثرهم شيوعًا واستخدامًا","تحميل تعريف الربط (Load Driver)","إنشاء الاتصال (Establish Connection)","إنشاء كائن تنفيذ الاستعلام (Create Statement)","تنفيذ الاستعلام واستقبال النتائج في Result Set","إغلاق الاتصال (Close Connection)","الاستعلامات المتقدمة — الحديث عن استخدام PreparedStatement عند تكرار الاستعلامات مع تغيير القيم، و CallableStatement للتعامل مع الإجراءات المخزنة (Stored Procedures)","خصائص مجموعة النتائج (ResultSet) — شرح كيفية التحكم في اتجاه التصفح (Scrollable) وقابلية التعديل (Updatable) والاحتفاظ بالبيانات عند الالتزام (Holdability)","استخدام المعالجة بالدفعات (Batching) — شرح كيفية تنفيذ مجموعة من العمليات معًا لتحسين الأداء وضمان سلامة البيانات من خلال الترانزكشن"],"case_study_ar":"برنامج يبني الاستعلام بجمع النصوص من مدخلات المستخدم مباشرة.","case_question_ar":"ما ثغرة SQL Injection هنا؟ وكيف يمنعها PreparedStatement؟","challenge_ar":"نفّذ عملية تحويل بين حسابين داخل Transaction مع commit وrollback.","videos":[{"title_ar":"المحاضرة — ربط Java بقواعد البيانات JDBC","url":"https://youtu.be/gHkxBqbbKp0","description_ar":null}],"resources":[{"label":"Learn Java — dev.java","url":"https://dev.java/learn/","kind":"website"},{"label":"The Java Tutorials — Oracle","url":"https://docs.oracle.com/javase/tutorial/","kind":"website"}],"assignment":{"title_ar":"تكليف: ربط Java بقواعد البيانات JDBC","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_JAVA_L15_JavaDatabaseConnectivity\n\nالمطلوب:\n1️⃣ أنشئ جدول students في قاعدة بيانات (MySQL أو PostgreSQL أو SQLite).\n2️⃣ نفّذ عمليات CRUD كاملة باستخدام PreparedStatement.\n3️⃣ اعرض النتائج من ResultSet، ونفّذ إدخالاً بالدفعات (Batch).\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"المجموعات Collections وGenerics","title_en":"Java Collections Framework & Generics","kind":"video","summary_ar":"يقدم هذا الفيديو شرحًا تعليميًا حول مجموعات جافا (Java Collections Framework)، وهي مكتبة توفر هياكل بيانات جاهزة للمبرمجين.","outcomes_ar":["مفهوم الكولكشنز — هي مجموعة من الفئات (Classes) والواجهات (Interfaces) الجاهزة التي تسهل التعامل مع هياكل البيانات مثل القوائم والمجموعات","السيتس (Sets) — مجموعات تحتوي على عناصر فريدة ولا تكرر البيانات","السيكونسز (Sequences) — تشمل القوائم (Lists) مثل ArrayList وLinkedList، والطوابير (Queues) التي تتبع نظام الدخول والخروج","المابس (Maps) — تقوم بتخزين البيانات على شكل مفتاح وقيمة (Key-Value)","المكررات (Iterators) — أداة تتيح التنقل عبر العناصر داخل الكولكشن","الجينيريكس (Generics) — ميزة تسمح بتحديد نوع البيانات داخل الكولكشن لمنع أخطاء التحويل (Casting)","يركز الجزء الثاني من المحاضرة على التطبيق العملي للاتصال بقواعد بيانات MySQL باستخدام Java JDBC، والتعامل مع جمل الاستعلام (SQL statements) لتنفيذ عمليات الإضافة، الحذف، والتعديل، بالإضافة إلى كيفية إعداد بيئة العمل باست"],"case_study_ar":"برنامج يبحث في قائمة من مليون عنصر بحلقة for عن عنصر ما مرات كثيرة.","case_question_ar":"أي مجموعة أنسب للبحث السريع؟ ولماذا؟","challenge_ar":"قارن زمن البحث في ArrayList وHashSet لمليون عنصر ووثّق النتائج.","videos":[{"title_ar":"المحاضرة — المجموعات Collections وGenerics","url":"https://youtu.be/v79YbEzyIX4","description_ar":null}],"resources":[{"label":"Learn Java — dev.java","url":"https://dev.java/learn/","kind":"website"},{"label":"The Java Tutorials — Oracle","url":"https://docs.oracle.com/javase/tutorial/","kind":"website"}],"assignment":{"title_ar":"تكليف: المجموعات Collections وGenerics","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_JAVA_L16_JavaCollectionsFramework\n\nالمطلوب:\n1️⃣ أدر قائمة كتب باستخدام ArrayList: إضافة، حذف، بحث، وترتيب بـ Comparator.\n2️⃣ استخدم HashSet لإزالة التكرار وHashMap لعدّ تكرار الكلمات في نص.\n3️⃣ اكتب كلاساً عاماً Box<T> واستخدمه بنوعين مختلفين.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}}]},{"title_ar":"واجهات JavaFX","lessons":[{"title_ar":"مقدمة JavaFX ودورة حياة التطبيق","title_en":"Introduction to JavaFX & the Application Lifecycle","kind":"video","summary_ar":"يقدم هذا الفيديو مقدمة شاملة حول تطوير واجهات المستخدم الرسومية (GUI) في لغة Java، مع التركيز بشكل خاص على تقنية JavaFX.","outcomes_ar":["تطور واجهات Java — استعرض الفيديو رحلة تطوير الواجهات بدءاً من مكتبة AWT (Abstract Window Toolkit) التي كانت تعتمد على نظام التشغيل، مروراً بـ Swing التي وفرت مكونات أخف (Lightweight)، وصولاً إلى JavaFX كجيل حديث يواكب ا","مفاهيم JavaFX الأساسية — تم شرح بنية التطبيق المعتمدة على Stage (المسرح) و Scene (المشهد) و Nodes (العُقد)، وكيفية إدارة المكونات داخل هذه البنية","دورة حياة التطبيق (Life Cycle) — شرح الفيديو أهمية الدوال البرمجية مثل `start()`, `init()`, و `stop()`، وكيفية التعامل مع الخيوط (Threads) داخل بيئة JavaFX","التفاعل مع التطبيق — تم التطرق إلى أهمية الخيط الرئيسي (JavaFX Application Thread) وضرورة استخدامه عند تحديث واجهة المستخدم لتجنب أخطاء وقت التشغيل","التصميم والأسلوب — الإشارة إلى إمكانية استخدام ملفات CSS لتنسيق واجهات المستخدم، مما يفصل بين التصميم والمنطق البرمجي","كما أشار الفيديو إلى أن الممارسة العملية ستبدأ في المحاضرات التالية لتعلم التحكم في المكونات (Controls) وإدارة الأحداث (Event Handling)"],"case_study_ar":"فريق يختار بين Swing وJavaFX لتطبيق سطح مكتب جديد.","case_question_ar":"ما الذي يرجّح JavaFX لمشروع جديد؟","challenge_ar":"أضف نافذة ثانية تُفتح من الزر الأول.","videos":[{"title_ar":"المحاضرة — مقدمة JavaFX ودورة حياة التطبيق","url":"https://youtu.be/zkJLCDVo4Lc","description_ar":null}],"resources":[{"label":"Learn Java — dev.java","url":"https://dev.java/learn/","kind":"website"},{"label":"The Java Tutorials — Oracle","url":"https://docs.oracle.com/javase/tutorial/","kind":"website"}],"assignment":{"title_ar":"تكليف: مقدمة JavaFX ودورة حياة التطبيق","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_JAVA_L17_IntroductionToJavaFX\n\nالمطلوب:\n1️⃣ جهّز مشروع JavaFX وشغّل نافذة فيها عنوان وزر.\n2️⃣ اطبع رسائل في init وstart وstop لتتبع دورة الحياة.\n3️⃣ اشرح العلاقة بين Stage وScene وNode بمخطط بسيط.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"تنسيق واجهات JavaFX بـ CSS","title_en":"Styling JavaFX with CSS","kind":"video","summary_ar":"يركز هذا الدرس بشكل خاص على كيفية استخدام ملفات CSS لتنسيق واجهات المستخدم في JavaFX.","outcomes_ar":["تنسيق الواجهات — شرح المحاضر كيفية تعيين معرفات (IDs) للعناصر البرمجية لاستدعائها وتنسيقها لاحقًا","استخدام ملفات CSS — كيفية ربط ملف CSS خارجي بمشروع JavaFX لتطبيق الأنماط على عناصر الواجهة، سواء على مستوى الـ Root أو على عناصر محددة","خصائص الـ Stage — توضيح الأنماط المختلفة لنوافذ التطبيق مثل Decorated، Undecorated، و Transparent، بالإضافة إلى مفهوم الـ Modality للتحكم في كيفية تفاعل النوافذ مع بعضها","التطبيق العملي — قام المحاضر بإجراء تجربة عملية لإنشاء تطبيق \"Hello World\" وتعديل خصائصه مثل الخط والألوان باستخدام الكود البرمجي مباشرة","أدوات المطور — استعرض كيفية إعداد وتكامل أداة Scene Builder مع بيئة التطوير NetBeans لتسهيل تصميم الواجهات"],"case_study_ar":"التنسيق مكتوب داخل الكود في كل عنصر على حدة.","case_question_ar":"لماذا فصل التنسيق في ملف CSS أفضل للصيانة؟","challenge_ar":"أضف وضعاً داكناً بملف CSS ثانٍ وزر للتبديل.","videos":[{"title_ar":"المحاضرة — تنسيق واجهات JavaFX بـ CSS","url":"https://youtu.be/p409HlTuaak","description_ar":null}],"resources":[{"label":"Learn Java — dev.java","url":"https://dev.java/learn/","kind":"website"},{"label":"The Java Tutorials — Oracle","url":"https://docs.oracle.com/javase/tutorial/","kind":"website"}],"assignment":{"title_ar":"تكليف: تنسيق واجهات JavaFX بـ CSS","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_JAVA_L18_StylingJavaFXWith\n\nالمطلوب:\n1️⃣ أنشئ ملف style.css واربطه بالمشهد.\n2️⃣ نسّق الأزرار والخلفية والخطوط بألوان هوية TechMood.\n3️⃣ غيّر خصائص الـ Stage: العنوان، الأيقونة، والحجم الأدنى.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"عناصر التحكم في JavaFX","title_en":"JavaFX Controls","kind":"video","summary_ar":"يقدم هذا الفيديو شرحًا مفصلاً لعناصر التحكم الأساسية في مكتبة JavaFX، مع التركيز على كيفية بناء واجهات المستخدم الرسومية (GUI).","outcomes_ar":["فئات الأزرار (Buttons) — شرح المحاضر الفئات المشتقة من `ButtonBase` مثل الأزرار العادية (`Button`)، صناديق الاختيار (`CheckBox`)، الروابط التشعبية (`Hyperlink`)، وأزرار التبديل (`ToggleButton`)","أنماط الأزرار — أوضح المحاضر ميزة الأزرار الافتراضية (`Default`) وزر الإلغاء (`Cancel`)، وكيفية تفعيلها لتستجيب لمفاتيح Enter و Esc","صناديق الاختيار (CheckBox) — تم شرح الحالات الثلاث لصندوق الاختيار: المحدد (`Checked`)، غير المحدد (`Unchecked`)، والحالة غير المحددة (`Undefined/Indeterminate`) التي تُستخدم في البرمجة لحالات خاصة","عناصر إدخال النصوص — استعرض الفيديو `TextField` و `TextArea` والخصائص المشتركة بينهما، مثل التعامل مع النصوص، إدراجها، مسحها، وتحديد مكان مؤشر الكتابة","القوائم (Menus) — تم شرح مكونات القوائم الثلاثة: `MenuBar`، `Menu`، و `MenuItem`، مع توضيح كيفية إضافة اختصارات لوحة المفاتيح (`Accelerator`) وإدراج الصور داخل القوائم","التنظيم (Layout) — تم التنويه لاستخدام `BorderPane` لتقسيم واجهة المستخدم وتوزيع المكونات مثل شريط القوائم في الأعلى","كما أكد المحاضر على أهمية الرجوع إلى توثيق JavaFX الرسمي بدلاً من الاعتماد على توثيق Java الأساسي لفهم الكلاسات والدوال بشكل صحيح"],"case_study_ar":"نموذج يقبل حقولاً فارغة وبريداً غير صالح.","case_question_ar":"كيف تتحقق من المدخلات قبل الحفظ وتُظهر رسالة واضحة؟","challenge_ar":"احفظ البيانات المدخلة في ملف CSV.","videos":[{"title_ar":"المحاضرة — عناصر التحكم في JavaFX","url":"https://youtu.be/VqxUHCLwN9U","description_ar":null}],"resources":[{"label":"Learn Java — dev.java","url":"https://dev.java/learn/","kind":"website"},{"label":"The Java Tutorials — Oracle","url":"https://docs.oracle.com/javase/tutorial/","kind":"website"}],"assignment":{"title_ar":"تكليف: عناصر التحكم في JavaFX","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_JAVA_L19_JavaFXControls\n\nالمطلوب:\n1️⃣ ابنِ نموذج تسجيل: حقول نصية وكلمة مرور وCheckBox وRadioButton وComboBox.\n2️⃣ أضف قائمة MenuBar بخيارات ملف ومساعدة.\n3️⃣ اعرض ملخص البيانات المدخلة في Alert عند الضغط على «تسجيل».\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"التخطيط وScene Builder ومشروع Notepad","title_en":"Layouts, Scene Builder & a Notepad Project","kind":"video","summary_ar":"يشرح هذا الدرس إدارة الأحداث ومديري التخطيط في JavaFX (BorderPane وFlowPane وGridPane وAnchorPane)، وتصميم الواجهة بصرياً في Scene Builder، ثم بناء محرر نصوص كامل كمشروع عملي.","outcomes_ar":["إدارة الأحداث (Event Handling) — شرح المحاضر كيفية التعامل مع الأحداث (Events) في JavaFX باستخدام واجهة `EventHandler` الجينيريك، وطرق ربطها بالمكونات (Controls) عبر ميثود `setOnAction` أو `addEventHandler`","BorderPane — لتقسيم الواجهة إلى خمس مناطق (توب، بوتوم، يمين، يسار، ومركز)","FlowPane — لترتيب المكونات بتدفق مستمر","GridPane — لتقسيم الواجهة إلى شبكة من الصفوف والأعمدة","AnchorPane — لتثبيت المكونات بناءً على المسافة من الأطراف","مشروع عملي (نوت باد) — تطبيق عملي لبناء برنامج محرر نصوص بسيط باستخدام JavaFX و Scene Builder","استخدام Scene Builder لتصميم الواجهة بصرياً وتوليد ملفات FXML","دمج Scene Builder مع NetBeans وتوليد كلاسات جافا من ملفات FXML","برمجة الوظائف الأساسية مثل فتح الملفات باستخدام `FileChooser`"],"case_study_ar":"النافذة تتشوه عناصرها عند تكبيرها.","case_question_ar":"أي Layout يحافظ على ترتيب العناصر عند تغيير الحجم؟","challenge_ar":"أضف عدّاد كلمات وأسطر يتحدث أثناء الكتابة.","videos":[{"title_ar":"المحاضرة — التخطيط وScene Builder ومشروع Notepad","url":"https://youtu.be/kHVk8YlMWws","description_ar":null}],"resources":[{"label":"Learn Java — dev.java","url":"https://dev.java/learn/","kind":"website"},{"label":"The Java Tutorials — Oracle","url":"https://docs.oracle.com/javase/tutorial/","kind":"website"}],"assignment":{"title_ar":"تكليف: التخطيط وScene Builder ومشروع Notepad","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_JAVA_L20_LayoutsSceneBuilder\n\nالمطلوب:\n1️⃣ استخدم BorderPane وGridPane وFlowPane في شاشة واحدة.\n2️⃣ صمّم الواجهة في Scene Builder وولّد ملف FXML.\n3️⃣ ابنِ محرر نصوص (Notepad): جديد، فتح، حفظ، وقص/نسخ/لصق.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}}]},{"title_ar":"Java الحديثة","lessons":[{"title_ar":"Java 8: Lambda وMethod References وStream API","title_en":"Java 8: Lambdas, Method References & Streams","kind":"video","summary_ar":"يقدم هذا الفيديو شرحاً مفصلاً للمميزات البرمجية الحديثة التي تم تقديمها في Java 8، والتي أحدثت نقلة نوعية في لغة البرمجة.","outcomes_ar":["الواجهات الوظيفية (Functional Interfaces) — شرح لكيفية عمل الواجهات التي تحتوي على دالة مجردة واحدة فقط، وكيفية استخدامها","تعبيرات لامدا (Lambda Expressions) — توضيح كيفية كتابة دوال مختصرة ومباشرة للتعامل مع الواجهات الوظيفية لتحسين أداء وقراءة الكود","مراجعات الدوال (Method References) — شرح للحالات الخاصة التي يتم فيها استخدام تعبيرات لامدا لتقليل الكتابة واستدعاء الدوال مباشرة","واجهة برمجة تطبيقات الستريم (Stream API) — مناقشة قوية حول معالجة البيانات بكفاءة، حيث تتيح الستريمز إجراء عمليات متسلسلة (Pipeline) على المجموعات (Collections) بطريقة برمجية وظيفية، مع توضيح الفروق بين العمليات الوسيطة "],"case_study_ar":"كود من 30 سطراً بحلقات وشروط لفلترة وترتيب قائمة.","case_question_ar":"كيف يختصره Stream API ويجعله أوضح؟","challenge_ar":"احسب متوسط الراتب لكل قسم باستخدام Collectors.groupingBy.","videos":[{"title_ar":"المحاضرة — Java 8: Lambda وMethod References وStream API","url":"https://youtu.be/DgaZp2eay58","description_ar":null}],"resources":[{"label":"Learn Java — dev.java","url":"https://dev.java/learn/","kind":"website"},{"label":"The Java Tutorials — Oracle","url":"https://docs.oracle.com/javase/tutorial/","kind":"website"}],"assignment":{"title_ar":"تكليف: Java 8: Lambda وMethod References وStream API","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_JAVA_L21_Java8Lambdas\n\nالمطلوب:\n1️⃣ أعد كتابة Comparator ومستمع حدث باستخدام Lambda.\n2️⃣ على قائمة موظفين: صفِّ الرواتب الأعلى من حد، رتّب، واجمع أسماءهم بـ Stream.\n3️⃣ استخدم Method Reference مرة واحدة على الأقل.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"Parallel Streams وواجهة التاريخ والوقت","title_en":"Parallel Streams & the Date/Time API","kind":"video","summary_ar":"يقدم هذا الفيديو الجزء الثاني والعشرين من دورة تعليمية لبرمجة Java، حيث يركز على مواضيع متقدمة في البرمجة الوظيفية ومعالجة البيانات وتاريخ الوقت.","outcomes_ar":["معالجة البيانات المتوازية (Parallel Streams) — يشرح المحاضر كيف يمكن تحويل Streams من الحالة التسلسلية إلى الحالة المتوازية بسهولة باستخدام `parallel()`، مما يسمح بتوزيع العمليات الحسابية الكبيرة (مثل جمع الأرقام) على عد","واجهة برمجة تطبيقات الوقت والتاريخ (Date and Time API) — يتناول المحاضر مشكلات كلاس `Date` القديم في Java، ويقدم البديل الأفضل في JDK 8 وهو باكدج `java.time` التي تشمل كلاسات مثل `LocalDate` و`LocalTime` و`Duration` و`Pe"],"case_study_ar":"تطبيق يحسب مواعيد التسليم ويخطئ بيوم في بعض الأشهر.","case_question_ar":"لماذا Date/Time API الحديثة أدق من Date القديمة؟","challenge_ar":"ابنِ أداة صغيرة تعرض الوقت الحالي في ثلاث مناطق زمنية.","videos":[{"title_ar":"المحاضرة — Parallel Streams وواجهة التاريخ والوقت","url":"https://youtu.be/80QdxccQqUI","description_ar":null}],"resources":[{"label":"Learn Java — dev.java","url":"https://dev.java/learn/","kind":"website"},{"label":"The Java Tutorials — Oracle","url":"https://docs.oracle.com/javase/tutorial/","kind":"website"}],"assignment":{"title_ar":"تكليف: Parallel Streams وواجهة التاريخ والوقت","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_JAVA_L22_ParallelStreamsThe\n\nالمطلوب:\n1️⃣ قارن زمن معالجة قائمة كبيرة بـ stream و parallelStream ووثّق النتائج.\n2️⃣ استخدم LocalDate وLocalDateTime وPeriod لحساب العمر وأيام متبقية على موعد.\n3️⃣ نسّق التاريخ بـ DateTimeFormatter بصيغة عربية وإنجليزية.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}}]}]}$course$::jsonb);

select public.import_course($course${"slug":"db-foundations","title_ar":"أساسيات قواعد البيانات","title_en":"Database Fundamentals","description_ar":"لماذا قواعد البيانات وما الـDBMS، ومستويات معمارية قواعد البيانات، والتصميم بمخطط ERD وتحويله إلى جداول، ثم SQL: إنشاء الجداول والقيود، والإدخال والتعديل والاستعلام، والتجميع والاستعلامات الفرعية والربط، وصولاً إلى التطبيع.","level":"beginner","estimated_hours":30,"paths":[],"modules":[{"title_ar":"المفاهيم والمعمارية","lessons":[{"title_ar":"ما قواعد البيانات ولماذا نحتاجها","title_en":"What Databases Are & Why We Need Them","kind":"video","summary_ar":"يقدم هذا الفيديو، مقدمة شاملة حول مفاهيم قواعد البيانات وأهميتها في التطبيقات البرمجية.","outcomes_ar":["الفرق بين البيانات والمعلومات — البيانات هي مجرد حقائق أولية (مثل الأسماء والأرقام) لا قيمة لها بدون معالجة، بينما المعلومات هي نتاج معالجة هذه البيانات لاتخاذ قرارات","تكرار البيانات (Data Redundancy)","صعوبة تحديث البيانات وتعديلها (Inconsistency)","عزلة البيانات (Data Isolation)","اعتمادية التطبيق على هيكلية الملف","مفهوم قواعد البيانات (Database Systems) — شرح أن قواعد البيانات تنظم البيانات المترابطة وتقلل التكرار وتسمح بمشاركة البيانات بين المستخدمين","نظام إدارة قواعد البيانات (DBMS) — هو البرمجيات الوسيطة التي تعمل كحلقة وصل بين التطبيق وقاعدة البيانات، مما يوفر استقلالية للبيانات وأماناً أعلى","أهمية الميتا داتا (Metadata) — وصفها بأنها \"بيانات عن البيانات\"، وهي المسؤولة عن وصف هيكلية قاعدة البيانات للمحرك (DBMS)، مما يحدد كفاءة الأداء","المزايا والعيوب — تم تلخيص مزايا استخدام قواعد البيانات (مثل الأمان، النسخ الاحتياطي، وتقليل التكرار) ومقارنتها بالعيوب (مثل التكلفة والحاجة لخبرة تقنية لإدارة النظام)"],"case_study_ar":"عيادة تحفظ بيانات المرضى في ثلاثة ملفات Excel منفصلة، ورقم هاتف المريض مختلف بين الملفات.","case_question_ar":"ما اسم هذه المشكلة؟ وكيف تمنعها قاعدة البيانات؟","challenge_ar":"قارن بين ثلاثة أنظمة DBMS (مثل SQL Server وPostgreSQL وSQLite) في جدول: الترخيص، الاستخدام، المميزات.","videos":[{"title_ar":"المحاضرة — ما قواعد البيانات ولماذا نحتاجها","url":"https://youtu.be/TYyktNB9Ji8","description_ar":null}],"resources":[{"label":"SQL Tutorial — W3Schools","url":"https://www.w3schools.com/sql/","kind":"website"},{"label":"Relational databases — Microsoft Learn","url":"https://learn.microsoft.com/sql/relational-databases/databases/databases","kind":"website"}],"assignment":{"title_ar":"تكليف: ما قواعد البيانات ولماذا نحتاجها","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_DB_L01_WhatDatabasesAre\n\nالمطلوب:\n1️⃣ اختر نشاطاً حقيقياً (مكتبة، عيادة، متجر) واكتب كيف تُحفظ بياناته اليوم في ملفات أو Excel.\n2️⃣ حدّد ثلاث مشكلات من مشكلات نظام الملفات التي تظهر فيه (تكرار، تعارض، عزلة).\n3️⃣ اشرح كيف يحلّ DBMS كل مشكلة منها، وما الـMetadata التي سيحتاجها.\n\n📦 المطلوب تسليمه:\n📁 رابط مجلد Google Drive فيه تقرير PDF باسم TM-DB-L01.pdf\n✅ إجابات المطلوب والمخططات.\n📸 صور واضحة لكل خطوة.","required_evidence":["drive"],"is_required":true}},{"title_ar":"معمارية قواعد البيانات بثلاثة مستويات","title_en":"The Three-Level Database Architecture","kind":"video","summary_ar":"يقدم هذا الفيديو شرحاً وافياً لأساسيات هندسة قواعد البيانات (Database Architecture)، مستعرضاً كيفية التعامل مع البيانات عبر ثلاثة مستويات رئيسية.","outcomes_ar":["المستوى الخارجي (External Level) — يمثل الواجهة التي يراها المستخدم النهائي، حيث يتم إخفاء تفاصيل بنية قاعدة البيانات المعقدة","المستوى المنطقي/المفاهيمي (Logical/Conceptual Level) — هو النطاق الذي يعمل فيه المطورون لتصميم الجداول والعلاقات بين البيانات","المستوى الداخلي/الفيزيائي (Internal/Physical Level) — يهتم بكيفية تخزين البيانات فعلياً على الأقراص الصلبة، وهي مهمة تقع على عاتق نظام إدارة قواعد البيانات (DBMS)","عملية الربط (Mapping) — شرح المحاضر أهمية الربط بين لغات البرمجة (مثل C#) التي تستخدم الكائنات (Classes)، وبين قواعد البيانات التي تستخدم الجداول (Tables) بلغة SQL","توزيع طبقات التطبيق — ناقش الفيديو ثلاثة نماذج لتوزيع الواجهة، ومنطق الأعمال (Business Logic)، وقاعدة البيانات، مؤكداً أنه لا يوجد نموذج \"أفضل\" مطلقاً، بل يعتمد الاختيار على حالة العمل (Business Case)","الأدوار المهنية — أوضح الفيديو الفرق بين المحلل (Analyst)، ومصمم قاعدة البيانات، ومدير قاعدة البيانات (DBA)","أنواع قواعد البيانات — أشار إلى وجود نماذج مختلفة مثل قواعد البيانات العلائقية (Relational)، والشبكية، والهرمية، بالإضافة إلى قواعد البيانات غير العلائقية (NoSQL)"],"case_study_ar":"نُقلت قاعدة بيانات إلى قرص جديد بتنظيم ملفات مختلف، ولم يتغيّر أي سطر في التطبيق.","case_question_ar":"أي مستوى تغيّر؟ وأي ميزة سمحت بذلك؟","challenge_ar":"ابحث عن قاعدة بيانات NoSQL وقارنها بالعلائقية في ثلاث نقاط.","videos":[{"title_ar":"المحاضرة — معمارية قواعد البيانات بثلاثة مستويات","url":"https://youtu.be/rKJKkyyBmIs","description_ar":null}],"resources":[{"label":"SQL Tutorial — W3Schools","url":"https://www.w3schools.com/sql/","kind":"website"},{"label":"Relational databases — Microsoft Learn","url":"https://learn.microsoft.com/sql/relational-databases/databases/databases","kind":"website"}],"assignment":{"title_ar":"تكليف: معمارية قواعد البيانات بثلاثة مستويات","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_DB_L02_TheThreeLevel\n\nالمطلوب:\n1️⃣ ارسم مخطط المستويات الثلاثة (الخارجي، المنطقي، الفيزيائي) لنظام تختاره.\n2️⃣ اكتب مثالاً لما يراه كل نوع مستخدم في المستوى الخارجي.\n3️⃣ اشرح استقلالية البيانات المنطقية والفيزيائية بمثال.\n4️⃣ عدّد الأدوار المهنية حول قواعد البيانات (DBA، مصمم، مطور) ومهمة كل واحد.\n\n📦 المطلوب تسليمه:\n📁 رابط مجلد Google Drive فيه تقرير PDF باسم TM-DB-L02.pdf\n✅ إجابات المطلوب والمخططات.\n📸 صور واضحة لكل خطوة.","required_evidence":["drive"],"is_required":true}}]},{"title_ar":"التصميم بمخطط ERD","lessons":[{"title_ar":"النموذج المنطقي ومكونات ERD","title_en":"Logical Modeling & ERD Components","kind":"video","summary_ar":"يقدم هذا الفيديو الجزء الثاني من سلسلة أساسيات قواعد البيانات (Database Fundamentals).","outcomes_ar":["النموذج المنطقي (Logical Modeling) — أكد المحاضر على أهمية البدء برسم نموذج منطقي قبل الانتقال إلى بناء الجداول الفعلية، مستعرضاً مفهوم مخطط علاقات الكيانات (ERD)","الكيان (Entity) — وهو أي شيء مهم نحتاج لجمع بيانات عنه (مثل: الموظف، المتدرب، الكورس) ويمثل بمستطيل","الكيان الضعيف (Weak Entity) — الكيان الذي يعتمد وجوده على وجود كيان آخر، ويمثل بمستطيلين متداخلين","السمات (Attributes) — هي خصائص الكيان، وتتنوع بين سمات بسيطة، مركبة (Composite)، متعددة القيم (Multi-valued)، ومشتقة (Derived)","المفاتيح (Keys) — شرح المحاضر أهمية اختيار مفتاح أساسي (Primary Key) فريد لكل كيان، مع الإشارة إلى مفهوم المفاتيح المرشحة (Candidate Keys) والمفاتيح الأجنبية (Foreign Keys) التي تربط بين الجداول","سلامة البيانات (Referential Integrity) — أوضح دور نظام إدارة قواعد البيانات (DBMS) في ضمان صحة البيانات ومنع حدوث أخطاء عند إضافة أو حذف السجلات المترابطة","انتهى الجزء الأول من المحاضرة بالتمهيد لمناقشة العلاقات بين الكيانات بعد فترة استراحة"],"case_study_ar":"جدول كتب بلا مفتاح أساسي فيه نسختان من الكتاب نفسه بنفس البيانات.","case_question_ar":"كيف تختار مفتاحاً أساسياً يميّز كل نسخة؟","challenge_ar":"ارسم ERD المكتبة كاملاً بأداة مثل draw.io.","videos":[{"title_ar":"المحاضرة — النموذج المنطقي ومكونات ERD","url":"https://youtu.be/5htSh5nG41E","description_ar":null}],"resources":[{"label":"SQL Tutorial — W3Schools","url":"https://www.w3schools.com/sql/","kind":"website"},{"label":"Relational databases — Microsoft Learn","url":"https://learn.microsoft.com/sql/relational-databases/databases/databases","kind":"website"}],"assignment":{"title_ar":"تكليف: النموذج المنطقي ومكونات ERD","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_DB_L03_LogicalModelingERD\n\nالمطلوب:\n1️⃣ لنظام مكتبة: حدّد الكيانات والسمات والمفاتيح الأساسية.\n2️⃣ ميّز بين سمة بسيطة ومركبة ومتعددة القيم ومشتقة بمثال من النظام.\n3️⃣ حدّد كياناً ضعيفاً إن وُجد واشرح لماذا هو ضعيف.\n\n📦 المطلوب تسليمه:\n📁 رابط مجلد Google Drive فيه تقرير PDF باسم TM-DB-L03.pdf\n✅ إجابات المطلوب والمخططات.\n📸 صور واضحة لكل خطوة.","required_evidence":["drive"],"is_required":true}},{"title_ar":"العلاقات والـCardinality والمشاركة","title_en":"Relationships, Cardinality & Participation","kind":"video","summary_ar":"يقدم هذا الفيديو شرحاً مفصلاً لأساسيات قواعد البيانات، مع التركيز على تصميم مخطط علاقات الكيانات (ERD).","outcomes_ar":["العلاقات (Relationships) — يشرح الفيديو أنواع العلاقات بين الكيانات مثل (1:1)، (1:N)، و(M:N)، وكيفية تحديدها بناءً على الأفعال المشتركة في النظام","الكارديناليتي (Cardinality) — يوضح كيفية تحديد أقصى حد للمشاركة في العلاقة","الالتزام (Obligation/Participation) — يشرح مفهوم الحد الأدنى للمشاركة (اختياري أم إجباري) وكيفية تمثيله في الرسم","العلاقات الثلاثية (Ternary Relationships) — يناقش الحالات التي تشترك فيها أكثر من كيانين في علاقة واحدة","السمات في العلاقات — يوضح متى يتم وضع السمات (Attributes) على العلاقة نفسها بدلاً من الكيانات","علاقة (Is-A) — يشرح علاقات التوريث أو التخصص بين الكيانات","يؤكد المحاضر على أهمية عدم الافتراض من تلقاء النفس عند تصميم قواعد البيانات، والاعتماد دائماً على متطلبات العمل الفعلية (Business Requirements)"],"case_study_ar":"في التصميم كل كتاب له مؤلف واحد فقط، والمكتبة تكتشف كتباً بأكثر من مؤلف.","case_question_ar":"كيف يتغير نوع العلاقة؟ وما أثره على الجداول؟","challenge_ar":"صمّم ERD لمنصة تعليمية فيها مسارات ودورات وطلاب ومنتورز.","videos":[{"title_ar":"المحاضرة — العلاقات والـCardinality والمشاركة","url":"https://youtu.be/RkrrFKfEMtc","description_ar":null}],"resources":[{"label":"SQL Tutorial — W3Schools","url":"https://www.w3schools.com/sql/","kind":"website"},{"label":"Relational databases — Microsoft Learn","url":"https://learn.microsoft.com/sql/relational-databases/databases/databases","kind":"website"}],"assignment":{"title_ar":"تكليف: العلاقات والـCardinality والمشاركة","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_DB_L04_RelationshipsCardinalityParticipation\n\nالمطلوب:\n1️⃣ أكمل ERD المكتبة بالعلاقات: عضو يستعير كتباً، كتاب له مؤلفون، فرع فيه موظفون.\n2️⃣ حدّد لكل علاقة الـCardinality (1:1، 1:N، M:N) والمشاركة (إلزامية/اختيارية).\n3️⃣ أضف علاقة ثلاثية أو علاقة Is-A واحدة على الأقل.\n\n📦 المطلوب تسليمه:\n📁 رابط مجلد Google Drive فيه تقرير PDF باسم TM-DB-L04.pdf\n✅ إجابات المطلوب والمخططات.\n📸 صور واضحة لكل خطوة.","required_evidence":["drive"],"is_required":true}},{"title_ar":"تحويل ERD إلى جداول (Mapping)","title_en":"Mapping an ERD to Tables","kind":"video","summary_ar":"يقدم هذا الفيديو شرحاً مفصلاً لأساسيات قواعد البيانات (Database Fundamentals)، وتحديداً عملية تحويل مخطط علاقات الكيانات (ERD) إلى جداول فعلية في قاعدة البيانات.","outcomes_ar":["مرحلة التخطيط (Mapping) — يوضح المحاضر أن هذه المرحلة تأتي بين رسم الـ ERD وبناء الجداول فعلياً في نظام إدارة قواعد البيانات","كل كيان (Entity) يتحول افتراضياً إلى جدول (Table)","السمات البسيطة (Simple Attributes) تتحول إلى أعمدة (Columns)","التعامل مع السمات المركبة (Composite Attributes) والسمات المشتقة (Derived Attributes)","السمات متعددة القيم (Multi-valued Attributes) — شرح لماذا لا يفضل وضعها في الجدول الأساسي وكيفية إنشاء جدول منفصل لها","علاقة واحد لواحد (1 — 1): تم شرح حالاتها المختلفة (سواء كانت اختيارية أو إجبارية من الطرفين) وكيفية تحديد المفتاح الأجنبي (Foreign Key) أو الدمج بين الجداول","علاقة واحد لمتعدد (1 — M): شرح كيفية إدارة المفاتيح الأجنبية بناءً على طبيعة العلاقة (إجبارية أم اختيارية)","علاقة متعدد لمتعدد (M — M): توضيح ضرورة إنشاء جدول وسيط يربط بين الجدولين"],"case_study_ar":"علاقة M:N بين الطلاب والدورات وُضعت كعمود course_id داخل جدول الطلاب.","case_question_ar":"ما المشكلة؟ وما الجدول الذي يحلها؟","challenge_ar":"حوّل ERD المنصة التعليمية من الدرس السابق إلى جداول.","videos":[{"title_ar":"المحاضرة — تحويل ERD إلى جداول (Mapping)","url":"https://youtu.be/tLt1uYsRgZQ","description_ar":null}],"resources":[{"label":"SQL Tutorial — W3Schools","url":"https://www.w3schools.com/sql/","kind":"website"},{"label":"Relational databases — Microsoft Learn","url":"https://learn.microsoft.com/sql/relational-databases/databases/databases","kind":"website"}],"assignment":{"title_ar":"تكليف: تحويل ERD إلى جداول (Mapping)","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_DB_L05_MappingAnERD\n\nالمطلوب:\n1️⃣ حوّل ERD المكتبة إلى جداول: الأعمدة والمفاتيح الأساسية والأجنبية.\n2️⃣ طبّق قاعدة السمات متعددة القيم (جدول منفصل).\n3️⃣ طبّق تحويل علاقات 1:1 و1:N وM:N، واشرح أين وضعت المفتاح الأجنبي ولماذا.\n\n📦 المطلوب تسليمه:\n📁 رابط مجلد Google Drive فيه تقرير PDF باسم TM-DB-L05.pdf\n✅ إجابات المطلوب والمخططات.\n📸 صور واضحة لكل خطوة.","required_evidence":["drive"],"is_required":true}},{"title_ar":"العلاقات الذاتية والتعامل مع DBMS","title_en":"Recursive Relationships & Working with a DBMS","kind":"video","summary_ar":"يقدم هذا الفيديو شرحاً وافياً حول أساسيات قواعد البيانات (Database Fundamentals) من تقديم المهندس أحمد ممدوح.","outcomes_ar":["تحويل نماذج علاقات الكيانات (ERD) — يشرح كيفية التعامل مع سمات العلاقات، والعلاقات الثلاثية، وكيفية التعامل مع العلاقات المتعددة بين الجداول","العلاقات الذاتية (Recursive Relationships) — يوضح كيفية تصميم العلاقات التي تربط الجدول بنفسه، مثل علاقة الموظف بمديره","التعامل مع نظام إدارة قواعد البيانات (DBMS) — ينتقل الفيديو إلى الجانب العملي باستخدام SQL Server و Management Studio","لغة SQL — يستعرض أقسام اللغة (DDL, DML, DCL)، وكيفية إنشاء قاعدة بيانات باستخدام الاستعلامات (Queries) أو باستخدام الواجهة الرسومية (Wizard)","إدارة ملفات قاعدة البيانات — يشرح الفرق بين ملفات البيانات (MDF) وملفات السجلات (LDF) وأهمية كل منهما"],"case_study_ar":"شركة تريد معرفة سلسلة المدراء لأي موظف حتى المدير العام.","case_question_ar":"كيف تمثّل ذلك في جدول واحد؟","challenge_ar":"اكتب استعلاماً يعرض كل موظف مع اسم مديره.","videos":[{"title_ar":"المحاضرة — العلاقات الذاتية والتعامل مع DBMS","url":"https://youtu.be/Gq2jsZYTztA","description_ar":null}],"resources":[{"label":"SQL Tutorial — W3Schools","url":"https://www.w3schools.com/sql/","kind":"website"},{"label":"Relational databases — Microsoft Learn","url":"https://learn.microsoft.com/sql/relational-databases/databases/databases","kind":"website"}],"assignment":{"title_ar":"تكليف: العلاقات الذاتية والتعامل مع DBMS","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_DB_L06_RecursiveRelationshipsWorking\n\nالمطلوب:\n1️⃣ حوّل علاقة ذاتية (موظف يدير موظفين) إلى جدول بمفتاح أجنبي يشير لنفسه.\n2️⃣ ثبّت SQL Server أو PostgreSQL وأنشئ قاعدة بيانات المكتبة.\n3️⃣ وضّح ملفات قاعدة البيانات (البيانات والسجل) وأين تُحفظ.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}}]},{"title_ar":"لغة SQL","lessons":[{"title_ar":"إنشاء الجداول والقيود","title_en":"Creating Tables & Constraints","kind":"video","summary_ar":"يقدم هذا الفيديو تعليمًا عمليًا حول أساسيات قواعد البيانات (Database Fundamentals)، حيث يركز على كيفية إنشاء الجداول وتحديد العلاقات والقيود (Constraints) باستخدام لغة SQL وأدوات الواجهة الرسومية (Wizard).","outcomes_ar":["إنشاء الجداول — شرح المحاضر كيفية إنشاء الجداول (مثل Trainer و Department) باستخدام أمر `CREATE TABLE` وتحديد أنواع البيانات المختلفة (مثل `INT` للنصوص، `VARCHAR` للبيانات المتغيرة، و `NVARCHAR` لدعم الحروف غير الإنجليزي","المفتاح الأساسي (Primary Key) — لضمان تميز كل سجل","المفتاح الأجنبي (Foreign Key) — لربط الجداول ببعضها والحفاظ على سلامة العلاقات المرجعية","القيود الأخرى — مثل `NOT NULL` لمنع القيم الفارغة، `UNIQUE` لضمان عدم التكرار، و `DEFAULT` لتعيين قيمة افتراضية (34:30، 42:43)","تعديل الجداول (ALTER) — شرح كيفية تغيير هيكل الجدول بعد إنشائه باستخدام أمر `ALTER TABLE`","أدوات الـ Wizard — استعراض طريقة إنشاء الجداول والعلاقات عبر واجهة المستخدم الرسومية كبديل لـ SQL (22:09، 30:00)","ينتهي الجزء الأول من الفيديو بالتأكيد على أن هذه المفاهيم هي اللبنة الأساسية للتعامل مع أي نظام إدارة قواعد بيانات، مع الإشارة إلى أن هناك تفاصيل أكثر تقدمًا سيتم تناولها لاحقًا"],"case_study_ar":"أُدخل كتاب بسعر سالب واستعارة لعضو غير موجود.","case_question_ar":"أي قيود كانت ستمنع ذلك؟","challenge_ar":"أضف قيد CHECK يمنع أن يكون تاريخ الإرجاع قبل تاريخ الاستعارة.","videos":[{"title_ar":"المحاضرة — إنشاء الجداول والقيود","url":"https://youtu.be/AN2XHjgB0aQ","description_ar":null}],"resources":[{"label":"SQL Tutorial — W3Schools","url":"https://www.w3schools.com/sql/","kind":"website"},{"label":"Relational databases — Microsoft Learn","url":"https://learn.microsoft.com/sql/relational-databases/databases/databases","kind":"website"}],"assignment":{"title_ar":"تكليف: إنشاء الجداول والقيود","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_DB_L07_CreatingTablesConstraints\n\nالمطلوب:\n1️⃣ اكتب سكريبت CREATE TABLE لجداول المكتبة كلها.\n2️⃣ أضف PRIMARY KEY وFOREIGN KEY وUNIQUE وCHECK وDEFAULT وNOT NULL حيث يلزم.\n3️⃣ عدّل جدولاً بـ ALTER لإضافة عمود وقيد.\n4️⃣ جرّب إدخال بيانات تخالف القيود ووثّق رسائل الرفض.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"معالجة البيانات DML والتجميع","title_en":"DML: Insert, Update, Delete, Select & Aggregates","kind":"video","summary_ar":"يقدم هذا الفيديو شرحاً وافياً لأساسيات لغة معالجة البيانات (DML) في قواعد بيانات SQL، مستعرضاً كيفية التعامل مع البيانات عبر أوامر Insert و Update و Delete و Select.","outcomes_ar":["إدراج البيانات (Insert) — شرح كيفية إضافة بيانات للجداول، سواء إدراج كامل البيانات أو أعمدة محددة، مع التنبيه لاستخدام Single Quotes للقيم النصية والتعامل مع قيم Null","تحديث وحذف البيانات (Update & Delete) — توضيح كيفية تعديل البيانات أو حذفها باستخدام شرط Where لتجنب تطبيق العمليات على كامل الجدول","استرجاع البيانات (Select) — استعراض طرق عرض البيانات، واستخدام Distinct لمنع التكرار، واستخدام Like للبحث عن أنماط نصية، مع توضيح أهمية Order By للترتيب","الدوال التجميعية (Aggregate Functions) — شرح دوال مثل Count، Sum، Avg، Min، و Max، مع التأكيد على أنها لا تأخذ القيم Null في الحسبان","تجميع البيانات (Group By) — شرح كيفية تجميع البيانات حسب أعمدة معينة لاستخراج إحصائيات لكل مجموعة، واستخدام Having للفلترة بعد عملية التجميع، حيث لا يمكن استخدام Where مع الدوال التجميعية"],"case_study_ar":"موظف نفّذ UPDATE books SET price = 0 ونسي WHERE.","case_question_ar":"ماذا حدث؟ وكيف تحمي نفسك من هذا الخطأ (Transaction، SELECT قبل UPDATE)؟","challenge_ar":"اعرض أكثر 3 أعضاء استعارة للكتب في كل شهر.","videos":[{"title_ar":"المحاضرة — معالجة البيانات DML والتجميع","url":"https://youtu.be/1T3Il2bsj5g","description_ar":null}],"resources":[{"label":"SQL Tutorial — W3Schools","url":"https://www.w3schools.com/sql/","kind":"website"},{"label":"Relational databases — Microsoft Learn","url":"https://learn.microsoft.com/sql/relational-databases/databases/databases","kind":"website"}],"assignment":{"title_ar":"تكليف: معالجة البيانات DML والتجميع","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_DB_L08_DMLInsertUpdate\n\nالمطلوب:\n1️⃣ أدخل 20 سجلاً على الأقل في جداول المكتبة.\n2️⃣ نفّذ UPDATE وDELETE بشروط آمنة (WHERE).\n3️⃣ اكتب استعلامات بـ COUNT وSUM وAVG وMAX وMIN مع GROUP BY وHAVING.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"UNION والاستعلامات الفرعية","title_en":"UNION & Subqueries","kind":"video","summary_ar":"يقدم هذا الفيديو شرحاً مفصلاً لبعض مفاهيم قواعد البيانات الأساسية (Database Fundamentals) ضمن دورة تدريبية، حيث يركز على عمليات معالجة البيانات (DML).","outcomes_ar":["تم شرح كيفية دمج نتائج استعلامين مختلفين في مجموعة نتائج واحدة باستخدام `UNION` (لإزالة التكرار) أو `UNION ALL` (لإبقاء التكرار)، مع التأكيد على ضرورة تطابق عدد وأنواع الأعمدة في كلا الاستعلامين","كيفية استخدام `IN` عندما يرجع الاستعلام الفرعي أكثر من قيمة","الفرق بين استخدام `ALL` و `ANY` عند مقارنة القيم","توضيح أن الاستعلامات الفرعية تُستخدم غالباً للربط بين الجداول عبر المفاتيح الخارجية والأساسية","جلب بيانات الموظفين بناءً على اسم القسم","إيجاد اسم القسم الذي يضم الموظف صاحب أعلى راتب","جلب بيانات الموظفين بناءً على شروط متعددة في جداول مختلفة مثل جدول الموظفين والمشاريع"],"case_study_ar":"استعلام فرعي يرجع أكثر من قيمة فيفشل الاستعلام كله مع =.","case_question_ar":"لماذا؟ وما البديل الصحيح؟","challenge_ar":"اكتب الاستعلام نفسه مرة بـ subquery ومرة بـ JOIN وقارن الوضوح.","videos":[{"title_ar":"المحاضرة — UNION والاستعلامات الفرعية","url":"https://youtu.be/rcw70wRfw6E","description_ar":null}],"resources":[{"label":"SQL Tutorial — W3Schools","url":"https://www.w3schools.com/sql/","kind":"website"},{"label":"Relational databases — Microsoft Learn","url":"https://learn.microsoft.com/sql/relational-databases/databases/databases","kind":"website"}],"assignment":{"title_ar":"تكليف: UNION والاستعلامات الفرعية","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_DB_L09_UNIONSubqueries\n\nالمطلوب:\n1️⃣ اعرض أسماء الأعضاء والموظفين في قائمة واحدة بـ UNION.\n2️⃣ اكتب استعلاماً فرعياً بـ IN، وآخر بـ ALL أو ANY.\n3️⃣ اعرض اسم القسم الذي يضم الموظف صاحب أعلى راتب.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"الربط Joins وEXISTS","title_en":"Joins & EXISTS","kind":"video","summary_ar":"يقدم هذا الفيديو شرحاً وافياً حول أساسيات قواعد البيانات، مع التركيز بشكل خاص على عمليات الربط (Joins) وكيفية استرجاع البيانات من جداول متعددة.","outcomes_ar":["عملية الربط (Joins) — أوضح الفيديو أن الربط ضروري عندما نحتاج لعرض بيانات من أكثر من جدول في استعلام واحد، وذلك على عكس الاستعلامات الفرعية (Subqueries) التي تُستخدم لجلب بيانات من جدول واحد","المنتج الديكارتي (Cartesian Product) — شرح المحاضر أن عملية الربط تبدأ بضرب الجدولين في بعضهما لتكوين جميع الاحتمالات الممكنة، ثم يتم استخدام شروط التصفية (Filtering) لاستبعاد النتائج غير الصحيحة","الربط الداخلي (Inner Join) — يجلب فقط السجلات التي لها مقابل في الجدولين","الربط الخارجي (Outer Join) — يشمل الربط اليساري (Left Join)، واليميني (Right Join)، والكامل (Full Join)، وهي تُستخدم لجلب السجلات حتى في حال عدم وجود مقابل لها في الجدول الآخر","الربط الذاتي (Recursive Relationship) — ناقش الفيديو كيفية التعامل مع العلاقات المتداخلة داخل نفس الجدول، مثل ربط الموظف بمديره المباشر","التحقق من الوجود (Exists) — تم شرح استخدام عامل `EXISTS` مع الاستعلامات الفرعية للتحقق من وجود سجلات مطابقة، موضحاً الفروق في الأداء مقارنة بطرق الربط التقليدية","يؤكد الفيديو على أهمية اختيار الأداة المناسبة (Join vs Subquery) بناءً على طبيعة البيانات المطلوبة واعتبارات الأداء"],"case_study_ar":"تقرير «كل الكتب» يُظهر الكتب المستعارة فقط.","case_question_ar":"أي نوع ربط استُخدم خطأً؟ وما الصحيح؟","challenge_ar":"اكتب تقريراً بعدد مرات استعارة كل كتاب بما فيها الكتب التي لم تُستعر (صفر).","videos":[{"title_ar":"المحاضرة — الربط Joins وEXISTS","url":"https://youtu.be/wRF7Kl9eeeI","description_ar":null}],"resources":[{"label":"SQL Tutorial — W3Schools","url":"https://www.w3schools.com/sql/","kind":"website"},{"label":"Relational databases — Microsoft Learn","url":"https://learn.microsoft.com/sql/relational-databases/databases/databases","kind":"website"}],"assignment":{"title_ar":"تكليف: الربط Joins وEXISTS","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_DB_L10_JoinsEXISTS\n\nالمطلوب:\n1️⃣ اعرض الاستعارات مع اسم العضو وعنوان الكتاب بـ INNER JOIN.\n2️⃣ اعرض كل الكتب حتى غير المستعارة بـ LEFT JOIN.\n3️⃣ نفّذ Self Join لعرض الموظف ومديره، واستخدم EXISTS لإيجاد أعضاء بلا استعارات.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"التطبيع Normalization","title_en":"Normalization: 1NF, 2NF & 3NF","kind":"video","summary_ar":"يقدم هذا الفيديو شرحاً مفصلاً لأساسيات قواعد البيانات، مع التركيز بشكل خاص على عملية تطبيع قواعد البيانات (Normalization) وأهميتها في تصميم الجداول.","outcomes_ar":["مفهوم التطبيع (Normalization) — هي عملية إعادة هيكلة وتفكيك الجداول (Decomposition) لتقليل تكرار البيانات وتفادي مشاكل الإدراج، التحديث، والحذف (Anomalies)","الاعتمادية الوظيفية (Functional Dependency) — شرح جوهري لكيفية اعتماد قيمة عمود على عمود آخر (مثل اعتماد الرسوم على نوع النشاط)، وهو الأساس الذي يقوم عليه التطبيع","الصيغة الأولى (1NF) — التأكد من خلو الجدول من القيم المتعددة (Multi-valued attributes) أو المجموعات المتكررة","الصيغة الثانية (2NF) — التخلص من الاعتمادية الجزئية (Partial Dependency)، حيث يجب أن تعتمد الأعمدة غير المفتاحية على كامل المفتاح الأساسي وليس جزءاً منه","الصيغة الثالثة (3NF) — التخلص من الاعتمادية المتعدية (Transitive Dependency)، لضمان عدم وجود علاقة اعتمادية غير مباشرة بين الأعمدة","إدارة المخططات (Schema) — في نهاية الفيديو (بدءاً من 1:06:36)، تم شرح كيفية استخدام المخططات (Schemas) كتقسيم منطقي لتنظيم الجداول داخل قاعدة البيانات لتسهيل إدارتها"],"case_study_ar":"جدول طلبات يكرر عنوان العميل في كل طلب، وتغيّر العنوان فصار مختلفاً بين الطلبات.","case_question_ar":"أي صيغة تطبيع تُخالَف؟ وكيف يبدو التصميم الصحيح؟","challenge_ar":"ابحث متى يُفضَّل عدم التطبيع (Denormalization) واذكر مثالاً.","videos":[{"title_ar":"المحاضرة — التطبيع Normalization","url":"https://youtu.be/HkhLeuM2zoc","description_ar":null}],"resources":[{"label":"SQL Tutorial — W3Schools","url":"https://www.w3schools.com/sql/","kind":"website"},{"label":"Relational databases — Microsoft Learn","url":"https://learn.microsoft.com/sql/relational-databases/databases/databases","kind":"website"}],"assignment":{"title_ar":"تكليف: التطبيع Normalization","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_DB_L11_Normalization1NF2NF\n\nالمطلوب:\n1️⃣ خذ جدولاً غير مطبّع (فاتورة فيها بيانات العميل والمنتجات في صف واحد).\n2️⃣ حدّد الاعتماديات الوظيفية فيه.\n3️⃣ طبّعه خطوة خطوة إلى 1NF ثم 2NF ثم 3NF مع شرح كل خطوة.\n\n📦 المطلوب تسليمه:\n📁 رابط مجلد Google Drive فيه تقرير PDF باسم TM-DB-L11.pdf\n✅ إجابات المطلوب والمخططات.\n📸 صور واضحة لكل خطوة.","required_evidence":["drive"],"is_required":true}}]}]}$course$::jsonb);

select public.import_course($course${"slug":"sql-server","title_ar":"SQL Server من التصميم إلى ذكاء الأعمال","title_en":"SQL Server: From Design to Business Intelligence","description_ar":"قواعد بيانات عملية على SQL Server: من ERD والتطبيع إلى الاستعلامات المتقدمة والقيود والفهارس والـViews، ثم الدوال والإجراءات المخزنة والمشغلات والمعاملات والنسخ الاحتياطي، وصولاً إلى ذكاء الأعمال: مستودع البيانات وSSIS وSSAS وSSRS.","level":"intermediate","estimated_hours":40,"paths":[],"modules":[{"title_ar":"التصميم والاستعلامات","lessons":[{"title_ar":"مقدمة الدورة وتصميم ERD","title_en":"Course Overview & ERD Design","kind":"video","summary_ar":"يقدم هذا الفيديو مقدمة شاملة لدورة قواعد البيانات (Database). يركز هذا الدرس اليوم الأول بشكل أساسي على أساسيات تصميم قواعد البيانات، بما في ذلك.","outcomes_ar":["مفاهيم التصميم — شرح ماهية قواعد البيانات وكيفية ارتباط الجداول ببعضها","نموذج العلاقة بين الكيانات (ERD) — مقدمة عن كيفية رسم وتصميم الهيكل المفاهيمي للبيانات","مقارنة الأنظمة — مناقشة الفرق بين نظام الملفات التقليدي (File-Based System) ونظم إدارة قواعد البيانات الحديثة (DBMS)، مع توضيح عيوب النظام القديم مثل تكرار البيانات (Redundancy) وعدم التكامل","الأدوار المهنية — توضيح الفرق بين أدوار مصمم قواعد البيانات (Database Designer)، مطور قواعد البيانات (Database Developer)، ومطوري التطبيقات","مكونات الـ ERD — شرح مفصل للكيانات (Entities)، السمات (Attributes) بأنواعها المختلفة، والعلاقات (Relationships) بين الكيانات"],"case_study_ar":"العميل يصف نظامه في صفحتين من الكلام غير المنظم.","case_question_ar":"كيف تستخرج منه الكيانات والعلاقات؟","challenge_ar":"أضف للمخطط تابعي الموظفين (Dependents) ككيان ضعيف.","videos":[{"title_ar":"المحاضرة — مقدمة الدورة وتصميم ERD","url":"https://youtu.be/eYkCO6TDj-E","description_ar":null}],"resources":[{"label":"Transact-SQL reference — Microsoft Learn","url":"https://learn.microsoft.com/sql/t-sql/language-reference","kind":"website"},{"label":"SQL Server Management Studio — Microsoft Learn","url":"https://learn.microsoft.com/sql/ssms/sql-server-management-studio-ssms","kind":"website"}],"assignment":{"title_ar":"تكليف: مقدمة الدورة وتصميم ERD","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_SQLSERVER_L01_CourseOverviewERD\n\nالمطلوب:\n1️⃣ صمّم ERD لنظام شركة: أقسام وموظفون ومشاريع وساعات عمل.\n2️⃣ حدّد الكيانات والسمات والعلاقات ونوع كل علاقة.\n3️⃣ اشرح الفرق بين دور مصمم قاعدة البيانات والمطوّر والـDBA.\n\n📦 المطلوب تسليمه:\n📁 رابط مجلد Google Drive فيه تقرير PDF باسم TM-SQLSERVER-L01.pdf\n✅ إجابات المطلوب والمخططات.\n📸 صور واضحة لكل خطوة.","required_evidence":["drive"],"is_required":true}},{"title_ar":"من ERD إلى SQL Server","title_en":"From ERD to SQL Server","kind":"video","summary_ar":"يقدم هذا الفيديو تعليمياً شاملاً حول قواعد البيانات (Database)، حيث يركز على تحويل المخططات النظرية (ER Diagrams) إلى قواعد بيانات عملية باستخدام SQL Server.","outcomes_ar":["ناقش المحاضر كيفية التعامل مع العلاقات (Relationships) بين الكيانات مثل (Total vs. Partial Participation)","شرح قواعد تحويل المخططات (Mapping Rules) إلى جداول برمجية، بما في ذلك التعامل مع العلاقات الثنائية (Binary)، الثلاثية (Ternary)، والعلاقات الذاتية (Self-relationship)","توضيح كيفية اختيار المفاتيح الأساسية (Primary Keys) والمفاتيح الأجنبية (Foreign Keys) لضمان سلامة البيانات","استعرض كيفية إنشاء قواعد بيانات وجداول باستخدام واجهة المستخدم الرسومية (Wizard) وأكواد SQL","شرح أنواع أوامر SQL الأساسية (DDL للتعريف، DML للتعامل مع البيانات، وDQL للاستعلام عن البيانات)","قدم أمثلة عملية على أوامر مثل `INSERT` و`UPDATE` و`SELECT`، مع التحذير من التعامل بحذر مع أوامر الحذف والتعديل"],"case_study_ar":"زميل أنشأ الجداول يدوياً على جهازه ولا يستطيع نقلها لجهاز آخر.","case_question_ar":"كيف يحل سكريبت القاعدة هذه المشكلة؟","challenge_ar":"أنشئ القاعدة نفسها بالكامل بسكريبت T-SQL دون الواجهة.","videos":[{"title_ar":"المحاضرة — من ERD إلى SQL Server","url":"https://youtu.be/RfVQuZb_DGk","description_ar":null}],"resources":[{"label":"Transact-SQL reference — Microsoft Learn","url":"https://learn.microsoft.com/sql/t-sql/language-reference","kind":"website"},{"label":"SQL Server Management Studio — Microsoft Learn","url":"https://learn.microsoft.com/sql/ssms/sql-server-management-studio-ssms","kind":"website"}],"assignment":{"title_ar":"تكليف: من ERD إلى SQL Server","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_SQLSERVER_L02_FromERDTo\n\nالمطلوب:\n1️⃣ حوّل ERD الشركة إلى قاعدة بيانات في SQL Server بالواجهة الرسومية.\n2️⃣ أنشئ مخطط العلاقات (Database Diagram).\n3️⃣ ولّد سكريبت قاعدة البيانات وارفعه على GitHub.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"Joins والتطبيع","title_en":"Joins & Normalization","kind":"video","summary_ar":"يقدم هذا الفيديو شرحاً مفصلاً ومكثفاً حول موضوعين أساسيين في قواعد البيانات (Database). الاستعلامات المتقدمة (SQL Joins) وعملية التسوية (Normalization).","outcomes_ar":["شرح فكرة الـ Joins — يوضح الفيديو كيفية استخراج البيانات من جداول متعددة في وقت واحد بدلاً من جدول واحد، وكيفية استخدام الـ `JOIN` في جملة `SELECT` أو حتى مع عمليات `DML` (مثل الإضافة والتحديث والحذف)","أنواع الربط — تم استعراض أنواع الربط المختلفة مثل `Inner Join` و`Left/Right Outer Join` و`Full Outer Join`، مع التركيز على فهم العلاقات بين الجداول (Parent/Child) عبر مخططات البيانات (ER Diagram)","الربط الذاتي (Self Join) — شرح كيفية ربط الجدول بنفسه (مثل علاقة الموظف بمديره)","التعامل مع القيم الفارغة (NULL) — استعرض الفيديو دوال مثل `ISNULL` و`COALESCE` للتحكم في كيفية عرض القيم الفارغة","مفهوم التسوية — هي عملية إعادة هيكلة الجداول لتقليل تكرار البيانات (Redundancy) وتجنب مشاكل التحديث والحذف والإضافة (DML Anomalies)","النموذج الأول (1NF) — التخلص من القيم المتعددة (Multi-valued) والمجموعات المتكررة","النموذج الثاني (2NF) — التخلص من التبعية الجزئية (Partial Dependency) بحيث تعتمد كل الأعمدة على المفتاح الأساسي بالكامل","النموذج الثالث (3NF) — التخلص من التبعية المتعدية (Transitive Dependency) عن طريق فصل الأعمدة التي تعتمد على أعمدة غير مفتاحية","التبعية الوظيفية (Functional Dependency) — شرح كيفية تحديد العلاقات بين الأعمدة (Full, Partial, Transitive) كخطوة أساسية قبل تطبيق قواعد التسوية"],"case_study_ar":"تقرير الموظفين يُسقط الموظفين بلا قسم.","case_question_ar":"كيف تعدّل الربط ليظهروا مع عبارة «بلا قسم»؟","challenge_ar":"اكتب استعلاماً يعرض أسماء المشاريع التي لا يعمل عليها أحد.","videos":[{"title_ar":"المحاضرة — Joins والتطبيع","url":"https://youtu.be/7u4PRP4gC1E","description_ar":null}],"resources":[{"label":"Transact-SQL reference — Microsoft Learn","url":"https://learn.microsoft.com/sql/t-sql/language-reference","kind":"website"},{"label":"SQL Server Management Studio — Microsoft Learn","url":"https://learn.microsoft.com/sql/ssms/sql-server-management-studio-ssms","kind":"website"}],"assignment":{"title_ar":"تكليف: Joins والتطبيع","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_SQLSERVER_L03_JoinsNormalization\n\nالمطلوب:\n1️⃣ نفّذ INNER وLEFT وRIGHT وFULL وSelf Join على قاعدة الشركة.\n2️⃣ تعامل مع NULL بـ ISNULL وCOALESCE.\n3️⃣ طبّع جدول بيانات غير مطبّع حتى 3NF.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"التجميع والاستعلامات الفرعية وEERD","title_en":"Aggregates, Subqueries, UNION & EERD","kind":"video","summary_ar":"هذا الفيديو عبارة عن محاضرة تعليمية شاملة في قواعد البيانات (SQL) قدمها المهندس رامي، وتغطي مجموعة من المواضيع الأساسية والمتقدمة.","outcomes_ar":["الدوال التجميعية (Aggregate Functions) — شرح لكيفية استخدام دوال مثل `COUNT`، `MAX`، `MIN`، و `AVG` لإجراء عمليات حسابية على البيانات","التجميع (Grouping) — استخدام `GROUP BY` لتنظيم البيانات في مجموعات منطقية، مع توضيح كيفية تأثير `WHERE` و `HAVING` على الفلترة (55:17، 01:00:23)","الاستعلامات الفرعية (Subqueries) — كيفية استخدام استعلام داخل استعلام آخر لتحسين دقة النتائج، ومتى يُفضل استخدامها مقارنة بـ `JOIN`","عمليات الدمج (Union) — كيفية دمج نتائج عدة استعلامات عمودياً باستخدام `UNION` و `INTERSECT`","نمذجة البيانات (EERD - Enhanced Entity-Relationship Diagram) — مقدمة حول الوراثة (Inheritance) في تصميم قواعد البيانات، وكيفية بناء علاقات بين الجداول (Super/Sub-entities)، مع شرح مفاهيم مثل `Total/Partial Specialization","دوال النظام والمتفرقات — استعراض بعض الدوال الجاهزة للتعامل مع النصوص والتواريخ ومعلومات النظام","يؤكد المحاضر على أهمية فهم منطق العمل (Business Logic) قبل البدء في كتابة الاستعلامات، ويوضح كيفية استخدام الأدوات المساعدة داخل بيئة العمل لتسهيل كتابة الكود"],"case_study_ar":"المدير يريد الأقسام التي يزيد متوسط رواتبها عن متوسط الشركة.","case_question_ar":"كيف تكتب هذا الاستعلام؟","challenge_ar":"استخدم دوال النظام (GETDATE، DATEDIFF، FORMAT) لحساب مدة خدمة كل موظف.","videos":[{"title_ar":"المحاضرة — التجميع والاستعلامات الفرعية وEERD","url":"https://youtu.be/LLglZEyLRuY","description_ar":null}],"resources":[{"label":"Transact-SQL reference — Microsoft Learn","url":"https://learn.microsoft.com/sql/t-sql/language-reference","kind":"website"},{"label":"SQL Server Management Studio — Microsoft Learn","url":"https://learn.microsoft.com/sql/ssms/sql-server-management-studio-ssms","kind":"website"}],"assignment":{"title_ar":"تكليف: التجميع والاستعلامات الفرعية وEERD","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_SQLSERVER_L04_AggregatesSubqueriesUNION\n\nالمطلوب:\n1️⃣ احسب متوسط الرواتب وعدد الموظفين لكل قسم مع HAVING.\n2️⃣ اكتب استعلاماً فرعياً مرتبطاً (Correlated) واحداً على الأقل.\n3️⃣ ارسم EERD فيه تخصيص (Specialization) لأنواع الموظفين.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"محرك القاعدة والأمان والاستعلامات المتقدمة","title_en":"Database Engine, Security & Advanced Queries","kind":"video","summary_ar":"هذا الفيديو هو خامس محاضرة ضمن كورس متقدم في قواعد البيانات (SQL Server).","outcomes_ar":["إدارة محرك قواعد البيانات (Database Engine) — شرح المحاضر الفرق بين Default Instance و Named Instance عند تثبيت SQL Server، وكيفية الاتصال بالسيرفر","الأمان وصلاحيات الوصول (Security) — تم توضيح الفرق بين Authentication (التحقق من الهوية) و Authorization (الصلاحيات)، وأنواع المصادقة مثل Windows Authentication و SQL Server Authentication، بالإضافة إلى كيفية إعداد Mixed","استخدام السطر البرمجي (Command Line) — كيفية التعامل مع السيرفر عبر CMD بدلاً من الواجهة الرسومية","استخدام `TOP` و `ORDER BY` مع الاستعلامات","وظيفة `NEWID()` لتوليد معرفات فريدة وعشوائية","شرح كيفية تنفيذ الاستعلامات (Execution Order) وترتيب العمليات","إدارة الجداول — شرح استعلام `SELECT INTO` لإنشاء جداول جديدة بناءً على بيانات موجودة، وكيفية فصل البيانات عن الهيكل","دوال التصنيف (Ranking Functions) — شرح مفصل لدوال مثل `ROWNUMBER` و `DENSERANK` وكيفية استخدامها في تقسيم البيانات (Partitioning) للإجابة على أسئلة تحليلية معقدة","أنواع البيانات (Data Types) — استعراض أنواع البيانات في SQL Server (مثل الأرقام، النصوص، والتاريخ والوقت) وكيفية اختيار النوع المناسب لتحسين الأداء"],"case_study_ar":"متدرّب يحتاج قراءة تقارير الرواتب فقط ومُنح صلاحية db_owner.","case_question_ar":"ما الخطر؟ وما أقل صلاحية تكفيه؟","challenge_ar":"اعرض أعلى راتبين في كل قسم باستخدام دوال الترتيب.","videos":[{"title_ar":"المحاضرة — محرك القاعدة والأمان والاستعلامات المتقدمة","url":"https://youtu.be/EKHH7JvGGKs","description_ar":null}],"resources":[{"label":"Transact-SQL reference — Microsoft Learn","url":"https://learn.microsoft.com/sql/t-sql/language-reference","kind":"website"},{"label":"SQL Server Management Studio — Microsoft Learn","url":"https://learn.microsoft.com/sql/ssms/sql-server-management-studio-ssms","kind":"website"}],"assignment":{"title_ar":"تكليف: محرك القاعدة والأمان والاستعلامات المتقدمة","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_SQLSERVER_L05_DatabaseEngineSecurity\n\nالمطلوب:\n1️⃣ أنشئ Login وUser بصلاحيات قراءة فقط على جدول واحد واختبرها.\n2️⃣ نفّذ استعلامات بـ TOP وORDER BY وNEWID.\n3️⃣ استخدم دوال الترتيب ROW_NUMBER وRANK وDENSE_RANK.\n4️⃣ اشرح ترتيب تنفيذ الاستعلام المنطقي.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"القيود والأعمدة المحسوبة ومجموعات الملفات","title_en":"Constraints, Computed Columns & Filegroups","kind":"video","summary_ar":"يقدم هذا الفيديو شرحاً شاملاً وتفصيلياً حول قيود قواعد البيانات (Database Constraints) وكيفية إدارة وتصميم قواعد البيانات في SQL Server.","outcomes_ar":["التمثيل الفيزيائي والمنطقي — شرح الفرق بين الملفات الفيزيائية (MDF و LDF) والمفاهيم المنطقية مثل Filegroups","مجموعات الملفات (Filegroups) — أهمية توزيع البيانات لتقليل الحمل على الملف الرئيسي","خصائص الأعمدة — مناقشة خصائص مثل Identity، القيم الافتراضية (Default Values)، وكيفية التعامل مع القيم الفارغة (NULL) باستخدام دالة `ISNULL`","الأعمدة المحسوبة (Computed Columns) — الفرق بين الأعمدة المحسوبة العادية والمخزنة (Persisted)","Primary Key — لضمان فرادة الصفوف","Unique Constraint — لضمان عدم تكرار القيم في أعمدة معينة","Foreign Key — للربط بين الجداول","Check Constraint — لتطبيق شروط معينة على البيانات","الاسكيما (Schema) — تعريفها كطريقة تنظيمية منطقية للجداول وتسهيل إدارة الصلاحيات","الفرق بين DELETE و TRUNCATE — توضيح أن Delete تسمح بالفلترة وحذف صفوف معينة، بينما Truncate أسرع وتُعيد تعيين قيمة الـ Identity (123:36 - 127:10)"],"case_study_ar":"سعر الفاتورة الإجمالي يُدخل يدوياً ويخطئ أحياناً.","case_question_ar":"كيف يحل العمود المحسوب ذلك؟","challenge_ar":"وثّق الفرق بين التمثيل المنطقي والفيزيائي لقاعدتك.","videos":[{"title_ar":"المحاضرة — القيود والأعمدة المحسوبة ومجموعات الملفات","url":"https://youtu.be/STThcNEOUQg","description_ar":null}],"resources":[{"label":"Transact-SQL reference — Microsoft Learn","url":"https://learn.microsoft.com/sql/t-sql/language-reference","kind":"website"},{"label":"SQL Server Management Studio — Microsoft Learn","url":"https://learn.microsoft.com/sql/ssms/sql-server-management-studio-ssms","kind":"website"}],"assignment":{"title_ar":"تكليف: القيود والأعمدة المحسوبة ومجموعات الملفات","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_SQLSERVER_L06_ConstraintsComputedColumns\n\nالمطلوب:\n1️⃣ أنشئ جدولاً بكل أنواع القيود وعموداً محسوباً.\n2️⃣ أنشئ Filegroup إضافياً وضع عليه جدولاً.\n3️⃣ أنشئ Rule أو Default مخصصاً واستخدمه.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}}]},{"title_ar":"البرمجة داخل SQL Server","lessons":[{"title_ar":"الاستعلامات الديناميكية والمعاملات والدوال","title_en":"Dynamic Queries, Transactions & Functions","kind":"video","summary_ar":"يقدم هذا الفيديو محاضرة تقنية متقدمة في قواعد البيانات (SQL)، حيث يغطي المهندس رامي عدة مواضيع هامة لتطوير مهارات التعامل مع قواعد البيانات.","outcomes_ar":["الاستعلامات الديناميكية (Dynamic Queries) — شرح كيفية استخدام الأمر `EXECUTE` لتحويل النصوص إلى استعلامات برمجية","التحقق من وجود الكائنات (EXISTS) — استخدام جملة `IF EXISTS` للتحقق من وجود الجداول قبل إنشائها، مما يمنع حدوث أخطاء برمجية","المعاملات (Transactions) — توضيح الفرق بين المعاملات الضمنية (Implicit) والصريحة (Explicit) باستخدام `BEGIN TRANSACTION` و `COMMIT` و `ROLLBACK` لضمان سلامة البيانات","دوال النطاق الواحد (Scalar Functions) — التي تعيد قيمة واحدة","دوال الجدول المضمنة (Inline Table Functions) — التي تعيد جدولاً كاملاً","دوال الجدول متعددة العبارات (Multi-Statement Table Functions) — التي تتيح كتابة منطق برمجي معقد داخل الدالة","دوال النافذة (Window Functions) — شرح كيفية استخدام `LAG` و `LEAD` للوصول إلى البيانات في الصفوف السابقة أو اللاحقة"],"case_study_ar":"خُصم المبلغ من الحساب الأول ثم انقطع الاتصال قبل إضافته للثاني.","case_question_ar":"كيف تضمن Transaction ألا يحدث ذلك؟","challenge_ar":"اكتب استعلاماً ديناميكياً آمناً بـ sp_executesql مع معاملات.","videos":[{"title_ar":"المحاضرة — الاستعلامات الديناميكية والمعاملات والدوال","url":"https://youtu.be/7ldUIuU6aaQ","description_ar":null}],"resources":[{"label":"Transact-SQL reference — Microsoft Learn","url":"https://learn.microsoft.com/sql/t-sql/language-reference","kind":"website"},{"label":"SQL Server Management Studio — Microsoft Learn","url":"https://learn.microsoft.com/sql/ssms/sql-server-management-studio-ssms","kind":"website"}],"assignment":{"title_ar":"تكليف: الاستعلامات الديناميكية والمعاملات والدوال","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_SQLSERVER_L07_DynamicQueriesTransactions\n\nالمطلوب:\n1️⃣ نفّذ تحويل رصيد بين حسابين داخل Transaction مع TRY/CATCH وROLLBACK.\n2️⃣ اكتب Scalar Function وInline Table Function وMulti-Statement Function.\n3️⃣ استخدم دوال النافذة (LAG، LEAD، SUM OVER).\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"الفهارس والجداول المؤقتة والـViews وMERGE","title_en":"Indexes, Temp Tables, Pivot, Views & MERGE","kind":"video","summary_ar":"يقدم هذا الفيديو شرحاً مفصلاً لعدة مفاهيم متقدمة في قواعد البيانات باستخدام SQL Server، وذلك ضمن كورس تدريبي.","outcomes_ar":["الفهارس (Indexes) — تم شرح الفرق بين Clustered Index و Non-Clustered Index، وكيفية عملها لتحسين أداء البحث. كما تمت الإشارة إلى أدوات مساعدة مثل SQL Server Profiler و Tuning Advisor لتحديد الأعمدة التي تحتاج إلى فهرسة","الجداول المؤقتة (Temporary Tables) — توضيح لأنواع الجداول المؤقتة (Local و Global) وكيفية استخدامها في الذاكرة","عمليات التجميع والبيفوت (Pivot & Grouping) — شرح دوال مثل Rollup و Cube و Grouping Sets لتلخيص وتحليل البيانات بطرق متقدمة","طرق العرض (Views) — مناقشة أهمية Views في حماية البيانات (Security) وإخفاء تعقيدات الجداول عن المستخدمين، مع التطرق إلى أنواعها مثل Standard View و Partitioned View و Indexed View","جملة الدمج (Merge Statement) — كيفية استخدام Merge للمقارنة بين جدولين وتنفيذ عمليات Insert أو Update بناءً على النتائج"],"case_study_ar":"استعلام بحث بالاسم على مليون صف يأخذ ثواني.","case_question_ar":"أي فهرس يسرّعه؟ وما ثمن الفهارس الكثيرة؟","challenge_ar":"استخدم ROLLUP أو CUBE في تقرير مبيعات.","videos":[{"title_ar":"المحاضرة — الفهارس والجداول المؤقتة والـViews وMERGE","url":"https://youtu.be/bqGmbSDPWp4","description_ar":null}],"resources":[{"label":"Transact-SQL reference — Microsoft Learn","url":"https://learn.microsoft.com/sql/t-sql/language-reference","kind":"website"},{"label":"SQL Server Management Studio — Microsoft Learn","url":"https://learn.microsoft.com/sql/ssms/sql-server-management-studio-ssms","kind":"website"}],"assignment":{"title_ar":"تكليف: الفهارس والجداول المؤقتة والـViews وMERGE","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_SQLSERVER_L08_IndexesTempTables\n\nالمطلوب:\n1️⃣ أنشئ Clustered وNon-Clustered Index وقارن خطة التنفيذ قبل وبعد.\n2️⃣ استخدم جدولاً مؤقتاً ومتغير جدول.\n3️⃣ أنشئ View لتقرير الرواتب ونفّذ PIVOT لعرض الأقسام كأعمدة.\n4️⃣ نفّذ MERGE لمزامنة جدولين.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"الإجراءات المخزنة والمشغلات وXML","title_en":"Stored Procedures, Triggers & XML","kind":"video","summary_ar":"يقدم هذا الفيديو محاضرة تعليمية متقدمة في قواعد البيانات (Database)، حيث يركز على تحسين أداء الاستعلامات (Query Execution) وتطوير تطبيقات احترافية.","outcomes_ar":["يوضح الفيديو كيف تعمل محركات قواعد البيانات عند معالجة الاستعلامات (Parsing, Optimization, Execution Plan)","يشرح أهمية Stored Procedures في تحسين الأداء (Performance)، تقليل ضغط النتورك، وتعزيز الأمان (Security) من خلال إخفاء تفاصيل الجداول عن المستخدم النهائي","يغطي الفيديو كيفية استخدام Triggers ككود تلقائي يستجيب لأحداث معينة (مثل Insert, Update, Delete) على مستوى الجداول","يتم استخدامها في مهام حساسة مثل الأمان (Security) (منع عمليات الحذف غير المصرح بها) والتدقيق (Auditing)","تم شرح الجداول المؤقتة `Inserted` و `Deleted` وكيفية الوصول للبيانات القديمة والجديدة عند إجراء تعديلات","يشرح الفيديو كيفية تحويل البيانات من جداول إلى صيغة XML باستخدام `FOR XML`","كيفية قراءة وتحويل بيانات XML إلى جداول باستخدام `OPENXML`، مع شرح تقني لاستخدام المؤشرات (Handlers/Pointers) لإدارة ذاكرة XML Tree","يؤكد المحاضر أن المحتوى مكثف، وأفضل طريقة للاستيعاب هي تطبيق"],"case_study_ar":"رواتب تتغير دون معرفة من غيّرها ومتى.","case_question_ar":"كيف يحل Trigger التدقيق ذلك؟","challenge_ar":"أضف Instead Of Trigger يمنع حذف الموظفين ويحوّلهم إلى «غير نشط».","videos":[{"title_ar":"المحاضرة — الإجراءات المخزنة والمشغلات وXML","url":"https://youtu.be/twzXc6m7ijM","description_ar":null}],"resources":[{"label":"Transact-SQL reference — Microsoft Learn","url":"https://learn.microsoft.com/sql/t-sql/language-reference","kind":"website"},{"label":"SQL Server Management Studio — Microsoft Learn","url":"https://learn.microsoft.com/sql/ssms/sql-server-management-studio-ssms","kind":"website"}],"assignment":{"title_ar":"تكليف: الإجراءات المخزنة والمشغلات وXML","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_SQLSERVER_L09_StoredProceduresTriggers\n\nالمطلوب:\n1️⃣ اكتب Stored Procedure لإضافة موظف مع التحقق من المدخلات ومعاملات الإخراج.\n2️⃣ أنشئ Trigger يسجّل أي تعديل على الرواتب في جدول تدقيق.\n3️⃣ حوّل نتيجة استعلام إلى XML بـ FOR XML.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"Cursor والنسخ الاحتياطي والجدولة","title_en":"Cursors, Backup & Restore, Jobs & Bulk Insert","kind":"video","summary_ar":"هذا الفيديو عبارة عن محاضرة تقنية متقدمة في قواعد البيانات (Database)، ويغطي مجموعة من المواضيع الأساسية والمتقدمة.","outcomes_ar":["تم شرح مفهوم الكيرسور كطريقة للتعامل مع نتائج الاستعلام (Result Set) صفاً بصف (Row by Row) بدلاً من معالجتها ككتلة واحدة","كما ناقش كيفية استعادة البيانات والتعامل مع الجداول","توضيح كيفية أتمتة المهام (مثل النسخ الاحتياطي) باستخدام خدمة SQL Server Agent لتعمل في أوقات محددة","استعراض طريقة نقل البيانات من ملفات خارجية (مثل ملفات النصوص) إلى الجداول مباشرة باستخدام أمر Bulk Insert","شرح مفهوم السناب شوت كطريقة لأخذ لقطة زمنية لقاعدة البيانات للعودة إليها عند الحاجة","تحدث المحاضر عن كيفية استخدام كود #C داخل SQL Server للاستفادة من مكتبات البرمجة المتقدمة وإضافة أنواع بيانات مخصصة"],"case_study_ar":"حُذفت بيانات اليوم الساعة 3 عصراً وآخر نسخة كاملة من منتصف الليل.","case_question_ar":"أي خطة نسخ تسمح باستعادة البيانات حتى 2:59؟","challenge_ar":"اكتب خطة نسخ احتياطي لشركة صغيرة: الأنواع والتوقيت ومدة الاحتفاظ.","videos":[{"title_ar":"المحاضرة — Cursor والنسخ الاحتياطي والجدولة","url":"https://youtu.be/q9kBZYI59Fg","description_ar":null}],"resources":[{"label":"Transact-SQL reference — Microsoft Learn","url":"https://learn.microsoft.com/sql/t-sql/language-reference","kind":"website"},{"label":"SQL Server Management Studio — Microsoft Learn","url":"https://learn.microsoft.com/sql/ssms/sql-server-management-studio-ssms","kind":"website"}],"assignment":{"title_ar":"تكليف: Cursor والنسخ الاحتياطي والجدولة","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_SQLSERVER_L10_CursorsBackupRestore\n\nالمطلوب:\n1️⃣ نفّذ Full وDifferential وLog Backup ثم استعد القاعدة.\n2️⃣ أنشئ Job في SQL Server Agent للنسخ الاحتياطي اليومي.\n3️⃣ استورد ملف CSV بـ BULK INSERT.\n4️⃣ اكتب Cursor واحداً واشرح لماذا يُفضّل تجنبه عادةً.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}}]},{"title_ar":"ذكاء الأعمال BI","lessons":[{"title_ar":"مدخل ذكاء الأعمال وETL مع SSIS","title_en":"Business Intelligence & ETL with SSIS","kind":"video","summary_ar":"هذا الفيديو عبارة عن محاضرة تعليمية مكثفة حول أساسيات ذكاء الأعمال (Business Intelligence - BI)، ويغطي مجموعة من المفاهيم التقنية والعملية لتجهيز البيانات.","outcomes_ar":["مستودع البيانات (Data Warehouse) — تم شرح الفرق الجوهري بين قواعد البيانات العادية (OLTP) التي تتعامل مع العمليات اليومية، ومستودعات البيانات (OLAP) المخصصة للتحليل","تصميم النماذج (Dimensional Modeling) — التركيز على بناء مخططات النجوم (Star Schema) واستخدام الأبعاد (Dimensions) والمقاييس (Measures) بدلاً من المخططات التقليدية (ERD)","مستوى التفصيل (Granularity) — توضيح أهمية تحديد مستوى تفصيل البيانات (مثل يومي، شهري، أو سنوي) وكيف يؤثر ذلك على كفاءة التحليل","تدفق التحكم (Control Flow) — تم توضيح كيفية استخدام أدوات مثل SSIS للتحكم في مهام مثل النسخ الاحتياطي، وإدارة الملفات، وتنفيذ الأكواد (مثل C#)","تدفق البيانات (Data Flow) — شرح كيفية تحويل البيانات، مثل استخدام Conditional Split لتقسيم البيانات بناءً على شروط معينة، أو Data Conversion لتغيير أنواع البيانات","التعامل مع الأخطاء — تم مناقشة كيفية التعامل مع الأخطاء وإدارة الأحداث داخل حزم البيانات (Packages)","تؤكد المحاضرة أن الهدف من BI ليس مجرد تخزين البيانات، بل تحويلها إلى معلومات قيمة من خلال عمليات منظمة (ETL) تضمن دقة البيانات وسرعة استرجاعها للتحليل المستقبلي واتخاذ القرارات"],"case_study_ar":"المدير يريد تقارير مبيعات سريعة، والاستعلامات على قاعدة التشغيل تبطئ النظام.","case_question_ar":"لماذا نحتاج مستودع بيانات منفصلاً؟","challenge_ar":"حدد مستوى التفصيل (Granularity) المناسب لجدول الحقائق واشرح سببك.","videos":[{"title_ar":"المحاضرة — مدخل ذكاء الأعمال وETL مع SSIS","url":"https://youtu.be/9Oj3ccVcsKo","description_ar":null}],"resources":[{"label":"Transact-SQL reference — Microsoft Learn","url":"https://learn.microsoft.com/sql/t-sql/language-reference","kind":"website"},{"label":"SQL Server Management Studio — Microsoft Learn","url":"https://learn.microsoft.com/sql/ssms/sql-server-management-studio-ssms","kind":"website"}],"assignment":{"title_ar":"تكليف: مدخل ذكاء الأعمال وETL مع SSIS","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_SQLSERVER_L11_BusinessIntelligenceETL\n\nالمطلوب:\n1️⃣ صمّم Star Schema لمبيعات: جدول حقائق وأبعاد الزمن والمنتج والعميل.\n2️⃣ ابنِ حزمة SSIS تنقل بيانات من ملف وقاعدة إلى مستودع البيانات.\n3️⃣ أضف معالجة للأخطاء في Data Flow.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"مستودع البيانات وخدمات التحليل SSAS","title_en":"Data Warehouse & Analysis Services (SSAS)","kind":"video","summary_ar":"هذا الفيديو هو الجزء الثاني من سلسلة تعليمية حول ذكاء الأعمال (BI)، ويركز بشكل أساسي على كيفية بناء وإدارة مخزن البيانات (Data Warehouse) واستخدام خدمات التحليل (Analysis Services).","outcomes_ar":["مراحل تجهيز البيانات — شرح أهمية عمليات الـ ETL (الاستخراج، التحويل، والتحميل) لتحسين جودة البيانات ودمج المصادر المختلفة","مفهوم مخزن البيانات (Data Warehouse) — توضيح الفرق بين قواعد البيانات التقليدية (OLTP) ومخازن البيانات، مع التركيز على الخصائص الخمس للمخزن: (Subject-oriented, Integrated, Time-variant, Non-volatile, De-normalized)","هيكلية البيانات — مناقشة نماذج التصميم مثل Star Schema و Snowflake Schema و Galaxy Schema","خدمات التحليل (Analysis Services) — شرح كيفية إنشاء المكعبات (Cubes)، وإجراء عمليات الـ Roll-up و Drill-down لتحليل البيانات بعمق","أنواع المعالجة (OLAP) — الفرق بين MOLAP (تخزين البيانات والمجاميع)، ROLAP (بنية فقط)، و HOLAP (هجين)","أدوات العرض — كيفية إنشاء لوحات التحكم (Dashboards) واستخدام مؤشرات الأداء الرئيسية (KPIs) لعرض البيانات بشكل مرئي وفعال و","الاستعلام — مقدمة حول لغة MDX لاستخراج البيانات من المكعبات بدلاً من SQL التقليدية"],"case_study_ar":"فريق المبيعات يريد تحليل المبيعات حسب السنة ثم الربع ثم الشهر بسرعة.","case_question_ar":"كيف يخدم التسلسل الهرمي في الـCube ذلك؟","challenge_ar":"اكتب استعلام MDX بسيطاً على الـCube.","videos":[{"title_ar":"المحاضرة — مستودع البيانات وخدمات التحليل SSAS","url":"https://youtu.be/ZMQkMIfqZx0","description_ar":null}],"resources":[{"label":"Transact-SQL reference — Microsoft Learn","url":"https://learn.microsoft.com/sql/t-sql/language-reference","kind":"website"},{"label":"SQL Server Management Studio — Microsoft Learn","url":"https://learn.microsoft.com/sql/ssms/sql-server-management-studio-ssms","kind":"website"}],"assignment":{"title_ar":"تكليف: مستودع البيانات وخدمات التحليل SSAS","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_SQLSERVER_L12_DataWarehouseAnalysis\n\nالمطلوب:\n1️⃣ ابنِ Cube في SSAS على مستودع المبيعات.\n2️⃣ عرّف المقاييس (Measures) والأبعاد والتسلسلات الهرمية.\n3️⃣ استعرض الـCube في Excel بجدول محوري.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"خدمات التقارير SSRS","title_en":"Reporting Services (SSRS)","kind":"video","summary_ar":"هذا الفيديو عبارة عن محاضرة عملية تغطي الجانب الثالث من دورة ذكاء الأعمال (BI) وهو خدمات التقارير (SSRS). التعامل مع مصادر البيانات، ونشر التقارير على خادم الويب.","outcomes_ar":["مقدمة في SSRS — يوضح المحاضر أن هذه الأداة هي المسؤولة عن مرحلة عرض التقارير (Reporting) في دورة حياة الـ BI، وتدعم الاتصال بمصادر بيانات متنوعة","تصميم التقارير — شرح أنواع التقارير (جدولية، مصفوفة، ورسوم بيانية) وكيفية سحب البيانات وتنسيقها","استخدام الرسوم البيانية — إضافة أدوات بصرية مثل الرسوم البيانية، المؤشرات (Indicators)، والـ Sparklines لتمثيل البيانات بفعالية","التعامل مع الباراميترات (Parameters) — شرح كيفية جعل التقارير تفاعلية، مثل إنشاء قوائم منسدلة تعتمد على بيانات من قاعدة البيانات، والربط بين التقارير (Drill-through)","نشر التقارير (Deployment) — يوضح المحاضر العملية التقنية لنشر التقارير على خادم الويب (Report Server) وكيفية ارتباط الأداة بقواعد بيانات النظام الأساسية لتخزين التقارير وعرضها عبر متصفح الويب","الجانب التطبيقي — يتضمن الفيديو خطوات برمجية بسيطة لربط التقارير بتطبيقات خارجية (مثل Windows Forms) عبر استخدام مكتبات معينة"],"case_study_ar":"كل مدير منطقة يريد التقرير نفسه لكن لمنطقته فقط.","case_question_ar":"كيف تحقق ذلك بتقرير واحد؟","challenge_ar":"أضف Drill-down من الإجمالي إلى تفاصيل الفواتير.","videos":[{"title_ar":"المحاضرة — خدمات التقارير SSRS","url":"https://youtu.be/rGwP6yRo3Hk","description_ar":null}],"resources":[{"label":"Transact-SQL reference — Microsoft Learn","url":"https://learn.microsoft.com/sql/t-sql/language-reference","kind":"website"},{"label":"SQL Server Management Studio — Microsoft Learn","url":"https://learn.microsoft.com/sql/ssms/sql-server-management-studio-ssms","kind":"website"}],"assignment":{"title_ar":"تكليف: خدمات التقارير SSRS","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_SQLSERVER_L13_ReportingServicesSSRS\n\nالمطلوب:\n1️⃣ صمّم تقريراً في SSRS بجدول ورسم بياني.\n2️⃣ أضف Parameters للتصفية حسب السنة والمنطقة.\n3️⃣ انشر التقرير على خادم التقارير.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}}]}]}$course$::jsonb);

select public.import_course($course${"slug":"design-patterns","title_ar":"أنماط التصميم ومبادئ SOLID","title_en":"Design Patterns & SOLID","description_ar":"لماذا نحتاج أنماط التصميم، ومشكلات الوراثة ومتى نفضّل التكوين، ومبادئ SOLID الخمسة، ثم الأنماط الإنشائية (Singleton وFactory وAbstract Factory وBuilder) والهيكلية (Adapter وBridge وComposite وDecorator وRepository).","level":"intermediate","estimated_hours":15,"paths":[],"modules":[{"title_ar":"المبادئ","lessons":[{"title_ar":"مدخل إلى أنماط التصميم وتصنيفاتها","title_en":"Introduction to Design Patterns","kind":"video","summary_ar":"هذا الفيديو هو الجزء الأول من دورة تدريبية حول أنماط التصميم (Design Patterns) يقدمها المهندس أحمد ممدوح. يهدف الكورس إلى شرح أهمية هذه الأنماط وكيفية استخدامها لحل مشكلات البرمجة المتكررة.","outcomes_ar":["مفهوم أنماط التصميم — تم توضيح أن أنماط التصميم ليست مجرد حلول برمجية جاهزة (كود)، بل هي قوالب فكرية أو استراتيجيات لحل المشاكل الهيكلية المتكررة في بناء التطبيقات","أسباب تعلمها — تساعد المطورين على كتابة كود قابل لإعادة الاستخدام (Code Reusability)، وسهل التوسع (Extensibility)، وتوفر لغة مشتركة بين فريق العمل","الأنماط الإنشاءية (Creational Patterns) — تتعلق بكيفية إنشاء الكائنات","الأنماط الهيكلية (Structural Patterns) — تتعلق بهيكلة الكلاسات والعلاقات بينها","الأنماط السلوكية (Behavioral Patterns) — تتعلق بكيفية تواصل الكلاسات وتصرفاتها","تغليف ما يتغير (Encapsulate what varies) — عزل الأجزاء التي قد تتغير في الكود","البرمجة مقابل الواجهات (Program to an Interface, not an Implementation): لتقليل الارتباط الوثيق (Tight Coupling) بين الكلاسات","تفضيل التكوين على الوراثة (Composition over Inheritance) — توضيح متى يكون استخدام الـ Composition أفضل لبناء مرن"],"case_study_ar":"كل مرة يضيف الفريق طريقة دفع جديدة يعدّل نفس الدالة الضخمة بشرط if جديد.","case_question_ar":"أي مبدأ يُخالَف؟ وكيف تعيد تصميمه؟","challenge_ar":"اكتب فقرة: متى يكون استخدام نمط تصميم مبالغة (Over-engineering)؟","videos":[{"title_ar":"المحاضرة — مدخل إلى أنماط التصميم وتصنيفاتها","url":"https://youtu.be/jcqHtFr8UMo","description_ar":null}],"resources":[{"label":"Design Patterns — Refactoring.Guru","url":"https://refactoring.guru/design-patterns","kind":"website"},{"label":"SOLID principles — Microsoft Learn","url":"https://learn.microsoft.com/dotnet/architecture/modern-web-apps-azure/architectural-principles","kind":"website"}],"assignment":{"title_ar":"تكليف: مدخل إلى أنماط التصميم وتصنيفاتها","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_PATTERNS_L01_IntroductionToDesign\n\nالمطلوب:\n1️⃣ اكتب جدولاً بالتصنيفات الثلاثة (إنشائية، هيكلية، سلوكية) ومثالين لكل تصنيف من مشاريع حقيقية.\n2️⃣ خذ كوداً قديماً لك وحدّد فيه جزءاً «يتغير كثيراً» واعزله خلف واجهة (Encapsulate what varies).\n3️⃣ ارفع الكود قبل وبعد مع شرح التغيير.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"الوراثة مقابل التكوين ومبدأي SRP وOCP","title_en":"Inheritance vs Composition, SRP & OCP","kind":"video","summary_ar":"يشرح هذا الدرس مشكلات الوراثة ولماذا يُفضَّل التكوين (Composition) في كثير من الحالات، ثم مبدأ المسؤولية الواحدة ومبدأ المفتوح والمغلق من مبادئ SOLID بأمثلة عملية.","outcomes_ar":["مشاكل الوراثة — يوضح المحاضر أن الوراثة قد تؤدي إلى مشاكل مثل عدم القدرة على تقليل الواجهة (Interface التي يرثها الابن من الأب)، وتداخل المسؤوليات، وظاهرة \"انفجار الفئات\" (Class Explosion)","التكوين (Composition) — يُفضل كبديل للوراثة لأنه يوفر مرونة أكبر ويقلل من الارتباط الوثيق (Tight Coupling) بين الكلاسات","مبدأ المسؤولية الواحدة (Single Responsibility Principle) — التأكيد على أن الكلاس يجب أن يمتلك مسؤولية واحدة فقط، مع تقديم حلول لاستخدام Events و Delegates للفصل بين الكلاسات وتقليل الارتباط","مبدأ المفتوح والمغلق (Open/Closed Principle) — ضرورة أن تكون البرمجيات مفتوحة للتوسع ومغلقة للتعديل، مع شرح كيفية استخدام Interfaces و Dependency Injection لتحقيق ذلك"],"case_study_ar":"كلاس Report يحسب البيانات ويطبعها ويرسلها بالبريد ويحفظها في ملف.","case_question_ar":"كم سبباً للتغيير لديه؟ وكيف تقسّمه؟","challenge_ar":"اكتب اختبار وحدة (Unit Test) لأحد الكلاسات بعد التقسيم.","videos":[{"title_ar":"المحاضرة — الوراثة مقابل التكوين ومبدأي SRP وOCP","url":"https://youtu.be/MVonWc_gUGY","description_ar":null}],"resources":[{"label":"Design Patterns — Refactoring.Guru","url":"https://refactoring.guru/design-patterns","kind":"website"},{"label":"SOLID principles — Microsoft Learn","url":"https://learn.microsoft.com/dotnet/architecture/modern-web-apps-azure/architectural-principles","kind":"website"}],"assignment":{"title_ar":"تكليف: الوراثة مقابل التكوين ومبدأي SRP وOCP","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_PATTERNS_L02_InheritanceVsComposition\n\nالمطلوب:\n1️⃣ صمّم مثال «بطة» بالوراثة ولاحظ المشكلة عند إضافة بطة مطاطية لا تطير.\n2️⃣ أعد تصميمه بالتكوين (Composition) عبر سلوكيات قابلة للتبديل.\n3️⃣ أعد كتابة كلاس يقوم بثلاث مهام ليصبح ثلاثة كلاسات وفق SRP.\n4️⃣ طبّق OCP بإضافة نوع خصم جديد دون تعديل الكود الموجود.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"LSP وISP وDIP ونمط Singleton","title_en":"LSP, ISP, DIP & the Singleton Pattern","kind":"video","summary_ar":"يقدم هذا الفيديو الذي يقدمه م. أحمد ممدوح شرحاً وافياً لمبادئ SOLID الخاصة بتصميم البرمجيات، مع التركيز بشكل خاص على كيفية تطبيق هذه المبادئ لتحسين جودة الكود واستدامته.","outcomes_ar":["مبدأ ليسكوف للاستبدال (Liskov Substitution Principle) — شرح كيف يمكن استبدال الكائنات من الفئة الأصلية (Parent) بكائنات من الفئات المشتقة (Child) دون التأثير على صحة البرنامج، مع مناقشة التعامل مع الاستثناءات (Exceptions","مبدأ فصل الواجهات (Interface Segregation Principle) — توضيح أهمية تقسيم الواجهات الكبيرة إلى واجهات أصغر وأكثر تخصصاً لضمان عدم اضطرار الكلاسات لتنفيذ وظائف لا تحتاجها","مبدأ انعكاس الاعتمادية (Dependency Inversion Principle) — التأكيد على أن الطبقات عالية المستوى (High-level) لا يجب أن تعتمد على الطبقات منخفضة المستوى (Low-level)، بل يجب أن تعتمد كلتاهما على التجريد (Abstractions) مثل ا","نمط السنجلتون (Singleton Pattern) — شرح كيفية ضمان إنشاء نسخة واحدة فقط من الكلاس في ذاكرة التطبيق، وكيفية التحكم في عملية إنشاء الكائنات باستخدام كلاس السنجلتون","أداء الكلاسات المغلقة (Sealed Classes) — نقاش تقني حول تأثير استخدام `Sealed Classes` على أداء التطبيق عند وقت التشغيل (Runtime) من خلال تقليل عمليات التحقق التي يقوم بها نظام التشغيل"],"case_study_ar":"كلاس OrderService ينشئ SqlRepository بنفسه، ولا يمكن اختباره دون قاعدة بيانات.","case_question_ar":"كيف يحل DIP ذلك؟","challenge_ar":"قارن Singleton بتسجيل الخدمة كـ Singleton في حاوية DI: أيهما أفضل ولماذا؟","videos":[{"title_ar":"المحاضرة — LSP وISP وDIP ونمط Singleton","url":"https://youtu.be/ZRd0UIdJHd4","description_ar":null}],"resources":[{"label":"Design Patterns — Refactoring.Guru","url":"https://refactoring.guru/design-patterns","kind":"website"},{"label":"SOLID principles — Microsoft Learn","url":"https://learn.microsoft.com/dotnet/architecture/modern-web-apps-azure/architectural-principles","kind":"website"}],"assignment":{"title_ar":"تكليف: LSP وISP وDIP ونمط Singleton","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_PATTERNS_L03_LSPISPDIP\n\nالمطلوب:\n1️⃣ اكتب مثالاً يخالف LSP (مثل مربع يرث من مستطيل) ثم صحّحه.\n2️⃣ قسّم واجهة ضخمة إلى واجهات أصغر وفق ISP.\n3️⃣ طبّق DIP بحقن مخزن البيانات عبر واجهة بدل إنشائه داخل الكلاس.\n4️⃣ نفّذ Singleton آمناً مع تعدد الخيوط.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}}]},{"title_ar":"الأنماط","lessons":[{"title_ar":"الأنماط الإنشائية: Factory وAbstract Factory وBuilder","title_en":"Creational Patterns: Factory, Abstract Factory & Builder","kind":"video","summary_ar":"يقدم هذا الفيديو شرحاً مفصلاً لأنماط التصميم البرمجي (Design Patterns) ضمن فئة الأنماط الإنتاجية (Creational Design Patterns)، ويستعرض مجموعة من الأنماط الأساسية التي تساعد في تنظيم عملية إنشاء الكائنات (Objects) في البرمجة.","outcomes_ar":["نمط الطريقة المصنعية (Factory Method) — يهدف إلى إنشاء الكائنات دون تحديد نوع الكلاس بدقة داخل الكود، مما يقلل من الترابط (Coupling) ويزيد من مرونة النظام. يوضح المحاضر كيف أن هذا النمط يغني عن استخدام الكلمات المفتاحية ","نمط المصنع المجرد (Abstract Factory) — يتوسع هذا النمط في الفكرة السابقة ليشمل عائلات من الكائنات المترابطة. يُستخدم عندما يكون لديك تصنيفات (Categories) أو عائلات للمنتجات (مثل أثاث مودرن أو كلاسيك)، حيث يضمن عدم تداخل ","نمط البنّاء (Builder Pattern) — يركز على إنشاء كائنات معقدة تتكون من أجزاء متعددة (مثل بناء منزل بمواصفات اختيارية). يسمح هذا النمط ببناء الكائن خطوة بخطوة وتجنب المشاكل الناتجة عن وجود"],"case_study_ar":"إنشاء كائن Pizza يحتاج مُنشئاً بعشرة معاملات أغلبها اختياري.","case_question_ar":"كيف يجعل Builder الكود أوضح؟","challenge_ar":"أضف نوع إشعار جديد (WhatsApp) دون تعديل أي كلاس موجود.","videos":[{"title_ar":"المحاضرة — الأنماط الإنشائية: Factory وAbstract Factory وBuilder","url":"https://youtu.be/U_AN6vZ53M4","description_ar":null}],"resources":[{"label":"Design Patterns — Refactoring.Guru","url":"https://refactoring.guru/design-patterns","kind":"website"},{"label":"SOLID principles — Microsoft Learn","url":"https://learn.microsoft.com/dotnet/architecture/modern-web-apps-azure/architectural-principles","kind":"website"}],"assignment":{"title_ar":"تكليف: الأنماط الإنشائية: Factory وAbstract Factory وBuilder","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_PATTERNS_L04_CreationalPatternsFactory\n\nالمطلوب:\n1️⃣ نفّذ Factory Method لإنشاء إشعارات (بريد، SMS، Push) حسب النوع.\n2️⃣ نفّذ Abstract Factory لعائلتي واجهة (فاتح وداكن).\n3️⃣ نفّذ Builder لبناء كائن طلب معقد خطوة خطوة.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"الأنماط الهيكلية: Adapter وBridge وComposite وDecorator وRepository","title_en":"Structural Patterns: Adapter, Bridge, Composite, Decorator & Repository","kind":"video","summary_ar":"يقدم هذا الفيديو محاضرة تعليمية للمحاضر أحمد ممدوح حول أنماط التصميم الهيكلي (Structural Design Patterns)، حيث يتناول بالتفصيل المفاهيم الأساسية والأسباب التي تدعو لاستخدام هذه الأنماط في البرمجة لضمان بناء نظام مرن وقابل للتوسع.","outcomes_ar":["نمط المحول (Adapter Pattern) — شرح كيفية استخدامه كطبقة وسيطة (Layer) للربط بين مكتبتين أو فئتين (Classes) لا تفهمان لغة بعضهما البعض","نمط الجسر (Bridge Pattern) — تم استخدامه لفصل الهياكل المعقدة إلى هيكلين منفصلين لتبسيط العلاقات بينهما، خاصة عند وجود أكثر من بُعد (Dimension) للتصنيف","نمط المُكرر (Iterator Pattern) — تم التنويه عنه وكيفية استخدامه في التعامل مع المجموعات (Collections)","نمط المركب (Composite Pattern) — تم شرحه بعمق لتنظيم الكائنات في هيكل شجري (Tree structure)، مما يسمح بالتعامل مع العناصر الفردية والمجموعات (مثل الصناديق التي تحتوي على عناصر) ككائن واحد","نمط المُزخرف (Decorator Pattern) — تم عرضه كطريقة لإضافة ميزات جديدة لكائن موجود بالفعل دون الحاجة لتغيير هيكله الأساسي، مثل إضافة أنواع مختلفة من الإشعارات","نمط المستودع (Repository Pattern) — تمت مناقشة أهميته في فصل منطق الوصول للبيانات عن منطق العمل (Business Logic) مع الإشارة إلى مفهوم وحدة العمل (Unit of Work)"],"case_study_ar":"نظامك يستخدم مزوّد رسائل SMS، والشركة غيّرته لمزود بواجهة مختلفة تماماً.","case_question_ar":"أي نمط يسمح بالتبديل دون تعديل بقية النظام؟","challenge_ar":"اكتب README يلخص كل نمط في سطرين ومتى تستخدمه.","videos":[{"title_ar":"المحاضرة — الأنماط الهيكلية: Adapter وBridge وComposite وDecorator وRepository","url":"https://youtu.be/07HcOQhOx8w","description_ar":null}],"resources":[{"label":"Design Patterns — Refactoring.Guru","url":"https://refactoring.guru/design-patterns","kind":"website"},{"label":"SOLID principles — Microsoft Learn","url":"https://learn.microsoft.com/dotnet/architecture/modern-web-apps-azure/architectural-principles","kind":"website"}],"assignment":{"title_ar":"تكليف: الأنماط الهيكلية: Adapter وBridge وComposite وDecorator وRepository","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_PATTERNS_L05_StructuralPatternsAdapter\n\nالمطلوب:\n1️⃣ نفّذ Adapter يجعل مكتبة دفع خارجية تعمل مع واجهتك.\n2️⃣ نفّذ Decorator يضيف تسجيلاً (Logging) وتخزيناً مؤقتاً لخدمة دون تعديلها.\n3️⃣ نفّذ Composite لشجرة مجلدات وملفات تحسب الحجم الكلي.\n4️⃣ نفّذ Repository لكيان واحد.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}}]}]}$course$::jsonb);

select public.import_course($course${"slug":"clean-code","title_ar":"الكود النظيف","title_en":"Clean Code","description_ar":"كتابة كود يقرؤه الآخرون ويصونونه: أسماء معبّرة، وتجنب الأرقام السحرية، ودوال صغيرة بمعاملات واضحة وبلا آثار جانبية، والتعليقات المفيدة، ومعالجة الأخطاء، وتصميم الكلاسات ومبادئ التصميم.","level":"intermediate","estimated_hours":8,"paths":[],"modules":[{"title_ar":"الكود النظيف","lessons":[{"title_ar":"لماذا الكود النظيف","title_en":"Why Clean Code Matters","kind":"video","summary_ar":"يقدم هذا الفيديو مقدمة شاملة حول مفهوم الكود النظيف (Clean Code) وأهميته للمبرمجين.","outcomes_ar":["أهمية الكود النظيف — الهدف من كتابة كود عالي الجودة ليس مجرد الرفاهية، بل هو ضرورة لضمان كود قابل للقراءة (Readable)، سهل الصيانة (Maintainable)، وقابل للاختبار (Testable)","تقليل الأخطاء (Bugs) — لا يمكن منع ظهور الأخطاء تماماً، لكن الكود النظيف يقلل من احتمالية ظهورها ويجعل اكتشافها وإصلاحها أسهل بكثير","سهولة التعاون — يركز الفيديو على أن الكود يُقرأ من قبل أشخاص آخرين لاحقاً، لذا يجب أن يكون الكود \"يشرح نفسه\" (Self-documenting) من خلال اختيار أسماء معبرة للمتغيرات والدوال بدلاً من الاعتماد المفرط على التعليقات","مبادئ التصميم — تطرق المحاضر إلى أهمية التصميم البرمجي الجيد الذي يسمح بالتوسع (Open-Closed Principle) دون الحاجة لتعديل الكود الأصلي بشكل جذري","الاختبارات — تم التأكيد على ضرورة وجود اختبارات الوحدة (Unit Tests) واختبارات القبول (Acceptance Tests) للتأكد من أن النظام يعمل وفق توقعات العميل","مبدأ السهولة — يُشدد الفيديو على كتابة حلول مباشرة (Straightforward) وتجنب التعقيد غير الضروري في البداية، والتعامل مع حالات الاستثناء (Exceptions) لاحقاً وليس كخطوة أولى"],"case_study_ar":"مطوّر جديد احتاج أسبوعاً ليفهم دالة من 400 سطر قبل أن يعدّل فيها سطراً.","case_question_ar":"ما كلفة الكود غير النظيف على الفريق؟","challenge_ar":"اقرأ فصلاً من Clean Code لـ Robert Martin واكتب أهم ثلاث أفكار.","videos":[{"title_ar":"المحاضرة — لماذا الكود النظيف","url":"https://youtu.be/9QW2b7whhd0","description_ar":null}],"resources":[{"label":"Refactoring — Refactoring.Guru","url":"https://refactoring.guru/refactoring","kind":"website"},{"label":"Code smells — Refactoring.Guru","url":"https://refactoring.guru/refactoring/smells","kind":"website"}],"assignment":{"title_ar":"تكليف: لماذا الكود النظيف","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_CLEANCODE_L01_WhyCleanCode\n\nالمطلوب:\n1️⃣ اختر مشروعاً قديماً لك واكتب قائمة بخمس مشكلات تجعل قراءته صعبة.\n2️⃣ صنّف كل مشكلة: تسمية، طول دالة، تكرار، تعليق مضلل، أو غياب اختبار.\n3️⃣ اقترح إصلاحاً لكل مشكلة.\n\n📦 المطلوب تسليمه:\n📁 رابط مجلد Google Drive فيه تقرير PDF باسم TM-CLEANCODE-L01.pdf\n✅ إجابات المطلوب والمخططات.\n📸 صور واضحة لكل خطوة.","required_evidence":["drive"],"is_required":true}},{"title_ar":"الأسماء والدوال والمعاملات","title_en":"Names, Functions & Parameters","kind":"video","summary_ar":"يقدم هذا الفيديو محاضرة تعليمية حول مفاهيم الكود النظيف (Clean Code)، مع التركيز على كيفية تحسين جودة البرمجيات من خلال تحسين قابلية القراءة والصيانة.","outcomes_ar":["أهمية اختيار أسماء معبرة — يجب أن تعبر أسماء المتغيرات والدوال والكلاسات عن الهدف منها (Intent) بوضوح، مع تجنب الاختصارات الغامضة أو كتابة تعليقات لتفسير أسماء سيئة","تجنب \"الأرقام السحرية\" (Magic Numbers) — يشدد الفيديو على استبدال الأرقام الغامضة في الكود بأسماء ثابتة (Constants) أو تعدادات (Enums) لجعل المعنى واضحاً وتسهيل التعديل مستقبلاً","معايير الدوال — يجب أن تكون الدوال قصيرة (في حدود 20 سطراً تقريباً) وأن تؤدي وظيفة واحدة فقط (Single Responsibility Principle)","معالجة البارامترات — يفضل تقليل عدد بارامترات الدوال. كما ينصح بتجنب الـ Output Parameters والاعتماد على الـ Return Value بدلاً منها","تجنب الـ Flag Arguments — يفضل تقسيم الدوال التي تحتوي على شرط منطقي (مثل Boolean) إلى دالتين منفصلتين بدلاً من استخدام المعامل لتغيير سلوك الدالة","مبدأ المدخل والمخرج الواحد — ينصح بأن يكون لكل دالة مدخل واحد واضح، ويفضل أن يكون لها نقطة خروج (Return) واحدة لزيادة الوضوح","تجنب الآثار الجانبية (Side Effects) — يجب أن تقوم الدالة بما هو مذكور في اسمها فقط دون التأثير بشكل غير متوقع على متغيرات خارجية أو ملفات أو قواعد بيانات"],"case_study_ar":"دالة اسمها process(data, true, 3) ولا أحد يعرف ماذا تعني true و3.","case_question_ar":"كيف تعيد كتابتها لتكون مفهومة دون قراءة جسمها؟","challenge_ar":"ابحث عن دالة لها آثار جانبية مخفية في كودك وأصلحها.","videos":[{"title_ar":"المحاضرة — الأسماء والدوال والمعاملات","url":"https://youtu.be/WmSvIIosvGM","description_ar":null}],"resources":[{"label":"Refactoring — Refactoring.Guru","url":"https://refactoring.guru/refactoring","kind":"website"},{"label":"Code smells — Refactoring.Guru","url":"https://refactoring.guru/refactoring/smells","kind":"website"}],"assignment":{"title_ar":"تكليف: الأسماء والدوال والمعاملات","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_CLEANCODE_L02_NamesFunctionsParameters\n\nالمطلوب:\n1️⃣ أعد تسمية متغيرات ودوال مشروعك بأسماء معبّرة.\n2️⃣ استبدل كل رقم سحري بثابت باسم واضح.\n3️⃣ قسّم دالة طويلة إلى دوال صغيرة تفعل شيئاً واحداً، وأزل الـFlag Arguments.\n4️⃣ ارفع الكود قبل وبعد (commit لكل خطوة).\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"التعليقات ومعالجة الأخطاء وتصميم الكلاسات","title_en":"Comments, Error Handling & Class Design","kind":"video","summary_ar":"يقدم هذا الفيديو درساً عملياً حول مبادئ الكود النظيف (Clean Code)، مع التركيز على تحسين جودة البرمجيات وسهولة قراءتها وصيانتها.","outcomes_ar":["تحسين كتابة الأكواد — يؤكد المحاضر على أهمية اختيار أسماء معبرة للمتغيرات، وتجنب التعقيد في التعبيرات البرمجية، وضرورة تقسيم العمليات الحسابية أو المنطقية المعقدة إلى خطوات أبسط لتعزيز القابلية للقراءة","استخدام التعليقات — يوضح أن الكود الجيد لا يحتاج إلى الكثير من التعليقات. يجب أن تكون التعليقات مفيدة وتوضح \"النية\" خلف الكود فقط إذا لم يكن الكود نفسه قادراً على التعبير عن ذلك بوضوح، مع التحذير من التعليقات الزائدة أو ","معالجة الأخطاء — يوصي باستخدام الاستثناءات (Exceptions) بدلاً من رموز الخطأ (Error Codes) لتنظيم معالجة الأخطاء بشكل مركزي ونظيف","تصميم الفئات (Classes) — يشدد على مبدأ المسؤولية الواحدة (Single Responsibility)، حيث يجب أن يكون لكل فئة سبب واحد للتغيير، مع ترتيب العناصر داخل الفئة (من العامة إلى الخاصة) لسهولة القراءة","مبادئ التصميم — يتطرق إلى أهمية التجريد (Abstraction) في الواجهات (Interfaces)، ومبدأ عدم تكرار الكود (DRY - Don't Repeat Yourself)، وتجنب الشروط المنطقية المعقدة أو السلبية، مع ترشيح أدوات مثل StyleCop و ReSharper للمسا"],"case_study_ar":"تعليق في الكود يقول «يحسب الضريبة 15%» والكود يحسب 16% منذ سنة.","case_question_ar":"لماذا التعليقات المضللة أخطر من غيابها؟","challenge_ar":"شغّل أداة تحليل ثابت (Linter) على مشروعك وأصلح أهم 10 تنبيهات.","videos":[{"title_ar":"المحاضرة — التعليقات ومعالجة الأخطاء وتصميم الكلاسات","url":"https://youtu.be/2pxlf95U3rQ","description_ar":null}],"resources":[{"label":"Refactoring — Refactoring.Guru","url":"https://refactoring.guru/refactoring","kind":"website"},{"label":"Code smells — Refactoring.Guru","url":"https://refactoring.guru/refactoring/smells","kind":"website"}],"assignment":{"title_ar":"تكليف: التعليقات ومعالجة الأخطاء وتصميم الكلاسات","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_CLEANCODE_L03_CommentsErrorHandling\n\nالمطلوب:\n1️⃣ احذف التعليقات التي تكرر ما يقوله الكود، وأبقِ التي تشرح «لماذا».\n2️⃣ استبدل رموز الأخطاء بالاستثناءات مع رسائل واضحة.\n3️⃣ أعد تصميم كلاس كبير إلى كلاسات أصغر متماسكة.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}}]}]}$course$::jsonb);

select public.import_course($course${"slug":"data-structures","title_ar":"هياكل البيانات والخوارزميات","title_en":"Data Structures & Algorithms","description_ar":"تمثيل البيانات في الذاكرة وبناء الهياكل بنفسك: المصفوفات والقوائم المترابطة المزدوجة، والمكدس والطابور، وخوارزميات الترتيب والبحث الثنائي، وأشجار البحث الثنائية، وتحليل التعقيد الزمني بـ Big O.","level":"intermediate","estimated_hours":24,"paths":[{"slug":"software-engineering","required":false}],"modules":[{"title_ar":"الهياكل الخطية","lessons":[{"title_ar":"مقدمة هياكل البيانات والقائمة المترابطة المزدوجة","title_en":"Introduction & the Doubly Linked List","kind":"video","summary_ar":"يركز هذا الدرس على المفاهيم الأساسية وكيفية تمثيل البيانات في الذاكرة.","outcomes_ar":["مقدمة عن هياكل البيانات — ناقشت المحاضرة أهمية اختيار هيكل البيانات المناسب بناءً على طبيعة المشكلة، بدءاً من المتغيرات (Variables) وصولاً إلى المصفوفات (Arrays)","المصفوفات (Arrays) — تم توضيح مميزات المصفوفات (مثل سهولة الوصول للعناصر) وعيوبها (مثل ثبات الحجم)","القوائم المترابطة مزدوجة الاتجاه (Doubly Linked List) — قضى الفيديو جزءاً كبيراً في شرح كيفية بناء Doubly Linked List برمجياً، حيث تحتوي كل عقدة (Node) على بيانات ومؤشرين (Pointers) للسابق واللاحق","التعامل مع الذاكرة (Memory Management) — شرحت المحاضرة كيفية استخدام الكلمة المفتاحية `new` لإنشاء العقد في منطقة Heap بدلاً من Stack لضمان بقائها بعد انتهاء الدالة","عمليات الإضافة والعرض — تم شرح كيفية إضافة عناصر جديدة للقائمة (Add) وكيفية عرض محتويات القائمة (Display) باستخدام مؤشر مؤقت (Pointer) للمرور على جميع العقد"],"case_study_ar":"تطبيق موسيقى يحتاج التنقل للأغنية التالية والسابقة بسرعة.","case_question_ar":"لماذا تناسبه القائمة المزدوجة؟","challenge_ar":"أضف دالة insertAfter تضيف عقدة بعد قيمة معينة.","videos":[{"title_ar":"المحاضرة — مقدمة هياكل البيانات والقائمة المترابطة المزدوجة","url":"https://youtu.be/MrwZYbBWt_4","description_ar":null}],"resources":[{"label":"VisuAlgo — visualising algorithms","url":"https://visualgo.net/en","kind":"website"},{"label":"Big-O Cheat Sheet","url":"https://www.bigocheatsheet.com/","kind":"website"}],"assignment":{"title_ar":"تكليف: مقدمة هياكل البيانات والقائمة المترابطة المزدوجة","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_DS_L01_IntroductionTheDoubly\n\nالمطلوب:\n1️⃣ نفّذ Doubly Linked List بنفسك: إضافة في البداية والنهاية وعرض للأمام والخلف.\n2️⃣ ارسم شكل العقد والمؤشرات في الذاكرة بعد ثلاث إضافات.\n3️⃣ قارن في README بين المصفوفة والقائمة المترابطة في الإضافة والوصول.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"الحذف والبحث في القائمة المترابطة","title_en":"Deleting & Searching in a Linked List","kind":"video","summary_ar":"يكمل هذا الدرس القائمة المترابطة المزدوجة: حذف العقدة الأولى والأخيرة ومن المنتصف، ودالة البحث، مع تمارين عملية مثل عدّ العقد.","outcomes_ar":["حذف العقدة الأولى (الهيد)","حذف العقدة الأخيرة (التيل)","حذف عقدة من المنتصف","دالة البحث (Search Function) — تم بناء دالة للبحث عن البيانات قبل إجراء عملية الحذف، للتأكد من وجود العنصر","التخطيط المنطقي — أكدت المحاضرة على أهمية الرسم والتخطيط قبل كتابة أي كود برمجي، لتجنب الأخطاء في التعامل مع الروابط (Pointers)","كتابة دالة `count` لحساب عدد العقد","دالة `getbyindex` للوصول إلى بيانات عقدة محددة","دالة `insert_after` لإضافة عقدة بعد عقدة أخرى","دالة اختيارية `reverse` لعكس القائمة"],"case_study_ar":"برنامج يتعطل عند حذف آخر عنصر متبقٍ في القائمة.","case_question_ar":"أي حالة حدّية لم تُعالَج؟","challenge_ar":"نفّذ دالة تعكس القائمة في مكانها.","videos":[{"title_ar":"المحاضرة — الحذف والبحث في القائمة المترابطة","url":"https://youtu.be/EQgwjx884Zo","description_ar":null}],"resources":[{"label":"VisuAlgo — visualising algorithms","url":"https://visualgo.net/en","kind":"website"},{"label":"Big-O Cheat Sheet","url":"https://www.bigocheatsheet.com/","kind":"website"}],"assignment":{"title_ar":"تكليف: الحذف والبحث في القائمة المترابطة","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_DS_L02_DeletingSearchingIn\n\nالمطلوب:\n1️⃣ نفّذ حذف العقدة الأولى والأخيرة ومن المنتصف.\n2️⃣ نفّذ دوال search وcount وgetByIndex.\n3️⃣ اختبر الحالات الحدّية: قائمة فارغة، عقدة واحدة.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"المكدس Stack","title_en":"The Stack","kind":"video","summary_ar":"هذا الفيديو عبارة عن محاضرة تعليمية حول هيكلة البيانات (Data Structures)، وتحديداً حول المكدس (Stack).","outcomes_ar":["مراجعة سريعة — استرجاع لمعلومات المحاضرة السابقة حول القوائم المترابطة ثنائية الاتجاه (Doubly Linked Lists) وعمليات الإضافة والحذف","مقدمة عن المكدس (Stack) — شرح مفهوم المكدس الذي يعتمد على مبدأ \"آخر من يدخل هو أول من يخرج\" (LIFO - Last In First Out)","Push — إضافة عنصر جديد إلى المكدس","Pop — حذف العنصر الأخير الذي تمت إضافته","Peek — معاينة العنصر الموجود في أعلى المكدس دون حذفه","استخدام متغير `top` لتتبع مؤشر أعلى عنصر في المكدس","معالجة حالات المكدس الممتلئ (Stack Overflow) والمكدس الفارغ (Stack Underflow)","شرح تقنيات تمرير الباراميترات (Passing by reference) في الدوال لضمان تحديث القيم بشكل صحيح"],"case_study_ar":"زر «تراجع» في محرر نصوص يجب أن يلغي آخر خطوة أولاً.","case_question_ar":"لماذا المكدس هو الهيكل المناسب؟","challenge_ar":"حوّل تعبيراً من Infix إلى Postfix واحسب قيمته.","videos":[{"title_ar":"المحاضرة — المكدس Stack","url":"https://youtu.be/caXSpuvRMe8","description_ar":null}],"resources":[{"label":"VisuAlgo — visualising algorithms","url":"https://visualgo.net/en","kind":"website"},{"label":"Big-O Cheat Sheet","url":"https://www.bigocheatsheet.com/","kind":"website"}],"assignment":{"title_ar":"تكليف: المكدس Stack","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_DS_L03_TheStack\n\nالمطلوب:\n1️⃣ نفّذ Stack بمصفوفة وبقائمة مترابطة: push وpop وpeek وisEmpty.\n2️⃣ استخدمه للتحقق من توازن الأقواس في تعبير رياضي.\n3️⃣ وثّق تعقيد كل عملية.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"المكدس والطابور Queue","title_en":"Stack & Queue","kind":"video","summary_ar":"يقدم هذا الفيديو محاضرة تعليمية ضمن دورة هياكل البيانات (Data Structure)، حيث يركز المحتوى على شرح مفاهيم برمجية أساسية وكيفية تطبيقها عملياً.","outcomes_ar":["هيكل البيانات \"المكدس\" (Stack) — ناقشت المحاضرة منطق عمل المكدس، وتحديداً كيفية ضبط الشروط (Conditions) مثل `Push` و `Pop` داخل مصفوفة (Array)، مع التركيز على أهمية الانتباه لمؤشر `Top` وتجنب الأخطاء البرمجية (مثل تجاوز ","هيكل البيانات \"الطابور\" (Queue) — انتقلت المحاضرة لشرح الطابور الذي يتبع مبدأ الداخل أولاً يخرج أولاً (First In First Out). تم شرح عمليات الإضافة `Enqueue` والحذف `Dequeue` باستخدام مصفوفة مع استخدام مؤشرات `Front` و `Re","تحديات الطابور البرمجي — تم استعراض المشاكل الشائعة عند تطبيق الطابور باستخدام المصفوفات، مثل امتلاء المصفوفة بينما توجد مساحات فارغة نتيجة الحذف، وتم طرح حلول مثل الإزاحة (Shifting) أو استخدام الطابور الدائري (Circular ","تطبيق عملي ولاب — تخلل المحاضرة نقاشات حول كيفية التفكير المنطقي قبل كتابة الكود، وأهمية الرسم لتوضيح الروابط بين العناصر، خاصة عند التعامل مع القوائم المتصلة (Linked Lists) وعمليات الإدراج في المنتصف"],"case_study_ar":"طابور بمصفوفة يقول «ممتلئ» رغم وجود أماكن فارغة في بدايته.","case_question_ar":"كيف يحل الطابور الدائري ذلك؟","challenge_ar":"نفّذ Queue باستخدام مكدسين فقط.","videos":[{"title_ar":"المحاضرة — المكدس والطابور Queue","url":"https://youtu.be/jf7J215TUJE","description_ar":null}],"resources":[{"label":"VisuAlgo — visualising algorithms","url":"https://visualgo.net/en","kind":"website"},{"label":"Big-O Cheat Sheet","url":"https://www.bigocheatsheet.com/","kind":"website"}],"assignment":{"title_ar":"تكليف: المكدس والطابور Queue","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_DS_L04_StackQueue\n\nالمطلوب:\n1️⃣ نفّذ Queue: enqueue وdequeue وpeek.\n2️⃣ نفّذ Circular Queue لحل مشكلة المساحة الضائعة.\n3️⃣ حاكِ طابور طلبات في مطعم باستخدامه.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}}]},{"title_ar":"الترتيب والبحث","lessons":[{"title_ar":"خوارزميات الترتيب وتحسين الأداء","title_en":"Sorting Algorithms & Optimisation","kind":"video","summary_ar":"يركز هذا الدرس على المفاهيم البرمجية المتقدمة.","outcomes_ar":["هياكل البيانات (Data Structures) — تم استعراض كيفية التعامل مع الـ Stack والـ Queue، مع توضيح أن الهدف الأساسي من هذه الهياكل هو إدارة البيانات بترتيب محدد وليس مجرد عرضها","خوارزميات الترتيب (Sorting Algorithms) — شرحت المحاضرة بالتفصيل خوارزمية Bubble Sort، وكيفية عملها من خلال مقارنة العناصر وتبديل أماكنها (Swap) للوصول إلى الترتيب التصاعدي أو التنازلي","تحسين الأداء (Optimization) — ناقشت المحاضرة كيفية تحسين خوارزمية Bubble Sort لتقليل عدد العمليات غير الضرورية في حال كانت البيانات مرتبة بالفعل أو عند وصول العناصر إلى أماكنها الصحيحة","التعامل مع الـ Linked List — تمت مناقشة صعوبات تنفيذ عملية التبديل (Swap) في القوائم المترابطة، واقتراح بدائل مثل الحذف والإضافة (Deletion and Insertion) لتجنب تعقيد إعادة ربط الـ Nodes"],"case_study_ar":"ترتيب قائمة مرتبة أصلاً يأخذ وقت الحالة الأسوأ نفسه.","case_question_ar":"ما التحسين الذي يجعلها O(n) في هذه الحالة؟","challenge_ar":"نفّذ Insertion Sort وقارنه بـ Bubble Sort.","videos":[{"title_ar":"المحاضرة — خوارزميات الترتيب وتحسين الأداء","url":"https://youtu.be/RbHWANrHmHY","description_ar":null}],"resources":[{"label":"VisuAlgo — visualising algorithms","url":"https://visualgo.net/en","kind":"website"},{"label":"Big-O Cheat Sheet","url":"https://www.bigocheatsheet.com/","kind":"website"}],"assignment":{"title_ar":"تكليف: خوارزميات الترتيب وتحسين الأداء","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_DS_L05_SortingAlgorithmsOptimisation\n\nالمطلوب:\n1️⃣ نفّذ Bubble Sort على مصفوفة وعلى قائمة مترابطة.\n2️⃣ أضف تحسين التوقف المبكر عندما لا يحدث تبديل.\n3️⃣ قِس عدد المقارنات قبل التحسين وبعده.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"Bubble Sort وSelection Sort","title_en":"Bubble Sort vs Selection Sort","kind":"video","summary_ar":"يشرح هذا الدرس خوارزميتي الترتيب بالفقاعات والترتيب بالاختيار باستخدام أدوات تصوير الخوارزميات، ويقارن بينهما من حيث الكفاءة وعدد العمليات.","outcomes_ar":["عرضت المحاضرة موقعاً تفاعلياً يساعد الطلاب على رؤية كيفية عمل خوارزميات البيانات بشكل مرئي، مع شرح كيفية التنقل فيه وتطبيق الخطوات","تم التركيز بشكل كبير على شرح منطق خوارزمية Selection Sort، حيث يتم البحث عن أصغر عنصر في مصفوفة غير مرتبة ثم تبديله مع العنصر الأول، وتكرار العملية لباقي المصفوفة","ناقشت المحاضرة بالتفصيل كيفية كتابة الكود البرمجي (Code Implementation) لهذه الخوارزمية، مع تعديلات لتحسين كفاءة التنفيذ وتجنب المقارنات غير الضرورية","تم توضيح أهمية استخدام حلقة تكرار (Nested Loop) للبحث والتبديل","تم عقد مقارنة بين Bubble Sort و Selection Sort من حيث الأداء (Performance) وعدد عمليات التبديل (Swapping)، حيث أشارت المحاضرة إلى أن Selection Sort قد يكون أفضل في بعض الحالات لتقليل عدد عمليات التبديل","تم نقاش إمكانية تحسين الخوارزميات لاكتشاف ما إذا كانت المصفوفة مرتبة بالفعل مسبقاً، وكيف يؤثر ذلك على كفاءة الخوارزمية في حالات معينة"],"case_study_ar":"نظام يكون فيه التبديل (Swap) مكلفاً جداً مقارنة بالمقارنة.","case_question_ar":"أي الخوارزميتين أنسب؟ ولماذا؟","challenge_ar":"نفّذ Merge Sort واشرح لماذا تعقيده O(n log n).","videos":[{"title_ar":"المحاضرة — Bubble Sort وSelection Sort","url":"https://youtu.be/OKJGX6ZysRs","description_ar":null}],"resources":[{"label":"VisuAlgo — visualising algorithms","url":"https://visualgo.net/en","kind":"website"},{"label":"Big-O Cheat Sheet","url":"https://www.bigocheatsheet.com/","kind":"website"}],"assignment":{"title_ar":"تكليف: Bubble Sort وSelection Sort","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_DS_L06_BubbleSortVs\n\nالمطلوب:\n1️⃣ نفّذ Selection Sort.\n2️⃣ استخدم أداة تصوير (مثل VisuAlgo) وتتبع خطوات الخوارزميتين على 8 أرقام.\n3️⃣ قارن عدد المقارنات والتبديلات بينهما في جدول.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"البحث الثنائي Binary Search","title_en":"Binary Search","kind":"video","summary_ar":"يقدم هذا الفيديو شرحاً عملياً لخوارزمية البحث الثنائي (Binary Search) كجزء من دورة هياكل البيانات (Data Structures).","outcomes_ar":["تجربة عملية — بدأت المحاضرة بلعبة تخمين أرقام لتوضيح كيف يمكن لتقسيم البيانات إلى نصفين في كل خطوة أن يختصر وقت البحث مقارنة بالبحث المتسلسل (Sequential Search)","شرط أساسي — أكدت المحاضرة أن خوارزمية البحث الثنائي لا تعمل إلا على بيانات مرتبة (Sorted Data)","تحديد نقطة المنتصف (Mid index) بناءً على البداية (Minimum) والنهاية (Maximum)","مقارنة القيمة المطلوبة بقيمة المنتصف","في حال عدم تطابقها، يتم استبعاد نصف البيانات (سواء الأكبر أو الأصغر) وتكرار العملية على النصف المتبقي","التطبيق البرمجي — تم كتابة الكود الخاص بالخوارزمية باستخدام حلقة `while` لضمان استمرار البحث حتى العثور على العنصر أو التأكد من عدم وجوده، مع توضيح كيفية التعامل مع مؤشرات `Minimum` و `Maximum` لتحديث نطاق البحث"],"case_study_ar":"قاموس إلكتروني فيه 100 ألف كلمة مرتبة أبجدياً.","case_question_ar":"كم خطوة على الأكثر يحتاج البحث الثنائي؟","challenge_ar":"عدّل الخوارزمية لتجد أول ظهور لقيمة مكررة.","videos":[{"title_ar":"المحاضرة — البحث الثنائي Binary Search","url":"https://youtu.be/U2Y9p9pc46c","description_ar":null}],"resources":[{"label":"VisuAlgo — visualising algorithms","url":"https://visualgo.net/en","kind":"website"},{"label":"Big-O Cheat Sheet","url":"https://www.bigocheatsheet.com/","kind":"website"}],"assignment":{"title_ar":"تكليف: البحث الثنائي Binary Search","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_DS_L07_BinarySearch\n\nالمطلوب:\n1️⃣ نفّذ البحث الثنائي بحلقة وبالـRecursion.\n2️⃣ قِس عدد الخطوات للبحث في مليون عنصر مقارنة بالبحث الخطي.\n3️⃣ وضّح لماذا يشترط ترتيب البيانات.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}}]},{"title_ar":"الأشجار والتعقيد","lessons":[{"title_ar":"أشجار البحث الثنائية BST","title_en":"Binary Search Trees","kind":"video","summary_ar":"يقدم هذا الفيديو ضمن كورس هياكل البيانات (Data Structures) شرحاً تفصيلياً لمفهوم الأشجار (Trees)، وتحديداً أشجار البحث الثنائية (Binary Search Trees - BST).","outcomes_ar":["مقدمة عن الأشجار — يوضح الفيديو الفرق بين هياكل البيانات الخطية (Linear) وغير الخطية، حيث تُعد الأشجار هياكل غير خطية تعتمد على علاقة الأب والابن (Parent-Child Relationship)","مفهوم الـ BST — يتم شرح كيفية بناء شجرة بحث ثنائية بحيث تكون القيم في الجهة اليسرى دائماً أقل من العقدة الجذرية (Root)، والقيم في الجهة اليمنى أكبر منها","عملية الإضافة (Insertion) — يشرح الفيديو الخوارزمية الخاصة بإضافة عناصر جديدة للشجرة باستخدام مؤشرات (Pointers) للتنقل، مع التأكيد على كيفية التعامل مع حالة عدم وجود جذر أو إضافة عناصر جديدة في أماكنها الصحيحة","عرض البيانات (Traversal) — يتناول الفيديو طرق استعراض عناصر الشجرة، مع التركيز على طريقة الاستعراض بالترتيب (In-order Traversal - LDR)، والتي تؤدي إلى ترتيب البيانات تصاعدياً","استخدام الـ Recursion — يوضح الفيديو كيفية تطبيق خوارزمية العرض باستخدام الاستدعاء الذاتي (Recursion) للوصول إلى كافة أوراق الشجرة (Leaf nodes)"],"case_study_ar":"إدخال أرقام مرتبة تصاعدياً في BST أنتج شجرة تشبه قائمة.","case_question_ar":"لماذا؟ وما أثره على سرعة البحث؟","challenge_ar":"احسب ارتفاع الشجرة وعدد الأوراق بدالتين.","videos":[{"title_ar":"المحاضرة — أشجار البحث الثنائية BST","url":"https://youtu.be/deue7jmYbsk","description_ar":null}],"resources":[{"label":"VisuAlgo — visualising algorithms","url":"https://visualgo.net/en","kind":"website"},{"label":"Big-O Cheat Sheet","url":"https://www.bigocheatsheet.com/","kind":"website"}],"assignment":{"title_ar":"تكليف: أشجار البحث الثنائية BST","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_DS_L08_BinarySearchTrees\n\nالمطلوب:\n1️⃣ نفّذ BST: إضافة وبحث.\n2️⃣ نفّذ الاستعراض In-order وPre-order وPost-order بالـRecursion.\n3️⃣ ارسم الشجرة الناتجة من إدخال 10 أرقام.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"الحذف من BST وتعقيد Big O","title_en":"BST Deletion & Big O Complexity","kind":"video","summary_ar":"يدور هذا الفيديو حول شرح مفصل لعمليات حذف العقد (Deletion) في شجرة البحث الثنائية (Binary Search Tree - BST)، بالإضافة إلى شرح مفهوم تعقيد الوقت (Time Complexity) ورموز Big O Notation.","outcomes_ar":["حذف الروت (Root) — تم استعراض 4 احتمالات تعتمد على ما إذا كان الروت هو العقدة الوحيدة، أو له ابن واحد (يسار أو يمين)، أو له ابنان","حذف عقدة ليست روت (Non-root node) — تم شرح الحالات الأربع المشابهة لحالة الروت (عقدة ورقة Leaf، أو عقدة لها ابن واحد، أو عقدة لها ابنان)، مع توضيح كيفية إعادة ربط مؤشرات الشجرة للحفاظ على هيكليتها","مفهوم Big O — هو مقياس للعلاقة بين عدد المدخلات (n) والوقت المستغرق لتنفيذ الكود","O(1) — تعقيد ثابت (Constant Time)، مثل عمليات الإضافة في المصفوفة أو القوائم","O(n) — تعقيد خطي (Linear Time)، مثل المرور على جميع عناصر مصفوفة أو قائمة","O(log n) — تعقيد لوغاريتمي، يظهر في خوارزميات مثل البحث الثنائي","O(n²) — تعقيد تربيعي (Quadratic Time)، يظهر غالباً عند استخدام الحلقات المتداخلة (Nested Loops)","ترافرس الشجرة — تم توضيح أن تعقيد وقت المرور في شجرة البحث الثنائية يعتمد على ارتفاع الشجرة (h) وليس فقط عدد العقد (n)"],"case_study_ar":"مقابلة عمل تسألك: لماذا بحث HashMap أسرع من البحث في BST؟","case_question_ar":"كيف تجيب بلغة Big O؟","challenge_ar":"ابحث عن AVL Tree واشرح كيف تمنع الشجرة من أن تصبح قائمة.","videos":[{"title_ar":"المحاضرة — الحذف من BST وتعقيد Big O","url":"https://youtu.be/ARIeLGCKIv4","description_ar":null}],"resources":[{"label":"VisuAlgo — visualising algorithms","url":"https://visualgo.net/en","kind":"website"},{"label":"Big-O Cheat Sheet","url":"https://www.bigocheatsheet.com/","kind":"website"}],"assignment":{"title_ar":"تكليف: الحذف من BST وتعقيد Big O","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_DS_L09_BSTDeletionBig\n\nالمطلوب:\n1️⃣ نفّذ الحذف بحالاته الثلاث: ورقة، ابن واحد، ابنان.\n2️⃣ اكتب جدولاً بتعقيد كل عملية درستها في الدورة.\n3️⃣ صنّف أمثلة من كودك إلى O(1) وO(n) وO(log n) وO(n²).\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}}]}]}$course$::jsonb);

select public.import_course($course${"slug":"operating-systems","title_ar":"أنظمة التشغيل","title_en":"Operating Systems","description_ar":"كيف يعمل الحاسوب من الداخل: تعريف نظام التشغيل وتطوره وأنواعه، والمعالج والمسجلات والمقاطعات والإقلاع، والأقراص والملفات، والحماية والوضع المزدوج، وبنية نظام التشغيل وخدماته، وإدارة العمليات وجدولة المعالج وإدارة الذاكرة.","level":"beginner","estimated_hours":26,"paths":[{"slug":"software-engineering","required":false},{"slug":"sysadmin","required":false}],"modules":[{"title_ar":"المفاهيم الأساسية","lessons":[{"title_ar":"ما نظام التشغيل ولماذا نحتاجه","title_en":"What an Operating System Is","kind":"video","summary_ar":"يقدم هذا الدرس تعريف نظام التشغيل ودوره كوسيط بين التطبيقات والعتاد، ومكونات الحاسب في معمارية فون نيومان، وإدارة الذاكرة ومفهوم النواة (Kernel).","outcomes_ar":["تعريف نظام التشغيل — هو مجموعة من البرامج والمكونات التي تعمل كواجهة (Interface) بين المستخدم/التطبيقات وبين الهاردوير، مما يسهل إدارة الموارد بكفاءة","يعمل كوسيط لتجنب التعامل المباشر مع الهاردوير المعقد (لغة الأصفار والواحدات)","ينظم تنفيذ البرامج ويوزع موارد الجهاز (مثل الذاكرة) بين التطبيقات المختلفة","وحدة المعالجة المركزية (CPU)، الذاكرة (Memory)، وأجهزة الإدخال والإخراج (I/O Devices)","الفرق بين الرام (RAM) التي تخزن البيانات مؤقتاً أثناء عمل البرامج، والروم (ROM) التي تحتوي على تعليمات بدء التشغيل (BIOS)","يتم تخزين نظام التشغيل فعلياً على وحدة تخزين دائمة (مثل الهارد ديسك)، وعند تشغيل الجهاز يتم تحميل الأجزاء الضرورية منه إلى الرام","مفهوم الكيرنال (Kernel) — هو الجزء الأساسي والقلب لنظام التشغيل المسؤول عن إدارة الذاكرة، المعالجات، والموارد، ويتم تحميل الأجزاء الهامة منه فقط لتوفير مساحة في الذاكرة"],"case_study_ar":"شخص يسأل: لماذا لا تعمل التطبيقات مباشرة على العتاد دون نظام تشغيل؟","case_question_ar":"كيف تجيبه في ثلاث نقاط؟","challenge_ar":"قارن بين Windows وLinux وmacOS في إدارة التحديثات والصلاحيات.","videos":[{"title_ar":"المحاضرة — ما نظام التشغيل ولماذا نحتاجه","url":"https://youtu.be/vi2pTXY09DI","description_ar":null}],"resources":[{"label":"Operating Systems: Three Easy Pieces (free book)","url":"https://pages.cs.wisc.edu/~remzi/OSTEP/","kind":"website"}],"assignment":{"title_ar":"تكليف: ما نظام التشغيل ولماذا نحتاجه","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_OS_L01_WhatAnOperating\n\nالمطلوب:\n1️⃣ ارسم معمارية فون نيومان وحدد مكان نظام التشغيل بين العتاد والتطبيقات.\n2️⃣ اشرح دور الـKernel بمثال من جهازك.\n3️⃣ افتح مدير المهام وصوّر استهلاك الذاكرة والمعالج واشرح ما تراه.\n\n📦 المطلوب تسليمه:\n📁 رابط مجلد Google Drive فيه تقرير PDF باسم TM-OS-L01.pdf\n✅ إجابات المطلوب والمخططات.\n📸 صور واضحة لكل خطوة.","required_evidence":["drive"],"is_required":true}},{"title_ar":"تطور أنظمة التشغيل والبرمجة المتعددة","title_en":"The Evolution of OS, Multiprogramming & Time Sharing","kind":"video","summary_ar":"يقدم هذا الفيديو شرحاً مفصلاً لتطور أنظمة التشغيل (Operating Systems) وعلاقتها بتطور العتاد (Hardware).","outcomes_ar":["تطور أنظمة التشغيل — بدأ الفيديو باستعراض أنظمة Mainframe في الخمسينات، حيث كان الجهاز ينفذ برنامجاً واحداً فقط في كل مرة، وكان دور نظام التشغيل يقتصر على التنسيق التلقائي للمهام (Automatic Job Sequencing)","مفهوم البرنامج والعمليات — تم توضيح أن البرامج تتكون من تعليمات برمجية (عمليات حسابية، منطقية، وعمليات إدخال وإخراج)، وعند تشغيل البرنامج يصبح ما يسمى بـ Process أو Job","نظام البرمجة المتعددة (Multiprogramming) — نشأت هذه الفكرة لاستغلال سرعة المعالج (CPU) التي تفوق بكثير سرعة أجهزة الإدخال والإخراج، حيث يتم تحميل أكثر من برنامج في الذاكرة للتبديل بينها عند انتظار أحدها لعملية إدخال/إخرا","نظام مشاركة الوقت (Time Sharing) — هو نظام تفاعلي (Interactive) يعتمد على تقسيم وقت المعالج إلى فترات زمنية قصيرة جداً (Time Slots) لكل برنامج، مما يضمن استجابة النظام للمستخدمين وحل مشكلة تعليق البرامج في حلقات غير منته","انتهاء تنفيذ المهام","طلب عملية إدخال أو إخراج","انتهاء الوقت المخصص للعملية (Time Slot)","حدوث مقاطعة (Interrupt)"],"case_study_ar":"جهاز قديم ينفّذ برنامجاً واحداً، والمعالج ينتظر الطابعة معظم الوقت.","case_question_ar":"كيف حسّنت البرمجة المتعددة استغلال المعالج؟","challenge_ar":"احسب نسبة استغلال المعالج لثلاث عمليات تقضي كل منها 50% من وقتها في الإدخال والإخراج.","videos":[{"title_ar":"المحاضرة — تطور أنظمة التشغيل والبرمجة المتعددة","url":"https://youtu.be/citzDsOcVyo","description_ar":null}],"resources":[{"label":"Operating Systems: Three Easy Pieces (free book)","url":"https://pages.cs.wisc.edu/~remzi/OSTEP/","kind":"website"}],"assignment":{"title_ar":"تكليف: تطور أنظمة التشغيل والبرمجة المتعددة","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_OS_L02_TheEvolutionOf\n\nالمطلوب:\n1️⃣ ارسم خطاً زمنياً لتطور أنظمة التشغيل من الدفعات إلى مشاركة الوقت.\n2️⃣ اشرح الفرق بين البرنامج والعملية.\n3️⃣ عدّد أسباب خروج العملية من المعالج بمثال لكل سبب.\n\n📦 المطلوب تسليمه:\n📁 رابط مجلد Google Drive فيه تقرير PDF باسم TM-OS-L02.pdf\n✅ إجابات المطلوب والمخططات.\n📸 صور واضحة لكل خطوة.","required_evidence":["drive"],"is_required":true}},{"title_ar":"أنواع أنظمة التشغيل وبيئات الحوسبة","title_en":"Types of Systems & Computing Environments","kind":"video","summary_ar":"يقدم هذا الفيديو شرحاً مفصلاً لأنواع أنظمة التشغيل (Operating Systems) وبيئات الحوسبة المختلفة، وذلك كجزء من كورس متخصص.","outcomes_ar":["أنظمة سطح المكتب (Desktop Systems) — الأجهزة الشخصية المعتادة","أنظمة المعالجة المتعددة (Multiprocessor Systems) — وتعرف بالأنظمة المترابطة بإحكام (Tightly Coupled)، حيث تتشارك المعالجات في الذاكرة واللوحة الأم لزيادة الأداء (Throughput)","الأنظمة الموزعة (Distributed Systems) — وتعرف بالأنظمة المترابطة برفق (Loosely Coupled)، حيث تعمل الأجهزة بشكل منفصل وتتواصل عبر الشبكات","أنظمة العناقيد (Clustered Systems) — تسمح لمجموعة من الأنظمة بمشاركة نفس التخزين، وتتميز بكونها متماثلة (Symmetric) أو غير متماثلة (Asymmetric) لضمان توفر الخدمة (Availability)","أنظمة الوقت الحقيقي (Real-Time Systems) — مخصصة للمهام التي تتطلب دقة زمنية صارمة، مثل الأنظمة الطبية والعسكرية","الأنظمة المحمولة (Handheld Systems) — مثل الهواتف والأجهزة اللوحية، والتي تتطلب قيوداً خاصة في استهلاك الطاقة وحجم المعالجات","الحوسبة التقليدية (Traditional Computing) — تعتمد على الخوادم وأجهزة البي سي","الحوسبة المستندة إلى الويب (Web-based Computing) — تعتمد على نموذج العميل والخادم (Client-Server)","الحوسبة المدمجة (Embedded Computing) — أنظمة بسيطة داخل الأجهزة مثل الميكروويف والغسالات"],"case_study_ar":"جهاز تنظيم ضربات القلب يجب أن يستجيب خلال أجزاء من الثانية دائماً.","case_question_ar":"أي نوع نظام تشغيل يحتاج؟ ولماذا؟","challenge_ar":"ابحث عن نظام تشغيل للزمن الحقيقي (RTOS) واذكر أين يُستخدم.","videos":[{"title_ar":"المحاضرة — أنواع أنظمة التشغيل وبيئات الحوسبة","url":"https://youtu.be/pubcKoI-H9g","description_ar":null}],"resources":[{"label":"Operating Systems: Three Easy Pieces (free book)","url":"https://pages.cs.wisc.edu/~remzi/OSTEP/","kind":"website"}],"assignment":{"title_ar":"تكليف: أنواع أنظمة التشغيل وبيئات الحوسبة","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_OS_L03_TypesOfSystems\n\nالمطلوب:\n1️⃣ اكتب جدولاً بأنواع الأنظمة (سطح المكتب، متعدد المعالجات، موزّع، عنقودي، زمن حقيقي، محمول) ومثالاً لكل نوع.\n2️⃣ صنّف خمسة أجهزة حولك حسب نوع نظام تشغيلها.\n3️⃣ اشرح بيئات الحوسبة: التقليدية، العميل والخادم، الند للند، السحابية.\n\n📦 المطلوب تسليمه:\n📁 رابط مجلد Google Drive فيه تقرير PDF باسم TM-OS-L03.pdf\n✅ إجابات المطلوب والمخططات.\n📸 صور واضحة لكل خطوة.","required_evidence":["drive"],"is_required":true}}]},{"title_ar":"العتاد والتشغيل","lessons":[{"title_ar":"مكونات النظام والمقاطعات والإقلاع","title_en":"System Components, Interrupts & Booting","kind":"video","summary_ar":"يقدم هذا الفيديو شرحاً مفصلاً ومبسطاً لمفاهيم نظم التشغيل (Operating Systems)، مع التركيز على كيفية إدارة الكمبيوتر وتفاعل المكونات مع بعضها البعض.","outcomes_ar":["يوضح الفيديو البنية الأساسية للكمبيوتر، مؤكداً أن المكونات (المعالج، الذاكرة، وأجهزة الإدخال والإخراج) لا تتصل ببعضها مباشرة، بل من خلال متحكمات الأجهزة (Device Controllers) والمسارات (Buses)","يتم استخدام الذاكرة المؤقتة (Local Buffer) داخل كل متحكم لتسهيل تبادل البيانات","شرح لدور المسارات الثلاثة — مسار البيانات (Data Bus)، مسار العناوين (Address Bus)، ومسار التحكم (Control Bus) في إدارة نقل المعلومات","تعد المقاطعات جزءاً حيوياً من عمل نظام التشغيل؛ حيث تسمح للأجهزة بإخطار المعالج عند انتهاء مهمة معينة","يتم استخدام جدول المقاطعات (Interrupt Vector) لتوجيه المعالج إلى روتين خدمة المقاطعة (Interrupt Service Routine) المناسب لتنفيذ الكود المطلوب","تم تعريف العملية (Process) بأنها \"برنامج قيد التنفيذ\" (Program in execution)","عند حدوث مقاطعة، يقوم النظام بحفظ حالة العملية الحالية (Context) لضمان استئنافها لاحقاً بشكل صحيح","شرح لمرحلة الإقلاع التي تبدأ ببرنامج البايوز (BIOS) أو UEFI المخزن في الذاكرة الدائمة (ROM)، والذي يقوم بفحص النظام ثم تحميل النواة (Kernel) الخاصة بنظام التشغيل لتبدأ السيطرة على العتاد","تأكيد أن نظام التشغيل يعتمد بشكل أساسي على المقاطعات في إدارة الأجهزة الخارجية، حيث يقوم المتحكم بدور الوسيط بين الجهاز (مثل USB) والذاكرة الرئيسية"],"case_study_ar":"جهاز يتأخر في الاستجابة لأن المعالج يسأل كل جهاز باستمرار «هل لديك بيانات؟».","case_question_ar":"كيف تحل المقاطعات ذلك مقارنة بالاستطلاع (Polling)؟","challenge_ar":"اعرض قائمة المقاطعات في جهازك (Windows: msinfo32، Linux: /proc/interrupts).","videos":[{"title_ar":"المحاضرة — مكونات النظام والمقاطعات والإقلاع","url":"https://youtu.be/YLCHcC66WgQ","description_ar":null}],"resources":[{"label":"Operating Systems: Three Easy Pieces (free book)","url":"https://pages.cs.wisc.edu/~remzi/OSTEP/","kind":"website"}],"assignment":{"title_ar":"تكليف: مكونات النظام والمقاطعات والإقلاع","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_OS_L04_SystemComponentsInterrupts\n\nالمطلوب:\n1️⃣ ارسم المسارات الثلاثة (البيانات والعناوين والتحكم) وما ينقله كل مسار.\n2️⃣ اشرح المقاطعة بمثال ضغط زر في لوحة المفاتيح.\n3️⃣ وثّق خطوات إقلاع جهازك من التشغيل حتى سطح المكتب.\n\n📦 المطلوب تسليمه:\n📁 رابط مجلد Google Drive فيه تقرير PDF باسم TM-OS-L04.pdf\n✅ إجابات المطلوب والمخططات.\n📸 صور واضحة لكل خطوة.","required_evidence":["drive"],"is_required":true}},{"title_ar":"المعالج والمسجلات","title_en":"The CPU & Its Registers","kind":"video","summary_ar":"يركز هذا الدرس على شرح المكونات الأساسية للكمبيوتر (Hardware) وكيفية عمل المعالج (CPU).","outcomes_ar":["مكونات الهاردوير — استعراض وحدات الإدخال والإخراج (مثل الشاشة، الطابعة، والرسام) وأجهزة التخزين","مكونات المعالج (CPU) — شرح تفصيلي للأجزاء الداخلية للمعالج مثل وحدة الحساب والمنطق (ALU) المسؤولة عن العمليات الحسابية والمنطقية، ووحدة التحكم (Control Unit)","برنامج العداد (Program Counter) — لتخزين معلومات معينة","سجل التعليمات (Instruction Register) — لتخزين التعليمات البرمجية","المراكم (Accumulator) وسجل الحالة (Condition Code Register)"],"case_study_ar":"برنامج فيه قفزة (Jump) إلى عنوان آخر.","case_question_ar":"أي سجل يتغير؟ وكيف؟","challenge_ar":"اكتب برنامجاً صغيراً بلغة تجميع في محاكٍ أونلاين واشرح كل سطر.","videos":[{"title_ar":"المحاضرة — المعالج والمسجلات","url":"https://youtu.be/mDdwH059Mh8","description_ar":null}],"resources":[{"label":"Operating Systems: Three Easy Pieces (free book)","url":"https://pages.cs.wisc.edu/~remzi/OSTEP/","kind":"website"}],"assignment":{"title_ar":"تكليف: المعالج والمسجلات","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_OS_L05_TheCPUIts\n\nالمطلوب:\n1️⃣ اشرح دور PC وIR والـAccumulator وسجل الحالة.\n2️⃣ تتبع تنفيذ تعليمة جمع بسيطة خطوة خطوة في دورة Fetch-Decode-Execute.\n3️⃣ ارسم مخططاً لمكونات المعالج.\n\n📦 المطلوب تسليمه:\n📁 رابط مجلد Google Drive فيه تقرير PDF باسم TM-OS-L05.pdf\n✅ إجابات المطلوب والمخططات.\n📸 صور واضحة لكل خطوة.","required_evidence":["drive"],"is_required":true}},{"title_ar":"الإدخال والإخراج وDMA وهرم التخزين","title_en":"I/O, DMA & the Storage Hierarchy","kind":"video","summary_ar":"يركز هذا الدرس على المفاهيم الأساسية التي يحتاجها كل متخصص في علوم الحاسب.","outcomes_ar":["مقدمة عن نظم التشغيل — تم توضيح أهمية نظام التشغيل كوسيط (Interface) بين المستخدم والأجهزة (Hardware)، وكيف يساعد في إدارة الموارد وتشغيل تطبيقات متعددة","عمليات نظام الحاسب — شرح كيفية عمل النظام، دور الـ Interrupts، وعملية بدء التشغيل (Boot Sequence) بدءًا من الـ BIOS ووصولًا إلى تحميل الـ Kernel","إدارة المدخلات والمخرجات — مناقشة الفرق بين العمليات المتزامنة (Synchronous) وغير المتزامنة (Asynchronous)، وكيفية تنظيم إدارة الأجهزة من خلال جداول الحالة (Device Status Tables) وطوابير الانتظار","الوصول المباشر للذاكرة (DMA) — توضيح كيف يساهم الـ DMA في تسريع نقل البيانات بين الأجهزة والذاكرة دون إشغال المعالج (CPU) في كل بايت","هيكلية التخزين والذاكرة — شرح تراتبية أجهزة التخزين من حيث السرعة والمساحة (الريجسترز، الكاش، الرام، والأقراص)، مع توضيح الفرق بين العناوين المنطقية (Logical Addresses) والفيزيائية (Physical Addresses) وكيفية استخدام سجل"],"case_study_ar":"نسخ ملف بحجم 10GB يجعل الجهاز بطيئاً جداً على جهاز قديم بلا DMA.","case_question_ar":"لماذا؟","challenge_ar":"قارن سرعة القراءة لقرص HDD وSSD وذاكرة RAM بأرقام حقيقية.","videos":[{"title_ar":"المحاضرة — الإدخال والإخراج وDMA وهرم التخزين","url":"https://youtu.be/I8xzNo0NIBA","description_ar":null}],"resources":[{"label":"Operating Systems: Three Easy Pieces (free book)","url":"https://pages.cs.wisc.edu/~remzi/OSTEP/","kind":"website"}],"assignment":{"title_ar":"تكليف: الإدخال والإخراج وDMA وهرم التخزين","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_OS_L06_IODMA\n\nالمطلوب:\n1️⃣ اشرح عمليات نظام الحاسب وإدارة الإدخال والإخراج.\n2️⃣ وضّح كيف يقلّل DMA حمل المعالج عند نسخ ملف كبير.\n3️⃣ ارسم هرم التخزين مع السرعة والسعة والتكلفة التقريبية لكل مستوى.\n\n📦 المطلوب تسليمه:\n📁 رابط مجلد Google Drive فيه تقرير PDF باسم TM-OS-L06.pdf\n✅ إجابات المطلوب والمخططات.\n📸 صور واضحة لكل خطوة.","required_evidence":["drive"],"is_required":true}},{"title_ar":"الأقراص والتقسيم ونظام الملفات والإقلاع","title_en":"Disks, Partitioning, File Systems & Boot","kind":"video","summary_ar":"يقدم هذا الفيديو شرحاً مفصلاً ومبسطاً لمفاهيم نظم التشغيل (Operating System) ودورها في إدارة مكونات الحاسوب.","outcomes_ar":["كيفية عمل المعالج (CPU) — شرح لكيفية تنفيذ العمليات الحسابية والمنطقية، بدءاً من جلب البيانات من الذاكرة العشوائية (RAM) مروراً بذاكرة الكاش (Cache) ووصولاً إلى السجلات (Registers) داخل المعالج","شرح مفصل لمكونات الهارد ديسك المغناطيسي (Magnetic Hard Disk) وكيفية عمله ميكانيكياً باستخدام الأسطوانات (Platters) والأذرع","توضيح الفرق بين الهارد التقليدي وأقراص الحالة الصلبة (SSD)","تقسيم القرص (Partitioning) — شرح لمفاهيم تقسيم الهارد إلى أجزاء (Partitions) والفرق بين جدول تقسيم القرص القديم (MBR) والحديث (GPT)","نظام الملفات (File System) — توضيح كيفية إدارة الملفات، وما يحدث فعلياً عند حذف البيانات أو إجراء عملية التنسيق (Format)، وكيفية استعادة البيانات المحذوفة","عملية إقلاع الجهاز (Boot Process) — نبذة عن دور MBR و Bootloader في بدء تشغيل نظام التشغيل"],"case_study_ar":"فلاشة لا تقبل نسخ ملف بحجم 5GB رغم وجود مساحة كافية.","case_question_ar":"ما السبب؟ وما الحل؟","challenge_ar":"جهّز فلاشة إقلاع لنظام Linux ووثّق الخطوات.","videos":[{"title_ar":"المحاضرة — الأقراص والتقسيم ونظام الملفات والإقلاع","url":"https://youtu.be/klyIroqf3Jo","description_ar":null}],"resources":[{"label":"Operating Systems: Three Easy Pieces (free book)","url":"https://pages.cs.wisc.edu/~remzi/OSTEP/","kind":"website"}],"assignment":{"title_ar":"تكليف: الأقراص والتقسيم ونظام الملفات والإقلاع","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_OS_L07_DisksPartitioningFile\n\nالمطلوب:\n1️⃣ اشرح الفرق بين HDD وSSD.\n2️⃣ اعرض أقسام قرصك ونوع نظام ملفات كل قسم.\n3️⃣ قارن NTFS وFAT32 وext4 في جدول.\n4️⃣ اشرح الفرق بين MBR وGPT.\n\n📦 المطلوب تسليمه:\n📁 رابط مجلد Google Drive فيه تقرير PDF باسم TM-OS-L07.pdf\n✅ إجابات المطلوب والمخططات.\n📸 صور واضحة لكل خطوة.","required_evidence":["drive"],"is_required":true}},{"title_ar":"الحماية والوضع المزدوج","title_en":"Protection & Dual Mode","kind":"video","summary_ar":"يقدم هذا الفيديو شرحاً مفصلاً ومبسطاً لدور نظام التشغيل (Operating System) في حماية موارد الكمبيوتر وإدارتها، مع التركيز على أهمية الحماية الهاردوير لضمان استقرار النظام عند تشغيل تطبيقات متعددة في نفس الوقت.","outcomes_ar":["حماية الإدخال والإخراج (I/O Protection) — لا يُسمح للتطبيقات بالوصول المباشر إلى الأجهزة (مثل الأقراص المدمجة أو الشاشة)، بل يجب أن تتم جميع الطلبات عبر نظام التشغيل باستخدام System Calls","نمط التشغيل المزدوج (Dual Mode) — يتم التمييز بين User Mode و Monitor Mode لحماية النظام من التعليمات غير القانونية، حيث يتم استخدام بت (bit) معينة لتحديد وضع التشغيل الحالي","حماية المعالج (CPU Protection) — لمنع التطبيقات من الدخول في حلقات لا نهائية (Infinite Loops) والاستحواذ على المعالج، تم إدخال مفهوم المؤقت (Timer) الذي يقطع عمل التطبيق بعد فترة زمنية محددة (Time Sharing) و","حماية الذاكرة (Memory Protection) — يتم استخدام مسجلي القاعدة (Base Register) و الحد (Limit Register) للتأكد من أن كل تطبيق يعمل فقط داخل المساحة المخصصة له في الذاكرة، ويقوم جهاز Memory Management Unit (MMU) بالتحقق من ","تطرق الفيديو أيضاً إلى الفرق بين الهارد ديسك (الوصول العشوائي) و الأشرطة المغناطيسية (الوصول التسلسلي) واستخداماتها خاصة في النسخ الاحتياطي"],"case_study_ar":"برنامج فيه حلقة لا نهائية لكن بقية البرامج ما زالت تعمل.","case_question_ar":"أي آلية حماية منعت سيطرته على المعالج؟","challenge_ar":"ابحث ما هي System Call واذكر ثلاثة أمثلة.","videos":[{"title_ar":"المحاضرة — الحماية والوضع المزدوج","url":"https://youtu.be/MiuzUF1kOQA","description_ar":null}],"resources":[{"label":"Operating Systems: Three Easy Pieces (free book)","url":"https://pages.cs.wisc.edu/~remzi/OSTEP/","kind":"website"}],"assignment":{"title_ar":"تكليف: الحماية والوضع المزدوج","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_OS_L08_ProtectionDualMode\n\nالمطلوب:\n1️⃣ اشرح الوضع المزدوج (User/Kernel) ولماذا يحتاجه النظام.\n2️⃣ وضّح حماية الإدخال والإخراج والمعالج والذاكرة بمثال لكل منها.\n3️⃣ اشرح دور المؤقّت (Timer) في حماية المعالج.\n\n📦 المطلوب تسليمه:\n📁 رابط مجلد Google Drive فيه تقرير PDF باسم TM-OS-L08.pdf\n✅ إجابات المطلوب والمخططات.\n📸 صور واضحة لكل خطوة.","required_evidence":["drive"],"is_required":true}}]},{"title_ar":"العمليات والذاكرة","lessons":[{"title_ar":"بنية نظام التشغيل وخدماته","title_en":"Operating System Structure & Services","kind":"video","summary_ar":"يقدم هذا الفيديو شرحًا تعليميًا حول هيكلية أنظمة التشغيل (Operating System Structure)، ويركز على المكونات الأساسية والخدمات التي يوفرها نظام التشغيل لإدارة موارد الحاسوب.","outcomes_ar":["إدارة العمليات (Process Management) — المسؤول عن إنشاء العمليات وحذفها وإدارتها","إدارة الذاكرة (Memory Management) — تتبع الأجزاء المستخدمة والفارغة في الذاكرة وتخصيصها للعمليات","إدارة الملفات (File Management) — تنظيم الملفات والمجلدات وتسهيل الوصول إليها","إدارة التخزين الثانوي (Secondary Storage Management) — التعامل مع الأقراص الصلبة وتخزين البيانات بشكل دائم","إدارة أجهزة الإدخال والإخراج (I/O System Management) — التعامل مع الأجهزة الطرفية وتخفيف تعقيداتها عن المستخدم","الحماية والشبكات — توفير الحماية للموارد ودعم الاتصال بالشبكات","واجهة سطر الأوامر (CLI) — تم توضيح الفرق بينها وبين الواجهة الرسومية (GUI)، حيث توفر CLI تحكمًا أكبر وقدرة على أتمتة المهام","أوضاع الطاقة — تم شرح الفرق بين الإيقاف التام (Shutdown)، إعادة التشغيل (Restart)، وضع السكون (Sleep)، والإسبات (Hibernate) وكيف يتعامل نظام التشغيل مع الذاكرة في كل حالة","نداءات النظام (System Calls) — الوسيط البرمجي الذي يسمح للتطبيقات بطلب خدمات من نظام التشغيل","نهج الطبقات (Layered Approach) — هيكلة نظام التشغيل في طبقات فوق بعضها البعض لتحسين الموديلاريتي (Modularity) وسهولة التطوير"],"case_study_ar":"خطأ في تعريف طابعة أسقط النظام بالكامل.","case_question_ar":"أي بنية نواة كانت ستعزل هذا الخطأ؟","challenge_ar":"اكتب سكريبت يعرض معلومات النظام (المعالج والذاكرة والقرص).","videos":[{"title_ar":"المحاضرة — بنية نظام التشغيل وخدماته","url":"https://youtu.be/3tNMhKDAiQw","description_ar":null}],"resources":[{"label":"Operating Systems: Three Easy Pieces (free book)","url":"https://pages.cs.wisc.edu/~remzi/OSTEP/","kind":"website"}],"assignment":{"title_ar":"تكليف: بنية نظام التشغيل وخدماته","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_OS_L09_OperatingSystemStructure\n\nالمطلوب:\n1️⃣ لخّص مكونات نظام التشغيل: العمليات والذاكرة والملفات والتخزين والإدخال والإخراج.\n2️⃣ نفّذ 10 أوامر في سطر الأوامر (CLI) تخص الملفات والعمليات ووثّقها.\n3️⃣ قارن بين البنية الأحادية (Monolithic) والنواة الصغيرة (Microkernel).\n\n📦 المطلوب تسليمه:\n📁 رابط مجلد Google Drive فيه تقرير PDF باسم TM-OS-L09.pdf\n✅ إجابات المطلوب والمخططات.\n📸 صور واضحة لكل خطوة.","required_evidence":["drive"],"is_required":true}},{"title_ar":"العمليات وحالاتها والمجدولات","title_en":"Processes, States & Schedulers","kind":"video","summary_ar":"يقدم هذا الفيديو شرحًا تعليميًا لمفاهيم أساسية في نظم التشغيل (Operating System)، ويركز بشكل خاص على إدارة العمليات (Process Management).","outcomes_ar":["مفهوم العملية (Process) — هي برنامج قيد التنفيذ، ويتم تخزين محتويات العملية في الذاكرة مقسمة إلى أجزاء تشمل: التكست (للكود)، البيانات (للمتغيرات)، الذاكرة المكدسة (Stack)، والذاكرة الحرة (Heap)","حالات العملية (Process States) — تمر العملية بعدة حالات: جديدة (New)، جاهزة (Ready)، قيد التنفيذ (Running)، منتظرة (Waiting)، ومنتهية (Terminated)","كتلة التحكم في العملية (PCB) — هي هيكل بيانات يخزن معلومات عن كل عملية، مثل الحالة، البرامج المساعدة (Program Counter)، السجلات (Registers)، ومعلومات الذاكرة","تبديل السياق (Context Switch) — العملية التي تحدث عند إيقاف عملية مؤقتًا لحفظ حالتها وتحميل حالة عملية أخرى، ويجب تقليل الوقت المستغرق فيها لزيادة كفاءة النظام","المجدول طويل الأمد (Long-term) — يختار أي العمليات تدخل إلى الذاكرة","المجدول قصير الأمد (Short-term) — المعروف بـ CPU Scheduler، يختار العملية التالية للتنفيذ على المعالج","المجدول متوسط الأمد (Medium-term) — مسؤول عن عمليات السواب (Swap in/out) بين الذاكرة والقرص الصلب عند امتلاء الذاكرة"],"case_study_ar":"نظام يقضي وقتاً طويلاً في تبديل السياق بدل التنفيذ.","case_question_ar":"ما السبب المحتمل؟ وكيف يؤثر طول الـTime Slice؟","challenge_ar":"اعرض شجرة العمليات في جهازك ووضّح العملية الأب لعملية تختارها.","videos":[{"title_ar":"المحاضرة — العمليات وحالاتها والمجدولات","url":"https://youtu.be/q5pXXhr8ouU","description_ar":null}],"resources":[{"label":"Operating Systems: Three Easy Pieces (free book)","url":"https://pages.cs.wisc.edu/~remzi/OSTEP/","kind":"website"}],"assignment":{"title_ar":"تكليف: العمليات وحالاتها والمجدولات","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_OS_L10_ProcessesStatesSchedulers\n\nالمطلوب:\n1️⃣ ارسم مخطط حالات العملية مع أسباب الانتقال بين الحالات.\n2️⃣ اشرح محتوى الـPCB وما يحدث في تبديل السياق.\n3️⃣ قارن المجدول طويل وقصير ومتوسط الأمد.\n\n📦 المطلوب تسليمه:\n📁 رابط مجلد Google Drive فيه تقرير PDF باسم TM-OS-L10.pdf\n✅ إجابات المطلوب والمخططات.\n📸 صور واضحة لكل خطوة.","required_evidence":["drive"],"is_required":true}},{"title_ar":"إدارة العمليات والتعاون بينها","title_en":"Process Management & Cooperation","kind":"video","summary_ar":"يقدم هذا الفيديو شرحاً مفصلاً ومبسطاً لمفاهيم نظم التشغيل (Operating Systems)، مع التركيز بشكل خاص على إدارة العمليات (Process Management).","outcomes_ar":["أنواع العمليات — تم توضيح الفرق بين العمليات المرتبطة بالإدخال والإخراج (I/O-bound processes) والعمليات المرتبطة بالمعالج (CPU-bound processes)، وكيف تؤثر طبيعة التطبيقات على أداء النظام","تبديل السياق (Context Switch) — شرح العملية التي يقوم بها نظام التشغيل لحفظ حالة العملية الحالية وتحميل حالة عملية أخرى، والتأكيد على أن هذا الوقت يعتبر أوفرهيد (overhead) يجب تقليله لزيادة كفاءة الجهاز","كيفية إنشاء العمليات (Process Creation) وتكوين شجرة العمليات (Process Tree)","العلاقة بين العملية الأم (Parent) والعملية الابنة (Child)، بما في ذلك مشاركة الموارد وطرق التنفيذ (بالتوازي أو انتظار انتهاء الابن)","إنهاء العمليات (Process Termination)، وكيف يقوم نظام التشغيل بإنهاء العمليات التابعة تلقائياً عند إنهاء العملية الأم (Cascading Termination)","الفرق بين العمليات المستقلة (Independent) والعمليات المتعاونة (Cooperating)","طرق التواصل بين العمليات (IPC)، مثل تمرير الرسائل (Message Passing) وذاكرة المشاركة (Shared Memory)، مع شرح مفاهيم المزامنة (Synchronization) وحالات الإرسال والاستقبال (Blocking vs. Non-blocking)"],"case_study_ar":"متصفح يشغّل كل تبويب في عملية مستقلة.","case_question_ar":"ما فائدة ذلك؟ وما كلفته؟","challenge_ar":"اكتب برنامجاً ينشئ عملية ابن ويتبادل معها رسالة.","videos":[{"title_ar":"المحاضرة — إدارة العمليات والتعاون بينها","url":"https://youtu.be/1Ablv86a5AQ","description_ar":null}],"resources":[{"label":"Operating Systems: Three Easy Pieces (free book)","url":"https://pages.cs.wisc.edu/~remzi/OSTEP/","kind":"website"}],"assignment":{"title_ar":"تكليف: إدارة العمليات والتعاون بينها","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_OS_L11_ProcessManagementCooperation\n\nالمطلوب:\n1️⃣ صنّف العمليات إلى I/O-bound وCPU-bound بأمثلة.\n2️⃣ اشرح إنشاء عملية وإنهاءها.\n3️⃣ وضّح طرق التواصل بين العمليات (الذاكرة المشتركة والرسائل).\n\n📦 المطلوب تسليمه:\n📁 رابط مجلد Google Drive فيه تقرير PDF باسم TM-OS-L11.pdf\n✅ إجابات المطلوب والمخططات.\n📸 صور واضحة لكل خطوة.","required_evidence":["drive"],"is_required":true}},{"title_ar":"جدولة المعالج","title_en":"CPU Scheduling","kind":"video","summary_ar":"يقدم هذا الفيديو شرحًا مفصلًا حول مفهوم جدولة المعالج (CPU Scheduling) في أنظمة التشغيل، وهو الجزء المسؤول عن اختيار العملية (Process) التي سيتم تنفيذها على المعالج لتحقيق أقصى استفادة منه.","outcomes_ar":["الهدف من الجدولة — تحسين استغلال المعالج (CPU Utilization) وضمان عدم بقائه خاملاً أثناء انتظار العمليات لعمليات الإدخال والإخراج (I/O Operations)","معايير الجدولة (Scheduling Criteria) — ناقش الفيديو المقاييس التي يتم تقييم الخوارزميات بناءً عليها، مثل سرعة الإنجاز (Throughput)، زمن الانتظار (Waiting Time)، وزمن الاستجابة (Response Time)","العمل الأقصر أولاً (Shortest Job First - SJF) — سواء كان بنظام غير استباقي (Non-preemptive) أو استباقي (Preemptive)","الأولوية (Priority Scheduling) — حيث تُعطى الأولوية للعمليات بناءً على رقم محدد","جدولة الراوند روبن (Round Robin) — القائمة على تقاسم الوقت (Time Sharing) وتخصيص فترة زمنية (Quantum) لكل عملية","مفاهيم هامة — تم توضيح الفرق بين الجدولة الاستباقية (Preemptive) وغير الاستباقية (Non-preemptive)، وكيفية إدارة مشكلة \"المجاعة\" (Starvation) باستخدام تقنية \"التقادم\" (Aging)"],"case_study_ar":"عملية بأولوية منخفضة لم تُنفَّذ منذ ساعات.","case_question_ar":"ما اسم المشكلة؟ وكيف يحلها التقادم (Aging)؟","challenge_ar":"اكتب برنامجاً يحاكي Round Robin ويحسب المتوسطات.","videos":[{"title_ar":"المحاضرة — جدولة المعالج","url":"https://youtu.be/KNs5wzji64g","description_ar":null}],"resources":[{"label":"Operating Systems: Three Easy Pieces (free book)","url":"https://pages.cs.wisc.edu/~remzi/OSTEP/","kind":"website"}],"assignment":{"title_ar":"تكليف: جدولة المعالج","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_OS_L12_CPUScheduling\n\nالمطلوب:\n1️⃣ احسب متوسط زمن الانتظار والدوران لخمس عمليات بخوارزميات FCFS وSJF وPriority وRound Robin.\n2️⃣ ارسم مخطط Gantt لكل خوارزمية.\n3️⃣ قارن النتائج واختر الأفضل مع التبرير.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"إدارة الذاكرة","title_en":"Memory Management","kind":"video","summary_ar":"يقدم هذا الفيديو شرحاً مفصلاً ومبسطاً لمفاهيم إدارة الذاكرة (Memory Management) في أنظمة التشغيل.","outcomes_ar":["العناوين المنطقية والفيزيائية (Logical & Physical Addresses) — يوضح الفرق بين العنوان الذي يطلبه المعالج (CPU) والعنوان الفعلي في الذاكرة (RAM)، ودور وحدة إدارة الذاكرة (MMU) في الربط بينهما","مفهوم التبديل (Swapping) — شرح كيفية إدارة النظام للذاكرة عندما تمتلئ، من خلال نقل العمليات (Processes) مؤقتاً إلى التخزين الثانوي","تجزئة الذاكرة (Fragmentation) — يوضح مشاكل تجزئة الذاكرة الداخلية والخارجية التي تحدث عند تخصيص أماكن متجاورة للعمليات، وكيفية التعامل معها باستخدام التقنيات المختلفة","تقنية التجزئة إلى صفحات (Paging) — يعرض كيف تحل هذه التقنية مشكلة التجزئة الخارجية عن طريق تقسيم الذاكرة إلى إطارات متساوية، مما يسمح بتحميل العمليات في أماكن غير متجاورة","تقنية التجزئة إلى مقاطع (Segmentation) — يوضح هذا الأسلوب الذي يركز على وجهة نظر المستخدم، حيث يقسم البرنامج إلى وحدات منطقية (مثل الدوال أو المكدس) بدلاً من صفحات متساوية","الدمج بين التجزئة والصفحات (Segmentation with Paging) — يشرح الطريقة الأكثر كفاءة التي تدمج بين المفهومين لضمان مرونة التقسيم المنطقي مع سهولة الإدارة الفيزيائية للذاكرة"],"case_study_ar":"ذاكرة فيها مساحة حرة كافية لكنها مقسّمة لقطع صغيرة متفرقة.","case_question_ar":"ما اسم المشكلة؟ وكيف يحلها Paging؟","challenge_ar":"ابحث عن الذاكرة الافتراضية وصفحة الـSwap واشرح متى يبطئ الجهاز بسببها.","videos":[{"title_ar":"المحاضرة — إدارة الذاكرة","url":"https://youtu.be/arOIYWXJzcU","description_ar":null}],"resources":[{"label":"Operating Systems: Three Easy Pieces (free book)","url":"https://pages.cs.wisc.edu/~remzi/OSTEP/","kind":"website"}],"assignment":{"title_ar":"تكليف: إدارة الذاكرة","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_OS_L13_MemoryManagement\n\nالمطلوب:\n1️⃣ اشرح العنوان المنطقي والفيزيائي.\n2️⃣ وضّح التجزؤ الداخلي والخارجي بمثال.\n3️⃣ حوّل عنواناً منطقياً إلى فيزيائي بجدول صفحات.\n4️⃣ قارن Paging وSegmentation.\n\n📦 المطلوب تسليمه:\n📁 رابط مجلد Google Drive فيه تقرير PDF باسم TM-OS-L13.pdf\n✅ إجابات المطلوب والمخططات.\n📸 صور واضحة لكل خطوة.","required_evidence":["drive"],"is_required":true}}]}]}$course$::jsonb);

select public.import_course($course${"slug":"linux","title_ar":"إدارة أنظمة Linux (Red Hat)","title_en":"Linux System Administration (Red Hat)","description_ar":"إدارة خوادم Linux على توزيعات Red Hat: المستخدمون والمجموعات وsudo والصلاحيات ومحرر vi، والمتغيرات وملفات التهيئة، والعمليات وإعادة التوجيه والأنابيب، والضغط والبحث وإدارة الحزم بـ RPM وYUM، ومعالجة النصوص بـ sed وawk وكتابة السكريبتات.","level":"beginner","estimated_hours":30,"paths":[],"modules":[{"title_ar":"المستخدمون والصلاحيات","lessons":[{"title_ar":"إدارة المستخدمين والمجموعات","title_en":"Users & Groups Administration","kind":"video","summary_ar":"يقدم هذا الفيديو شرحاً مفصلاً لأساسيات إدارة المستخدمين والمجموعات (Users and Group Administration) في نظام Linux.","outcomes_ar":["ملف /etc/passwd — يحتوي على معلومات المستخدمين، حيث يمثل كل سطر مستخدماً واحداً","ملف /etc/shadow — يُستخدم لتخزين كلمات المرور المشفرة لزيادة الأمان، حيث تم نقلها من ملف `passwd`","ملف /etc/group — يحتوي على معلومات المجموعات التي ينتمي إليها المستخدمون","`useradd` — لإنشاء مستخدم جديد","`usermod` — لتعديل خصائص المستخدم (مثل تغيير اسم المستخدم `usermod -l` أو قفل الحساب `usermod -L`)","`userdel` — لحذف مستخدم، مع خيار `-r` لحذف الدليل الرئيسي (Home Directory) أيضاً","`groupadd` و `groupdel` — لإنشاء وحذف المجموعات","`gpasswd` — لإدارة كلمات مرور المجموعات والمستخدمين","`newgrp` — لتغيير المجموعة الأساسية للمستخدم مؤقتاً","المجموعات الأساسية والثانوية — شرح الفرق بينهما، وكيف أن المجموعة الأساسية يتم تعيينها عند إنشاء الملفات"],"case_study_ar":"موظف غادر الشركة وما زال حسابه يعمل على الخادم.","case_question_ar":"ما الخطوات الصحيحة لإيقافه دون حذف ملفاته فوراً؟","challenge_ar":"اكتب سكريبت ينشئ مستخدمين من ملف نصي فيه الأسماء.","videos":[{"title_ar":"المحاضرة — إدارة المستخدمين والمجموعات","url":"https://youtu.be/dQ80jUwkmpg","description_ar":null}],"resources":[{"label":"Red Hat Enterprise Linux documentation","url":"https://docs.redhat.com/en/documentation/red_hat_enterprise_linux/9","kind":"website"},{"label":"Linux Journey","url":"https://linuxjourney.com/","kind":"website"}],"assignment":{"title_ar":"تكليف: إدارة المستخدمين والمجموعات","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_LINUX_L01_UsersGroupsAdministration\n\nالمطلوب:\n1️⃣ أنشئ ثلاثة مستخدمين ومجموعتين بـ useradd وgroupadd وأضف المستخدمين للمجموعات.\n2️⃣ عدّل مستخدماً بـ usermod (المجلد والصدفة وتاريخ الانتهاء) واحذف آخر بـ userdel.\n3️⃣ اشرح حقول /etc/passwd و/etc/shadow و/etc/group بسطر من كل ملف.\n\n📦 المطلوب تسليمه:\n📁 رابط مجلد Google Drive فيه تقرير PDF باسم TM-LINUX-L01.pdf\n✅ إجابات المطلوب والمخططات.\n📸 صور واضحة لكل خطوة.","required_evidence":["drive"],"is_required":true}},{"title_ar":"أمر ls والملكية وإنشاء المستخدمين","title_en":"ls, Ownership & Creating Users","kind":"video","summary_ar":"يقدم هذا الفيديو الجزء الثاني من سلسلة محاضرات إدارة أنظمة Red Hat، حيث يركز على مجموعة من المفاهيم الأساسية في بيئة Linux.","outcomes_ar":["شرح مفصل لأمر `ls` مع استخدام خيارات متنوعة مثل `-l` لعرض التفاصيل (التصاريح، المالك، المجموعة، والحجم) و `-a` لعرض الملفات المخفية","توضيح كيفية عمل \"توسيع أسماء الملفات\" (File Globbing) باستخدام الميتا-كاركترز مثل النجمة `*` وعلامة الاستفهام `?` والأقواس المربعة `[]`","خطوات إنشاء مستخدم جديد باستخدام `useradd` وتعديل بياناته باستخدام `usermod`","شرح الفرق بين المجموعات الأساسية والثانوية وكيفية الانتقال بينها باستخدام `newgrp`","الفرق بين أمر `chgrp` لتغيير مجموعة الملف وأمر `chown` لتغيير ملكية الملف","تأكيد أن تغيير الملكية (Owner) يتطلب صلاحيات Root، بينما يمكن للمستخدم تغيير المجموعة إذا كان عضواً فيها"],"case_study_ar":"فريق يحتاج مجلداً مشتركاً يكتب فيه أعضاؤه فقط.","case_question_ar":"كيف تضبط المالك والمجموعة والصلاحيات؟","challenge_ar":"استخدم SGID على المجلد المشترك واشرح أثره على الملفات الجديدة.","videos":[{"title_ar":"المحاضرة — أمر ls والملكية وإنشاء المستخدمين","url":"https://youtu.be/v3KwVYWorW0","description_ar":null}],"resources":[{"label":"Red Hat Enterprise Linux documentation","url":"https://docs.redhat.com/en/documentation/red_hat_enterprise_linux/9","kind":"website"},{"label":"Linux Journey","url":"https://linuxjourney.com/","kind":"website"}],"assignment":{"title_ar":"تكليف: أمر ls والملكية وإنشاء المستخدمين","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_LINUX_L02_LsOwnershipCreating\n\nالمطلوب:\n1️⃣ استخدم ls بخياراته (-l -a -h -R -t) ووثّق معنى كل عمود.\n2️⃣ غيّر مالك ملف بـ chown ومجموعته بـ chgrp.\n3️⃣ أنشئ مستخدماً بمجلد منزل ومجموعة أساسية محددة وتحقق من النتيجة.\n\n📦 المطلوب تسليمه:\n📁 رابط مجلد Google Drive فيه تقرير PDF باسم TM-LINUX-L02.pdf\n✅ إجابات المطلوب والمخططات.\n📸 صور واضحة لكل خطوة.","required_evidence":["drive"],"is_required":true}},{"title_ar":"صلاحيات sudo وvisudo","title_en":"sudo & visudo","kind":"video","summary_ar":"يشرح هذا الدرس منح الصلاحيات الإدارية بأمان عبر sudo: تحرير الإعدادات بـ visudo، والأسماء المستعارة للمستخدمين والأجهزة والأوامر، وكتابة القواعد واختبارها.","outcomes_ar":["استخدام `visudo` — يشدد الفيديو على أهمية استخدام أمر `visudo` بدلاً من تعديل ملف `/etc/sudoers` مباشرة، لأن هذا الأمر يقوم بالتحقق من صحة الصيغة (syntax check) قبل حفظ الملف لمنع حدوث أخطاء قد تعطل النظام","User Alias — لتجميع عدة مستخدمين تحت اسم واحد لتسهيل تطبيق القواعد عليهم","Host Alias — لتجميع الأجهزة أو عناوين IP تحت اسم واحد","Command Alias — لتجميع مجموعة من الأوامر (مثل أدوات إدارة المستخدمين) التي يُسمح لمستخدم معين بتنفيذها","تطبيق القواعد (Rules) — شرح كيفية ربط المستخدمين أو المجموعات (باستخدام علامة `%` للمجموعات) بالأجهزة والأوامر المسموح لهم بها (10:17-10:57، 19:27-20:19)","تحذيرات الأمان — عند استخدام `sudo` لأول مرة، يظهر النظام تحذيرات حول احترام خصوصية المستخدمين الآخرين، وتوخي الحذر عند كتابة الأوامر، والمسؤولية الملقاة على عاتق مدير النظام"],"case_study_ar":"متدرّب يحتاج إعادة تشغيل خدمة الويب فقط، وأُعطي كلمة مرور root.","case_question_ar":"ما الخطر؟ وكيف يحل sudo ذلك؟","challenge_ar":"فعّل تسجيل أوامر sudo وأين تجد السجل.","videos":[{"title_ar":"المحاضرة — صلاحيات sudo وvisudo","url":"https://youtu.be/zoDV6ZqkCxI","description_ar":null}],"resources":[{"label":"Red Hat Enterprise Linux documentation","url":"https://docs.redhat.com/en/documentation/red_hat_enterprise_linux/9","kind":"website"},{"label":"Linux Journey","url":"https://linuxjourney.com/","kind":"website"}],"assignment":{"title_ar":"تكليف: صلاحيات sudo وvisudo","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_LINUX_L03_SudoVisudo\n\nالمطلوب:\n1️⃣ امنح مستخدماً صلاحية تشغيل أمر واحد فقط كـ root عبر visudo.\n2️⃣ أنشئ User Alias وCommand Alias وطبّق قاعدة عليهما.\n3️⃣ اختبر الصلاحية بـ sudo -l ووثّق النتيجة.\n\n📦 المطلوب تسليمه:\n📁 رابط مجلد Google Drive فيه تقرير PDF باسم TM-LINUX-L03.pdf\n✅ إجابات المطلوب والمخططات.\n📸 صور واضحة لكل خطوة.","required_evidence":["drive"],"is_required":true}},{"title_ar":"صلاحيات الملفات ومحرر vi","title_en":"File Permissions & the vi Editor","kind":"video","summary_ar":"يقدم هذا الفيديو شرحاً وافياً حول أساسيات إدارة نظام Red Hat Linux، مع التركيز على موضوعين رئيسيين هما صلاحيات الملفات (Permissions) واستخدام محرر النصوص vi.","outcomes_ar":["تم شرح كيفية تحديد مالك الملف (Owner) والمجموعة (Group) المرتبطة به، وكيفية تغييرها باستخدام أوامر مثل `chown` و `chmod`","توضيح معاني صلاحيات القراءة (r)، الكتابة (w)، والتنفيذ (x)، وكيف يختلف تأثيرها بين الملفات والمجلدات","مناقشة مفهوم الـ Umask وكيف يؤثر على الصلاحيات الافتراضية للملفات والمجلدات الجديدة","توضيح أن حذف ملف يتطلب صلاحيات الكتابة والتنفيذ على المجلد الأب وليس على الملف نفسه","مناقشة حالات إعادة تشغيل السيرفر (Shutdown/Reboot)","شرح مفصل لاستخدام محرر النصوص *vi*، وهو المحرر الأساسي في حالات الطوارئ","تم استعراض أوضاع العمل في vi — وضع الأوامر (Command Mode)، وضع الإدخال (Insert Mode)، ووضع السطر الأخير (Last Line Mode)","تعلم مهارات التنقل داخل الملف، الحذف، البحث، واستبدال الكلمات، بالإضافة إلى كيفية حفظ التغييرات أو الخروج دون حفظ"],"case_study_ar":"سكريبت لا يعمل ويظهر Permission denied رغم أنك مالكه.","case_question_ar":"ما الصلاحية الناقصة؟","challenge_ar":"اشرح الفرق بين shutdown وreboot وhalt وخيارات الجدولة الزمنية.","videos":[{"title_ar":"المحاضرة — صلاحيات الملفات ومحرر vi","url":"https://youtu.be/oPLm9XVeqcY","description_ar":null}],"resources":[{"label":"Red Hat Enterprise Linux documentation","url":"https://docs.redhat.com/en/documentation/red_hat_enterprise_linux/9","kind":"website"},{"label":"Linux Journey","url":"https://linuxjourney.com/","kind":"website"}],"assignment":{"title_ar":"تكليف: صلاحيات الملفات ومحرر vi","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_LINUX_L04_FilePermissionsThe\n\nالمطلوب:\n1️⃣ اضبط صلاحيات ملفات بالصيغة الرمزية والرقمية (chmod).\n2️⃣ اشرح umask وغيّرها واختبر أثرها.\n3️⃣ حرّر ملف إعدادات بـ vi: إدراج، حذف، بحث، استبدال، حفظ وخروج.\n\n📦 المطلوب تسليمه:\n📁 رابط مجلد Google Drive فيه تقرير PDF باسم TM-LINUX-L04.pdf\n✅ إجابات المطلوب والمخططات.\n📸 صور واضحة لكل خطوة.","required_evidence":["drive"],"is_required":true}}]},{"title_ar":"الصدفة والعمليات","lessons":[{"title_ar":"المتغيرات وملفات التهيئة","title_en":"Variables & Initialisation Files","kind":"video","summary_ar":"يقدم هذا الفيديو شرحاً مفصلاً حول المتغيرات (Variables) وملفات التهيئة (Initialization Files) في بيئة Linux، مع التركيز على التعامل مع الصدفة (Shell) من نوع Bash.","outcomes_ar":["متغيرات المستخدم (User Variables) — يتم إنشاؤها وتسميتها بواسطة المستخدم، وتكون عادةً من نوع النصوص (Strings) افتراضياً","متغيرات البيئة (Environment Variables) — متغيرات محددة مسبقاً في النظام مثل HOME وPATH، وتؤثر على سلوك Shell","العمليات الحسابية — توضيح كيفية التعامل مع المتغيرات كأرقام صحيحة (Integers) باستخدام الأقواس المدورة `(())` أو الأمر `typeset -i`","أوامر الإدارة — شرح أهمية أوامر مثل `export` لجعل المتغيرات متاحة للعمليات الفرعية (Child Shells)، والأمر `alias` لاختصار الأوامر الطويلة و (104:19-106:18)","شرح الفرق بين ملفات النظام العامة مثل `/etc/profile` وملفات المستخدم الشخصية مثل `.bash_profile` و `.bashrc`","التأكيد على أن `.bashrc` هو المكان المفضل لإجراء التعديلات الدائمة لأنه يُقرأ عند كل فتح لـ Shell جديدة","نصائح إضافية — كيفية العودة للقيم الافتراضية باستخدام ملفات الهيكل (Skeleton) الموجودة في `/etc/skel` (110:49-112:12)"],"case_study_ar":"متغير عرّفته يعمل في الطرفية الحالية ويختفي في طرفية جديدة.","case_question_ar":"لماذا؟ وأين تضعه ليبقى؟","challenge_ar":"خصّص سطر الأوامر PS1 ليعرض المستخدم والمجلد والوقت.","videos":[{"title_ar":"المحاضرة — المتغيرات وملفات التهيئة","url":"https://youtu.be/zYlk8oM2rVw","description_ar":null}],"resources":[{"label":"Red Hat Enterprise Linux documentation","url":"https://docs.redhat.com/en/documentation/red_hat_enterprise_linux/9","kind":"website"},{"label":"Linux Journey","url":"https://linuxjourney.com/","kind":"website"}],"assignment":{"title_ar":"تكليف: المتغيرات وملفات التهيئة","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_LINUX_L05_VariablesInitialisationFiles\n\nالمطلوب:\n1️⃣ عرّف متغيرات مستخدم وصدّر متغير بيئة بـ export.\n2️⃣ نفّذ عمليات حسابية في bash.\n3️⃣ أضف alias ومتغيراً دائماً في ‎~/.bashrc واشرح الفرق بينه وبين ‎/etc/profile.\n\n📦 المطلوب تسليمه:\n📁 رابط مجلد Google Drive فيه تقرير PDF باسم TM-LINUX-L05.pdf\n✅ إجابات المطلوب والمخططات.\n📸 صور واضحة لكل خطوة.","required_evidence":["drive"],"is_required":true}},{"title_ar":"العمليات وأولوياتها","title_en":"Processes & Priorities","kind":"video","summary_ar":"يشرح هذا الدرس العمليات في Linux: هيكليتها ومعرّفاتها PID وPPID، ومراقبتها بـ ps وtop، والتحكم في أولويتها بـ nice وrenice، وتشغيلها في الخلفية والأمام.","outcomes_ar":["مفهوم العمليات — يوضح الفيديو الفرق بين الملفات المصدرية (Source code)، الملفات الثنائية (Binary files)، وكيف تتحول هذه الملفات إلى عمليات (Processes) تستهلك موارد الجهاز مثل المعالج (CPU) والرامات (RAM)","هيكلية النظام — يشرح المراحل الأولى لتشغيل الجهاز بدءاً من BIOS ووصولاً إلى محمل الإقلاع (GRUB2) ونواة النظام (Kernel)","كيفية الحصول على معرف العملية (PID) والعملية الأب (PPID)","استخدام أوامر مثل `ps` لمراقبة الحالة، و `top` لعرض العمليات التفاعلية واستهلاك الموارد","شرح أولوية العمليات (Nice value) وكيفية التحكم فيها","كيفية إرسال الإشارات (Signals) مثل `SIGTERM` و `SIGKILL` لإنهاء العمليات (103:44-108:44)","تشغيل العمليات في الخلفية (Background) باستخدام علامة `&` واستخدام أمر `jobs` لمتابعتها (109:24-118:05)"],"case_study_ar":"عملية نسخ احتياطي تبطئ الخادم وقت الذروة.","case_question_ar":"كيف تخفض أولويتها دون إيقافها؟","challenge_ar":"اكتب أمراً يعرض أكثر خمس عمليات استهلاكاً للذاكرة.","videos":[{"title_ar":"المحاضرة — العمليات وأولوياتها","url":"https://youtu.be/ztigsbBCT9o","description_ar":null}],"resources":[{"label":"Red Hat Enterprise Linux documentation","url":"https://docs.redhat.com/en/documentation/red_hat_enterprise_linux/9","kind":"website"},{"label":"Linux Journey","url":"https://linuxjourney.com/","kind":"website"}],"assignment":{"title_ar":"تكليف: العمليات وأولوياتها","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_LINUX_L06_ProcessesPriorities\n\nالمطلوب:\n1️⃣ اعرض العمليات بـ ps وtop واستخرج PID وPPID لعملية.\n2️⃣ شغّل عملية في الخلفية وانقلها للأمام والعكس (jobs وbg وfg).\n3️⃣ غيّر أولوية عملية بـ nice وrenice.\n\n📦 المطلوب تسليمه:\n📁 رابط مجلد Google Drive فيه تقرير PDF باسم TM-LINUX-L06.pdf\n✅ إجابات المطلوب والمخططات.\n📸 صور واضحة لكل خطوة.","required_evidence":["drive"],"is_required":true}},{"title_ar":"التحكم بالعمليات وإعادة التوجيه والأنابيب","title_en":"Signals, Redirection & Pipelines","kind":"video","summary_ar":"يقدم هذا الفيديو شرحاً مفصلاً لإدارة العمليات (Processes) في نظام Red Hat Linux، مع التركيز على كيفية التحكم في تشغيلها وتنظيمها.","outcomes_ar":["إدارة العمليات — شرح كيفية تشغيل العمليات في الخلفية (Background) باستخدام علامة `&` أو تحويلها من المقدمة (Foreground) إلى الخلفية باستخدام `Ctrl+Z` ثم أمر `bg`، وإعادتها للمقدمة باستخدام `fg`","الفرق بين أوامر الإغلاق — توضيح الفرق الجوهري بين Terminate (إغلاق البرنامج نهائياً عبر `Ctrl+C`) و Stop (إيقاف مؤقت للعملية عبر `Ctrl+Z`)","حالة الزومبي — تعريف العمليات من نوع Zombie وكيفية التعامل معها، حيث أكد الفيديو أنها ليست تعليقاً للنظام بل مشكلة برمجية عند إغلاق العملية","إعادة التوجيه (Redirection) — شرح كيفية توجيه مخرجات الأوامر (سواء كانت نتائج صحيحة أو أخطاء) إلى ملفات بدلاً من الشاشة باستخدام `1>` و `2>`، بالإضافة إلى استخدام `/dev/null` كـ \"ثقب أسود\" للتخلص من المخرجات غير المرغوب ","خطوط الأنابيب (Pipeline) — استخدام الرمز `|` لتمرير مخرج أمر معين كمدخل لأمر آخر، مثل تمرير مخرجات `ls` إلى `grep` للبحث عن ملف معين","`wc` — لحساب الأسطر والكلمات","`diff` — للمقارنة بين ملفين","`tr` — لترجمة أو استبدال الحروف","`cut` — لاستخراج حقول معينة من الملفات","`sort` — لترتيب البيانات أبجدياً أو رقمياً"],"case_study_ar":"ملف سجل ضخم وتحتاج عدد الأخطاء المختلفة فيه.","case_question_ar":"أي سلسلة أوامر تعطيك ذلك في سطر واحد؟","challenge_ar":"اشرح عملية الزومبي وكيف تتخلص منها.","videos":[{"title_ar":"المحاضرة — التحكم بالعمليات وإعادة التوجيه والأنابيب","url":"https://youtu.be/TtuhVNy60kQ","description_ar":null}],"resources":[{"label":"Red Hat Enterprise Linux documentation","url":"https://docs.redhat.com/en/documentation/red_hat_enterprise_linux/9","kind":"website"},{"label":"Linux Journey","url":"https://linuxjourney.com/","kind":"website"}],"assignment":{"title_ar":"تكليف: التحكم بالعمليات وإعادة التوجيه والأنابيب","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_LINUX_L07_SignalsRedirectionPipelines\n\nالمطلوب:\n1️⃣ أنهِ عملية بإشارات مختلفة (kill -15 وkill -9) واشرح الفرق.\n2️⃣ استخدم > و>> و2> و&> لإعادة التوجيه.\n3️⃣ اربط أوامر بالأنابيب مع wc وdiff وtr وsort وuniq.\n\n📦 المطلوب تسليمه:\n📁 رابط مجلد Google Drive فيه تقرير PDF باسم TM-LINUX-L07.pdf\n✅ إجابات المطلوب والمخططات.\n📸 صور واضحة لكل خطوة.","required_evidence":["drive"],"is_required":true}},{"title_ar":"مراجعة شاملة: العمليات والجلسات ومعالجة النصوص","title_en":"Review: Processes, Sessions & Text Tools","kind":"video","summary_ar":"يقدم هذا الفيديو مراجعة شاملة لأساسيات إدارة أنظمة لينكس (Red Hat Administration)، مع التركيز على أدوات التحكم في العمليات (Processes) وأدوات معالجة النصوص.","outcomes_ar":["إدارة العمليات (Processes) — شرح المحاضر كيفية مراقبة العمليات باستخدام أوامر مثل `ps` و`top`، وكيفية ترتيبها حسب استهلاك الموارد (الميموري أو المعالج). كما تطرق إلى مفاهيم مثل العمليات الزومبي (Zombie Processes) والعملي","إدارة الجلسات واليوزرات — ناقش الفرق بين فتح التيرمنال عبر الواجهة الرسومية (pts) وعبر السيرفر (tty)، وكيفية التنقل بين الجلسات","أدوات معالجة النصوص — بدأ المحاضر في شرح أداة sed القوية، موضحاً أنها تستخدم للبحث، الاستبدال، وحذف الأسطر داخل الملفات دون التأثير على الملف الأصلي إلا إذا تم طلب ذلك","أوامر متفرقة — استعرض أوامر مفيدة مثل `split` لتقسيم الملفات، وأوامر `kill` و`jobs` لإدارة البرامج التي تعمل في الخلفية"],"case_study_ar":"تريد معرفة من دخل الخادم أمس ومن أي عنوان.","case_question_ar":"أي أوامر وملفات تستخدم؟","challenge_ar":"اعرض أكثر 5 مستخدمين دخولاً للنظام خلال الشهر.","videos":[{"title_ar":"المحاضرة — مراجعة شاملة: العمليات والجلسات ومعالجة النصوص","url":"https://youtu.be/_MaWfNFgnq4","description_ar":null}],"resources":[{"label":"Red Hat Enterprise Linux documentation","url":"https://docs.redhat.com/en/documentation/red_hat_enterprise_linux/9","kind":"website"},{"label":"Linux Journey","url":"https://linuxjourney.com/","kind":"website"}],"assignment":{"title_ar":"تكليف: مراجعة شاملة: العمليات والجلسات ومعالجة النصوص","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_LINUX_L08_ReviewProcessesSessions\n\nالمطلوب:\n1️⃣ اعرض المستخدمين المتصلين وجلساتهم (who وw وlast).\n2️⃣ استخدم cut وsort وhead وtail وgrep لاستخراج معلومات من /etc/passwd.\n3️⃣ اكتب ملخصاً بأهم 20 أمراً درستها مع مثال لكل أمر.\n\n📦 المطلوب تسليمه:\n📁 رابط مجلد Google Drive فيه تقرير PDF باسم TM-LINUX-L08.pdf\n✅ إجابات المطلوب والمخططات.\n📸 صور واضحة لكل خطوة.","required_evidence":["drive"],"is_required":true}}]},{"title_ar":"الملفات والحزم","lessons":[{"title_ar":"الضغط والبحث عن الملفات","title_en":"Archiving, Compression & Finding Files","kind":"video","summary_ar":"يقدم هذا الفيديو تعليمًا عمليًا حول إدارة الملفات وتثبيت البرمجيات في أنظمة التشغيل القائمة على Red Hat (مثل CentOS).","outcomes_ar":["استعراض أدوات ضغط الملفات مثل `compress` و `gzip` و `bzip2` ومقارنة كفاءتها في تقليل الحجم والوقت المستغرق","شرح كيفية التعامل مع المجلدات باستخدام أمر `tar` لجمع الملفات (الأرشفة) قبل ضغطها للحصول على أفضل نتائج","المقارنة بين أمر `find` (الذي يبحث في النظام بالكامل وببطء) وأمر `locate` (الذي يعتمد على قاعدة بيانات محلية ليكون أسرع)","شرح الفرق بين `rpm` كمدير حزم منخفض المستوى (Low-level) يواجه تحديات في إدارة الاعتماديات (Dependencies)، وبين `yum` كمدير حزم متقدم يقوم تلقائيًا بجلب الاعتماديات من المستودعات (Repositories)","مناقشة كيفية التعامل مع مفاتيح الأمان (GPG Keys) لضمان موثوقية البرمجيات"],"case_study_ar":"القرص امتلأ فجأة وتحتاج أكبر الملفات في النظام.","case_question_ar":"أي أمر find يعطيك ذلك؟","challenge_ar":"اكتب سكريبت يضغط مجلد السجلات يومياً ويحذف النسخ الأقدم من 7 أيام.","videos":[{"title_ar":"المحاضرة — الضغط والبحث عن الملفات","url":"https://youtu.be/zKtLB6XrQwg","description_ar":null}],"resources":[{"label":"Red Hat Enterprise Linux documentation","url":"https://docs.redhat.com/en/documentation/red_hat_enterprise_linux/9","kind":"website"},{"label":"Linux Journey","url":"https://linuxjourney.com/","kind":"website"}],"assignment":{"title_ar":"تكليف: الضغط والبحث عن الملفات","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_LINUX_L09_ArchivingCompressionFinding\n\nالمطلوب:\n1️⃣ اضغط مجلداً بـ tar مع gzip ثم bzip2 وقارن الأحجام.\n2️⃣ ابحث عن ملفات بالاسم والحجم والتاريخ والمالك بـ find.\n3️⃣ استخدم locate وwhich وwhereis واشرح الفرق.\n\n📦 المطلوب تسليمه:\n📁 رابط مجلد Google Drive فيه تقرير PDF باسم TM-LINUX-L09.pdf\n✅ إجابات المطلوب والمخططات.\n📸 صور واضحة لكل خطوة.","required_evidence":["drive"],"is_required":true}},{"title_ar":"إدارة الحزم RPM وYUM","title_en":"Package Management with RPM & YUM","kind":"video","summary_ar":"يقدم هذا الفيديو شرحاً عملياً لإدارة الحزم البرمجية في أنظمة Linux (تحديداً توزيعات Red Hat و CentOS)، مع التركيز على أداتي RPM و YUM.","outcomes_ar":["يوضح الفيديو أن أداة RPM تُعتبر أداة منخفضة المستوى (Low-level)، حيث تتطلب من المستخدم التعامل يدوياً مع المفاتيح العامة (Public Keys) للتحقق من أمان البرامج والتأكد من أنها موثقة","تم شرح كيفية استيراد المفاتيح (`rpm --import`) والتحقق من التوقيع الرقمي للحزم (`rpm --checksig`) لضمان سلامة الملفات","استعراض بعض الأوامر الأساسية للاستعلام عن الحزم المثبتة (`rpm -qi`, `rpm -ql`)","يشرح الفيديو أن YUM هو أداة إدارة حزم عالية المستوى (High-level) صُممت لتسهيل عملية التثبيت","يتميز YUM بقدرته التلقائية على إدارة الاعتماديات (Dependencies)، مما يغني المستخدم عن تثبيت المكتبات البرمجية يدوياً","يعتمد YUM على المستودعات (Repositories)، ويمكن للمستخدم البحث عن الحزم (`yum search`)، وتثبيتها، وحذفها بسهولة","أوضح الفيديو أن أداة YUM في الواقع تستخدم RPM في الخلفية لتنفيذ عمليات التثبيت الفعلية","تطرق الفيديو أيضاً إلى كيفية التعامل مع المستودعات وتحديث النظام لضمان توافق الحزم المثبتة"],"case_study_ar":"تثبيت حزمة بـ rpm فشل بسبب اعتماديات ناقصة.","case_question_ar":"لماذا يحل yum هذه المشكلة تلقائياً؟","challenge_ar":"ثبّت خادم ويب (httpd) وشغّله وافتح صفحته من المتصفح.","videos":[{"title_ar":"المحاضرة — إدارة الحزم RPM وYUM","url":"https://youtu.be/I3SjDycGxeM","description_ar":null}],"resources":[{"label":"Red Hat Enterprise Linux documentation","url":"https://docs.redhat.com/en/documentation/red_hat_enterprise_linux/9","kind":"website"},{"label":"Linux Journey","url":"https://linuxjourney.com/","kind":"website"}],"assignment":{"title_ar":"تكليف: إدارة الحزم RPM وYUM","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_LINUX_L10_PackageManagementWith\n\nالمطلوب:\n1️⃣ ثبّت حزمة وحدّثها واحذفها بـ yum (أو dnf).\n2️⃣ استعلم عن حزمة مثبتة وملفاتها بـ rpm -qi وrpm -ql.\n3️⃣ أضف مستودعاً (Repository) واعرض المستودعات المفعّلة.\n\n📦 المطلوب تسليمه:\n📁 رابط مجلد Google Drive فيه تقرير PDF باسم TM-LINUX-L10.pdf\n✅ إجابات المطلوب والمخططات.\n📸 صور واضحة لكل خطوة.","required_evidence":["drive"],"is_required":true}}]},{"title_ar":"معالجة النصوص والسكريبتات","lessons":[{"title_ar":"sed والصدفة وكتابة السكريبتات","title_en":"sed, the Shell & Writing Scripts","kind":"video","summary_ar":"يشرح هذا الدرس أداة sed لتعديل النصوص، وبيئة الصدفة، وسطر Shebang، وتنفيذ السكريبتات، ومتغير PATH.","outcomes_ar":["أداة Sed — شرح كيفية استخدام أمر `sed` في معالجة النصوص، بما في ذلك استخدام `الأنماط (Regex)` للبحث والطباعة والاستبدال، وتوضيح الفرق بين استخدام `-n` مع `p` مقابل استخدام الأمر بدونها","بيئة العمل (Shell) — مناقشة الفرق بين Terminal و Shell، وكيفية عمل المفسرات (Interpreters) مثل Python و Bash","الماجيك لاين (Shebang) — أهمية السطر الأول في السكريبتات `#!` لتحديد المفسر المطلوب لتشغيل الملف","تنفيذ السكريبتات — شرح طريقتين لتنفيذ الملفات: Sourcing (داخل نفس الشل) مقابل Child Process (إنشاء عملية جديدة)","متغير البيئة PATH — كيفية إضافة مسارات مخصصة إلى متغير `PATH` عبر ملف `~/.bashrc` لتشغيل السكريبتات من أي مكان في النظام","نصائح إضافية — ملاحظات حول إدارة المستخدمين وأهمية تعلم أدوات مثل AWK لاحقاً، مع اقتراحات لمصادر تعليمية أخرى"],"case_study_ar":"تحتاج تغيير منفذ الخدمة في 50 ملف إعدادات.","case_question_ar":"كيف ينجز sed ذلك بأمر واحد؟","challenge_ar":"اكتب سكريبت فيه شروط وحلقة يفحص وجود مجموعة ملفات ويطبع تقريراً.","videos":[{"title_ar":"المحاضرة — sed والصدفة وكتابة السكريبتات","url":"https://youtu.be/h_7Y5xpR0L4","description_ar":null}],"resources":[{"label":"Red Hat Enterprise Linux documentation","url":"https://docs.redhat.com/en/documentation/red_hat_enterprise_linux/9","kind":"website"},{"label":"Linux Journey","url":"https://linuxjourney.com/","kind":"website"}],"assignment":{"title_ar":"تكليف: sed والصدفة وكتابة السكريبتات","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_LINUX_L11_SedTheShell\n\nالمطلوب:\n1️⃣ استخدم sed للاستبدال والحذف والطباعة في ملف إعدادات.\n2️⃣ اكتب أول سكريبت بسطر Shebang وشغّله بعد إعطائه صلاحية التنفيذ.\n3️⃣ أضف مجلد سكريبتاتك إلى PATH.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"معالجة النصوص بـ awk","title_en":"Text Processing with awk","kind":"video","summary_ar":"يقدم هذا الفيديو شرحاً عملياً ومتقدماً لأدوات معالجة النصوص في بيئة Linux، مع التركيز بشكل خاص على أداة Awk.","outcomes_ar":["`$0` — يمثل السطر كاملاً","`1 ` comma `2`, إلخ — تمثل الأعمدة (الحقول)","`NR` — رقم السجل (رقم السطر)","`NF` — عدد الحقول في السطر","التحكم والبرمجة — يتطرق الفيديو إلى استخدام الشروط (if)، والحلقات التكرارية (Loops) داخل Awk لمعالجة البيانات بشكل معقد، وتغيير الفواصل بين الحقول (Field Separators) (7:50، 24:50)","أمثلة عملية — يقوم المحاضر بتطبيق الأداة على ملفات النظام مثل `/etc/passwd` لاستخراج بيانات محددة (مثل أسماء المستخدمين أو أرقام الأسطر) (4:16، 14:03)","نصائح برمجية — يؤكد المحاضر على أهمية الحذر من المسافات في لغة Bash، حيث إن خطأً بسيطاً في المسافات قد يؤدي إلى توقف السكريبت عن العمل (14:32، 15:24)"],"case_study_ar":"المدير يريد تقريراً يومياً بأكثر الصفحات زيارة من سجل الخادم.","case_question_ar":"كيف تكتبه بـ awk؟","challenge_ar":"اجمع sed وawk في سكريبت يولّد تقريراً منسقاً من ملف CSV.","videos":[{"title_ar":"المحاضرة — معالجة النصوص بـ awk","url":"https://youtu.be/l7U_tMYJ7S4","description_ar":null}],"resources":[{"label":"Red Hat Enterprise Linux documentation","url":"https://docs.redhat.com/en/documentation/red_hat_enterprise_linux/9","kind":"website"},{"label":"Linux Journey","url":"https://linuxjourney.com/","kind":"website"}],"assignment":{"title_ar":"تكليف: معالجة النصوص بـ awk","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_LINUX_L12_TextProcessingWith\n\nالمطلوب:\n1️⃣ استخدم awk لطباعة أعمدة محددة من ملف بيانات.\n2️⃣ استخدم NR وNF والشروط لحساب مجموع ومتوسط عمود.\n3️⃣ حلّل ملف سجل لخادم ويب: عدد الطلبات لكل عنوان IP.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}}]}]}$course$::jsonb);

select public.import_course($course${"slug":"wordpress","title_ar":"بناء المواقع بـ WordPress","title_en":"Building Websites with WordPress","description_ar":"بناء مواقع حقيقية دون برمجة ثقيلة: لوحة التحكم والوسائط والمستخدمون والتصنيفات ومحرر البلوكات، ثم القوالب وبناة الصفحات وElementor والقوائم والنماذج، والاستضافة والمتجر بـ WooCommerce، وتعدد اللغات بـ WPML، والتخصيص بالكود والنسخ الاحتياطي، وصولاً إلى موقع صحيفة كامل.","level":"beginner","estimated_hours":30,"paths":[{"slug":"web","required":false},{"slug":"freelancing","required":false}],"modules":[{"title_ar":"أساسيات ووردبريس","lessons":[{"title_ar":"أنظمة إدارة المحتوى ولماذا ووردبريس","title_en":"CMS & Why WordPress","kind":"video","summary_ar":"يقدم هذا الفيديو مقدمة شاملة حول تطوير الويب والتحول من استخدام لغات البرمجة التقليدية إلى أنظمة إدارة المحتوى (CMS)، مع التركيز بشكل خاص على ووردبريس (WordPress).","outcomes_ar":["تطور بناء المواقع — يوضح المحاضر كيف كان المطورون في البداية مضطرين لتعلم لغات مثل HTML، CSS، JavaScript للواجهات الأمامية، ولغات مثل PHP وقواعد بيانات مثل MySQL للتعامل مع الخلفية","مفهوم أنظمة إدارة المحتوى (CMS) — يشرح لماذا ظهرت أنظمة مثل WordPress، Joomla، وDrupal لتسهيل عملية إدارة المحتوى دون الحاجة لكتابة كود برمجي من الصفر، مما يوفر الوقت والجهد","لماذا ووردبريس؟ — يُعتبر ووردبريس حالياً نظاماً قوياً يتجاوز كونه مجرد CMS ليصل إلى كونه إطار عمل (Framework) متكامل يمكن ربطه بـ Bootstrap، React، أو حتى التعامل معه عبر REST API للمشاريع المتقدمة","خطوات العمل — استعرض الفيديو خطوات عملية لإنشاء موقع باستخدام ووردبريس، بدءاً من تحميل النسخة من wordpress.org، ثم إعداد قاعدة البيانات، ووصولاً إلى عملية التثبيت","التحكم بالموقع — شرح المحاضر الفرق بين واجهة الموقع الأمامية (التي يراها الزائر) وبوابة التحكم الخلفية (wp-admin)، مؤكداً على أهمية تأمين بيانات الدخول"],"case_study_ar":"صاحب مطعم يريد موقعاً يعدّل قائمة الطعام فيه بنفسه أسبوعياً.","case_question_ar":"لماذا يناسبه CMS أكثر من موقع مبرمج يدوياً؟","challenge_ar":"ابحث عن ثلاثة مواقع مشهورة مبنية بووردبريس.","videos":[{"title_ar":"المحاضرة — أنظمة إدارة المحتوى ولماذا ووردبريس","url":"https://youtu.be/3d1batwDWYk","description_ar":null}],"resources":[{"label":"Learn WordPress","url":"https://learn.wordpress.org/","kind":"website"},{"label":"WooCommerce documentation","url":"https://woocommerce.com/documentation/","kind":"website"}],"assignment":{"title_ar":"تكليف: أنظمة إدارة المحتوى ولماذا ووردبريس","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_WP_L01_CMSWhyWordPress\n\nالمطلوب:\n1️⃣ ثبّت ووردبريس محلياً (LocalWP أو XAMPP) أو على استضافة مجانية.\n2️⃣ اكتب مقارنة بين بناء موقع بالكود وبناؤه بـ CMS: الوقت والتكلفة والمرونة.\n3️⃣ صوّر لوحة التحكم بعد التثبيت.\n\n📦 المطلوب تسليمه:\n📁 رابط مجلد Google Drive فيه تقرير PDF باسم TM-WP-L01.pdf\n✅ إجابات المطلوب والمخططات.\n📸 صور واضحة لكل خطوة.","required_evidence":["drive"],"is_required":true}},{"title_ar":"لوحة التحكم ومكتبة الوسائط","title_en":"The Dashboard & Media Library","kind":"video","summary_ar":"يقدم هذا الفيديو شرحاً عملياً حول كيفية إدارة وتطوير المواقع باستخدام منصة ووردبريس (WordPress).","outcomes_ar":["التحكم في الموقع (لوحة التحكم) — أوضح الفيديو كيفية الوصول إلى لوحة تحكم الموقع عبر المسار `wp-admin` (التي تُسمى Dashboard)، وكيفية التبديل السريع بين واجهة الموقع الأمامية ولوحة التحكم","إدارة الوسائط (Media Library) — شرح الفيديو كيفية رفع الصور والملفات وإدارتها داخل ووردبريس، بما في ذلك كيفية إضافة نصوص بديلة (Alt Text) للصور لأغراض التوافق","ربط الملفات للتحميل — تم توضيح كيفية أخذ رابط ملف (مثل ملف PDF) واستخدامه لإنشاء رابط تحميل مباشر داخل الموقع","مسار الملفات على السيرفر — تم شرح أين تُحفظ الملفات المرفوعة فعلياً على السيرفر، وتحديداً داخل مجلد `wp-content/uploads`، حيث يقوم ووردبريس بتنظيمها تلقائياً حسب السنة والشهر","بشكل عام، يركز الفيديو على الربط بين ما يراه المستخدم وبين البنية التقنية لـ ووردبريس خلف الكواليس، مع تأكيد أهمية فهم كيفية تعامل النظام مع البيانات"],"case_study_ar":"صور الموقع ثقيلة والموقع بطيء على الهاتف.","case_question_ar":"كيف تجهّز الصور قبل رفعها؟","challenge_ar":"ثبّت إضافة لضغط الصور وقارن الحجم قبل وبعد.","videos":[{"title_ar":"المحاضرة — لوحة التحكم ومكتبة الوسائط","url":"https://youtu.be/vSNo0qqJR1Y","description_ar":null}],"resources":[{"label":"Learn WordPress","url":"https://learn.wordpress.org/","kind":"website"},{"label":"WooCommerce documentation","url":"https://woocommerce.com/documentation/","kind":"website"}],"assignment":{"title_ar":"تكليف: لوحة التحكم ومكتبة الوسائط","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_WP_L02_TheDashboardMedia\n\nالمطلوب:\n1️⃣ ارفع صوراً وملف PDF إلى مكتبة الوسائط ونظّمها بعناوين ونصوص بديلة (Alt).\n2️⃣ أنشئ صفحة فيها رابط تحميل للملف.\n3️⃣ حدد مكان الملفات المرفوعة على الخادم (wp-content/uploads).\n\n📦 المطلوب تسليمه:\n📁 رابط مجلد Google Drive فيه تقرير PDF باسم TM-WP-L02.pdf\n✅ إجابات المطلوب والمخططات.\n📸 صور واضحة لكل خطوة.","required_evidence":["drive"],"is_required":true}},{"title_ar":"المستخدمون والإعدادات والتصنيفات ومحرر البلوكات","title_en":"Users, Settings, Categories & the Block Editor","kind":"video","summary_ar":"يقدم هذا الفيديو شرحًا مفصلًا وعمليًا حول كيفية التعامل مع منصة ووردبريس (WordPress)، مع التركيز على تنظيم المحتوى وإدارة الموقع.","outcomes_ar":["إدارة المستخدمين والأدوار — شرح المحاضر كيفية إضافة مستخدمين جدد (مثل إضافة أحمد)، وتعيين صلاحيات مختلفة لهم (مثل المسؤول أو المشترك)، مع توضيح أهمية جدول المستخدمين في قاعدة البيانات","إعدادات الموقع — استعراض شامل لخيارات الإعدادات، بما في ذلك تغيير عنوان الموقع، ضبط التوقيت المحلي، تفعيل خاصية التسجيل للمستخدمين الجدد، وتغيير لغة الموقع (وكيفية التحكم في اتجاه الموقع من اليمين إلى اليسار RTL)","تنظيم المحتوى باستخدام التصنيفات (114 — 50 - 119:00): شرح كيفية إنشاء \"تصنيفات\" (Categories) لتنظيم المقالات (مثل الرياضة، السياسة، الفنون) وإمكانية إنشاء تصنيفات فرعية داخلها","الروابط — إضافة روابط خارجية وتنسيق ألوانها","الجداول — إنشاء جداول ديناميكية وتنسيقها","الوسائط — إضافة الصور، الفيديوهات، واستخدام \"البلوكات القابلة لإعادة الاستخدام\" (Reusable Blocks)","الكود — كيفية إضافة كود HTML مخصص"],"case_study_ar":"كاتب جديد نشر مقالاً قبل مراجعته.","case_question_ar":"أي دور كان يجب أن يأخذه؟","challenge_ar":"أنشئ نموذج مقال قابل لإعادة الاستخدام (Pattern).","videos":[{"title_ar":"المحاضرة — المستخدمون والإعدادات والتصنيفات ومحرر البلوكات","url":"https://youtu.be/QuJlp9hVxHU","description_ar":null}],"resources":[{"label":"Learn WordPress","url":"https://learn.wordpress.org/","kind":"website"},{"label":"WooCommerce documentation","url":"https://woocommerce.com/documentation/","kind":"website"}],"assignment":{"title_ar":"تكليف: المستخدمون والإعدادات والتصنيفات ومحرر البلوكات","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_WP_L03_UsersSettingsCategories\n\nالمطلوب:\n1️⃣ أنشئ مستخدمين بأدوار مختلفة (محرر، كاتب، مساهم) واشرح صلاحيات كل دور.\n2️⃣ اضبط إعدادات الموقع: العنوان، المنطقة الزمنية، الروابط الدائمة.\n3️⃣ أنشئ تصنيفات ووسوماً، واكتب مقالاً بالبلوكات فيه جدول وصورة ورابط وكود.\n\n📦 المطلوب تسليمه:\n📁 رابط مجلد Google Drive فيه تقرير PDF باسم TM-WP-L03.pdf\n✅ إجابات المطلوب والمخططات.\n📸 صور واضحة لكل خطوة.","required_evidence":["drive"],"is_required":true}},{"title_ar":"مشروع: موقع صحيفة «الوطن»","title_en":"Lab: A Newspaper Website","kind":"video","summary_ar":"تطبيق عملي لبناء موقع صحيفة بووردبريس: إعداد الموقع، إدارة المحتوى والأقسام، صلاحيات المستخدمين، وتصميم المقالات.","outcomes_ar":["تصميم البوست — يجب استخدام أكبر عدد ممكن من عناصر التحرير (Block Elements) مثل اليوتيوب، الأكواد، الفقرات، والوسائط المتعددة في منشور واحد على الأقل لإثراء المحتوى"],"case_study_ar":"الصحيفة تريد أن يظهر خبر عاجل أعلى الصفحة الرئيسية دائماً.","case_question_ar":"كيف تنفّذ ذلك بالتثبيت (Sticky) أو تصنيف خاص؟","challenge_ar":"أضف صفحة «من نحن» و«اتصل بنا».","videos":[{"title_ar":"المحاضرة — مشروع: موقع صحيفة «الوطن»","url":"https://youtu.be/3A57DC9rkPw","description_ar":null}],"resources":[{"label":"Learn WordPress","url":"https://learn.wordpress.org/","kind":"website"},{"label":"WooCommerce documentation","url":"https://woocommerce.com/documentation/","kind":"website"}],"assignment":{"title_ar":"تكليف: مشروع: موقع صحيفة «الوطن»","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_WP_L04_LabANewspaper\n\nالمطلوب:\n1️⃣ ابنِ موقع صحيفة: أقسام (سياسة، رياضة، تقنية) كتصنيفات.\n2️⃣ أضف 6 مقالات بصور بارزة وكُتّاب مختلفين.\n3️⃣ اضبط الصلاحيات بحيث يراجع المحرر مقالات الكتّاب قبل نشرها.\n\n📦 المطلوب تسليمه:\n📁 رابط مجلد Google Drive فيه تقرير PDF باسم TM-WP-L04.pdf\n✅ إجابات المطلوب والمخططات.\n📸 صور واضحة لكل خطوة.","required_evidence":["drive"],"is_required":true}}]},{"title_ar":"التصميم وبناة الصفحات","lessons":[{"title_ar":"التدوينات والصفحات والقوالب وبناة الصفحات","title_en":"Posts, Pages, Themes & Page Builders","kind":"video","summary_ar":"يشرح هذا الدرس التعامل مع التدوينات والصورة البارزة، وإعدادات الصفحات، وتخصيص القوالب، واستخدام بناة الصفحات.","outcomes_ar":["التعامل مع التدوينات (Posts) — شرح كيفية إضافة التدوينات، استخدام التصنيفات (Categories)، وأهمية الكلمات المفتاحية (Tags) لربط المحتوى ببعضه","الصورة البارزة (Featured Image) — توضيح كيفية إضافة صورة الغلاف للتدوينة لتظهر بشكل احترافي في واجهة الموقع","إعدادات الصفحات — كيفية إنشاء صفحات ثابتة (Pages) وتعيين صفحة رئيسية مخصصة بدلاً من عرض آخر التدوينات تلقائياً عبر إعدادات القراءة (Reading settings)","تخصيص القوالب (Themes) — شرح كيفية اختيار وتثبيت القوالب، مع توضيح الفارق بين القوالب المجانية والمدفوعة، وكيفية تفعيلها","بناة الصفحات (Page Builders) — استعراض أهمية أدوات بناء الصفحات مثل Elementor، وكيفية استخدام قوالب جاهزة (Starter Templates) لتصميم موقع كامل في دقائق"],"case_study_ar":"عميل يريد تغيير شكل موقعه كاملاً دون فقدان المحتوى.","case_question_ar":"لماذا يسمح فصل القالب عن المحتوى بذلك؟","challenge_ar":"قارن ثلاثة قوالب مجانية من حيث السرعة والمرونة.","videos":[{"title_ar":"المحاضرة — التدوينات والصفحات والقوالب وبناة الصفحات","url":"https://youtu.be/U6LGxjzNOzY","description_ar":null}],"resources":[{"label":"Learn WordPress","url":"https://learn.wordpress.org/","kind":"website"},{"label":"WooCommerce documentation","url":"https://woocommerce.com/documentation/","kind":"website"}],"assignment":{"title_ar":"تكليف: التدوينات والصفحات والقوالب وبناة الصفحات","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_WP_L05_PostsPagesThemes\n\nالمطلوب:\n1️⃣ وضّح الفرق بين Post وPage بمثالين.\n2️⃣ ثبّت قالباً وخصّصه من Customizer (الألوان والشعار والخطوط).\n3️⃣ جرّب باني صفحات واحد وابنِ صفحة هبوط بسيطة.\n\n📦 المطلوب تسليمه:\n📁 رابط مجلد Google Drive فيه تقرير PDF باسم TM-WP-L05.pdf\n✅ إجابات المطلوب والمخططات.\n📸 صور واضحة لكل خطوة.","required_evidence":["drive"],"is_required":true}},{"title_ar":"استيراد قالب تجريبي والتعديل بـ Elementor","title_en":"Demo Import & Editing with Elementor","kind":"video","summary_ar":"يقدم هذا الفيديو شرحاً عملياً لكيفية التعامل مع قالب Wordpress بعد استيراد البيانات التجريبية (Demo Import)، حيث يركز على تعديل المحتوى باستخدام أداة Elementor.","outcomes_ar":["إدارة الصفحات والقوائم — أوضح الفيديو كيفية ترتيب القوائم (Menus) وتحديد موقعها الرئيسي، بالإضافة إلى شرح الفرق بين صفحات الموقع (مثل الصفحة الرئيسية ومدونة الأخبار)","تعديل المحتوى (Posts & Pages) — تم استعراض طرق تعديل المنشورات، سواء عبر المحرر الافتراضي أو Elementor، مع شرح كيفية تغيير العنوان، الصورة المميزة (Featured Image)، والتحكم في الروابط الدائمة (Permalinks) والمسارات (Slug","استخدام Elementor — استعرض الفيديو أدوات بناء الصفحات، مثل التحكم في الأقسام (Sections)، الأعمدة (Columns)، وتغيير الخلفيات أو إضافة عناصر جديدة، مع التأكيد على أهمية الحفاظ على أبعاد الصور عند استبدالها لتجنب أي خلل في ","ميزات إضافية — تم التطرق إلى ميزة سجل التعديلات (History) التي تسمح بالعودة للخطوات السابقة، وأدوات التحكم في عرض الموقع على مختلف الشاشات (Responsive Mode)"],"case_study_ar":"بعد استيراد الـDemo ظهرت عشرات الصفحات والصور غير المطلوبة.","case_question_ar":"كيف تنظّف الموقع دون كسر التصميم؟","challenge_ar":"أنشئ قالباً عاماً للرأس والتذييل يظهر في كل الصفحات.","videos":[{"title_ar":"المحاضرة — استيراد قالب تجريبي والتعديل بـ Elementor","url":"https://youtu.be/fJFmPLTxrQ4","description_ar":null}],"resources":[{"label":"Learn WordPress","url":"https://learn.wordpress.org/","kind":"website"},{"label":"WooCommerce documentation","url":"https://woocommerce.com/documentation/","kind":"website"}],"assignment":{"title_ar":"تكليف: استيراد قالب تجريبي والتعديل بـ Elementor","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_WP_L06_DemoImportEditing\n\nالمطلوب:\n1️⃣ استورد بيانات تجريبية (Demo) لقالب جاهز.\n2️⃣ عدّل الصفحة الرئيسية بـ Elementor لتناسب نشاطاً حقيقياً.\n3️⃣ نظّم الصفحات والقوائم بعد الاستيراد.\n\n📦 المطلوب تسليمه:\n📁 رابط مجلد Google Drive فيه تقرير PDF باسم TM-WP-L06.pdf\n✅ إجابات المطلوب والمخططات.\n📸 صور واضحة لكل خطوة.","required_evidence":["drive"],"is_required":true}},{"title_ar":"Elementor ونماذج الاتصال والقوائم","title_en":"Elementor, Contact Forms & Menus","kind":"video","summary_ar":"يقدم هذا الدرس شرحاً عملياً حول كيفية بناء صفحات الويب وإدارة المحتوى باستخدام إضافات ووردبريس.","outcomes_ar":["التعامل مع إضافة إليمنتور (Elementor) — استعرض الفيديو كيفية تصميم الصفحات، حفظ التصميمات كقوالب (Templates)، واستيرادها أو تصديرها كملفات (JSON) لنقل التصاميم بين المواقع","حل مشكلات الإصدارات — تم التطرق إلى حل مشكلة عدم القدرة على استيراد القوالب من خلال التحكم في إصدار إضافة إليمنتور","إنشاء نماذج الاتصال (Contact Forms) — شرح الفيديو كيفية تثبيت واستخدام إضافة WPForms لإنشاء نماذج تفاعلية، وكيفية استقبال رسائل الزوار وتخزينها في قاعدة البيانات","إدارة القوائم (Menus) — توضيح كيفية إضافة الصفحات الجديدة إلى قائمة الموقع وترتيبها، بما في ذلك إنشاء قوائم فرعية (Sub-menus) بسهولة عبر السحب والإفلات"],"case_study_ar":"نموذج الاتصال يستقبل عشرات الرسائل المزعجة يومياً.","case_question_ar":"كيف تحميه (reCAPTCHA أو Honeypot)؟","challenge_ar":"اربط النموذج بجدول Google Sheets أو بإضافة لحفظ الرسائل.","videos":[{"title_ar":"المحاضرة — Elementor ونماذج الاتصال والقوائم","url":"https://youtu.be/9DRQSxDn-EA","description_ar":null}],"resources":[{"label":"Learn WordPress","url":"https://learn.wordpress.org/","kind":"website"},{"label":"WooCommerce documentation","url":"https://woocommerce.com/documentation/","kind":"website"}],"assignment":{"title_ar":"تكليف: Elementor ونماذج الاتصال والقوائم","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_WP_L07_ElementorContactForms\n\nالمطلوب:\n1️⃣ ابنِ صفحة خدمات بـ Elementor بأقسام وأيقونات وأزرار.\n2️⃣ أنشئ نموذج اتصال يرسل للبريد واختبره.\n3️⃣ أنشئ قائمة رئيسية فيها قائمة فرعية.\n\n📦 المطلوب تسليمه:\n📁 رابط مجلد Google Drive فيه تقرير PDF باسم TM-WP-L07.pdf\n✅ إجابات المطلوب والمخططات.\n📸 صور واضحة لكل خطوة.","required_evidence":["drive"],"is_required":true}},{"title_ar":"الصفحة الرئيسية والودجت والقوائم","title_en":"Homepage, Widgets & Menus","kind":"video","summary_ar":"يقدم هذا الفيديو ضمن كورس WordPress مقدمة عملية حول كيفية تخصيص صفحات الموقع الإلكتروني وإدارته باستخدام إضافات متنوعة.","outcomes_ar":["إدارة الصفحات الرئيسية — ناقش الفيديو كيفية الفصل بين صفحة المتجر (Shop) والصفحة الرئيسية للموقع (Home)، مما يتيح حرية أكبر في تصميم الصفحة الرئيسية وإضافة أقسام متنوعة (مثل العروض أو التصنيفات) بدلاً من عرض المنتجات فقط","استخدام إضافات بناء الصفحات — قام المحاضر بتثبيت إضافة Elementor وتفعيل نسخة الـ Pro لاستخدام ميزات أكثر احترافية في التصميم (06:39 - 07:02، 41:25 - 42:36)","إدارة الودجت (Widgets) — شرح كيفية التعامل مع الودجت وتوزيعها في أماكن مختلفة مثل الشريط الجانبي (Sidebar) أو تحت الهيدر، وكيفية إزالتها أو إضافة عناصر جديدة منها","إعداد القوائم (Menus) — وضح كيفية إنشاء قائمة رئيسية وتخصيص عناصرها، مع التركيز على أهمية ميزة \"خيارات الشاشة\" (Screen Options) لإظهار تصنيفات المنتجات داخل القائمة"],"case_study_ar":"زوار الموقع لا يجدون صفحة الأسعار.","case_question_ar":"كيف تحسّن القائمة والوصول إليها؟","challenge_ar":"أضف شريط بحث وقائمة «أحدث المقالات» في الشريط الجانبي.","videos":[{"title_ar":"المحاضرة — الصفحة الرئيسية والودجت والقوائم","url":"https://youtu.be/wS-eC20IcUQ","description_ar":null}],"resources":[{"label":"Learn WordPress","url":"https://learn.wordpress.org/","kind":"website"},{"label":"WooCommerce documentation","url":"https://woocommerce.com/documentation/","kind":"website"}],"assignment":{"title_ar":"تكليف: الصفحة الرئيسية والودجت والقوائم","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_WP_L08_HomepageWidgetsMenus\n\nالمطلوب:\n1️⃣ اضبط صفحة رئيسية ثابتة وصفحة للمدونة.\n2️⃣ أضف ودجت في الشريط الجانبي والتذييل.\n3️⃣ نظّم قوائم الرأس والتذييل ومواقعها.\n\n📦 المطلوب تسليمه:\n📁 رابط مجلد Google Drive فيه تقرير PDF باسم TM-WP-L08.pdf\n✅ إجابات المطلوب والمخططات.\n📸 صور واضحة لكل خطوة.","required_evidence":["drive"],"is_required":true}}]},{"title_ar":"الاستضافة والمتجر الإلكتروني","lessons":[{"title_ar":"من الجهاز المحلي إلى الاستضافة","title_en":"From Localhost to Online Hosting","kind":"video","summary_ar":"يقدم هذا الفيديو شرحاً وافياً حول كيفية الانتقال من العمل على المواقع محلياً (Localhost) إلى استضافتها عبر الإنترنت (Online Hosting).","outcomes_ar":["مفهوم الاستضافة — شرح المحاضر الفرق بين العمل على الجهاز الشخصي والخوادم الخارجية، وكيفية عمل الدومين (Domain) كعنوان يشير إلى عنوان الـ IP الخاص بالخادم","شركات الاستضافة — استعرض المحاضر أمثلة لشركات عالمية تقدم خدمات الاستضافة، موضحاً أهمية فهم تفاصيل الباقات، الترافيك، شهادات الأمان (SSL)، والفرق بين بروتوكولات نقل الملفات مثل FTP و SFTP","نصائح للتعامل مع العملاء — أكد المحاضر على أهمية فهم تكاليف الاستضافة والدومين السنوية، وكيفية تسعير الخدمة للعملاء كجزء من العمل الحر","التطبيق العملي المجاني — قام المحاضر بشرح عملي لكيفية حجز استضافة مجانية باستخدام منصة Pantheon.io وتثبيت نظام WordPress عليها، لتكون بديلاً للعمل المحلي","البدء في التجارة الإلكترونية — بدأ المحاضر التمهيد لفكرة إنشاء متجر إلكتروني باستخدام إضافة WooCommerce، وهي الخطوة التالية في الكورس"],"case_study_ar":"عميل يسأل: لماذا أدفع استضافة ونطاقاً كل سنة؟","case_question_ar":"كيف تشرح له الفرق بينهما وتكلفتهما؟","challenge_ar":"اكتب قائمة تسليم (Checklist) للعميل بعد نقل الموقع.","videos":[{"title_ar":"المحاضرة — من الجهاز المحلي إلى الاستضافة","url":"https://youtu.be/F1kYUk5DSNE","description_ar":null}],"resources":[{"label":"Learn WordPress","url":"https://learn.wordpress.org/","kind":"website"},{"label":"WooCommerce documentation","url":"https://woocommerce.com/documentation/","kind":"website"}],"assignment":{"title_ar":"تكليف: من الجهاز المحلي إلى الاستضافة","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_WP_L09_FromLocalhostTo\n\nالمطلوب:\n1️⃣ قارن ثلاث شركات استضافة: السعر والمساحة والدعم وموقع الخوادم.\n2️⃣ انقل موقعاً من جهازك إلى استضافة (مجانية أو تجريبية) بإضافة نقل.\n3️⃣ اربط نطاقاً أو نطاقاً فرعياً مجانياً وفعّل SSL.\n\n📦 المطلوب تسليمه:\n📁 رابط مجلد Google Drive فيه تقرير PDF باسم TM-WP-L09.pdf\n✅ إجابات المطلوب والمخططات.\n📸 صور واضحة لكل خطوة.","required_evidence":["drive"],"is_required":true}},{"title_ar":"المتجر الإلكتروني بـ WooCommerce","title_en":"An Online Store with WooCommerce","kind":"video","summary_ar":"يقدم هذا الفيديو شرحاً عملياً وشاملاً لكيفية إعداد واستخدام إضافة WooCommerce في موقع WordPress لتحويله إلى متجر إلكتروني.","outcomes_ar":["يبدأ الفيديو بتفعيل إضافة WooCommerce وشرح الخطوات الأولية لإدخال بيانات المتجر، واختيار الصناعة، وتحديد نوع المنتجات","يوضح المتحدث التغييرات التي تحدث في الموقع بعد التثبيت، مثل إنشاء الصفحات الأساسية (المتجر، السلة، إتمام الطلب، وحساب العميل) وإضافة أدوار مستخدمين جديدة","استعراض لوحة تحكم WooCommerce لمتابعة المبيعات، الطلبات، والتقارير","شرح كيفية إعداد مناطق الشحن (Shipping Zones) ووسائل الدفع (مثل الدفع عند الاستلام)","كيفية إنشاء تصنيفات للمنتجات، إضافة الوسوم (Tags)، وتحديد السمات (Attributes) مثل الحجم واللون","خطوات إضافة منتج جديد بالتفصيل، بما في ذلك السعر، المخزون، والصور","قام المحاضر بإجراء تجربة حية للشراء مع الطلاب للتأكد من وصول الطلبات وتفعيل الحسابات","ناقش المشكلات التقنية الشائعة مثل وصول رسائل البريد الإلكتروني إلى مجلد Spam وكيفية التعامل معها"],"case_study_ar":"متجر ملابس يبيع القميص نفسه بثلاثة مقاسات وأربعة ألوان.","case_question_ar":"أي نوع منتج تستخدم؟ وكيف تدير المخزون لكل خيار؟","challenge_ar":"أضف كوبون خصم وطريقة دفع عند الاستلام.","videos":[{"title_ar":"المحاضرة — المتجر الإلكتروني بـ WooCommerce","url":"https://youtu.be/DkKveZUQPE8","description_ar":null}],"resources":[{"label":"Learn WordPress","url":"https://learn.wordpress.org/","kind":"website"},{"label":"WooCommerce documentation","url":"https://woocommerce.com/documentation/","kind":"website"}],"assignment":{"title_ar":"تكليف: المتجر الإلكتروني بـ WooCommerce","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_WP_L10_AnOnlineStore\n\nالمطلوب:\n1️⃣ ثبّت WooCommerce واضبط العملة والشحن والضرائب.\n2️⃣ أضف 6 منتجات بأنواع مختلفة (بسيط، متغير بمقاسات).\n3️⃣ نفّذ طلب شراء تجريبياً حتى صفحة الشكر.\n\n📦 المطلوب تسليمه:\n📁 رابط مجلد Google Drive فيه تقرير PDF باسم TM-WP-L10.pdf\n✅ إجابات المطلوب والمخططات.\n📸 صور واضحة لكل خطوة.","required_evidence":["drive"],"is_required":true}}]},{"title_ar":"تعدد اللغات والتخصيص المتقدم","lessons":[{"title_ar":"موقع متعدد اللغات بـ WPML","title_en":"Multilingual Sites with WPML","kind":"video","summary_ar":"يقدم هذا الفيديو شرحاً عملياً حول كيفية جعل موقع WordPress يدعم لغات متعددة (Multi-language) باستخدام إضافة WPML الشهيرة.","outcomes_ar":["مقدمة عن تعدد اللغات — أوضح المحاضر أن المواقع تحتاج إلى إضافات متخصصة للترجمة بدلاً من الاعتماد على ترجمة جوجل الحرفية، مع استعراض لأهم الإضافات المتاحة مثل WPML و TranslatePress","خطوات التثبيت — قام المحاضر باستعراض طريقتين للتثبيت؛ الأولى من الصفر (بما في ذلك ربط قاعدة البيانات)، والثانية عبر رفع ملفات جاهزة تم تجهيزها للطلاب","إدارة التحديثات والنسخ — شرح الفرق بين النسخ القديمة والجديدة من الإضافات، وكيفية التعامل مع تحديثات WPML للحصول على الميزات الحديثة مثل دمج إضافات الترجمة الفرعية","إعدادات الموقع — تناول الفيديو كيفية ضبط واجهة المستخدم لإضافة تبديل اللغات (Language Switcher) في القائمة الرئيسية ليتمكن الزائر من التنقل بين العربية والإنجليزية","انتهى الجزء الأول من الفيديو بالتحضير لمتابعة الخطوات العملية بعد فترة استراحة"],"case_study_ar":"الصفحة الإنجليزية تظهر من اليمين لليسار.","case_question_ar":"أين تضبط اتجاه كل لغة؟","challenge_ar":"ترجم عناوين SEO لكل صفحة.","videos":[{"title_ar":"المحاضرة — موقع متعدد اللغات بـ WPML","url":"https://youtu.be/wI8rixWT-so","description_ar":null}],"resources":[{"label":"Learn WordPress","url":"https://learn.wordpress.org/","kind":"website"},{"label":"WooCommerce documentation","url":"https://woocommerce.com/documentation/","kind":"website"}],"assignment":{"title_ar":"تكليف: موقع متعدد اللغات بـ WPML","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_WP_L11_MultilingualSitesWith\n\nالمطلوب:\n1️⃣ اجعل الموقع بالعربية والإنجليزية بإضافة ترجمة (WPML أو Polylang المجانية).\n2️⃣ ترجم الصفحات والقوائم وأضف مبدّل اللغة.\n3️⃣ تأكد من اتجاه RTL للعربية وLTR للإنجليزية.\n\n📦 المطلوب تسليمه:\n📁 رابط مجلد Google Drive فيه تقرير PDF باسم TM-WP-L11.pdf\n✅ إجابات المطلوب والمخططات.\n📸 صور واضحة لكل خطوة.","required_evidence":["drive"],"is_required":true}},{"title_ar":"WPML مع WooCommerce والعملات","title_en":"WPML with WooCommerce & Currencies","kind":"video","summary_ar":"يقدم هذا الفيديو شرحاً عملياً حول كيفية إنشاء موقع ويب متعدد اللغات باستخدام إضافة WPML مع متجر WooCommerce، مع التركيز على التعامل مع المنتجات، العملات، والنصوص البرمجية.","outcomes_ar":["إعداد المكونات الإضافية — شرح أهمية إضافة WooCommerce Multilingual كجسر بين WooCommerce و WPML لضمان توافق المتجر","إعدادات المتجر — كيفية تهيئة صفحات المتجر للترجمة وتفعيل ميزة تعدد العملات (Multi-currency)","ترجمة العناصر — الخطوات التفصيلية لترجمة تصنيفات المنتجات (Categories)، الوسوم (Tags)، والألوان والأحجام (Attributes)","نظام العملات — كيفية إعداد عملات مختلفة (مثل الدولار والجنيه) وتفعيل التحويل التلقائي لأسعار الصرف","ترجمة المنتجات — كيفية ترجمة عناوين المنتجات، الأوصاف المختصرة والطويلة، والتأكد من ظهورها بشكل صحيح في واجهة الموقع","ترجمة نصوص النظام — استخدام خاصية String Translation لترجمة الكلمات الثابتة التي تظهر في المتجر (مثل رسائل الدفع عند الاستلام) عن طريق عمل"],"case_study_ar":"متجر يبيع في بلدين بعملتين وأسعار مختلفة.","case_question_ar":"كيف تضبط ذلك دون تكرار المنتجات؟","challenge_ar":"اختبر رحلة شراء كاملة باللغة الإنجليزية.","videos":[{"title_ar":"المحاضرة — WPML مع WooCommerce والعملات","url":"https://youtu.be/pnbYkepvqBc","description_ar":null}],"resources":[{"label":"Learn WordPress","url":"https://learn.wordpress.org/","kind":"website"},{"label":"WooCommerce documentation","url":"https://woocommerce.com/documentation/","kind":"website"}],"assignment":{"title_ar":"تكليف: WPML مع WooCommerce والعملات","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_WP_L12_WPMLWithWooCommerce\n\nالمطلوب:\n1️⃣ ترجم المنتجات والتصنيفات وصفحات المتجر.\n2️⃣ أضف عملتين وبدّل بينهما.\n3️⃣ ترجم نصوص النظام (مثل «أضف للسلة»).\n\n📦 المطلوب تسليمه:\n📁 رابط مجلد Google Drive فيه تقرير PDF باسم TM-WP-L12.pdf\n✅ إجابات المطلوب والمخططات.\n📸 صور واضحة لكل خطوة.","required_evidence":["drive"],"is_required":true}},{"title_ar":"التخصيص بالكود وبنية القالب","title_en":"Customising with Code & Theme Structure","kind":"video","summary_ar":"يقدم هذا الفيديو ضمن كورس WordPress مقدمة عملية حول كيفية تخصيص وتعديل المواقع الإلكترونية بعمق باستخدام الكود.","outcomes_ar":["تعديل الكود مباشرة (Code Editor) — شرح المحاضر كيفية استخدام محررات الكود داخل WordPress لتعديل عناصر مثل عناوين المقالات (Post Titles) وإضافة تأثيرات CSS أو JavaScript مخصصة","هيكلية القوالب (Blocks) — أوضح كيف يتم التعامل مع البلوكات داخل WordPress وكيفية عرضها كـ HTML داخل محررات الكود","مشكلات التنسيق (Minification) — ناقش المحاضر مشكلة ظهور وسوم ` ` غير مرغوبة عند تعديل الكود وكيفية حلها عبر استخدام تقنية Minify للكود، مع التأكيد على أهمية ذلك في تحسين سرعة تحميل الموقع","تخصيص القالب (Appearance Customization) — استعرض كيفية تغيير الألوان، اللوجو، وأيقونة الموقع (Site Icon) من قائمة Customize، بالإضافة إلى إضافة كود CSS خاص لتعديل عناصر محددة مثل القوائم (Menu)","التعامل مع اللغات المتعددة — قدم المحاضر نصيحة برمجية ذكية لتغيير تنسيق العناصر بناءً على لغة الموقع (مثلاً العربي RTL مقابل الإنجليزي) باستخدام محددات السمات (Attributes) في CSS مثل `[lang="],"case_study_ar":"تعديلات CSS في القالب الأصلي اختفت بعد تحديثه.","case_question_ar":"كيف يحمي القالب الفرعي تعديلاتك؟","challenge_ar":"أضف دالة في functions.php تغيّر نص التذييل.","videos":[{"title_ar":"المحاضرة — التخصيص بالكود وبنية القالب","url":"https://youtu.be/_Y53gX60TXU","description_ar":null}],"resources":[{"label":"Learn WordPress","url":"https://learn.wordpress.org/","kind":"website"},{"label":"WooCommerce documentation","url":"https://woocommerce.com/documentation/","kind":"website"}],"assignment":{"title_ar":"تكليف: التخصيص بالكود وبنية القالب","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_WP_L13_CustomisingWithCode\n\nالمطلوب:\n1️⃣ أنشئ قالباً فرعياً (Child Theme) وأضف عليه تعديلات CSS.\n2️⃣ استعرض بنية ملفات القالب ودور functions.php.\n3️⃣ عالج مشكلة تنسيق ناتجة عن ضغط الملفات (Minification).\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"الأكواد القصيرة والنسخ الاحتياطي والقوالب المدفوعة","title_en":"Shortcodes, Backups & Premium Themes","kind":"video","summary_ar":"يتناول هذا الدرس دمج كود خارجي في ووردبريس، والأكواد القصيرة (Shortcodes)، وأخذ النسخ الاحتياطية وربطها بالتخزين السحابي، والقوالب المدفوعة.","outcomes_ar":["دمج الكود الخارجي — شرح كيفية استخدام إضافة لإدراج أكواد HTML و CSS و JavaScript بشكل مباشر في الموقع، وكيفية تحويل الأكواد (مثل SCSS) إلى صيغ يفهمها المتصفح","استخدام الشورت كود (Shortcodes) — توضيح كيفية اختزال كتل الكود المعقدة في \"شورت كود\" بسيط يمكن استخدامه بسهولة داخل الصفحات","أخذ النسخ الاحتياطية (Backups) — شرح مفصل لاستخدام إضافة All-in-One WP Migration لأخذ نسخة احتياطية من الموقع بالكامل وكيفية استعادتها في حال حدوث أي عطل أو حذف للمحتوى","القوالب المدفوعة (Premium Themes) — مناقشة أهمية التحقق من أرقام إصدارات القوالب (Changelog) قبل تثبيتها لضمان التوافق مع إصدارات PHP والمميزات الجديدة","إضافات الجوجل درايف (Google Drive Extensions) — تجربة ربط النسخ الاحتياطي بخدمات التخزين السحابي لمواجهة مشاكل الحجم ومحدودية الرفع على السيرفرات"],"case_study_ar":"تحديث إضافة كسر الموقع قبل إطلاق حملة تسويقية بساعة.","case_question_ar":"ما خطتك للعودة السريعة؟","challenge_ar":"جدول نسخاً احتياطياً أسبوعياً تلقائياً.","videos":[{"title_ar":"المحاضرة — الأكواد القصيرة والنسخ الاحتياطي والقوالب المدفوعة","url":"https://youtu.be/KTkSF-g-cl4","description_ar":null}],"resources":[{"label":"Learn WordPress","url":"https://learn.wordpress.org/","kind":"website"},{"label":"WooCommerce documentation","url":"https://woocommerce.com/documentation/","kind":"website"}],"assignment":{"title_ar":"تكليف: الأكواد القصيرة والنسخ الاحتياطي والقوالب المدفوعة","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_WP_L14_ShortcodesBackupsPremium\n\nالمطلوب:\n1️⃣ اكتب Shortcode بسيطاً واستخدمه في صفحة.\n2️⃣ خذ نسخة احتياطية كاملة واستعدها على نسخة تجريبية.\n3️⃣ اربط النسخ الاحتياطي بالتخزين السحابي.\n\n📦 المطلوب تسليمه:\n📁 رابط مجلد Google Drive فيه تقرير PDF باسم TM-WP-L14.pdf\n✅ إجابات المطلوب والمخططات.\n📸 صور واضحة لكل خطوة.","required_evidence":["drive"],"is_required":true}},{"title_ar":"مشروع: موقع صحيفة احترافي بقالب مدفوع","title_en":"Project: A Professional News Site with a Premium Theme","kind":"video","summary_ar":"يقدم هذا الفيديو درساً عملياً حول كيفية استخدام القوالب المدفوعة (مثل قالب صحيفة) في ووردبريس لبناء موقع إلكتروني احترافي بالكامل في وقت قصير.","outcomes_ar":["إعداد الموقع — تم البدء بمسح محتويات الموقع القديم باستخدام إضافة WP Reset للحصول على نسخة نظيفة","تثبيت القالب — شرح كيفية رفع وتفعيل القالب المدفوع (مثل صحيفة) وأهمية قراءة ملف التوثيق (Documentation) المرفق معه","إدارة الإضافات — تثبيت الإضافات المطلوبة لتشغيل القالب، مثل الإضافات الخاصة بالتقييمات والشرائح (Sliders)","بناء الصفحة الرئيسية — استخدام أداة بناء الصفحات الخاصة بالقالب (Page Builder) لتصميم الواجهة، وإضافة عناصر مثل السلايدر، الأخبار، والتقسيمات","إدارة الويدجت والقوائم — تخصيص الشريط الجانبي (Sidebar) بإضافة أدوات لعرض منصات التواصل الاجتماعي، التبويبات، ونماذج تسجيل الدخول","تعديلات التصميم — تغيير اللوجو والأيقونة الخاصة بالموقع (Favicon) وضبط الإعدادات العامة للقالب"],"case_study_ar":"العميل يريد الموقع جاهزاً خلال ثلاثة أيام.","case_question_ar":"ما خطة العمل يوماً بيوم؟","challenge_ar":"حسّن نتيجة PageSpeed على الهاتف إلى 80 أو أكثر.","videos":[{"title_ar":"المحاضرة — مشروع: موقع صحيفة احترافي بقالب مدفوع","url":"https://youtu.be/S_m4CXSYpMI","description_ar":null}],"resources":[{"label":"Learn WordPress","url":"https://learn.wordpress.org/","kind":"website"},{"label":"WooCommerce documentation","url":"https://woocommerce.com/documentation/","kind":"website"}],"assignment":{"title_ar":"تكليف: مشروع: موقع صحيفة احترافي بقالب مدفوع","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_WP_L15_ProjectAProfessional\n\nالمطلوب:\n1️⃣ ابنِ موقع صحيفة كامل بقالب أخبار: صفحة رئيسية بأقسام، شريط عاجل، وودجت.\n2️⃣ اضبط الإضافات المطلوبة فقط واحذف غير المستخدم.\n3️⃣ اختبر الموقع على الهاتف وسرعته بـ PageSpeed Insights.\n4️⃣ سلّم رابط الموقع أو فيديو جولة فيه.\n\n📦 المطلوب تسليمه:\n📁 رابط مجلد Google Drive فيه تقرير PDF باسم TM-WP-L15.pdf\n✅ إجابات المطلوب والمخططات.\n📸 صور واضحة لكل خطوة.","required_evidence":["drive"],"is_required":true}}]}]}$course$::jsonb);

select public.import_course($course${"slug":"linq-adonet","title_ar":"الوصول للبيانات في ‎.NET: ADO.NET وLINQ","title_en":"Data Access in .NET: ADO.NET & LINQ","description_ar":"ميزات C# الحديثة التي يقوم عليها LINQ، ثم الاستعلام عن البيانات بـ LINQ، والاتصال بـ SQL Server عبر ADO.NET بالنمطين المتصل وغير المتصل والإجراءات المخزنة، وصولاً إلى تنظيم التطبيق في طبقات (N-Tier).","level":"intermediate","estimated_hours":18,"paths":[{"slug":"csharp-dotnet","required":true,"after":"csharp"}],"modules":[{"title_ar":"C# الحديثة وLINQ","lessons":[{"title_ar":"var والأنواع المجهولة وطرق التوسعة ومدخل LINQ","title_en":"var, Anonymous Types, Extension Methods & Intro to LINQ","kind":"video","summary_ar":"يقدم هذا الفيديو شرحاً وافياً ومبسطاً لمفاهيم أساسية في لغة البرمجة #C وLINQ، والتي تعد ضرورية للمطورين.","outcomes_ar":["الكلمة المفتاحية `var` — شرح كيفية استخدامها لتعريف المتغيرات بحيث يستنتج المترجم (Compiler) نوع البيانات تلقائياً، مع التأكيد على أنها تستخدم فقط للمتغيرات المحلية داخل الدوال","الأنواع غير المسماة `Anonymous Types` — توضيح كيفية إنشاء كائنات مؤقتة بدون الحاجة لتعريف فئة (Class) مسبقة، حيث يقوم المترجم بإنشائها في وقت التشغيل، وتتميز بأنها غير قابلة للتغيير (Immutable)","طرق التوسعة `Extension Methods` — شرح كيفية إضافة دوال جديدة لأنواع بيانات موجودة مسبقاً (مثل `int`) دون تعديل الكود المصدري الأصلي لها، مما يجعل الكود أكثر سهولة في القراءة والاستخدام","المندوبون الجاهزون `Delegates` — استعراض أنواع `Action` و `Func` و `Predicate` وكيفية استخدامها مع تعبيرات اللمدا (Lambda Expressions) لتسهيل تنفيذ الدوال","مدخل إلى `LINQ` — البدء في شرح تقنية `LINQ` التي تعتمد على مجموعة من طرق التوسعة (Extension Methods) لتنفيذ عمليات الاستعلام والفلترة على مجموعات البيانات بكفاءة عالية","التنفيذ المؤجل `Deferred Execution` — توضيح الفرق الجوهري بين التنفيذ المؤجل (حيث لا يتم تنفيذ الاستعلام إلا عند قراءة البيانات) والتنفيذ الفوري (Immediate Execution) باستخدام دوال مثل `.ToList()`"],"case_study_ar":"استعلام LINQ أعطى نتيجة مختلفة عن المتوقع لأن القائمة تغيّرت قبل المرور عليه.","case_question_ar":"ما التنفيذ المؤجل؟ وكيف تثبّت النتيجة (ToList)؟","challenge_ar":"اكتب Extension Method عامة WhereIf تطبّق الشرط فقط إذا تحقق شرط آخر.","videos":[{"title_ar":"المحاضرة — var والأنواع المجهولة وطرق التوسعة ومدخل LINQ","url":"https://youtu.be/ZNWcHeWxnkE","description_ar":null}],"resources":[{"label":"LINQ — Microsoft Learn","url":"https://learn.microsoft.com/dotnet/csharp/linq/","kind":"website"},{"label":"ADO.NET — Microsoft Learn","url":"https://learn.microsoft.com/dotnet/framework/data/adonet/","kind":"website"}],"assignment":{"title_ar":"تكليف: var والأنواع المجهولة وطرق التوسعة ومدخل LINQ","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_LINQ_L01_VarAnonymousTypes\n\nالمطلوب:\n1️⃣ اكتب Extension Method باسم IsValidEmail على string.\n2️⃣ أنشئ أنواعاً مجهولة من قائمة طلاب تعرض الاسم والمعدل فقط.\n3️⃣ استخدم Func وAction وPredicate في أمثلة قصيرة.\n4️⃣ جرّب التنفيذ المؤجل: عدّل القائمة بعد كتابة الاستعلام ولاحظ النتيجة.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"معاملات LINQ: الفلترة والإسقاط والترتيب والتقسيم","title_en":"LINQ Operators: Filtering, Projection, Ordering & Paging","kind":"video","summary_ar":"يقدم هذا الفيديو شرحاً شاملاً وتفصيلياً حول تقنية LINQ (Language Integrated Query) في لغة البرمجة C#، والتي تُستخدم للاستعلام عن البيانات من مصادر مختلفة.","outcomes_ar":["Fluent Syntax — وهي الطريقة الأكثر شيوعاً، حيث نستخدم الأوبجكت مع دالة التشغيل مباشرةً (مثل `.Where` أو `.Select`)","Query Syntax — تشبه لغة SQL وتستخدم كلمات مفتاحية مثل `from`, `where`, `select`","الفلترة (Filtering) — شرح كيفية استخدام `.Where` لتصفية البيانات","الإسقاط (Projection) — استخدام `.Select` لتحويل البيانات أو اختيار حقول معينة","الترتيب (Ordering) — استخدام `.OrderBy` و `.ThenBy` لترتيب البيانات","التقسيم والترقيم (Partitioning) — استخدام `.Take` و `.Skip` للتحكم في عدد العناصر المسترجعة، وهو أساس عملية الـ Pagination","الدوال التجميعية (Aggregation) — مثل `.Count`, `.Min`, `.Max`, `.Average` لحساب البيانات","دوال التعامل مع العناصر (Element Operators) — مثل `.First()`, `.FirstOrDefault()`, `.Single()` للوصول لعنصر محدد","التجميع (Grouping) — استخدام `GroupBy` لتنظيم البيانات بناءً على خاصية معينة","التنفيذ المؤجل (Deferred Execution) — توضيح أن الكويري لا يُنفذ إلا عند الحاجة إليه (أثناء الـ iteration)"],"case_study_ar":"صفحة منتجات تحمّل 50 ألف منتج دفعة واحدة.","case_question_ar":"كيف يساعد Skip/Take في الترقيم؟","challenge_ar":"نفّذ Join بين قائمتي طلاب ودورات بـ LINQ.","videos":[{"title_ar":"المحاضرة — معاملات LINQ: الفلترة والإسقاط والترتيب والتقسيم","url":"https://youtu.be/XPIOx0YF7_I","description_ar":null}],"resources":[{"label":"LINQ — Microsoft Learn","url":"https://learn.microsoft.com/dotnet/csharp/linq/","kind":"website"},{"label":"ADO.NET — Microsoft Learn","url":"https://learn.microsoft.com/dotnet/framework/data/adonet/","kind":"website"}],"assignment":{"title_ar":"تكليف: معاملات LINQ: الفلترة والإسقاط والترتيب والتقسيم","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_LINQ_L02_LINQOperatorsFiltering\n\nالمطلوب:\n1️⃣ على قائمة منتجات: Where وSelect وOrderBy وThenBy.\n2️⃣ نفّذ ترقيم صفحات بـ Skip وTake.\n3️⃣ اكتب الاستعلام نفسه بصيغة Fluent وصيغة Query.\n4️⃣ استخدم GroupBy وFirstOrDefault وAny وAll وSum.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}}]},{"title_ar":"ADO.NET","lessons":[{"title_ar":"مدخل ADO.NET وعمليات CRUD","title_en":"ADO.NET Basics & CRUD","kind":"video","summary_ar":"يقدم هذا الفيديو شرحاً عملياً وتفصيلياً لمبادئ ADO.NET وتطبيقاتها في بيئة عمل Visual Studio و SQL Server. يتناول هذا الدرس الفيديو المفاهيم الأساسية التي يحتاجها المطور للتعامل مع قواعد البيانات باستخدام تقنية C#.","outcomes_ar":["مقدمة في ADO.NET — يشرح الفيديو الفرق بين النمط المتصل (Connected Mode) والنمط غير المتصل (Disconnected Mode)","إعداد الاتصال — يوضح كيفية تعريف Connection String والاتصال بقاعدة بيانات SQL Server","استخدام SqlCommand لتنفيذ استعلامات مثل Select، Insert، و Delete","شرح أنواع التنفيذ المختلفة مثل `ExecuteReader` (للاستعلامات) و `ExecuteNonQuery` (للإضافة والحذف والتعديل)","استخدام SqlDataReader لقراءة البيانات وعرضها في DataGridView","تحسينات برمجية — يوضح الفيديو كيفية تخزين Connection String في ملف الإعدادات `App.config` لتسهيل صيانة التطبيق","ربط البيانات (Data Binding) — التعامل مع القوائم المنسدلة (ComboBox) وربطها ببيانات قاعدة البيانات لجعل الواجهة أكثر تفاعلية"],"case_study_ar":"سلسلة الاتصال مكتوبة داخل كل نموذج في التطبيق.","case_question_ar":"أين تضعها؟ وكيف تقرؤها مرة واحدة؟","challenge_ar":"أضف بحثاً لحظياً بالاسم أثناء الكتابة.","videos":[{"title_ar":"المحاضرة — مدخل ADO.NET وعمليات CRUD","url":"https://youtu.be/vEwOKdJ94og","description_ar":null}],"resources":[{"label":"LINQ — Microsoft Learn","url":"https://learn.microsoft.com/dotnet/csharp/linq/","kind":"website"},{"label":"ADO.NET — Microsoft Learn","url":"https://learn.microsoft.com/dotnet/framework/data/adonet/","kind":"website"}],"assignment":{"title_ar":"تكليف: مدخل ADO.NET وعمليات CRUD","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_LINQ_L03_ADONETBasics\n\nالمطلوب:\n1️⃣ أنشئ تطبيق Windows Forms متصلاً بقاعدة SQL Server.\n2️⃣ نفّذ Select وInsert وUpdate وDelete بـ SqlCommand.\n3️⃣ اعرض البيانات في DataGridView بـ SqlDataReader.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"الاتصال وتنفيذ الأوامر والنمط المتصل","title_en":"Connections, Commands & Connected Mode","kind":"video","summary_ar":"يقدم هذا الفيديو شرحاً عملياً حول كيفية التعامل مع قواعد البيانات (SQL Server) باستخدام لغة #C و تقنيات ADO.NET، وذلك ضمن سياق دورة LINQ لعام 2025.","outcomes_ar":["إعداد البيئة — شرح كيفية إضافة حزمة Microsoft.Data.SqlClient عبر NuGet Package Manager للاتصال بقاعدة البيانات","إنشاء الاتصال (Connection) — توضيح كيفية كتابة سلسلة الاتصال (Connection String) والتعامل مع أمن الويندوز (Integrated Security) للاتصال بقاعدة البيانات","تنفيذ الأوامر (SQL Commands) — كيفية إنشاء كائن SqlCommand لتنفيذ استعلامات مثل `SELECT`","قراءة البيانات (Connected Mode) — استخدام SqlDataReader لقراءة البيانات من الجدول (مثل `Department` و `Student`) بشكل سطري","إدارة الإعدادات — شرح أهمية استخدام ملفات JSON (مثل appsettings.json) لتخزين سلسلة الاتصال، مما يسهل تعديلها عند نشر التطبيق (Deployment) دون الحاجة لتغيير الكود","أدوات المساعدة — الإشارة إلى استخدام SQL Server Profiler لتتبع الأوامر التي يتم إرسالها لقاعدة البيانات"],"case_study_ar":"التطبيق يتوقف بعد ساعة عمل برسالة «انتهت مهلة الاتصال».","case_question_ar":"ما علاقة ذلك بالاتصالات غير المغلقة؟","challenge_ar":"اكتب كلاس مساعد DbHelper يقلّل التكرار.","videos":[{"title_ar":"المحاضرة — الاتصال وتنفيذ الأوامر والنمط المتصل","url":"https://youtu.be/r99N3qAv1uI","description_ar":null}],"resources":[{"label":"LINQ — Microsoft Learn","url":"https://learn.microsoft.com/dotnet/csharp/linq/","kind":"website"},{"label":"ADO.NET — Microsoft Learn","url":"https://learn.microsoft.com/dotnet/framework/data/adonet/","kind":"website"}],"assignment":{"title_ar":"تكليف: الاتصال وتنفيذ الأوامر والنمط المتصل","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_LINQ_L04_ConnectionsCommandsConnected\n\nالمطلوب:\n1️⃣ انقل سلسلة الاتصال إلى ملف الإعدادات.\n2️⃣ نفّذ ExecuteScalar وExecuteNonQuery وExecuteReader في أمثلة.\n3️⃣ أغلق الاتصالات بـ using وتحقق من ذلك.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"المعاملات والإجراءات المخزنة والنمط غير المتصل","title_en":"Parameters, Stored Procedures & Disconnected Mode","kind":"video","summary_ar":"يقدم هذا الفيديو شرحاً عملياً حول كيفية التعامل مع قواعد البيانات في بيئة .NET باستخدام ADO.NET، مع التركيز على نمطي الاتصال (Connected) وغير المتصل (Disconnected).","outcomes_ar":["العمليات الأساسية (CRUD) — شرح كيفية تنفيذ أوامر SQL (مثل `INSERT` و `UPDATE` و `DELETE`) باستخدام `SqlCommand`","استخدام المعاملات (Parameters) — التأكيد على أهمية استخدام المعاملات (`SqlParameter`) بدلاً من دمج النصوص المباشر لتجنب ثغرات SQL Injection","استخدام الإجراءات المخزنة (Stored Procedures) — توضيح كيفية استدعاء Stored Procedure وتعيين نوع الأمر إلى `CommandType.StoredProcedure`","جلب النتائج — استخدام `ExecuteScalar` لجلب القيم المفردة أو معرفات الهوية (Identity) بعد الإضافة","استخدام `SqlDataAdapter` — شرح كيفية استخدام `DataAdapter` و `DataTable` لجلب البيانات إلى الذاكرة دون الحاجة لبقاء الاتصال مفتوحاً","تحديث البيانات — كيفية تعديل البيانات في الذاكرة (`DataTable`) ثم مزامنتها مع قاعدة البيانات باستخدام `SqlCommandBuilder` و `Adapter.Update`","تم توضيح متطلبات المشروع العملي الذي يتضمن التعامل مع جدولين (Departments و Students) باستخدام النمطين"],"case_study_ar":"حقل بحث يقبل نصاً مثل ‎' OR 1=1 --‎ فيعرض كل البيانات.","case_question_ar":"ما الثغرة؟ وكيف تمنعها المعاملات؟","challenge_ar":"قارن في جدول بين النمط المتصل وغير المتصل: متى تستخدم كلاً منهما.","videos":[{"title_ar":"المحاضرة — المعاملات والإجراءات المخزنة والنمط غير المتصل","url":"https://youtu.be/7iPO9E0gjus","description_ar":null}],"resources":[{"label":"LINQ — Microsoft Learn","url":"https://learn.microsoft.com/dotnet/csharp/linq/","kind":"website"},{"label":"ADO.NET — Microsoft Learn","url":"https://learn.microsoft.com/dotnet/framework/data/adonet/","kind":"website"}],"assignment":{"title_ar":"تكليف: المعاملات والإجراءات المخزنة والنمط غير المتصل","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_LINQ_L05_ParametersStoredProcedures\n\nالمطلوب:\n1️⃣ حوّل كل الاستعلامات إلى استعلامات بمعاملات (SqlParameter).\n2️⃣ استدعِ Stored Procedure بمعاملات إدخال وإخراج.\n3️⃣ استخدم SqlDataAdapter وDataSet لتعديل البيانات دون اتصال ثم حفظها.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"من الكود المتكرر إلى الطبقات N-Tier","title_en":"From Repeated Code to N-Tier Architecture","kind":"video","summary_ar":"يقدم هذا الفيديو شرحاً عملياً لتطوير تطبيقات قواعد البيانات باستخدام ADO.NET، مع التركيز على الانتقال من الأكواد المتكررة إلى بنية برمجية منظمة باستخدام الطبقات (N-Tier Architecture).","outcomes_ar":["الفرق بين المودز (Modes) — استعراض الفرق بين الاتصال المباشر بقاعدة البيانات (Connected Mode) والعمل دون اتصال مستمر (Disconnected Mode) باستخدام DataTable و SqlDataAdapter","التعامل مع العمليات (CRUD) — كيفية تنفيذ عمليات الإضافة، التعديل، والحذف في الوضع غير المتصل، مع توضيح كيفية تتبع حالة الصفوف (Row State) لضمان تحديث قاعدة البيانات بشكل صحيح","طبقة قاعدة البيانات (Database Layer) — فصل كود التعامل مع SQL في فئة (Class) مستقلة لتقليل تكرار الكود","طبقة الأعمال (Business Layer) — إنشاء طبقة وسيطة تحتوي على منطق العمل والعمليات الخاصة بكل جدول، مما يجعل واجهة المستخدم (UI) نظيفة وخالية من كود الاستعلام المباشر","الاحترافية في البرمجة — نصائح حول تحويل هذه الطبقات إلى مكتبات برمجية (DLLs) لإعادة استخدامها في مشاريع مختلفة (مثل الويب أو تطبيقات سطح المكتب)"],"case_study_ar":"تغيير اسم عمود في القاعدة تطلّب تعديل 15 نموذجاً.","case_question_ar":"كيف كانت الطبقات ستحصر التعديل في مكان واحد؟","challenge_ar":"اكتب مخططاً يوضح تدفق طلب «إضافة موظف» عبر الطبقات.","videos":[{"title_ar":"المحاضرة — من الكود المتكرر إلى الطبقات N-Tier","url":"https://youtu.be/C6ZA8TttQTc","description_ar":null}],"resources":[{"label":"LINQ — Microsoft Learn","url":"https://learn.microsoft.com/dotnet/csharp/linq/","kind":"website"},{"label":"ADO.NET — Microsoft Learn","url":"https://learn.microsoft.com/dotnet/framework/data/adonet/","kind":"website"}],"assignment":{"title_ar":"تكليف: من الكود المتكرر إلى الطبقات N-Tier","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_LINQ_L06_FromRepeatedCode\n\nالمطلوب:\n1️⃣ أعد تنظيم التطبيق في طبقات: Data Access وBusiness وUI.\n2️⃣ انقل كل كود SQL إلى طبقة البيانات.\n3️⃣ أضف قواعد العمل (التحقق) في طبقة الأعمال.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}}]},{"title_ar":"LINQ مع قواعد البيانات والطبقات","lessons":[{"title_ar":"LINQ مع قواعد البيانات في Windows Forms","title_en":"LINQ with Databases in Windows Forms","kind":"video","summary_ar":"يقدم هذا الفيديو محاضرة تعليمية حول استخدام LINQ مع قواعد البيانات في تطبيقات Windows Forms، ويشرح الفروق بين طريقتي التعامل مع البيانات (النمط المتصل والنمط غير المتصل).","outcomes_ar":["التعامل مع قواعد البيانات — شرح المحاضر لكيفية تنفيذ المعاملات (Transactions) لضمان سلامة البيانات في حال حدوث أخطاء، وكيفية إعداد اتصال بقاعدة البيانات باستخدام ملفات الإعداد (appsettings.json)","النمط المتصل (Connected Mode) — استخدام SqlDataReader لجلب البيانات وعرضها في ListBox، مع توضيح كيفية ربط كائنات (Objects) من نوع Department بالواجهة، وإجراء عمليات التحديث (Update) مباشرة على قاعدة البيانات","النمط غير المتصل (Disconnected Mode) — استخدام SqlDataAdapter و DataTable لجلب البيانات محلياً، وشرح مفهوم الربط المعقد (Complex Data Binding)، وكيفية إجراء التغييرات في DataTable ثم مزامنتها مع قاعدة البيانات باستخدام S","التنقل بين البيانات — شرح كيفية استخدام BindingSource للتنقل بين السجلات (Next, Previous, First, Last) وتسهيل إدارة البيانات باستخدام BindingNavigator","تتضمن المحاضرة أمثلة عملية برمجية لكيفية بناء واجهات المستخدم والربط بين الكود وقاعدة البيانات خطوة بخطوة"],"case_study_ar":"بيانات محمّلة في الذاكرة وتحتاج تصفيتها بشروط متغيرة دون العودة للقاعدة.","case_question_ar":"كيف يخدمك LINQ هنا؟","challenge_ar":"أضف تصفية متعددة الشروط (قسم + راتب + اسم).","videos":[{"title_ar":"المحاضرة — LINQ مع قواعد البيانات في Windows Forms","url":"https://youtu.be/N-FaLbgfwsE","description_ar":null}],"resources":[{"label":"LINQ — Microsoft Learn","url":"https://learn.microsoft.com/dotnet/csharp/linq/","kind":"website"},{"label":"ADO.NET — Microsoft Learn","url":"https://learn.microsoft.com/dotnet/framework/data/adonet/","kind":"website"}],"assignment":{"title_ar":"تكليف: LINQ مع قواعد البيانات في Windows Forms","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_LINQ_L07_LINQWithDatabases\n\nالمطلوب:\n1️⃣ استعلم عن DataTable بـ LINQ (AsEnumerable).\n2️⃣ نفّذ التنقل بين السجلات (الأول، السابق، التالي، الأخير).\n3️⃣ قارن الاستعلام بـ SQL والاستعلام بـ LINQ على البيانات المحمّلة.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"DataGridView والتطبيق متعدد الطبقات","title_en":"DataGridView & a Multi-Tier App","kind":"video","summary_ar":"يقدم هذا الفيديو شرحاً عملياً حول كيفية التعامل مع Data Grid View في تطبيقات Windows Forms، مع التركيز على تنظيم الكود باستخدام هيكلية الطبقات (Multi-Tier Architecture) بدلاً من وضع كل شيء في واجهة المستخدم.","outcomes_ar":["التعامل مع واجهات العرض — شرح كيفية عرض البيانات في `Data Grid View`، وإضافة عناصر تحكم مخصصة مثل `ComboBox` داخل الأعمدة لربط البيانات","مشاكل الكود التقليدي — ناقش المحاضر أن كتابة الكود داخل واجهة المستخدم مباشرة يؤدي إلى ما يُعرف بـ Spaghetti Code، مما يجعل التعديل أو تغيير قاعدة البيانات أمراً صعباً","Data Access Layer (DAL) — المسؤولة عن الاتصال المباشر بقاعدة البيانات وتنفيذ الأوامر","Business Logic Layer (BLL) — الطبقة التي تحتوي على Entities (مثل Department و Student) والمنطق الخاص بالعمليات التجارية","UI Layer — الطبقة التي تتعامل فقط مع عرض البيانات واستقبال مدخلات المستخدم","العمليات (CRUD) — تم شرح كيفية تنفيذ عمليات الإضافة، الحذف، التعديل، والاستعلام (CRUD) باستخدام هذه الطبقات، وكيفية تحويل البيانات القادمة من قاعدة البيانات (DataTable) إلى كائنات برمجية (Objects) داخل قوائم (Lists)","نظرة مستقبلية — أشار المحاضر في النهاية إلى أن استخدام Entity Framework Core و LINQ يقلل من الوقت والمجهود المطلوب مقارنة بالعمل اليدوي باستخدام ADO.NET"],"case_study_ar":"الواجهة فيها كود SQL وتحقق ومنطق حساب الرواتب كله في حدث زر واحد.","case_question_ar":"كيف توزعه على الطبقات؟","challenge_ar":"استبدل طبقة البيانات بـ Entity Framework دون تغيير الواجهة.","videos":[{"title_ar":"المحاضرة — DataGridView والتطبيق متعدد الطبقات","url":"https://youtu.be/40-s8a-t7mQ","description_ar":null}],"resources":[{"label":"LINQ — Microsoft Learn","url":"https://learn.microsoft.com/dotnet/csharp/linq/","kind":"website"},{"label":"ADO.NET — Microsoft Learn","url":"https://learn.microsoft.com/dotnet/framework/data/adonet/","kind":"website"}],"assignment":{"title_ar":"تكليف: DataGridView والتطبيق متعدد الطبقات","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_LINQ_L08_DataGridViewAMulti\n\nالمطلوب:\n1️⃣ ابنِ تطبيق إدارة موظفين بثلاث طبقات وCRUD كامل.\n2️⃣ اعرض البيانات في DataGridView مع تعديل وحذف من الجدول.\n3️⃣ ارفع المشروع على GitHub مع README يشرح الطبقات.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}}]}]}$course$::jsonb);

select public.import_course($course${"slug":"aspnet-mvc","title_ar":"تطوير الويب بـ ASP.NET Core MVC","title_en":"Web Development with ASP.NET Core MVC","description_ar":"بناء تطبيقات ويب كاملة بـ ASP.NET Core MVC: بنية المشروع والمتحكمات وRazor، وEntity Framework Core بنهج Code First، وتمرير البيانات وربط النماذج، وTag Helpers والتخطيطات، والتحقق من البيانات، والـMiddleware وإدارة الحالة وحقن الاعتمادية وSOLID، والفلاتر وIdentity والأدوار، وPartial Views وAjax والتوجيه والنشر.","level":"intermediate","estimated_hours":50,"paths":[{"slug":"csharp-dotnet","required":true,"after":"linq-adonet"},{"slug":"back-end","required":false}],"modules":[{"title_ar":"أساسيات MVC","lessons":[{"title_ar":"مدخل الويب وASP.NET Core MVC","title_en":"The Web & ASP.NET Core MVC","kind":"video","summary_ar":"يقدم هذا الدرس مفاهيم الويب الأساسية: الخادم والعميل والطلب والاستجابة، والفرق بين تطبيقات سطح المكتب والويب، ثم نمط MVC ومميزات ASP.NET Core MVC.","outcomes_ar":["شرح الفرق بين تطبيقات Desktop و Web، مع توضيح مفهوم الخادم (Web Server)، العميل (Client)، وكيفية عمل الـ Request والـ Response","توضيح نوعين من التطوير — Full Web Application (دمج الباك والفرونت) مقابل Web API (تطوير الباك فقط لخدمة واجهات متعددة)","Model — للتعامل مع البيانات ومنطق الأعمال (Business Logic)","View — واجهة المستخدم (صفحات HTML)","Controller — الجسر الذي يربط بين الموديل والفيو ويدير الطلبات","التخلص من تعقيدات الـ Web Forms القديمة","تطبيق Routing Map لتنظيم الروابط بشكل نظيف وسهل بدلاً من المسارات الطويلة","استخدام Razor Engine لكتابة كود #C داخل صفحات الويب","توضيح خطوات البدء في إنشاء مشروع جديد عبر Visual Studio 2022، واختيار التنسيق الصحيح، وإعداد المجلدات الأساسية (Models, Views, Controllers) والملفات المطلوبة"],"case_study_ar":"فريق يناقش: Razor Pages أم MVC لموقع إدارة متجر؟","case_question_ar":"متى يكون MVC أنسب؟","challenge_ar":"أضف صفحة «عن المشروع» بمتحكم وعرض جديدين.","videos":[{"title_ar":"المحاضرة — مدخل الويب وASP.NET Core MVC","url":"https://youtu.be/x6TuKY4YMGo","description_ar":null}],"resources":[{"label":"قائمة تشغيل الدورة كاملة","url":"https://youtube.com/playlist?list=PLNFDrRZdysFzmzqno6G1EoxhIKo5sKiwL","kind":"website"},{"label":"ASP.NET Core MVC — Microsoft Learn","url":"https://learn.microsoft.com/aspnet/core/mvc/overview","kind":"website"},{"label":"Entity Framework Core — Microsoft Learn","url":"https://learn.microsoft.com/ef/core/","kind":"website"}],"assignment":{"title_ar":"تكليف: مدخل الويب وASP.NET Core MVC","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_MVC_L01_TheWebASP\n\nالمطلوب:\n1️⃣ أنشئ مشروع ASP.NET Core MVC وشغّله.\n2️⃣ ارسم دورة الطلب: المتصفح ← Controller ← Model ← View.\n3️⃣ اشرح الفرق بين مواقع ثابتة وديناميكية بمثال.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"بنية المشروع والمتحكمات وRazor","title_en":"Project Structure, Controllers & Razor","kind":"video","summary_ar":"يقدم هذا الفيديو شرحاً تعليمياً مفصلاً لأساسيات بناء تطبيقات الويب باستخدام ASP.NET Core MVC.","outcomes_ar":["هيكلية المشروع — تم استعراض المجلدات الأساسية مثل Models (لتمثيل البيانات)، Controllers (للتحكم في منطق العمل)، و Views (لواجهات المستخدم بصيغة `.cshtml`)","إعدادات التشغيل (Launch Settings) — شرح كيفية عمل Virtual Hosting أثناء التطوير باستخدام IIS Express أو Kestrel، وكيفية التحكم في منافذ التشغيل (Ports) عبر ملف `launchSettings.json`","المجلد `wwwroot` — تم توضيح أنه المكان المخصص للملفات الثابتة (Static Files) مثل الصور، ملفات CSS، و JavaScript، حيث لا يمكن الوصول لأي ملفات خارجية خارج هذا المجلد مباشرة","نقطة الدخول (Program.cs) — شرح دور ملف `Program.cs` في بناء وتشغيل التطبيق باستخدام نمط Builder Pattern","التحكم (Controllers) — توضيح أن Controllers ترث من `ControllerBase` للوصول إلى `HttpContext` و `Request` و `Response`، وكيفية إنشاء Actions (دوال) تعيد نتائج متنوعة مثل ViewResult أو ContentResult","محرك العرض (Razor Engine) — شرح كيفية كتابة كود C# داخل ملفات HTML باستخدام علامة `@`، وتطبيق مفاهيم مثل الجمل الشرطية (`if`) وحلقات التكرار (`loops`) لعرض البيانات ديناميكياً"],"case_study_ar":"ملف CSS لا يظهر رغم وجوده في المشروع.","case_question_ar":"أين يجب أن يكون؟ وما الـMiddleware المسؤول؟","challenge_ar":"أضف مسار تشغيل (Profile) للتطوير وآخر للإنتاج.","videos":[{"title_ar":"المحاضرة — بنية المشروع والمتحكمات وRazor","url":"https://youtu.be/-27vpRNDcBE","description_ar":null}],"resources":[{"label":"ASP.NET Core MVC — Microsoft Learn","url":"https://learn.microsoft.com/aspnet/core/mvc/overview","kind":"website"},{"label":"Entity Framework Core — Microsoft Learn","url":"https://learn.microsoft.com/ef/core/","kind":"website"}],"assignment":{"title_ar":"تكليف: بنية المشروع والمتحكمات وRazor","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_MVC_L02_ProjectStructureControllers\n\nالمطلوب:\n1️⃣ وضّح دور launchSettings وwwwroot وProgram.cs.\n2️⃣ أنشئ متحكماً بثلاث Actions تُرجع View وContent وJson.\n3️⃣ استخدم Razor لعرض قائمة بحلقة وشرط.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"Model وController وView عملياً","title_en":"Model, Controller & View in Practice","kind":"video","summary_ar":"يشرح هذا الفيديو كيفية بناء تطبيق باستخدام ASP.NET Core MVC، مع التركيز على المفاهيم الأساسية لهيكلة المشروع (Model, View, Controller).","outcomes_ar":["نموذج البيانات (Model) — تم إنشاء فئة (Class) باسم Student في مجلد Models تحتوي على خصائص مثل ID، الاسم، وصورة الطالب. كما تم إنشاء طبقة منطق الأعمال (Student Business Layer) للتعامل مع البيانات والعمليات مثل جلب جميع ال","المتحكم (Controller) — تم إنشاء StudentController يحتوي على دوال (Actions) لعرض صفحة قائمة الطلاب (ShowAll) وصفحة تفاصيل الطالب (Details)","العرض (View) — شرح كيفية إنشاء ملفات الـ Razor View لعرض البيانات، وكيفية التعامل مع الـ Model الممرر من المتحكم. كما تم توضيح كيفية عرض الصور من مجلد wwwroot باستخدام المسارات الصحيحة","التعامل مع البيانات — تم شرح استخدام الـ Dynamic في الـ View وكيفية تحويله إلى نوع محدد للتعامل مع البيانات بأمان وسهولة","طُلب من المتدربين إنشاء نموذج مشابه لمنتجات (Product) يحتوي على السعر، والقيام بعمليات العرض والتفاصيل مع إضافة روابط تنقل بين الصفحات"],"case_study_ar":"طلب تفاصيل منتج بمعرّف غير موجود يعرض صفحة خطأ.","case_question_ar":"كيف تعيد NotFound بشكل لائق؟","challenge_ar":"أضف تصفية القائمة حسب التصنيف عبر Query String.","videos":[{"title_ar":"المحاضرة — Model وController وView عملياً","url":"https://youtu.be/2eKNjQ7GPLQ","description_ar":null}],"resources":[{"label":"ASP.NET Core MVC — Microsoft Learn","url":"https://learn.microsoft.com/aspnet/core/mvc/overview","kind":"website"},{"label":"Entity Framework Core — Microsoft Learn","url":"https://learn.microsoft.com/ef/core/","kind":"website"}],"assignment":{"title_ar":"تكليف: Model وController وView عملياً","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_MVC_L03_ModelControllerView\n\nالمطلوب:\n1️⃣ أنشئ Model للمنتج وقائمة منتجات ثابتة.\n2️⃣ اعرض القائمة وصفحة تفاصيل لكل منتج.\n3️⃣ أضف رابطاً من القائمة للتفاصيل بالمعرّف.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"Entity Framework Core بنهج Code First","title_en":"Entity Framework Core — Code First","kind":"video","summary_ar":"يقدم هذا الفيديو ضمن سلسلة كورس ASP.NET Core MVC شرحاً عملياً للمهندسة كريستين حول كيفية التعامل مع قواعد البيانات باستخدام تقنية Entity Framework Core (نهج Code First).","outcomes_ar":["مفاهيم برمجية أساسية — توضيح الفرق بين Strongly Typed Views و Dynamic Models، وكيفية عمل Razor Syntax","شرح كيفية إعداد Entity Framework Core باستخدام Code First approach","كيفية تنزيل الحزم البرمجية (NuGet Packages) اللازمة للتعامل مع SQL Server","إنشاء كلاسات الموديل (Models) والعلاقات بينها مثل One-to-Many","ضبط الاتصال بقاعدة البيانات — شرح أهمية الـ Connection String وكيفية استخدام الميثود `OnConfiguring` لضبط إعدادات الربط","الهجرة (Migrations) — خطوات تنفيذ `Add-Migration` و `Update-Database` لتوليد الجداول في قاعدة البيانات","عرض البيانات (MVC Workflow) — إنشاء الـ Controller والـ View لاستعراض البيانات المخزنة من قاعدة البيانات في واجهة المستخدم، مع توضيح كيفية تجنب مشاكل الـ Lazy Loading باستخدام `Include`"],"case_study_ar":"أضفت خاصية للكيان ولم تظهر في القاعدة.","case_question_ar":"ما الخطوة الناقصة؟","challenge_ar":"أضف بيانات أولية (Seed) للأقسام.","videos":[{"title_ar":"المحاضرة — Entity Framework Core بنهج Code First","url":"https://youtu.be/STCcpDZvpGs","description_ar":null}],"resources":[{"label":"ASP.NET Core MVC — Microsoft Learn","url":"https://learn.microsoft.com/aspnet/core/mvc/overview","kind":"website"},{"label":"Entity Framework Core — Microsoft Learn","url":"https://learn.microsoft.com/ef/core/","kind":"website"}],"assignment":{"title_ar":"تكليف: Entity Framework Core بنهج Code First","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_MVC_L04_EntityFrameworkCore\n\nالمطلوب:\n1️⃣ أنشئ DbContext وكيانين بينهما علاقة One-to-Many (قسم وموظفون).\n2️⃣ نفّذ Migrations وأنشئ القاعدة.\n3️⃣ اعرض الموظفين مع أقسامهم بـ Include.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"تمرير البيانات: ViewData وViewBag وViewModel","title_en":"Passing Data: ViewData, ViewBag & ViewModel","kind":"video","summary_ar":"يقدم هذا الفيديو محاضرة تعليمية حول تطوير تطبيقات الويب باستخدام ASP.NET Core MVC، مع التركيز على كيفية تمرير البيانات من Controller إلى View بأساليب مختلفة.","outcomes_ar":["دورة حياة الطلب (Request Lifecycle) — تم توضيح كيف يقوم الخادم بإنشاء نسخة جديدة من الـ Controller مع كل طلب","ViewData — استخدامها لتمرير بيانات إضافية بجانب الموديل، وهي تعتمد على Dictionary وتتطلب تحويلاً للأنواع (Type Casting)","ViewBag — أداة ديناميكية لتمرير البيانات وتعتبر أسهل في التعامل من ViewData لأنها تتجنب التحويل الصريح للأنواع، لكنها تفتقر إلى ميزة IntelliSense","ViewModel — هي الطريقة الاحترافية والأفضل، حيث يتم إنشاء كلاس خاص يجمع البيانات المطلوبة للـ View في كبسولة واحدة، مما يوفر أماناً أقوى للأنواع (Strongly Typed)"],"case_study_ar":"صفحة تحتاج بيانات من ثلاثة جداول وتستخدم ViewBag لكل شيء.","case_question_ar":"ما مشكلة ذلك؟ وكيف يحلها ViewModel؟","challenge_ar":"أنشئ لوحة إحصاءات بسيطة بـ ViewModel واحد.","videos":[{"title_ar":"المحاضرة — تمرير البيانات: ViewData وViewBag وViewModel","url":"https://youtu.be/zs0xHqf-TV0","description_ar":null}],"resources":[{"label":"ASP.NET Core MVC — Microsoft Learn","url":"https://learn.microsoft.com/aspnet/core/mvc/overview","kind":"website"},{"label":"Entity Framework Core — Microsoft Learn","url":"https://learn.microsoft.com/ef/core/","kind":"website"}],"assignment":{"title_ar":"تكليف: تمرير البيانات: ViewData وViewBag وViewModel","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_MVC_L05_PassingDataViewData\n\nالمطلوب:\n1️⃣ مرّر عنواناً بـ ViewData وعدداً بـ ViewBag.\n2️⃣ أنشئ ViewModel يجمع بيانات الموظف وقائمة الأقسام.\n3️⃣ اشرح لماذا يُفضّل ViewModel في الشاشات المعقدة.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}}]},{"title_ar":"النماذج والتحقق","lessons":[{"title_ar":"ربط النماذج Model Binding","title_en":"Model Binding","kind":"video","summary_ar":"يقدم هذا الفيديو شرحاً عملياً حول كيفية التعامل مع البيانات المرسلة من واجهة المستخدم (Front-end) إلى جانب الخادم (Back-end) في إطار عمل ASP.NET Core MVC. يركز هذا الدرس الشرح على عملية \"ربط النموذج\" (Model Binding) وكيفية استقبال البيانات من النماذج (Forms) في صفحات HTML ومعالجتها داخل المتحكم (Controller).","outcomes_ar":["مفاهيم ربط البيانات (Model Binding) — شرح كيفية قيام إطار العمل تلقائياً بربط بيانات الطلب (سواء كانت من Query String أو Form Data) بمتغيرات أو كائنات (Objects) في دوال الـ Controller","أنواع البيانات المدعومة — استعراض كيفية استقبال أنواع بيانات بسيطة (Primitive types)، ومصفوفات (Arrays)، وكائنات معقدة (Custom Classes)","التطبيق العملي (إضافة قسم جديد) — تم بناء سيناريو كامل لإضافة \"قسم\" (Department) جديد، يتضمن إنشاء رابط في صفحة الـ Index للانتقال لصفحة الإدخال، ثم معالجة البيانات عبر دالة `Save`","تحسين تجربة المستخدم — مناقشة كيفية الاحتفاظ بالبيانات المدخلة في حال حدوث خطأ في التحقق (Validation) لمنع مسح الحقول، واستخدام خاصية الـ Null-conditional operator لضمان عدم ظهور أخطاء عند تحميل الصفحة لأول مرة","استخدام الميثود (POST) — تحويل إرسال البيانات من GET إلى POST لزيادة الأمان وتنظيم إرسال البيانات عبر الـ Form Body بدلاً من الرابط"],"case_study_ar":"تحديث الصفحة بعد الإضافة يضيف القسم مرة ثانية.","case_question_ar":"كيف يمنع نمط PRG ذلك؟","challenge_ar":"استقبل بيانات من Route وQuery وForm في Action واحد ووضّح المصدر.","videos":[{"title_ar":"المحاضرة — ربط النماذج Model Binding","url":"https://youtu.be/MoUm7jufrkM","description_ar":null}],"resources":[{"label":"ASP.NET Core MVC — Microsoft Learn","url":"https://learn.microsoft.com/aspnet/core/mvc/overview","kind":"website"},{"label":"Entity Framework Core — Microsoft Learn","url":"https://learn.microsoft.com/ef/core/","kind":"website"}],"assignment":{"title_ar":"تكليف: ربط النماذج Model Binding","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_MVC_L06_ModelBinding\n\nالمطلوب:\n1️⃣ أنشئ نموذج إضافة قسم يرسل POST.\n2️⃣ استقبل البيانات بأنواع مختلفة (بسيطة، كائن، مجموعة).\n3️⃣ أعد التوجيه بعد الحفظ (Post-Redirect-Get).\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"التعديل والإضافة والقوائم المنسدلة","title_en":"Edit, Add & Dropdown Lists","kind":"video","summary_ar":"يدور هذا الفيديو حول تطوير تطبيقات ويب باستخدام ASP.NET Core MVC، حيث يركز على كيفية إدارة طلبات التعديل (Edit) والإضافة (Add) والتحقق من صحة البيانات.","outcomes_ar":["إدارة طلبات HTTP — شرحت المحاضرة الفرق بين استخدام `GET` و `POST`. من الضروري استخدام `[HttpPost]` فوق أكشن التعديل أو الحفظ لحماية قاعدة البيانات من الطلبات غير المصرح بها","يتم استرجاع بيانات العنصر (مثل الموظف) باستخدام `ID` وعرضها في نموذج (Form) للتحرير","تستخدم نماذج عرض (View Models) لنقل البيانات بين الكنترولر والفيو","استخدام القوائم المنسدلة (Dropdown Lists) — تم شرح كيفية إنشاء قوائم منسدلة لاختيار العناصر المرتبطة (مثل القسم) بدلاً من إدخال الرقم يدوياً، مع ربط قيمة الاختيار بـ `ID` الصحيح لضمان دقة البيانات","تجنب الأخطاء البرمجية — تم التركيز على أهمية التحقق من وجود البيانات قبل حفظها (`context.SaveChanges()`) واستخدام `Try-Catch` للتعامل مع الاستثناءات"],"case_study_ar":"المستخدم عدّل موظفاً فتغيّرت بيانات موظف آخر.","case_question_ar":"ما الخطأ المحتمل في تمرير المعرّف؟","challenge_ar":"أضف تأكيد حذف بصفحة مستقلة.","videos":[{"title_ar":"المحاضرة — التعديل والإضافة والقوائم المنسدلة","url":"https://youtu.be/_swGzrWITCw","description_ar":null}],"resources":[{"label":"ASP.NET Core MVC — Microsoft Learn","url":"https://learn.microsoft.com/aspnet/core/mvc/overview","kind":"website"},{"label":"Entity Framework Core — Microsoft Learn","url":"https://learn.microsoft.com/ef/core/","kind":"website"}],"assignment":{"title_ar":"تكليف: التعديل والإضافة والقوائم المنسدلة","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_MVC_L07_EditAddDropdown\n\nالمطلوب:\n1️⃣ نفّذ Edit كاملاً (GET وPOST) للموظف.\n2️⃣ أضف قائمة منسدلة للأقسام بـ SelectList.\n3️⃣ عالج حالة عدم وجود السجل.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"HTML Helpers وTag Helpers","title_en":"HTML Helpers & Tag Helpers","kind":"video","summary_ar":"يقدم هذا الفيديو شرحاً تقنياً حول كيفية استخدام مساعدات HTML و مساعدات الوسوم (Tag Helpers) في إطار عمل ASP.NET Core MVC.","outcomes_ar":["مساعدات HTML (HTML Helpers) — شرحت المحاضرة كيفية استخدام دوال C# داخل ملفات الـ View لتوليد كود HTML (مثل `TextBox` و `Label`) لضمان الربط الصحيح للبيانات بين الواجهة والخلفية","المساعدات ذات النوع القوي (Strongly Typed Helpers) — توضيح كيفية استخدامها لتقليل الأخطاء عبر الاعتماد على تعريفات الموديل (Model) واستخدام تعبيرات Lambda (مثل `TextBoxFor`)","تخصيص العرض (Display Attributes) — كيفية التحكم في تسمية الحقول وتنسيقها باستخدام سمات مثل `[Display]`","مساعدات الوسوم (Tag Helpers) — الانتقال إلى الطريقة الحديثة والأسهل، وهي استخدام سمات جانب السيرفر (Server-side attributes) تبدأ بـ `asp-` داخل وسوم HTML القياسية، مما يجعل الكود أكثر نظافة وقابلية للقراءة","روابط الصفحات والأكشن — شرح كيفية إنشاء روابط (Links) ونماذج (Forms) باستخدام `asp-action` و `asp-controller` و `asp-route` بدلاً من كتابة الروابط يدوياً"],"case_study_ar":"تغيير اسم Action كسر عشرين رابطاً مكتوباً يدوياً.","case_question_ar":"كيف تحمي Tag Helpers من ذلك؟","challenge_ar":"اكتب Tag Helper مخصصاً بسيطاً.","videos":[{"title_ar":"المحاضرة — HTML Helpers وTag Helpers","url":"https://youtu.be/ToNdnc1vwUY","description_ar":null}],"resources":[{"label":"ASP.NET Core MVC — Microsoft Learn","url":"https://learn.microsoft.com/aspnet/core/mvc/overview","kind":"website"},{"label":"Entity Framework Core — Microsoft Learn","url":"https://learn.microsoft.com/ef/core/","kind":"website"}],"assignment":{"title_ar":"تكليف: HTML Helpers وTag Helpers","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_MVC_L08_HTMLHelpersTag\n\nالمطلوب:\n1️⃣ أعد كتابة نموذج بـ HTML Helpers ثم بـ Tag Helpers.\n2️⃣ استخدم Display وDisplayName لتسميات عربية.\n3️⃣ أنشئ روابط بـ asp-action وasp-route.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"التخطيطات والأقسام والقوالب الجاهزة","title_en":"Layouts, Sections & Templates","kind":"video","summary_ar":"يقدم هذا الفيديو شرحاً عملياً لتطوير تطبيقات الويب باستخدام تقنية ASP.NET Core MVC، مع التركيز على تحسين واجهة المستخدم وتنظيم الكود.","outcomes_ar":["شرح كيفية استخدام الـ Tag Helpers بدلاً من الـ HTML Helpers التقليدية في بناء النماذج (Forms) لإضافة الموظفين، مما يجعل الكود أنظف وأسهل في القراءة","كيفية ربط البيانات (Binding) مع الموديلات واستخدام Data Validation","كيفية تعبئة القوائم المنسدلة للتعامل مع العلاقات بين الجداول (مثل Departments) باستخدام ViewBag أو ViewData وتنسيقها بشكل احترافي","كيفية استخدام `RenderBody` لتحديد مكان ظهور محتوى كل صفحة داخل الـ Layout","تعلم كيفية استخدام `RenderSection` لإنشاء مناطق ديناميكية داخل التصميم، مما يتيح لكل صفحة إضافة أكواد خاصة (مثل الجافا سكريبت) في أماكن محددة","خطوات تحميل واستخدام قوالب Bootstrap جاهزة ودمجها في المشروع، مع معالجة المسارات (Paths) للصور والملفات (103:00 - 115:00)","يركز الفيديو على بناء هيكل متين لمشروع MVC، مع تقديم تلميحات إضافية حول التحديات البرمجية مثل رفع الصور (Image Upload) والتحقق من الحذف (Delete Confirmation) كتكليف إضافي (Bonus) للمتدربين"],"case_study_ar":"كل صفحة تكرر الرأس والتذييل كاملين.","case_question_ar":"كيف يحل Layout ذلك؟","challenge_ar":"أضف Layout ثانياً للوحة الإدارة.","videos":[{"title_ar":"المحاضرة — التخطيطات والأقسام والقوالب الجاهزة","url":"https://youtu.be/0i4aFoO6_-Y","description_ar":null}],"resources":[{"label":"ASP.NET Core MVC — Microsoft Learn","url":"https://learn.microsoft.com/aspnet/core/mvc/overview","kind":"website"},{"label":"Entity Framework Core — Microsoft Learn","url":"https://learn.microsoft.com/ef/core/","kind":"website"}],"assignment":{"title_ar":"تكليف: التخطيطات والأقسام والقوالب الجاهزة","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_MVC_L09_LayoutsSectionsTemplates\n\nالمطلوب:\n1️⃣ أنشئ Layout رئيسياً بقائمة وتذييل.\n2️⃣ استخدم RenderSection لسكريبتات خاصة بصفحة.\n3️⃣ طبّق قالب HTML جاهزاً على المشروع.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"التحقق من البيانات","title_en":"Validation","kind":"video","summary_ar":"يقدم هذا الفيديو شرحاً تعليمياً حول التحقق من صحة البيانات (Validation) في تطبيقات ASP.NET Core MVC.","outcomes_ar":["مشكلة التحقق التقليدي — ناقشت المحاضرة كيف كان المطورون يكتبون شروط التحقق يدوياً داخل دوال الـ `Post` (مثل التأكد من أن الحقل ليس فارغاً)، وهو أسلوب غير فعال ويصعب صيانته وتوحيده","`[Required]` للتأكد من إدخال البيانات","`[Range]` لتحديد نطاق الأرقام (مثل العمر)","`[StringLength]` لتحديد طول النصوص","`[RegularExpression]` للتحقق من تنسيق البيانات (مثل البريد الإلكتروني أو الصور)","دور المتحكم (Controller) — شرحت المحاضرة أن المتحكم يتحقق من صحة البيانات من خلال الخاصية `ModelState.IsValid` قبل المتابعة في عملية الحفظ في قاعدة البيانات","عرض الأخطاء في الواجهة (View) — قدمت المحاضرة كيفية استخدام `Tag Helpers` في ملفات `Razor` (مثل `asp-validation-for`) لعرض رسائل الخطأ للمستخدم بشكل تلقائي وجميل","تخصيص الرسائل — أشارت المحاضرة إلى إمكانية تعديل رسائل الخطأ الافتراضية لتكون أكثر وضوحاً للمستخدم النهائي بدلاً من الرسائل التقنية المعقدة"],"case_study_ar":"التحقق يعمل في المتصفح فقط، وأحدهم أرسل الطلب مباشرة.","case_question_ar":"لماذا يجب التحقق في الخادم دائماً؟","challenge_ar":"خصّص رسائل الخطأ بالعربية.","videos":[{"title_ar":"المحاضرة — التحقق من البيانات","url":"https://youtu.be/PZ-FDS8TpLM","description_ar":null}],"resources":[{"label":"ASP.NET Core MVC — Microsoft Learn","url":"https://learn.microsoft.com/aspnet/core/mvc/overview","kind":"website"},{"label":"Entity Framework Core — Microsoft Learn","url":"https://learn.microsoft.com/ef/core/","kind":"website"}],"assignment":{"title_ar":"تكليف: التحقق من البيانات","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_MVC_L10_Validation\n\nالمطلوب:\n1️⃣ أضف Data Annotations (Required وRange وEmailAddress وStringLength).\n2️⃣ تحقق من ModelState في المتحكم.\n3️⃣ اعرض الأخطاء بجانب الحقول وفي ملخص.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"التحقق المخصص وRemote Validation","title_en":"Custom & Remote Validation","kind":"video","summary_ar":"يقدم هذا الفيديو شرحاً مفصلاً ومتقدماً حول كيفية إدارة التحقق من البيانات (Validation) في تطبيقات ASP.NET Core MVC. يركز هذا الدرس الفيديو على عدة جوانب تقنية رئيسية.","outcomes_ar":["التحقق المخصص (Custom Validation) — ناقشت المحاضرة طرقاً متنوعة لإنشاء قواعد تحقق خاصة تتجاوز الأدوات الجاهزة (Data Annotations)، مثل استخدام `Model State` في `Controller` أو إنشاء `Validation Attribute` مخصص","التحقق من جانب العميل (Client-side Validation) — شرح الفيديو كيفية تفعيل التحقق في المتصفح باستخدام مكتبات jQuery Validation و Unobtrusive Validation، لضمان استجابة سريعة للمستخدم دون الحاجة لإعادة تحميل الصفحة","استخدام خاصية Remote Validation — تم عرض كيفية استخدام سمة `[Remote]` للقيام بعمليات تحقق معقدة (مثل الاتصال بقاعدة البيانات للتحقق من عدم تكرار الاسم) عبر طلبات `AJAX` في الوقت الفعلي","أفضل الممارسات — تم التأكيد على ضرورة الجمع بين التحقق من جانب العميل (لتحسين تجربة المستخدم) والتحقق من جانب الخادم (لضمان أمن وسلامة البيانات)","كما تطرق الفيديو في النهاية إلى بعض النصائح حول التعامل مع التغييرات في قاعدة البيانات (Migrations)"],"case_study_ar":"المستخدم يكتشف أن بريده مستخدم فقط بعد إرسال النموذج كاملاً.","case_question_ar":"كيف يحسّن Remote التجربة؟","challenge_ar":"نفّذ IValidatableObject لتحقق يعتمد على أكثر من حقل.","videos":[{"title_ar":"المحاضرة — التحقق المخصص وRemote Validation","url":"https://youtu.be/XyovCXynEX8","description_ar":null}],"resources":[{"label":"ASP.NET Core MVC — Microsoft Learn","url":"https://learn.microsoft.com/aspnet/core/mvc/overview","kind":"website"},{"label":"Entity Framework Core — Microsoft Learn","url":"https://learn.microsoft.com/ef/core/","kind":"website"}],"assignment":{"title_ar":"تكليف: التحقق المخصص وRemote Validation","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_MVC_L11_CustomRemoteValidation\n\nالمطلوب:\n1️⃣ اكتب Attribute تحقق مخصصاً (مثل عمر لا يقل عن 18).\n2️⃣ فعّل التحقق في المتصفح.\n3️⃣ استخدم Remote للتحقق من عدم تكرار البريد.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}}]},{"title_ar":"بنية التطبيق","lessons":[{"title_ar":"الـMiddleware وخط المعالجة","title_en":"Middleware & the Request Pipeline","kind":"video","summary_ar":"يقدم هذا الفيديو شرحاً تقنياً لمفهوم الـ Middleware (البرمجيات الوسيطة) في إطار عمل ASP.NET Core MVC. يركز هذا الدرس الشرح على كيفية معالجة طلبات الويب (HTTP Requests) في التطبيق.","outcomes_ar":["مفهوم الـ Pipeline — يشرح الفيديو أن خط معالجة الطلبات (HTTP Request Pipeline) يتكون من مجموعة من المكونات (Middleware) التي يتم ترتيبها بتسلسل معين","الميدل وير المدمج (Built-in) — وهي مكونات جاهزة توفرها Microsoft للتعامل مع مهام مثل معالجة الاستثناءات (Exception Handling)، الملفات الثابتة (Static Files)، والتوثيق (Authentication)","الميدل وير المخصص (Custom Middleware) — يمكن للمطور كتابة كود خاص به باستخدام دوال مثل `Use` لتنفيذ كود وإرسال الطلب للمكون التالي، أو `Run` لإنهاء الطلب، أو `Map` لتوجيه الطلب بناءً على المسار","آلية العمل — يوضح الفيديو كيفية عمل الميدل وير كمصفوفة من الدوال (Delegates) حيث يقوم كل جزء بمعالجة الطلب ثم تمريره للذي يليه، أو اتخاذ قرار بـ \"تقصير الدائرة\" (Short-circuiting) ومنع وصول الطلب للمكونات التالية","أهمية الترتيب — يتم التأكيد مراراً على أن ترتيب وضع الميدل وير في الكود أمر حيوي جداً، حيث يؤثر على أداء التطبيق وسلوكه"],"case_study_ar":"المصادقة لا تعمل رغم إضافتها.","case_question_ar":"كيف يؤثر ترتيب UseAuthentication وUseAuthorization؟","challenge_ar":"أضف Middleware يعرض صفحة صيانة عند تفعيل إعداد.","videos":[{"title_ar":"المحاضرة — الـMiddleware وخط المعالجة","url":"https://youtu.be/PMXatB02SWc","description_ar":null}],"resources":[{"label":"ASP.NET Core MVC — Microsoft Learn","url":"https://learn.microsoft.com/aspnet/core/mvc/overview","kind":"website"},{"label":"Entity Framework Core — Microsoft Learn","url":"https://learn.microsoft.com/ef/core/","kind":"website"}],"assignment":{"title_ar":"تكليف: الـMiddleware وخط المعالجة","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_MVC_L12_MiddlewareTheRequest\n\nالمطلوب:\n1️⃣ ارسم ترتيب الـMiddleware في Program.cs.\n2️⃣ اكتب Middleware مخصصاً يسجل زمن كل طلب.\n3️⃣ جرّب تغيير الترتيب ولاحظ الأثر.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"إدارة الحالة: Session وCookies","title_en":"State Management: Session & Cookies","kind":"video","summary_ar":"يقدم هذا الفيديو شرحاً تعليمياً حول مفهوم إدارة الحالة (State Management) في إطار العمل ASP.NET Core MVC.","outcomes_ar":["شرح كيفية عمل الخادم (Server) وعدم احتفاظه بالبيانات بين الطلبات (Requests) المتتالية، حيث يقوم بتدمير الكائن (Object) الخاص بالـ Controller بعد إتمام كل طلب لتوفير الموارد","تشبيه العملية ببنك أو مطعم يحتاج فيه النظام إلى وسيلة للتعرف على المستخدم (عبر Session ID أو Cookies) للحفاظ على بياناته","كيفية إنشاء قنوات اتصال (Channels) لكل مستخدم لربط البيانات به","خطوات تفعيل الـ Session في تطبيق ASP.NET Core، بما في ذلك إضافة الـ Middleware الخاص بالـ Session وتعديل الإعدادات في ملف Program.cs (مثل تغيير وقت انتهاء الجلسة Idle Timeout)","كيفية تخزين وقراءة البيانات (مثل الأسماء والأرقام) باستخدام `SetString` و `SetInt32` و `GetString` و `GetInt32`","شرح الفرق بين تخزين البيانات في Session (جانب الخادم) مقابل Cookies (جانب المتصفح/العميل)","الفرق بين Session Cookies (التي تنتهي بانتهاء الجلسة) و Persistent Cookies (التي لها وقت محدد للبقاء)","كيفية إنشاء والتحكم في إعدادات الكوكيز باستخدام `CookieOptions`","توضيح كيفية تطبيق ما تم شرحه عبر أمثلة عملية","تحديد مهام برمجية (Assignments) للطلاب تتعلق باسترجاع بيانات الطلاب والكورسات من قاعدة البيانات وتنسيق النتائج في الواجهة (View) بناءً على حالة الطالب (ناجح/راسب)"],"case_study_ar":"سلة المشتريات تختفي عند إعادة تشغيل الخادم.","case_question_ar":"لماذا؟ وما البدائل؟","challenge_ar":"أضف TempData لرسالة نجاح بعد الحفظ.","videos":[{"title_ar":"المحاضرة — إدارة الحالة: Session وCookies","url":"https://youtu.be/LEB2TC99Vgc","description_ar":null}],"resources":[{"label":"ASP.NET Core MVC — Microsoft Learn","url":"https://learn.microsoft.com/aspnet/core/mvc/overview","kind":"website"},{"label":"Entity Framework Core — Microsoft Learn","url":"https://learn.microsoft.com/ef/core/","kind":"website"}],"assignment":{"title_ar":"تكليف: إدارة الحالة: Session وCookies","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_MVC_L13_StateManagementSession\n\nالمطلوب:\n1️⃣ احفظ سلة مشتريات في Session.\n2️⃣ احفظ تفضيل اللغة في Cookie.\n3️⃣ اشرح الفرق بينهما في الأمان والمدة.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"حقن الاعتمادية وIoC","title_en":"Dependency Injection & IoC","kind":"video","summary_ar":"يقدم هذا الفيديو شرحاً وافياً ومبسطاً لمفاهيم حقن الاعتمادية (Dependency Injection) و عكس التحكم (Inversion of Control - IoC) في إطار عمل ASP.NET Core MVC، وذلك من خلال تشبيهات واقعية (مثل تحضير حقيبة السفر) لتوضيح كيفية إدارة الكائنات والخدمات.","outcomes_ar":["مبدأ حقن الاعتمادية — توضيح أهمية عدم جعل الفئات (Classes) تعتمد على بعضها البعض بشكل مباشر، واستخدام الواجهات (Interfaces) كوسيط","آلية عمل الـ IoC Container — شرح دور Service Provider في إدارة وتوليد الكائنات (Resolve) بدلاً من أن يقوم المبرمج بإنشائها يدوياً (New)","أنواع الخدمات — التمييز بين الخدمات المدمجة (Built-in services) مثل IConfiguration والخدمات التي تحتاج إلى تسجيل (Register)","Singleton — كائن واحد لكل التطبيق","Transient — كائن جديد في كل مرة يتم طلبه","Scoped — كائن واحد خلال الطلب (Request) الواحد","التعامل مع قواعد البيانات — كيفية إعداد DbContext لاستخدام حقن الاعتمادية وقراءة سلسلة الاتصال (Connection String) من ملف appsettings.json بدلاً من كتابتها برمجياً (Hard-coding)"],"case_study_ar":"خدمة Singleton تستخدم DbContext فظهرت أخطاء متفرقة.","case_question_ar":"لماذا؟ وما نمط التسجيل الصحيح؟","challenge_ar":"اكتب خدمة إشعارات بواجهة وبدّل تنفيذها من الإعدادات.","videos":[{"title_ar":"المحاضرة — حقن الاعتمادية وIoC","url":"https://youtu.be/B4bzJWXfV7A","description_ar":null}],"resources":[{"label":"ASP.NET Core MVC — Microsoft Learn","url":"https://learn.microsoft.com/aspnet/core/mvc/overview","kind":"website"},{"label":"Entity Framework Core — Microsoft Learn","url":"https://learn.microsoft.com/ef/core/","kind":"website"}],"assignment":{"title_ar":"تكليف: حقن الاعتمادية وIoC","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_MVC_L14_DependencyInjectionIoC\n\nالمطلوب:\n1️⃣ سجّل خدمة بالأنماط الثلاثة Singleton وScoped وTransient.\n2️⃣ اعرض رقماً عشوائياً من كل خدمة في طلبين ولاحظ الفرق.\n3️⃣ احقن DbContext في خدمة بدل إنشائه.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"إعادة الهيكلة ومبادئ SOLID","title_en":"Refactoring & SOLID","kind":"video","summary_ar":"يشرح هذا الدرس إعادة هيكلة مشروع MVC وتطبيق مبادئ SOLID الخمسة عملياً لكود أسهل في الصيانة والاختبار.","outcomes_ar":["إعادة هيكلة المشروع — ناقشت المحاضرة أهمية الانتقال من كتابة منطق العمل (Business Logic) داخل المتحكمات (Controllers) مباشرة إلى استخدام نمط Repository Pattern، وذلك لفصل المسؤوليات (Separation of Concerns) وتجنب تكرار ا","Single Responsibility Principle (SRP) — بحيث يكون لكل كلاس وظيفة واحدة محددة","Open/Closed Principle (OCP) — تصميم الكلاسات لتكون مفتوحة للتوسع ومغلقة للتعديل","Liskov Substitution Principle (LSP) — لضمان إمكانية استبدال الكلاس الأساسي بالأنواع المشتقة منه دون مشاكل","Interface Segregation Principle (ISP) — تقسيم الانترفيسات الكبيرة إلى أصغر وأكثر تخصصاً","Dependency Inversion Principle (DIP) — الاعتماد على التجريد (Abstractions) بدلاً من الكلاسات الملموسة لتسهيل صيانة الكود","التطبيق العملي — قامت المحاضرة بتحويل التعامل مع البيانات من الاتصال المباشر بقاعدة البيانات داخل الـ Controller إلى استخدام Interfaces و Repositories، مما يسهل عملية الاختبار (Testing) ويجعل الكود أكثر مرونة"],"case_study_ar":"متحكم من 600 سطر يتعامل مع القاعدة والملفات والبريد.","case_question_ar":"كيف تقسّمه وفق SRP؟","challenge_ar":"أضف اختبار وحدة لخدمة واحدة باستخدام Mock.","videos":[{"title_ar":"المحاضرة — إعادة الهيكلة ومبادئ SOLID","url":"https://youtu.be/dHgTIio9qMY","description_ar":null}],"resources":[{"label":"ASP.NET Core MVC — Microsoft Learn","url":"https://learn.microsoft.com/aspnet/core/mvc/overview","kind":"website"},{"label":"Entity Framework Core — Microsoft Learn","url":"https://learn.microsoft.com/ef/core/","kind":"website"}],"assignment":{"title_ar":"تكليف: إعادة الهيكلة ومبادئ SOLID","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_MVC_L15_RefactoringSOLID\n\nالمطلوب:\n1️⃣ أعد هيكلة المشروع: Repository وServices وواجهات.\n2️⃣ طبّق كل مبدأ من SOLID في مكان واحد على الأقل ووثّقه.\n3️⃣ أزل أي استخدام مباشر لـ DbContext من المتحكمات.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}}]},{"title_ar":"الأمان والتفاعل والنشر","lessons":[{"title_ar":"الفلاتر وASP.NET Identity","title_en":"Filters & ASP.NET Identity","kind":"video","summary_ar":"يقدم هذا الفيديو شرحاً مفصلاً ومتقدماً حول موضوعين أساسيين في تطوير تطبيقات ASP.NET Core MVC.","outcomes_ar":["تم شرح ماهية الفلاتر ككتل برمجية تُنفذ قبل أو بعد أو أثناء تنفيذ إجراء معين (Action) داخل دورة حياة التطبيق","الفرق الجوهري بين الميدل وير (Middleware) والفلاتر، حيث تعمل الفلاتر على مستوى أكشن بايب لاين (Action Pipeline) الخاص بـ MVC","أنواع الفلاتر — تم التطرق إلى الفلاتر المدمجة (مثل الفلاتر الخاصة بالاستثناءات Exception Filters) وكيفية إنشاء فلاتر مخصصة (Custom Filters) وتنفيذها على مستوى الأكشن، أو الكنترولر، أو على مستوى التطبيق بالكامل (Global Fi","نظام الهوية والأمان (ASP.NET Identity) — (48:10 - نهاية الفيديو)","شرح كيفية إدارة المستخدمين، الأدوار (Roles)، والمطالبات (Claims) باستخدام نظام Identity","توضيح مفهوم Code-First في بناء قواعد البيانات، وكيفية ربط الجداول (Users, Roles) بنظام التطبيق","خطوات عملية لإنشاء نظام تسجيل دخول وتسجيل مستخدمين جديد، مع شرح كيفية التعامل مع تشفير كلمات المرور (Password Hashing) وتخزين البيانات بشكل آمن","استخدام Manager classes مثل `UserManager` و `SignInManager` لإدارة عمليات المستخدمين وتخزين ملفات تعريف الارتباط (Cookies)"],"case_study_ar":"الكود نفسه لتسجيل الأخطاء مكرر في كل Action.","case_question_ar":"كيف يزيل Filter هذا التكرار؟","challenge_ar":"أضف Filter يمنع الوصول خارج ساعات العمل.","videos":[{"title_ar":"المحاضرة — الفلاتر وASP.NET Identity","url":"https://youtu.be/6cXLwk971S8","description_ar":null}],"resources":[{"label":"ASP.NET Core MVC — Microsoft Learn","url":"https://learn.microsoft.com/aspnet/core/mvc/overview","kind":"website"},{"label":"Entity Framework Core — Microsoft Learn","url":"https://learn.microsoft.com/ef/core/","kind":"website"}],"assignment":{"title_ar":"تكليف: الفلاتر وASP.NET Identity","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_MVC_L16_FiltersASPNET\n\nالمطلوب:\n1️⃣ اكتب Action Filter يسجل الطلبات وException Filter يعالج الأخطاء.\n2️⃣ أضف Identity للمشروع وأنشئ صفحة تسجيل.\n3️⃣ احمِ متحكماً بـ Authorize.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"تسجيل الدخول والخروج والـClaims","title_en":"Login, Logout & Claims","kind":"video","summary_ar":"يشرح هذا الدرس بناء تسجيل الدخول والخروج بـ ASP.NET Identity، وحماية الصفحات بـ Authorize، وإعداد المصادقة في Program.cs، واستخدام الـClaims.","outcomes_ar":["معالجة مشاكل كلمة المرور — أوضحت المحاضرة أن المشكلة في تسجيل المستخدمين كانت ناتجة عن استخدام إصدار (Overload) غير صحيح من `UserManager` لا يقوم بتشفير كلمة المرور. تم توضيح كيفية تعديل إعدادات التشفير والقيود الخاصة بك","إدارة الجلسات وتسجيل الخروج — شرحت كيفية تنفيذ عملية `SignOut` بشكل صحيح لضمان تدمير ملف تعريف الارتباط (Cookie) ومنع الوصول غير المصرح به","تم استخدام خاصية `[Authorize]` لمنع المستخدمين غير المسجلين من الوصول لصفحات معينة","تم توضيح كيفية إضافة وسيط `UseAuthentication` في ملف `Program.cs` لتمكين النظام من قراءة بيانات المستخدم","إنشاء نظام تسجيل الدخول (Login) — تم بناء نموذج `LoginViewModel` والتعامل مع التحقق من بيانات المستخدم في قاعدة البيانات ومقارنة كلمة المرور المشفرة باستخدام `CheckPasswordAsync`","استخدام الكلايمز (Claims) — شرحت المحاضرة أن ASP.NET يقوم بتخزين بيانات المستخدم (مثل الهوية والاسم) في `Claims` داخل الـ `Cookie` تلقائياً بعد تسجيل الدخول، وكيفية استرجاع هذه البيانات برمجياً داخل الكنترولر"],"case_study_ar":"المستخدم يبقى مسجلاً للأبد على جهاز مشترك.","case_question_ar":"كيف تضبط مدة الجلسة وخيار «تذكرني»؟","challenge_ar":"أضف قفل الحساب بعد 5 محاولات فاشلة.","videos":[{"title_ar":"المحاضرة — تسجيل الدخول والخروج والـClaims","url":"https://youtu.be/GV0qER8HXuw","description_ar":null}],"resources":[{"label":"ASP.NET Core MVC — Microsoft Learn","url":"https://learn.microsoft.com/aspnet/core/mvc/overview","kind":"website"},{"label":"Entity Framework Core — Microsoft Learn","url":"https://learn.microsoft.com/ef/core/","kind":"website"}],"assignment":{"title_ar":"تكليف: تسجيل الدخول والخروج والـClaims","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_MVC_L17_LoginLogoutClaims\n\nالمطلوب:\n1️⃣ نفّذ تسجيل الدخول والخروج.\n2️⃣ أضف Claims (الاسم الكامل والقسم) واعرضها في الواجهة.\n3️⃣ عالج كلمة مرور خاطئة برسالة واضحة.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"الأدوار وAnti-Forgery","title_en":"Roles & Anti-Forgery Tokens","kind":"video","summary_ar":"يقدم هذا الفيديو شرحاً تقنياً متقدماً حول كيفية إدارة الهوية (Identity) في تطبيقات ASP.NET Core MVC.","outcomes_ar":["إضافة معلومات إضافية (Claims) — شرح كيفية إضافة بيانات إضافية (مثل العنوان) إلى ملف تعريف المستخدم (Cookie) أثناء عملية تسجيل الدخول باستخدام `SignInManager.SignInWithClaimsAsync`، بدلاً من الاكتفاء بالبيانات الافتراضية","تخصيص الواجهة (Layout) — كيفية التحكم في ظهور روابط التنقل (Navigation links) في واجهة المستخدم بناءً على حالة تسجيل الدخول، واستخدام خصائص مثل `User.Identity.IsAuthenticated` لعرض محتوى مخصص","إدارة الأدوار (Roles) — خطوات إنشاء نظام للأدوار (Roles) مثل \"Admin\" وتعيينها للمستخدمين باستخدام `RoleManager`، مع شرح كيفية تقييد الوصول لبعض الصفحات أو الروابط بحيث لا يراها إلا مستخدمون بصلاحيات معينة","الحماية من الثغرات (Anti-Forgery Tokens) — شرح أهمية استخدام `[ValidateAntiForgeryToken]` في ميثودات الـ `POST` للحماية من هجمات تزوير الطلبات عبر المواقع (CSRF)، وكيفية عمل التوكن الخفي الذي يضمن أن الطلب قادم من الموقع"],"case_study_ar":"موظف عادي فتح رابط صفحة الإدارة مباشرة ونجح.","case_question_ar":"ما الحماية الناقصة؟","challenge_ar":"أنشئ صفحة لإدارة أدوار المستخدمين.","videos":[{"title_ar":"المحاضرة — الأدوار وAnti-Forgery","url":"https://youtu.be/RPuKLVxSnRk","description_ar":null}],"resources":[{"label":"ASP.NET Core MVC — Microsoft Learn","url":"https://learn.microsoft.com/aspnet/core/mvc/overview","kind":"website"},{"label":"Entity Framework Core — Microsoft Learn","url":"https://learn.microsoft.com/ef/core/","kind":"website"}],"assignment":{"title_ar":"تكليف: الأدوار وAnti-Forgery","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_MVC_L18_RolesAntiForgery\n\nالمطلوب:\n1️⃣ أنشئ دوري Admin وEmployee وامنح كل دور صفحات مختلفة.\n2️⃣ خصّص القائمة حسب الدور.\n3️⃣ اشرح هجوم CSRF وكيف يحمي منه Anti-Forgery Token.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"Partial Views وAjax","title_en":"Partial Views & Ajax","kind":"video","summary_ar":"يشرح هذا الدرس تقسيم الصفحات إلى Partial Views وطرق استدعائها، والفرق بين الطلب العادي وطلب Ajax، وتحديث أجزاء من الصفحة دون إعادة تحميلها.","outcomes_ar":["شرح أهمية استخدام \"الـ Partial View\" لتقسيم الأكواد الطويلة في الصفحات (مثل Layout أو الصفحات التي تحتوي على كود مكرر)","كيفية إنشائها وتسميتها (يُفضل البدء بـ `_`) وكيفية استدعائها باستخدام طرق مختلفة مثل `Partial Tag Helper` أو `PartialAsync`","توضيح الفرق بين طلبات HTTP العادية (التي تعيد تحميل الصفحة بالكامل) وطلبات الـ Ajax (التي تسمح بتحديث أجزاء معينة من الصفحة)","ربط الـ Ajax مع الـ Partial View لجلب بيانات من السيرفر وعرضها في الصفحة دون إعادة تحميلها","ناقشت المحاضرة أيضاً كيف يمكن أن يعيد الـ Action في الـ Controller نوع `PartialView` بدلاً من `View` عادية، ومناقشة الفرق في التعامل مع البيانات (سواء إرجاع `HTML` أو `JSON` لاحقاً لتطوير واجهة المستخدم بشكل مرن)","وصل الفيديو حالياً إلى مرحلة مناقشة كيفية إرجاع بيانات بصيغة JSON لتسهيل التعامل معها برمجياً في الواجهة (الفرونت إند) بدلاً من الاعتماد الكلي على الـ Partial View الثابتة"],"case_study_ar":"الصفحة كلها تُعاد تحميلها لإضافة تعليق واحد.","case_question_ar":"كيف يحسّن Ajax التجربة؟","challenge_ar":"أضف ترقيم صفحات بـ Ajax.","videos":[{"title_ar":"المحاضرة — Partial Views وAjax","url":"https://youtu.be/bnNqwDBYqeA","description_ar":null}],"resources":[{"label":"ASP.NET Core MVC — Microsoft Learn","url":"https://learn.microsoft.com/aspnet/core/mvc/overview","kind":"website"},{"label":"Entity Framework Core — Microsoft Learn","url":"https://learn.microsoft.com/ef/core/","kind":"website"}],"assignment":{"title_ar":"تكليف: Partial Views وAjax","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_MVC_L19_PartialViewsAjax\n\nالمطلوب:\n1️⃣ استخرج بطاقة المنتج إلى Partial View.\n2️⃣ حمّل قائمة التعليقات بـ Ajax دون إعادة تحميل الصفحة.\n3️⃣ أضف بحثاً لحظياً بـ Ajax.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"Ajax والتوجيه والنشر","title_en":"Ajax, Routing & Deployment","kind":"video","summary_ar":"يقدم هذا الفيديو، شرحاً تقنياً متقدماً حول عدة مواضيع برمجية هامة.","outcomes_ar":["شرح كيفية جلب البيانات من السيرفر وعرضها في الصفحة دون الحاجة لإعادة تحميلها (Refresh)","توضيح كيفية إنشاء `Endpoint` تعيد بيانات بصيغة JSON ليتم معالجتها باستخدام JavaScript أو jQuery لعرضها في عناصر مثل القوائم المنسدلة (Dropdown Lists)","شرح مفهوم المابنج (Mapping) وكيفية توجيه الروابط (URLs) للوصول إلى المتحكمات (Controllers) والأكشنز (Actions)","كيفية تخصيص الروابط (Custom Routing) لتبدو أكثر وضوحاً واحترافية، والتعامل مع البارامترات الاختيارية والقيود (Constraints)","توضيح كيفية تحويل المشروع إلى ملفات قابلة للنشر (Publishing) ورفعها على السيرفر","شرح الفرق بين Framework-dependent و Self-contained عند عمل الببلش","تحديد التكليفات المطلوبة للمتدربين حول استخدام AJAX في مشاريعهم، بالإضافة إلى التنبيه لموعد تسليم المشاريع النهائية"],"case_study_ar":"التطبيق يعمل على جهازك ويظهر خطأ 500 بعد النشر.","case_question_ar":"كيف تبحث عن السبب (السجلات، سلسلة الاتصال، البيئة)؟","challenge_ar":"أضف صفحة خطأ مخصصة لبيئة الإنتاج.","videos":[{"title_ar":"المحاضرة — Ajax والتوجيه والنشر","url":"https://youtu.be/jZznjPipO3k","description_ar":null}],"resources":[{"label":"ASP.NET Core MVC — Microsoft Learn","url":"https://learn.microsoft.com/aspnet/core/mvc/overview","kind":"website"},{"label":"Entity Framework Core — Microsoft Learn","url":"https://learn.microsoft.com/ef/core/","kind":"website"}],"assignment":{"title_ar":"تكليف: Ajax والتوجيه والنشر","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_MVC_L20_AjaxRoutingDeployment\n\nالمطلوب:\n1️⃣ عرّف مسارات مخصصة بـ Attribute Routing.\n2️⃣ انشر التطبيق (IIS أو خدمة سحابية مجانية) مع قاعدة بياناته.\n3️⃣ وثّق خطوات النشر في README.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}}]}]}$course$::jsonb);

select public.import_course($course${"slug":"aspnet-core","title_ar":"بناء واجهات API بـ ASP.NET Core","title_en":"Building Web APIs with ASP.NET Core","description_ar":"من SOAP إلى REST وبناء Web API بـ ASP.NET Core: مبادئ HTTP ورموز الحالة وCRUD، وDTOs ومشكلة التسلسل، وربط الواجهات بالـAPI وCORS وSwagger، وRepository وUnit of Work وحقن الاعتمادية، والتأمين بـ JWT، والاستضافة على IIS. كل درس بتسجيلين من دفعتين مختلفتين.","level":"intermediate","estimated_hours":24,"paths":[],"modules":[{"title_ar":"أساسيات Web API","lessons":[{"title_ar":"من SOAP إلى REST: لماذا Web API","title_en":"From SOAP to REST: Why Web APIs","kind":"video","summary_ar":"يقدم هذا الفيديو محاضرة تعريفية حول تطور الـ Web APIs، موبايل، سطح مكتب) باستخدام تقنيات مختلفة.","outcomes_ar":["المشكلة الأساسية — صعوبة التواصل بين التطبيقات المختلفة (مثل Java و C#) وتنوع قواعد البيانات، مما استدعى وجود معايير موحدة لتبادل البيانات","نموذج SOAP — شرح المحاضر كيف كان يُستخدم سابقاً مع XML و WSDL للربط بين الأنظمة، لكنه كان معقداً وثقيلاً","نموذج REST — هو التوجه الحديث الذي يعتمد على بروتوكول HTTP، مما يجعل التواصل أخف وأسرع وأسهل للمطورين، باستخدام JSON أو XML","تطور تقنيات مايكروسوفت — استعرض المحاضر الانتقال من تقنية WCF (التي كانت تعاني من تعقيد الإعدادات) إلى ASP.NET Web API في عام 2012، والتي جعلت بناء الخدمات أسهل بكثير","التعامل مع الـ APIs — أوضح المحاضر أن بناء الـ API يعتمد على تقليل الاعتماد على الـ Views في نمط MVC والتركيز على الـ Controllers، مع استخدام أفعال HTTP (مثل GET, POST, PUT, DELETE) لتحديد العمليات المطلوبة"],"case_study_ar":"تطبيق ويب وتطبيق هاتف وتطبيق سطح مكتب يحتاجون البيانات نفسها.","case_question_ar":"كيف يخدمهم API واحد؟","challenge_ar":"صمّم ترقيم الصفحات والتصفية في روابط الـAPI.","videos":[{"title_ar":"الشرح الأول — من SOAP إلى REST: لماذا Web API","url":"https://youtu.be/vEbyuSPYkBo","description_ar":null},{"title_ar":"الشرح الثاني — تسجيل من دفعة أخرى","url":"https://youtu.be/NvAuzQV2ax4","description_ar":null}],"resources":[{"label":"ASP.NET Core Web API — Microsoft Learn","url":"https://learn.microsoft.com/aspnet/core/web-api/","kind":"website"},{"label":"Swagger / OpenAPI in ASP.NET Core","url":"https://learn.microsoft.com/aspnet/core/tutorials/web-api-help-pages-using-swagger","kind":"website"}],"assignment":{"title_ar":"تكليف: من SOAP إلى REST: لماذا Web API","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_API_L01_FromSOAPTo\n\nالمطلوب:\n1️⃣ اكتب مقارنة بين SOAP وREST في جدول.\n2️⃣ صمّم نقاط نهاية (Endpoints) RESTful لنظام مكتبة: المسارات والأفعال ورموز الحالة.\n3️⃣ جرّب API عاماً بـ Postman ووثّق طلبين.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"مشروع Web API وCRUD ورموز الحالة","title_en":"Your First Web API: CRUD & Status Codes","kind":"video","summary_ar":"يقدم هذا الفيديو محاضرة تقنية حول تطوير واجهات برمجة التطبيقات (Web API) في بيئة ASP.NET، حيث يركز على الانتقال من الأنماط التقليدية إلى بنية RESTful الحديثة.","outcomes_ar":["مقدمة عن الـ API — شرح المحاضر كيف تطورت الحاجة إلى الـ API لحل مشاكل التكامل بين تطبيقات مختلفة","مبادئ HTTP — تم التركيز على أهمية استخدام أفعال HTTP (GET, POST, PUT, DELETE) بشكل صحيح لتنفيذ عمليات الـ CRUD، وكيفية استجابة السيرفر عبر أكواد الحالة (Status Codes) مثل 200 و201 و404","إعدادات المشروع — استعرض الفيديو إعدادات ملف Program.cs، ودور Swagger في توثيق وتجربة الـ API، بالإضافة إلى كيفية التعامل مع السلاسل النصية للاتصال بقواعد البيانات (Connection Strings)","التعامل مع البيانات — تم تطبيق دوال لجلب البيانات، إضافة بيانات جديدة (POST)، وتعديلها (PUT)، مع توضيح الفرق بين إرسال البيانات عبر المسار (URL) أو عبر جسم الطلب (Request Body)","أدوات الاختبار — أشار المحاضر إلى استخدام أدوات مثل Swagger وFiddler لاختبار الطلبات وفهم هيكلية الـ JSON المتبادل بين العميل والسيرفر","اختتمت المحاضرة بتكليف عملي للطلاب يتضمن بناء API خاص بجدول Courses لتطبيق المبادئ التي تم شرحها"],"case_study_ar":"API يرجع 200 دائماً حتى عند الخطأ مع رسالة نصية.","case_question_ar":"لماذا يربك ذلك العملاء؟","challenge_ar":"أضف تحققاً من المدخلات بإرجاع ValidationProblem.","videos":[{"title_ar":"الشرح الأول — مشروع Web API وCRUD ورموز الحالة","url":"https://youtu.be/wysuMzMZabk","description_ar":null},{"title_ar":"الشرح الثاني — تسجيل من دفعة أخرى","url":"https://youtu.be/iTuW3K0_lGE","description_ar":null}],"resources":[{"label":"ASP.NET Core Web API — Microsoft Learn","url":"https://learn.microsoft.com/aspnet/core/web-api/","kind":"website"},{"label":"Swagger / OpenAPI in ASP.NET Core","url":"https://learn.microsoft.com/aspnet/core/tutorials/web-api-help-pages-using-swagger","kind":"website"}],"assignment":{"title_ar":"تكليف: مشروع Web API وCRUD ورموز الحالة","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_API_L02_YourFirstWeb\n\nالمطلوب:\n1️⃣ أنشئ مشروع Web API متصلاً بقاعدة بيانات بـ EF Core.\n2️⃣ نفّذ CRUD كاملاً لكيان واحد.\n3️⃣ أرجع رموز الحالة الصحيحة: 200 و201 و204 و400 و404.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"DTOs ومشكلة التسلسل","title_en":"DTOs & the Serialization Problem","kind":"video","summary_ar":"يقدم هذا الفيديو محاضرة تقنية حول تطوير تطبيقات الويب باستخدام ASP.NET Core Web API، مع التركيز على التعامل مع البيانات والعلاقات بين الجداول.","outcomes_ar":["إعداد المشروع — مراجعة سريعة لإنشاء مشروع API، وتهيئة Entity Framework، وضبط سلاسل الاتصال بقاعدة البيانات","مشكلة التسلسل (Serialization) — شرح مشكلة التكرار اللانهائي (Circular Reference Exception) عند التعامل مع العلاقات بين الجداول (مثل Student و Department) وكيفية حلها باستخدام مكتبة Newtonsoft.Json وضبط إعدادات الـ Refere","استخدام DTOs (Data Transfer Objects) — توضيح أهمية الـ DTOs لفصل طبقة البيانات عن واجهة المستخدم، مما يحسن الأداء، يقلل من حجم البيانات المرسلة، ويحل مشاكل الـ Serialization بشكل جذري","تقنيات إضافية — مناقشة مفاهيم مثل Pagination (التقسيم إلى صفحات) للتعامل مع البيانات الضخمة، واستخدام الأوسمة (Attributes) مثل Consumes و Produces للتحكم في أنواع البيانات المتبادلة","مستقبل الويب — لمحة عن مفهوم Modern Web وأهمية بناء واجهات خلفية تعتمد على API لتكون جاهزة للتعامل مع مختلف المنصات"],"case_study_ar":"الـAPI يرجع كلمة مرور المستخدم المشفرة ضمن الرد.","case_question_ar":"كيف تمنع DTOs تسرب البيانات؟","challenge_ar":"أضف Attributes للتحكم في أسماء الحقول في JSON.","videos":[{"title_ar":"الشرح الأول — DTOs ومشكلة التسلسل","url":"https://youtu.be/lGeX4SwrlLQ","description_ar":null},{"title_ar":"الشرح الثاني — تسجيل من دفعة أخرى","url":"https://youtu.be/3tNWL7r_FMc","description_ar":null}],"resources":[{"label":"ASP.NET Core Web API — Microsoft Learn","url":"https://learn.microsoft.com/aspnet/core/web-api/","kind":"website"},{"label":"Swagger / OpenAPI in ASP.NET Core","url":"https://learn.microsoft.com/aspnet/core/tutorials/web-api-help-pages-using-swagger","kind":"website"}],"assignment":{"title_ar":"تكليف: DTOs ومشكلة التسلسل","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_API_L03_DTOsTheSerialization\n\nالمطلوب:\n1️⃣ أنشئ علاقة بين كيانين وواجه مشكلة الحلقة في التسلسل.\n2️⃣ حلّها بـ DTOs بدل إرجاع الكيانات مباشرة.\n3️⃣ استخدم Select أو AutoMapper للتحويل.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}}]},{"title_ar":"العملاء والتوثيق","lessons":[{"title_ar":"ربط الواجهات بالـAPI وCORS وSwagger","title_en":"Consuming the API, CORS & Swagger","kind":"video","summary_ar":"يقدم هذا الفيديو محاضرة تقنية متخصصة حول كيفية بناء واجهات مستخدم (UI) تتفاعل مع واجهات برمجة التطبيقات (API).","outcomes_ar":["يوضح المحاضر أن أي واجهة مستخدم (سواء كانت تعتمد على C# أو JavaScript) تحتاج إلى طريقتين للتعامل مع الـ API: إرسال طلبات (HTTP Requests) ومعالجة بيانات JSON","يشرح كيفية استخدام لغة C# في تطبيقات سطح المكتب أو تطبيقات أخرى لاستهلاك البيانات عبر تحويل (Deserialize) بيانات الـ JSON إلى كائنات برمجية (Objects)","يخصص المحاضر جزءاً كبيراً لمشكلة سياسة مشاركة الموارد عبر المصادر (CORS) التي تواجه مطوري الويب عند استخدام تقنية AJAX مع الـ API، ويوضح أن المتصفح يقوم بحظر هذه الطلبات لأسباب أمنية ما لم يتم السماح بها في إعدادات الـ A","يبين كيفية تفعيل وإعداد الـ CORS في الـ API الخاص بـ .NET","يناقش أهمية إثراء توثيق الـ API ليكون أكثر وضوحاً للمطورين، وذلك من خلال إضافة وصف للفانكشنز (Functions)، والباراميترز (Parameters)، واستخدام تعليقات XML","يستعرض أدوات إضافية مثل Swashbuckle.Annotations لإضافة وصف دقيق للعمليات والردود"],"case_study_ar":"الواجهة تظهر خطأ CORS في المتصفح بينما Postman يعمل.","case_question_ar":"لماذا يحدث ذلك في المتصفح فقط؟","challenge_ar":"احمِ صفحة Swagger بحيث لا تظهر في الإنتاج.","videos":[{"title_ar":"الشرح الأول — ربط الواجهات بالـAPI وCORS وSwagger","url":"https://youtu.be/bjSe5WVGHeg","description_ar":null},{"title_ar":"الشرح الثاني — تسجيل من دفعة أخرى","url":"https://youtu.be/e9dt2Bb8AYQ","description_ar":null}],"resources":[{"label":"ASP.NET Core Web API — Microsoft Learn","url":"https://learn.microsoft.com/aspnet/core/web-api/","kind":"website"},{"label":"Swagger / OpenAPI in ASP.NET Core","url":"https://learn.microsoft.com/aspnet/core/tutorials/web-api-help-pages-using-swagger","kind":"website"}],"assignment":{"title_ar":"تكليف: ربط الواجهات بالـAPI وCORS وSwagger","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_API_L04_ConsumingTheAPI\n\nالمطلوب:\n1️⃣ اكتب صفحة HTML بـ fetch أو jQuery تعرض بيانات الـAPI وتضيف عليها.\n2️⃣ فعّل CORS لنطاق الواجهة فقط.\n3️⃣ وثّق الـAPI بـ Swagger مع وصف لكل نقطة.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}}]},{"title_ar":"البنية الاحترافية","lessons":[{"title_ar":"Repository Pattern وحقن الاعتمادية","title_en":"Repository Pattern & Dependency Injection","kind":"video","summary_ar":"يقدم هذا الفيديو شرحاً تقنياً متقدماً حول أفضل الممارسات (Best Practices) لبناء واجهات برمجة التطبيقات (Web API) باستخدام لغة C# وإطار عمل ASP.NET Core.","outcomes_ar":["نمط المستودع (Repository Pattern) — تم شرح كيفية فصل منطق الاستعلام عن البيانات (Queries) عن منطق التحكم (Controller)، مما يجعل الكود أكثر تنظيماً ويمنع تكرار الاستعلامات","حقن الاعتمادية (Dependency Injection) — توضيح أهمية حقن الاعتمادات بدلاً من إنشائها داخل الكنترولر، واستخدام مفهوم انعكاس الاعتمادية (Dependency Inversion) من خلال الواجهات (Interfaces) لتقليل الاقتران بين أجزاء التطبيق","المستودع العام (Generic Repository) — استعراض كيفية إنشاء مستودع عام يدعم أي نوع من البيانات (Entities) لتجنب كتابة كود مكرر لكل جدول في قاعدة البيانات، مع الحفاظ على القدرة على تخصيص المستودعات عند الحاجة","معالجة البيانات (Data Handling) — تم التطرق إلى تحويل البيانات باستخدام الـ DTOs، وكيفية التعامل مع قاعدة البيانات سواءً بطريقة مباشرة أو عبر قوائم ثابتة (Static Lists) لأغراض الاختبار","يهدف الفيديو في نهايته إلى جعل المتدربين قادرين على بناء بنية تطبيق احترافية (مثل Onion Architecture) تجعل التطبيق مرناً وقابلاً للتوسع"],"case_study_ar":"متحكمان يكرران الاستعلام نفسه بطريقتين مختلفتين.","case_question_ar":"كيف يوحدهما Repository؟","challenge_ar":"أضف دالة بحث عامة بشرط (Expression) في Generic Repository.","videos":[{"title_ar":"الشرح الأول — Repository Pattern وحقن الاعتمادية","url":"https://youtu.be/RHH3pBeRoY0","description_ar":null},{"title_ar":"الشرح الثاني — تسجيل من دفعة أخرى","url":"https://youtu.be/fJUrUoYTJmo","description_ar":null}],"resources":[{"label":"ASP.NET Core Web API — Microsoft Learn","url":"https://learn.microsoft.com/aspnet/core/web-api/","kind":"website"},{"label":"Swagger / OpenAPI in ASP.NET Core","url":"https://learn.microsoft.com/aspnet/core/tutorials/web-api-help-pages-using-swagger","kind":"website"}],"assignment":{"title_ar":"تكليف: Repository Pattern وحقن الاعتمادية","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_API_L05_RepositoryPatternDependency\n\nالمطلوب:\n1️⃣ انقل الاستعلامات من المتحكمات إلى Repository لكل كيان.\n2️⃣ أنشئ Generic Repository للعمليات المشتركة.\n3️⃣ سجّل المستودعات في حاوية DI واحقنها.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"Unit of Work","title_en":"Unit of Work","kind":"video","summary_ar":"يدور هذا الفيديو حول شرح مفهوم Unit of Work (وحدة العمل) وكيفية تطبيقها في مشاريع API لتنظيم التعامل مع قواعد البيانات.","outcomes_ar":["المشكلة — عند استخدام نمط Repository بشكل مباشر في المتحكمات (Controllers)، قد يضطر المطور للتعامل مع كائنات DBContext متعددة ومنفصلة. هذا يؤدي إلى مشاكل في مزامنة التغييرات، حيث لا يمكن حفظ التعديلات في جميع المستودعات ","ضمان أن جميع المستودعات تشترك في نفس كائن DBContext","توفير دالة موحدة لـ SaveChanges تقوم بحفظ كافة التغييرات في عملية واحدة متكاملة","تم إنشاء فئة UnitOfWork تقوم بإدارة كائنات Repositories (مثل StudentRepository و DepartmentRepository)","تم استخدام أسلوب التهيئة الكسولة (Lazy Loading) داخل خصائص الـ Unit of Work لضمان عدم إنشاء كائنات Repository غير مستخدمة، مما يحسن من أداء النظام","التكامل — تمت مناقشة كيفية تحديث الـ Controllers لتعمتد على Unit of Work بدلاً من الحقن المباشر للمستودعات (Dependency Injection)، مما يجعل الكود أكثر تنظيماً وقابلية للصيانة"],"case_study_ar":"إضافة طلب نجحت وتحديث المخزون فشل، فصارت البيانات غير متسقة.","case_question_ar":"كيف يضمن Unit of Work نجاحهما معاً أو فشلهما معاً؟","challenge_ar":"أضف Transaction صريحة لعملية معقدة.","videos":[{"title_ar":"الشرح الأول — Unit of Work","url":"https://youtu.be/7uEzouqoCIg","description_ar":null},{"title_ar":"الشرح الثاني — تسجيل من دفعة أخرى","url":"https://youtu.be/aL3PZkJsWPs","description_ar":null}],"resources":[{"label":"ASP.NET Core Web API — Microsoft Learn","url":"https://learn.microsoft.com/aspnet/core/web-api/","kind":"website"},{"label":"Swagger / OpenAPI in ASP.NET Core","url":"https://learn.microsoft.com/aspnet/core/tutorials/web-api-help-pages-using-swagger","kind":"website"}],"assignment":{"title_ar":"تكليف: Unit of Work","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_API_L06_UnitOfWork\n\nالمطلوب:\n1️⃣ نفّذ Unit of Work يجمع المستودعات على DbContext واحد.\n2️⃣ احفظ عمليتين على كيانين مختلفين بـ SaveChanges واحد.\n3️⃣ اشرح المشكلة التي يحلها بمثال.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"تأمين الـAPI بـ JWT","title_en":"Securing the API with JWT","kind":"video","summary_ar":"يشرح هذا الدرس مفهوم JSON Web Token ومكوناته، وتوليد التوكن وتحديد صلاحيته، وإعداد المصادقة بـ AddJwtBearer، وحماية نقاط النهاية بالأدوار.","outcomes_ar":["مفهوم JWT — شرح المحاضر هيكلية التوكن المكونة من ثلاثة أجزاء رئيسية: Header (نوع التوكن وخوارزمية التشفير)، Payload (البيانات أو الـ Claims)، و Signature (للتأكد من صحة التوكن باستخدام مفتاح سري)","آلية العمل — تم توضيح كيفية قيام السيرفر بإصدار التوكن بعد عملية تسجيل الدخول (Login)، ثم استخدامه من قبل العميل في كل طلب تالٍ داخل الـ Authorization Header","تثبيت الحزم اللازمة (NuGet Packages)","إنشاء دالة لتوليد التوكن (Generate Token) وتحديد صلاحية انتهاء (Expiration date)","إعداد خيارات المصادقة في ملف `Program.cs` باستخدام `AddAuthentication` و `AddJwtBearer`","التحقق من الصلاحيات — شرح كيفية استخراج البيانات من الـ Claims للتأكد من صلاحيات المستخدم (مثل الأدوار أو الرتب)"],"case_study_ar":"التوكن مكتوب فيه بيانات حساسة ومدته سنة.","case_question_ar":"ما المخاطر؟ وما الإعدادات الأفضل؟","challenge_ar":"أضف Refresh Token.","videos":[{"title_ar":"الشرح الأول — تأمين الـAPI بـ JWT","url":"https://youtu.be/e2pktjJB81U","description_ar":null},{"title_ar":"الشرح الثاني — تسجيل من دفعة أخرى","url":"https://youtu.be/DfqJUw-tWsM","description_ar":null}],"resources":[{"label":"ASP.NET Core Web API — Microsoft Learn","url":"https://learn.microsoft.com/aspnet/core/web-api/","kind":"website"},{"label":"Swagger / OpenAPI in ASP.NET Core","url":"https://learn.microsoft.com/aspnet/core/tutorials/web-api-help-pages-using-swagger","kind":"website"}],"assignment":{"title_ar":"تكليف: تأمين الـAPI بـ JWT","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_API_L07_SecuringTheAPI\n\nالمطلوب:\n1️⃣ أنشئ AccountController للتسجيل وتسجيل الدخول يرجع JWT.\n2️⃣ احمِ نقاط النهاية بـ Authorize واختبرها بالتوكن.\n3️⃣ أضف الأدوار في التوكن واحمِ نقطة للإدارة فقط.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"الاستضافة على IIS والنشر","title_en":"Hosting on IIS & Deployment","kind":"video","summary_ar":"يقدم هذا الفيديو شرحاً تقنياً عملياً حول كيفية استضافة (Hosting) تطبيقات ASP.NET Core و Web API على خادم ويندوز باستخدام IIS.","outcomes_ar":["متطلبات الاستضافة — يشرح المحاضر ضرورة تثبيت .NET Runtime و Hosting Bundle لضمان عمل تطبيقات .NET على خادم IIS","إعدادات خادم IIS — يوضح الخطوات اللازمة لتفعيل ميزات ASP.NET و .NET Extensibility من خلال لوحة التحكم (Control Panel)","إدارة قواعد البيانات — يركز على أهمية الانتقال من Windows Authentication إلى SQL Server Authentication لضمان عمل التطبيق عند استضافته على خوادم منفصلة","عملية النشر (Deployment) — يوضح كيفية تشغيل Visual Studio كمسؤول (Administrator) لنشر التطبيق (Publish) إلى مجلد محلي، ثم نقل الملفات إلى المسار المخصص في IIS","حل المشكلات — يناقش المحاضر التحديات الشائعة مثل ظهور خطأ 500 (500 Internal Server Error) وكيفية التعامل مع إعدادات الأمان في Swagger لتجنب تعارضها مع التوثيق (Authentication)"],"case_study_ar":"الـAPI يعمل محلياً ويرجع 500.30 بعد النشر.","case_question_ar":"ما الأسباب الشائعة وكيف تقرأ السجلات؟","challenge_ar":"انشر الـAPI على خدمة سحابية مجانية بدلاً من IIS.","videos":[{"title_ar":"الشرح الأول — الاستضافة على IIS والنشر","url":"https://youtu.be/h6IVQmMEc_g","description_ar":null},{"title_ar":"الشرح الثاني — تسجيل من دفعة أخرى","url":"https://youtu.be/eSwmUUILOW0","description_ar":null}],"resources":[{"label":"ASP.NET Core Web API — Microsoft Learn","url":"https://learn.microsoft.com/aspnet/core/web-api/","kind":"website"},{"label":"Swagger / OpenAPI in ASP.NET Core","url":"https://learn.microsoft.com/aspnet/core/tutorials/web-api-help-pages-using-swagger","kind":"website"}],"assignment":{"title_ar":"تكليف: الاستضافة على IIS والنشر","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_API_L08_HostingOnIIS\n\nالمطلوب:\n1️⃣ جهّز الخادم (Hosting Bundle) وانشر الـAPI على IIS.\n2️⃣ انقل قاعدة البيانات واضبط سلسلة الاتصال للإنتاج.\n3️⃣ وثّق المشكلات التي واجهتك وحلولها.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}}]}]}$course$::jsonb);

select public.import_course($course${"slug":"aspnet-mvc-3tier","title_ar":"ASP.NET Core MVC بمعمارية الطبقات الثلاث","title_en":"ASP.NET Core MVC with 3-Tier Architecture","description_ar":"مشروع MVC احترافي بثلاث طبقات: Builder وGenerics وRepository، وViewModels وTag Helpers وEF Core، ورفع الملفات والتحقق، وتعدد المسارات والبرمجة غير المتزامنة، وSOLID وحقن الاعتمادية وAutoMapper والترجمة، وIdentity والتحقق بالبريد، والمهام في الخلفية وAjax.","level":"advanced","estimated_hours":40,"paths":[{"slug":"csharp-dotnet","required":false,"after":"aspnet-mvc"}],"modules":[{"title_ar":"الأساس","lessons":[{"title_ar":"معمارية MVC والطبقات الثلاث","title_en":"MVC & 3-Tier Architecture","kind":"video","summary_ar":"يقدم هذا الفيديو مقدمة شاملة حول بنية MVC (Model-View-Controller) وكيفية عملها ضمن تطبيقات الويب باستخدام 3 Tier Architecture.","outcomes_ar":["شرح الفرق بين تطبيقات سطح المكتب وتطبيقات الويب، مع تسليط الضوء على تحديات نشر التطبيقات","توضيح كيفية عمل الخوادم (Servers) والاستضافة (Hosting)، ودور المتصفح في إرسال الطلبات (Requests) واستقبال الاستجابات (Responses)","Model (الموديل) — يمثل قاعدة البيانات ويعمل كـ \"عقل\" التطبيق، حيث يحتوي على المنطق البرمجي (Business Logic)","View (الفيو) — هو واجهة المستخدم (UI) التي يراها المستخدم، وتتكون من أكواد HTML وCSS مع إمكانية دمج كود C#","Controller (الكنترولر) — المسؤول عن استقبال طلبات المستخدم (Request Handling) والتنسيق بين الموديل والفيو","شرح مفصل لكيفية معالجة الطلبات عند وصولها للخادم، بدءاً من استقبال الطلب عبر Kestrel، مروره عبر Middleware، وصولاً إلى Routing وتحديد الكنترولر والأكشن المطلوب","كيفية إنشاء الكنترولر وكتابة الأكشن (Action) مع توضيح القيود البرمجية عليه مثل وجوب كونه `public` وعدم استخدام `Override` أو `Overload` إلا في حالات خاصة","استعراض مكونات المشروع (Folders) مثل Controllers، Models، وViews وكيفية ارتباطها ببعضها البعض","يؤكد الفيديو على أن هذه المفاهيم هي الأساس لأي مطور يعمل ببيئة .NET، مع التركيز على فهم كيفية تدفق البيانات داخل التطبيق"],"case_study_ar":"طبقة العرض تستدعي قاعدة البيانات مباشرة متجاوزة طبقة الأعمال.","case_question_ar":"ما المشكلة التي يسببها ذلك؟","challenge_ar":"اكتب README يشرح مسؤولية كل طبقة.","videos":[{"title_ar":"المحاضرة — معمارية MVC والطبقات الثلاث","url":"https://youtu.be/0KSFA_67S0I","description_ar":null}],"resources":[{"label":"Common web application architectures — Microsoft Learn","url":"https://learn.microsoft.com/dotnet/architecture/modern-web-apps-azure/common-web-application-architectures","kind":"website"}],"assignment":{"title_ar":"تكليف: معمارية MVC والطبقات الثلاث","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_MVC3TIER_L01_MVC3Tier\n\nالمطلوب:\n1️⃣ أنشئ حلاً (Solution) بثلاثة مشاريع: DAL وBLL وPL.\n2️⃣ اربط المراجع بينها بالاتجاه الصحيح.\n3️⃣ ارسم دورة حياة طلب MVC عبر الطبقات.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"نمط Builder في مشروع MVC","title_en":"The Builder Pattern in MVC","kind":"video","summary_ar":"يقدم هذا الفيديو محاضرة تقنية يقدمها المهندس محمد عصام، وتتناول مفاهيم متقدمة في هندسة البرمجيات وتصميم الأنظمة، مع التركيز بشكل أساسي على نمط التصميم (Builder Design Pattern) وكيفية استخدامه في تطوير تطبيقات ASP.NET Core MVC.","outcomes_ar":["مقدمة ونظام العمل — ناقش المحاضر أهمية طرح الأسئلة، واستخدام الأدوات الحديثة مثل ChatGPT بطريقة صحيحة للتعلم وليس للنسخ، مع التأكيد على أهمية الفهم العميق للمفاهيم","نمط البناء (Builder Design Pattern) — شرح المحاضر كيف يساهم هذا النمط في تنظيم عملية إنشاء الكائنات (Objects) التي تحتوي على العديد من الخصائص، وتجنب تعقيد الكود (Constructor Overload). أوضح كيفية استخدام Method Chaining","التطبيق العملي في MVC — ربط المحاضر بين نمط البناء وما يحدث خلف الكواليس في ملف `Program.cs` في تطبيقات ASP.NET Core، حيث يتم استخدام نمط البناء لتهيئة الإعدادات (Configuration) والخدمات","نصائح مهنية — قدم المحاضر نصائح حول سوق العمل، مؤكداً أن تعلم MVC يوفر أساساً قوياً لفهم كيفية عمل الويب (Request/Response Pipeline)، وهو أمر لا غنى عنه حتى عند التوجه نحو Web API","ختاماً، وعد المحاضر بتخصيص وقت في المحاضرات القادمة لشرح مفاهيم هامة في لغة C# مثل Generics و Async/Await لدعم الطلاب"],"case_study_ar":"كائن إعدادات بريد يحتاج 12 قيمة أغلبها اختياري.","case_question_ar":"كيف يبسّط Builder إنشاءه؟","challenge_ar":"أضف Fluent Interface للـBuilder.","videos":[{"title_ar":"المحاضرة — نمط Builder في مشروع MVC","url":"https://youtu.be/HVTO9ZqkY9w","description_ar":null}],"resources":[{"label":"Common web application architectures — Microsoft Learn","url":"https://learn.microsoft.com/dotnet/architecture/modern-web-apps-azure/common-web-application-architectures","kind":"website"}],"assignment":{"title_ar":"تكليف: نمط Builder في مشروع MVC","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_MVC3TIER_L02_TheBuilderPattern\n\nالمطلوب:\n1️⃣ اشرح كيف يستخدم Program.cs نمط Builder.\n2️⃣ نفّذ Builder لكائن تقرير معقد.\n3️⃣ اكتب مقارنة بين Builder والمُنشئ متعدد المعاملات.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"تقنيات الوصول للبيانات والمتحكمات","title_en":"Data Access Options & Controllers","kind":"video","summary_ar":"يقارن هذا الدرس تقنيات الوصول للبيانات في ‎.NET، ثم ينشئ المتحكمات ويتعامل مع البيانات عبر طبقات المشروع.","outcomes_ar":["مقدمة عن المسار المهني — ناقش المحاضر أهمية أنظمة الموارد البشرية (HR Systems) كبداية قوية للمطورين في الشركات، وأهمية التطوير الذاتي والبحث عن مشاريع حرة (Freelance)","مقارنة تقنيات الوصول للبيانات — شرح الفروقات بين ADO.NET و Entity Framework، مع توضيح مفهوم Disconnected Mode في ADO، وكيف توفر Entity Framework كائنات برمجية (Objects) بدلاً من الجداول التقليدية","إنشاء المتحكمات (Controllers) — توضيح كيفية إنشاء الـ Controller والتعامل مع أنواع النتائج المختلفة مثل ViewResult، JsonResult، و ContentResult، مع التركيز على استخدام الواجهة IActionResult لضمان مرونة الكود","التعامل مع البيانات — شرح كيفية عرض البيانات باستخدام Models، وإجراء عمليات الـ CRUD (إنشاء، قراءة، تحديث، حذف)، وتوضيح أهمية الفصل بين طبقات البرمجيات","نصائح وتوجيهات — قدم المحاضر نصائح حول أهمية فهم أساسيات ADO.NET حتى عند استخدام تقنيات حديثة، وشدد على ضرورة كتابة الكود بشكل منظم"],"case_study_ar":"فريق يختار بين ADO.NET وEF Core لمشروع جديد متوسط الحجم.","case_question_ar":"ما العوامل التي ترجّح أحدهما؟","challenge_ar":"نفّذ الاستعلام نفسه بـ Dapper وقارن الكود.","videos":[{"title_ar":"المحاضرة — تقنيات الوصول للبيانات والمتحكمات","url":"https://youtu.be/iZUIg7vjaVw","description_ar":null}],"resources":[{"label":"Common web application architectures — Microsoft Learn","url":"https://learn.microsoft.com/dotnet/architecture/modern-web-apps-azure/common-web-application-architectures","kind":"website"}],"assignment":{"title_ar":"تكليف: تقنيات الوصول للبيانات والمتحكمات","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_MVC3TIER_L03_DataAccessOptions\n\nالمطلوب:\n1️⃣ قارن ADO.NET وDapper وEF Core في جدول.\n2️⃣ أنشئ متحكم الأقسام بعمليات CRUD عبر طبقة الأعمال.\n3️⃣ وثّق تدفق إضافة قسم عبر الطبقات.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"Generics والقيود وRepository العام","title_en":"Generics, Constraints & a Generic Repository","kind":"video","summary_ar":"يقدم هذا الفيديو محاضرة تقنية متقدمة تركز على مفاهيم برمجية هامة في إطار عمل ASP.NET MVC و C#، وتحديداً مفهوم الأنواع العامة (Generics) وكيفية تطبيقها في بنية المشروع.","outcomes_ar":["مفهوم الـ Generics — شرح المحاضر كيف أن الـ Generics تتيح للمبرمج إرسال \"نوع البيانات\" (Data Type) كمعامل بدلاً من القيم فقط، مما يمنح مرونة عالية في الكود","أهمية الـ Where Constraint — أكد المحاضر على أن استخدام كلمة `where` هو أساس استخدام الـ Generics بشكل صحيح، فهي تحدد القيود على النوع المرسل وتمنع حدوث أخطاء برمجية","الجانب المتقدم في الذاكرة — أوضح كيف يقوم الـ CLR (Common Language Runtime) بإنشاء نسخ مختلفة من الميثود (Method) في الذاكرة بناءً على أنواع البيانات المستخدمة، مما يبرز أهمية تقييد الأنواع (Constraints)","تطبيق عملي في نمط المستودع (Repository Pattern) — ناقش المحاضر كيفية استخدام Generics لتقليل تكرار الكود (DRY Principle) عند التعامل مع عمليات الـ CRUD لأكثر من كيان (Entity) داخل قاعدة البيانات","أنهى المحاضر الجلسة بتقديم نصائح عملية للطلاب حول كيفية التعامل مع مشاكل بيئة العمل مثل IIS Express وكيفية إجراء عملية التنظيف (Clean & Rebuild) للحل البرمجي عند حدوث أخطاء"],"case_study_ar":"كل كيان له Repository مكرر بنفس الدوال الخمس.","case_question_ar":"كيف يزيل المستودع العام التكرار؟","challenge_ar":"أضف Specification Pattern للاستعلامات المركبة.","videos":[{"title_ar":"المحاضرة — Generics والقيود وRepository العام","url":"https://youtu.be/hbT63EeVE7Y","description_ar":null}],"resources":[{"label":"Common web application architectures — Microsoft Learn","url":"https://learn.microsoft.com/dotnet/architecture/modern-web-apps-azure/common-web-application-architectures","kind":"website"}],"assignment":{"title_ar":"تكليف: Generics والقيود وRepository العام","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_MVC3TIER_L04_GenericsConstraintsA\n\nالمطلوب:\n1️⃣ اكتب Generic Repository بقيد where T : BaseEntity.\n2️⃣ وضّح ما يحدث في الذاكرة مع الأنواع العامة.\n3️⃣ استخدم المستودع العام لكيانين.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}}]},{"title_ar":"البيانات والواجهة","lessons":[{"title_ar":"Tag Helpers وViewModels وEF Core","title_en":"Tag Helpers, ViewModels & EF Core","kind":"video","summary_ar":"يقدم هذا الفيديو محاضرة تعليمية للمهندس محمد عصام حول تطوير تطبيقات الويب باستخدام MVC (Model-View-Controller) بنظام 3-Tier Architecture. يتناول هذا الدرس الفيديو عدة مفاهيم تقنية هامة.","outcomes_ar":["Tag Helpers — شرح كيفية استخدامها بدلاً من الطرق التقليدية (مثل `Html.TextBox`) لربط البيانات بشكل أسهل وأكثر أماناً باستخدام `asp-for`","إدارة البيانات في الـ Edit — شرح كيفية تنفيذ عملية التعديل (Edit) بإرسال الـ ID الخاص بالموظف، مع استخدام حقل مخفي (`hidden input`) لضمان وصول الـ ID بشكل صحيح للـ Controller","هيكلة البيانات (ViewModels) — التأكيد على أهمية استخدام الـ ViewModels (VM) لفصل البيانات المعروضة في الواجهة عن الكيانات (Entities) الموجودة في قاعدة البيانات، وذلك لتقليل حجم البيانات المنقولة وتحسين الأداء","الفرق بين ADO.NET و Entity Framework Core — توضيح لماذا تعتبر ADO.NET أسرع في الأداء بسبب مباشرتها في التعامل مع قاعدة البيانات، بينما تعتمد EF Core على تقنيات مثل Reflection مما قد يجعلها أبطأ قليلاً، ولكنها توفر مرونة ","مبادئ الـ Entity Framework — مناقشة أنماط التعامل مع الجداول في الوراثة (Inheritance) مثل Table Per Hierarchy و Table Per Type، وأهمية Navigation Properties في بناء العلاقات بين الجداول"],"case_study_ar":"نموذج التعديل يرسل حقولاً لا يجب أن يغيّرها المستخدم (Overposting).","case_question_ar":"كيف يمنع ViewModel ذلك؟","challenge_ar":"فعّل AsNoTracking للاستعلامات التي للقراءة فقط.","videos":[{"title_ar":"المحاضرة — Tag Helpers وViewModels وEF Core","url":"https://youtu.be/TalfdeXHVQs","description_ar":null}],"resources":[{"label":"Common web application architectures — Microsoft Learn","url":"https://learn.microsoft.com/dotnet/architecture/modern-web-apps-azure/common-web-application-architectures","kind":"website"}],"assignment":{"title_ar":"تكليف: Tag Helpers وViewModels وEF Core","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_MVC3TIER_L05_TagHelpersViewModels\n\nالمطلوب:\n1️⃣ أنشئ ViewModel لشاشة تعديل الموظف.\n2️⃣ استخدم Tag Helpers للنموذج والقائمة المنسدلة.\n3️⃣ اشرح مبادئ EF Core: التتبع وMigrations والعلاقات.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"رفع الملفات والتحقق والتخطيطات","title_en":"File Uploads, Validation & Layouts","kind":"video","summary_ar":"يقدم هذا الفيديو الذي يقدمه المهندس محمد عصام شرحاً عملياً وتفصيلياً لآليات التعامل مع الملفات والتحقق من صحة البيانات (Validation) في تطبيقات MVC باستخدام بنية 3-Tier Architecture.","outcomes_ar":["رفع الصور والملفات — ناقش الفيديو تحديات رفع الصور إلى السيرفر مباشرة وتأثيرها على مساحة التخزين، ثم طرح حلولاً برمجية لاستخدام `IFormFile` لتخزين الملفات في مجلد خاص ضمن `wwwroot`","التحقق من صحة البيانات (Data Annotations) — شرح كيفية استخدام `Data Annotations` للتحقق من المدخلات مثل `Required` و `MinLength` و `MaxLength` لضمان سلامة البيانات (135:57)","التحقق المخصص (Custom Validation) — تم توضيح كيفية بناء كلاسات للتحقق المخصص من خلال وراثة `ValidationAttribute` واستخدام `ValidationContext` للتحقق من وجود قيم فريدة في قاعدة البيانات (245:13)","تصميم الواجهات (Layouts) — شرح أهمية ملفات الـ `Layout` في توحيد شكل الموقع وكيفية استخدام `RenderBody` لدمج المحتوى في الصفحات المختلفة (300:37)","تطبيقات عملية — تضمن الفيديو خطوات تطبيقية لتنسيق التمبلت (Template) الخاص بالموقع وربط الجافا سكريبت والمكتبات المطلوبة لتعزيز تجربة المستخدم (313:15)"],"case_study_ar":"شخص رفع ملفاً تنفيذياً باسم صورة.","case_question_ar":"كيف تتحقق من نوع الملف بأمان؟","challenge_ar":"احذف الصورة القديمة عند استبدالها.","videos":[{"title_ar":"المحاضرة — رفع الملفات والتحقق والتخطيطات","url":"https://youtu.be/3QJLwSAo2FI","description_ar":null}],"resources":[{"label":"Common web application architectures — Microsoft Learn","url":"https://learn.microsoft.com/dotnet/architecture/modern-web-apps-azure/common-web-application-architectures","kind":"website"}],"assignment":{"title_ar":"تكليف: رفع الملفات والتحقق والتخطيطات","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_MVC3TIER_L06_FileUploadsValidation\n\nالمطلوب:\n1️⃣ نفّذ رفع صورة للموظف وحفظها باسم فريد.\n2️⃣ تحقق من نوع الملف وحجمه.\n3️⃣ أضف تحققاً مخصصاً وLayout للوحة الإدارة.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"التزامن وتعدد المسارات في C#","title_en":"Concurrency & Threading in C#","kind":"video","summary_ar":"يقدم هذا الفيديو شرحاً مفصلاً لمفاهيم البرمجة المتزامنة (Concurrency) والخيوط (Threading) في لغة C#، موضحاً كيف يمكن تنفيذ مهام متعددة في نفس الوقت بدلاً من تنفيذ الكود سطراً بسطر بشكل تسلسلي (Synchronous).","outcomes_ar":["مفهوم الخيوط (Threads) — هي وحدات عمل مستقلة تسمح للبرنامج بتنفيذ عدة عمليات في وقت واحد، حيث يقوم نظام التشغيل بإنشاء خيط رئيسي (Main Thread) لتنفيذ الأوامر","إنشاء خيوط إضافية — شرح المهندس كيفية إنشاء خيط جديد باستخدام كلاس `Thread` واستخدام أمر `Start()` لتشغيل ميثود معينة في خلفية البرنامج","تبديل السياق (Context Switching) — أوضح أن المعالج (Processor) لا ينفذ المهام في نفس اللحظة حرفياً، بل يقوم بالتبديل السريع جداً بين الخيوط، وهو ما يستهلك موارد إضافية (Overhead)","خيوط الواجهة الأمامية (Foreground Threads) — البرنامج ينتظر انتهاء هذه الخيوط قبل الإغلاق","خيوط الخلفية (Background Threads) — لا ينتظرها البرنامج، ويتم إنهاؤها فور إغلاق التطبيق","الفرق بين التزامن (Concurrency) والتوازي (Parallelism) — أوضح أن التزامن يعتمد على التبديل بين المهام على نفس المعالج، بينما التوازي يستغل تعدد الأنوية (Cores) لتنفيذ المهام فعلياً في نفس اللحظة"],"case_study_ar":"تقرير يعالج 10 آلاف سجل في دقيقتين على معالج بثمانية أنوية.","case_question_ar":"كيف يسرّعه التوازي؟ ومتى لا يفيد؟","challenge_ar":"قِس الزمن بـ Stopwatch قبل التوازي وبعده.","videos":[{"title_ar":"المحاضرة — التزامن وتعدد المسارات في C#","url":"https://youtu.be/Xo-PzTVrbrI","description_ar":null}],"resources":[{"label":"Common web application architectures — Microsoft Learn","url":"https://learn.microsoft.com/dotnet/architecture/modern-web-apps-azure/common-web-application-architectures","kind":"website"}],"assignment":{"title_ar":"تكليف: التزامن وتعدد المسارات في C#","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_MVC3TIER_L07_ConcurrencyThreadingIn\n\nالمطلوب:\n1️⃣ أنشئ خيوطاً أمامية وخلفية ولاحظ الفرق عند انتهاء البرنامج.\n2️⃣ اشرح تبديل السياق والفرق بين التزامن والتوازي.\n3️⃣ استخدم Parallel.For لمعالجة قائمة كبيرة.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"Delegates والعلاقات والـMiddleware","title_en":"Delegates, EF Relationships & Middleware","kind":"video","summary_ar":"يقدم هذا الفيديو محاضرة تقنية للمهندس محمد عصام حول معمارية MVC باستخدام 3-Tier Architecture، مع التركيز على مفاهيم متقدمة في ASP.NET Core.","outcomes_ar":["Delegates — شرح كيفية استخدام Delegates لتنفيذ دوال ديناميكية ومعالجة أجزاء الكود المتغيرة","Entity Framework (EF) — مناقشة الفرق بين Conventions، Data Annotations، و Fluent API، مع توضيح كيفية تطبيق الإعدادات المتقدمة مثل Indexes، Required، و Ignore","العلاقات (Relationships) — شرح كيفية بناء العلاقات بين الجداول (مثل One-to-Many) باستخدام Navigation Properties و Fluent API","Middleware — شرح مفصل لـ Middleware Pipeline، كيف تسير الطلبات (Requests)، أنواع الـ Middleware (مثل Terminal و Short-circuiting)، وكيفية بناء Middleware مخصصة","دورة حياة الطلب (Request Lifecycle) — توضيح المراحل التي يمر بها الطلب داخل ASP.NET Core MVC، بدءاً من Kestrel وصولاً إلى الـ Controller Action"],"case_study_ar":"علاقة Many-to-Many تحتاج حفظ تاريخ التسجيل أيضاً.","case_question_ar":"متى تحتاج كيان ربط صريحاً؟","challenge_ar":"ارسم دورة حياة الطلب كاملة من الـMiddleware حتى الـView.","videos":[{"title_ar":"المحاضرة — Delegates والعلاقات والـMiddleware","url":"https://youtu.be/xhKecTvGNR8","description_ar":null}],"resources":[{"label":"Common web application architectures — Microsoft Learn","url":"https://learn.microsoft.com/dotnet/architecture/modern-web-apps-azure/common-web-application-architectures","kind":"website"}],"assignment":{"title_ar":"تكليف: Delegates والعلاقات والـMiddleware","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_MVC3TIER_L08_DelegatesEFRelationships\n\nالمطلوب:\n1️⃣ اربط Delegates بمفهوم الـMiddleware (RequestDelegate).\n2️⃣ نفّذ علاقات One-to-One وOne-to-Many وMany-to-Many في EF Core.\n3️⃣ اكتب Middleware مخصصاً.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"البرمجة غير المتزامنة وتكامل الذكاء الاصطناعي","title_en":"Async Programming & AI Integration","kind":"video","summary_ar":"يشرح هذا الدرس البرمجة غير المتزامنة والفرق بين التزامن والتوازي واستخدام Tasks، ثم ربط الخادم بخدمة ذكاء اصطناعي عبر HttpClient مع حفظ المفتاح بأمان.","outcomes_ar":["ناقش المحاضر مفهوم الموارد المشتركة (Shared Resources) والمشاكل التي قد تنتج عنها عند التعامل مع أكثر من خيط معالجة (Thread) في نفس الوقت","شرح الفرق بين التزامن (Concurrency) والتوازي (Parallelism)، وكيفية استخدام المهام (Tasks) في C# كطبقة مساعدة لتسهيل تنفيذ العمليات المعقدة وإدارة الموارد بذكاء","تناول كيفية ربط الخلفية البرمجية (Backend) بخدمات الذكاء الاصطناعي مثل OpenAI باستخدام API Secret Key","شرح أهمية هندسة الأوامر (Prompt Engineering)، وكيفية توجيه الذكاء الاصطناعي لأداء مهام محددة (مثل التلخيص) مع وضع قيود صارمة تمنع الخروج عن النطاق المخصص","شرح كيفية بناء طلبات HTTP باستخدام `HttpClient` لإرسال البيانات واستقبال الردود من الخدمات الخارجية، وكيفية التعامل مع هيكلية الـ Payload والـ Headers"],"case_study_ar":"الخادم يتباطأ تحت الضغط لأن الخيوط تنتظر القاعدة.","case_question_ar":"كيف يحرر async الخيوط؟","challenge_ar":"أضف ميزة تلخيص نص بالذكاء الاصطناعي في المشروع.","videos":[{"title_ar":"المحاضرة — البرمجة غير المتزامنة وتكامل الذكاء الاصطناعي","url":"https://youtu.be/kWODjr8UDTw","description_ar":null}],"resources":[{"label":"Common web application architectures — Microsoft Learn","url":"https://learn.microsoft.com/dotnet/architecture/modern-web-apps-azure/common-web-application-architectures","kind":"website"}],"assignment":{"title_ar":"تكليف: البرمجة غير المتزامنة وتكامل الذكاء الاصطناعي","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_MVC3TIER_L09_AsyncProgrammingAI\n\nالمطلوب:\n1️⃣ حوّل عمليات القاعدة إلى async/await.\n2️⃣ اشرح لماذا لا يجب استخدام ‎.Result و‎.Wait.\n3️⃣ استدعِ API ذكاء اصطناعي من الخادم (مع حفظ المفتاح في الإعدادات السرية).\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}}]},{"title_ar":"التصميم الاحترافي","lessons":[{"title_ar":"SOLID والطبقات DAL وBLL وPL","title_en":"SOLID & the DAL, BLL and PL Layers","kind":"video","summary_ar":"يقدم هذا الفيديو محاضرة تعليمية للمهندس محمد عصام حول تطوير تطبيقات الويب باستخدام نمط 3-Tier Architecture وASP.NET MVC.","outcomes_ar":["مبدأ المسؤولية الواحدة (Single Responsibility Principle) — أن يكون لكل كلاس سبب واحد فقط للتغيير","مبدأ المفتوح/المغلق (Open/Closed Principle) — أن يكون الكود مفتوحاً للتطوير ومغلقاً للتعديل المباشر","مبدأ ليسكوف للاستبدال (Liskov Substitution Principle) — ضمان قدرة الكلاسات المشتقة على العمل مكان الكلاسات الأساسية دون أخطاء","طبقة الوصول للبيانات (DAL) — تتعامل مباشرة مع قاعدة البيانات وتستخدم نمط Repository","طبقة منطق الأعمال (BLL) — تحتوي على العمليات والمنطق الخاص بالتطبيق","طبقة العرض (Presentation Layer) — تتعامل مع واجهة المستخدم والكنترولر","نصائح عملية — ناقش المهندس أهمية استخدام ViewModels بدلاً من ربط الـ Entities مباشرة بقاعدة البيانات، وكيفية إعداد المشاريع باستخدام Entity Framework Core"],"case_study_ar":"خدمة الموظفين تتغير كلما تغيّر شكل التقرير.","case_question_ar":"أي مبدأ يُخالَف؟ وكيف تصلحه؟","challenge_ar":"أضف واجهة لكل خدمة واحقنها.","videos":[{"title_ar":"المحاضرة — SOLID والطبقات DAL وBLL وPL","url":"https://youtu.be/ilGb2xYj40o","description_ar":null}],"resources":[{"label":"Common web application architectures — Microsoft Learn","url":"https://learn.microsoft.com/dotnet/architecture/modern-web-apps-azure/common-web-application-architectures","kind":"website"}],"assignment":{"title_ar":"تكليف: SOLID والطبقات DAL وBLL وPL","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_MVC3TIER_L10_SOLIDTheDAL\n\nالمطلوب:\n1️⃣ طبّق SRP وOCP وLSP في طبقة الأعمال بأمثلة.\n2️⃣ راجع حدود كل طبقة وانقل أي كود في غير مكانه.\n3️⃣ وثّق القرارات في README.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"حقن الاعتمادية وAutoMapper ومعالجة الأخطاء","title_en":"DI, ViewModels, Error Handling & AutoMapper","kind":"video","summary_ar":"يدور هذا الفيديو حول تطبيق مبادئ هندسة البرمجيات (3-Tier Architecture) في بناء تطبيق ويب باستخدام ASP.NET MVC. المهندس محمد عصام، على تنظيم الكود لضمان الفصل بين المهام (Separation of Concerns) وسهولة الصيانة.","outcomes_ar":["هيكلة الطبقات (Layered Architecture) — شرح كيفية فصل طبقة الوصول للبيانات (DAL) عن منطق الأعمال (Business Logic) وعن واجهة المستخدم، مما يسهل إدارة قاعدة البيانات وتعديلها","حقن التبعية (Dependency Injection) — شرح مفصل لأنواع أنماط الحقن وكيفية استخدامها (Scoped, Transient, Singleton) لضمان استقرار التطبيق وكفاءة استهلاك الذاكرة","نماذج العرض (View Models) — التأكيد على أهمية استخدام نماذج مخصصة لكل عملية (Create, Get, List) بدلاً من التعامل مباشرة مع كائنات قاعدة البيانات (Entities) لتجنب الثغرات وتداخل البيانات","التعامل مع الأخطاء — مناقشة كيفية معالجة الاستثناءات بشكل احترافي لضمان عدم انهيار التطبيق وتقديم تجربة مستخدم أفضل","خرائط البيانات (AutoMapper) — عرض كيفية أتمتة عملية تحويل البيانات بين الطبقات باستخدام مكتبة AutoMapper لتقليل الكود المتكرر","إدارة إعدادات الاتصال — شرح كيفية نقل سلاسل الاتصال (Connection Strings) من الكود البرمجي إلى ملف الإعدادات (`appsettings.json`) لتعزيز الأمان والقدرة على النشر (Production)"],"case_study_ar":"تحويل الكيانات للـViewModels مكتوب يدوياً في عشرين مكاناً.","case_question_ar":"كيف يوحده AutoMapper؟ وما مخاطره؟","challenge_ar":"اكتب Profile مخصصاً لتحويل معقد.","videos":[{"title_ar":"المحاضرة — حقن الاعتمادية وAutoMapper ومعالجة الأخطاء","url":"https://youtu.be/PTkM8sDbqjA","description_ar":null}],"resources":[{"label":"Common web application architectures — Microsoft Learn","url":"https://learn.microsoft.com/dotnet/architecture/modern-web-apps-azure/common-web-application-architectures","kind":"website"}],"assignment":{"title_ar":"تكليف: حقن الاعتمادية وAutoMapper ومعالجة الأخطاء","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_MVC3TIER_L11_DIViewModelsError\n\nالمطلوب:\n1️⃣ سجّل خدمات الطبقات في DI من مكان واحد (Extension Method).\n2️⃣ استخدم AutoMapper بين الكيانات والـViewModels.\n3️⃣ أضف معالجة أخطاء موحدة وإدارة لإعدادات الاتصال.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"Repository وAutoMapper والترجمة","title_en":"Repository, AutoMapper, Validation & Localization","kind":"video","summary_ar":"يقدم هذا الفيديو تعليمًا عمليًا حول تطوير تطبيقات الويب باستخدام بنية MVC (Model-View-Controller) المكونة من 3 طبقات (3-Tier Architecture)، حيث يركز المهندس محمد عصام على عدة جوانب تقنية رئيسية.","outcomes_ar":["إدارة البيانات في العرض — شرح الفرق بين ViewBag و ViewData وكيفية استخدامهما لنقل البيانات من المتحكم (Controller) إلى الواجهة (View)","بنية التطبيق (Repository Pattern) — تم توضيح كيفية بناء طبقة الـ Repository للتعامل مع قاعدة البيانات بشكل مرن، مع تطبيق مبدأ حقن التبعية (Dependency Injection) لربط الخدمات (Services) والـ Repositories","استخدام AutoMapper — شرح أهمية مكتبة AutoMapper في تحويل البيانات بين الكيانات (Entities) ونماذج العرض (View Models)","التحقق من البيانات (Validation) — كيفية تفعيل التحقق من المدخلات باستخدام Validation Attributes","التعامل مع اللغات (Localization & Globalization) — شرح كيفية جعل التطبيق يدعم لغات متعددة (مثل العربية والإنجليزية) باستخدام الـ Middleware وملفات الموارد (Resources) لتغيير النصوص الثابتة ديناميكيًا"],"case_study_ar":"العميل يريد الموقع بلغتين، والنصوص مكتوبة داخل الـViews.","case_question_ar":"كيف تنقلها لملفات موارد؟","challenge_ar":"أضف مبدّل لغة يحفظ الاختيار في Cookie.","videos":[{"title_ar":"المحاضرة — Repository وAutoMapper والترجمة","url":"https://youtu.be/sbfUfvhVXts","description_ar":null}],"resources":[{"label":"Common web application architectures — Microsoft Learn","url":"https://learn.microsoft.com/dotnet/architecture/modern-web-apps-azure/common-web-application-architectures","kind":"website"}],"assignment":{"title_ar":"تكليف: Repository وAutoMapper والترجمة","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_MVC3TIER_L12_RepositoryAutoMapperValidation\n\nالمطلوب:\n1️⃣ أكمل Repository لكل الكيانات عبر الطبقات.\n2️⃣ أضف التحقق في طبقة الأعمال.\n3️⃣ فعّل الترجمة (عربي/إنجليزي) لنصوص الواجهة ورسائل التحقق.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"معاملات الدوال والمجموعات وTuple","title_en":"Method Parameters, Collections & Tuples","kind":"video","summary_ar":"يقدم هذا الفيديو الذي يقدمه المهندس محمد عصام شرحاً تقنياً متعمقاً لمجموعة من مفاهيم البرمجة المتقدمة باستخدام لغة C#، مع التركيز على هندسة البرمجيات والأداء.","outcomes_ar":["`out` — تُستخدم عندما تريد إرجاع قيمة من دالة عبر متغير تم تمريره، وتلزمك بتعيين قيمة للمتغير داخل الدالة قبل انتهائها","`in` — تعمل كعكس تماماً لـ `out`؛ حيث تضمن أن القيمة المدخلة للدالة لا يمكن تغييرها داخلها","أوضح المحاضر الفرق بين List، Dictionary، وHashSet وأهمية اختيار الهيكل المناسب لتحسين الأداء (Performance)","أشار إلى أن List سهلة الاستخدام ولكنها قد تكون بطيئة في عمليات البحث (Linear Search)، بينما توفر Dictionary وHashSet سرعة أكبر في الوصول للبيانات (Hashing)","شرح كيفية استخدام Tuple كطريقة فعالة وسريعة لإرجاع أكثر من قيمة من دالة واحدة دون الحاجة لإنشاء كلاس (Class) جديد، موضحاً الفرق بين الأسلوب القديم والأسلوب الحديث الذي يدعم التسمية","أكد المحاضر على أهمية التفكير كمهندس عند حل المشكلات التقنية، مشدداً على ضرورة البحث عن حلول برمجية ذكية (مثل تقليل عدد الاتصالات بقاعدة البيانات) بدلاً من مجرد كتابة الكود ليعمل فقط"],"case_study_ar":"بحث متكرر عن مستخدم بالبريد في قائمة كبيرة يبطئ التطبيق.","case_question_ar":"أي مجموعة تختار؟ ولماذا؟","challenge_ar":"قِس زمن البحث في List وDictionary لمئة ألف عنصر.","videos":[{"title_ar":"المحاضرة — معاملات الدوال والمجموعات وTuple","url":"https://youtu.be/50sujm1QVOg","description_ar":null}],"resources":[{"label":"Common web application architectures — Microsoft Learn","url":"https://learn.microsoft.com/dotnet/architecture/modern-web-apps-azure/common-web-application-architectures","kind":"website"}],"assignment":{"title_ar":"تكليف: معاملات الدوال والمجموعات وTuple","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_MVC3TIER_L13_MethodParametersCollections\n\nالمطلوب:\n1️⃣ اكتب أمثلة لـ ref وout وin واشرح الفرق.\n2️⃣ قارن List وDictionary وHashSet في الأداء والاستخدام.\n3️⃣ أرجع أكثر من قيمة من دالة بـ Tuple.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}}]},{"title_ar":"الهوية والإنتاج","lessons":[{"title_ar":"Identity والأدوار والتحقق بالبريد","title_en":"Identity, Roles & Email Verification","kind":"video","summary_ar":"يقدم هذا الفيديو محاضرة تقنية تعليمية حول تطوير تطبيقات الويب باستخدام بنية 3-Tier Architecture في إطار عمل ASP.NET MVC. المهندس محمد عصام، على كيفية بناء وتأمين التطبيقات من خلال تنفيذ المفاهيم الأساسية لنظام الهوية في مايكروسوفت (Identity).","outcomes_ar":["المصادقة والصلاحيات (Authentication & Authorization) — شرح المحاضر الفرق الجوهري بين المصادقة، وهي التحقق من هوية المستخدم، والصلاحيات، وهي تحديد ما يمكن للمستخدم القيام به داخل التطبيق. تم توضيح كيفية إضافة قيود على الم","إدارة المستخدمين والأدوار (Identity & Roles) — شرح كيفية إنشاء جدول خاص بالمستخدمين وتخصيص الأدوار (Roles) مثل \"Admin\" أو \"HR\". كما تم التطرق إلى إعدادات كلمة المرور وكيفية تخصيصها عبر Program.cs لتسهيل تجربة المستخدم أو","العمليات الأساسية — تضمن الفيديو شرحاً لعمليات التسجيل (Register) وتسجيل الدخول (Login) وتسجيل الخروج (Sign Out)، مع التأكيد على أهمية العمل باستخدام النماذج (View Models) والبرمجة غير المتزامنة (Async/Await)","التحقق من البريد الإلكتروني (Email Verification) — في الجزء الأخير من الفيديو، تمت مناقشة استراتيجيات تأمين تسجيل المستخدمين عبر إرسال رموز تحقق (Verification Codes) إلى البريد الإلكتروني، وكيفية استخدام التخزين المؤقت (","ينصح المحاضر الطلاب دائماً بتطبيق هذه المفاهيم يدوياً بدلاً من الاعتماد الكلي على أدوات التوليد التلقائي (Scaffolding) لضمان فهم أعمق للبنية التحتية للمشروع"],"case_study_ar":"حسابات وهمية كثيرة تُنشأ ببريد غير حقيقي.","case_question_ar":"كيف يحدّ تأكيد البريد من ذلك؟","challenge_ar":"أضف «نسيت كلمة المرور».","videos":[{"title_ar":"المحاضرة — Identity والأدوار والتحقق بالبريد","url":"https://youtu.be/gAD7SV-fn9E","description_ar":null}],"resources":[{"label":"Common web application architectures — Microsoft Learn","url":"https://learn.microsoft.com/dotnet/architecture/modern-web-apps-azure/common-web-application-architectures","kind":"website"}],"assignment":{"title_ar":"تكليف: Identity والأدوار والتحقق بالبريد","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_MVC3TIER_L14_IdentityRolesEmail\n\nالمطلوب:\n1️⃣ أضف Identity بالمستخدمين والأدوار.\n2️⃣ نفّذ التسجيل وتسجيل الدخول وتأكيد البريد.\n3️⃣ احمِ الصفحات حسب الدور.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"إرسال البريد بـ MailKit","title_en":"Sending Email with MailKit","kind":"video","summary_ar":"يدور هذا الفيديو حول كيفية إرسال رسائل التحقق (Verification) عبر البريد الإلكتروني في تطبيقات ASP.NET MVC، حيث يوضح المهندس محمد عصام عدة نقاط رئيسية.","outcomes_ar":["تطور أساليب التحقق — يناقش الفيديو كيف أصبحت طرق التحقق تعتمد بشكل متزايد على إرسال أرقام (Numbers) بدلاً من الروابط لزيادة الأمان","استخدام مكتبة MailKit — يوصي المحاضر باستخدام مكتبة MailKit لأنها سهلة الاستخدام وتعتبر خياراً ممتازاً ومباشراً للمطورين","طريقة التنفيذ — يوضح أن المكتبة لا تحتاج إلى واجهة مستخدم (UI)، بل يتم إعدادها برمجياً من خلال كود (Configuration) يُضاف إلى مشروعك","بناء الخدمات — ينصح بإنشاء كلاس خاص باسم MailService ليكون مسؤولاً عن استدعاء ميثودات المكتبة بترتيب معين، مع الحصول على الإعدادات المطلوبة عبر نسخها من الإنترنت أو التوثيق الرسمي","نصائح حول الذكاء الاصطناعي — يتطرق النقاش إلى أهمية كتابة الـ Prompts بشكل صحيح عند استخدام أدوات الذكاء الاصطناعي للحصول على نتائج دقيقة في البرمجة بلغة C#","في نهاية الفيديو، يوجه المحاضر الطلاب للبدء في تنفيذ الـ Lab الخاص بهم، مع التأكيد على مرونة مواعيد التسليم"],"case_study_ar":"كلمة مرور البريد رُفعت على GitHub داخل appsettings.json.","case_question_ar":"ماذا تفعل فوراً؟ وكيف تمنع تكرار ذلك؟","challenge_ar":"أضف إعادة المحاولة عند فشل الإرسال.","videos":[{"title_ar":"المحاضرة — إرسال البريد بـ MailKit","url":"https://youtu.be/795zvclrBA8","description_ar":null}],"resources":[{"label":"Common web application architectures — Microsoft Learn","url":"https://learn.microsoft.com/dotnet/architecture/modern-web-apps-azure/common-web-application-architectures","kind":"website"}],"assignment":{"title_ar":"تكليف: إرسال البريد بـ MailKit","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_MVC3TIER_L15_SendingEmailWith\n\nالمطلوب:\n1️⃣ اكتب خدمة بريد بـ MailKit عبر واجهة.\n2️⃣ أرسل رسالة تأكيد بقالب HTML.\n3️⃣ احفظ إعدادات SMTP في الإعدادات السرية لا في الكود.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}},{"title_ar":"المهام في الخلفية وAjax ومتطلبات المشروع","title_en":"Background Jobs, Ajax & the Final Project","kind":"video","summary_ar":"يقدم هذا الفيديو محاضرة ختامية في دورة تطوير المواقع باستخدام نمط MVC (Model-View-Controller) ضمن 3-Tier Architecture، حيث يستعرض المهندس محمد عصام مجموعة من التقنيات والمفاهيم المتقدمة التي يحتاجها المطور في مشروعه العملي.","outcomes_ar":["العمليات في الخلفية (Background Jobs) — شرح كيفية استخدام Hangfire لتنفيذ مهام مؤجلة أو دورية دون التأثير على تجربة المستخدم","تقنيات التحميل — توضيح الفرق بين Lazy Loading و Eager Loading و Explicit Loading وكيفية تفعيل Lazy Loading باستخدام Proxies في إطار العمل","تنظيم العرض (UI/UX) — استخدام Partial Views لتقسيم الكود (مثل الهيدر والفوتر) و RenderSection للتحكم في الأجزاء الديناميكية داخل صفحات الـ Layout","التفاعل اللحظي (Ajax Calls) — كيفية تنفيذ عمليات بحث وفلترة دون الحاجة لإعادة تحميل الصفحة بالكامل","شدد المحاضر على أهمية تطبيق 3-Tier Architecture بشكل صحيح، وتوظيف التقنيات المشروحة (مثل رفع الصور، إرسال الإيميلات، والربط مع خدمات خارجية) في مشروع التخرج. كما نصح باستخدام ASP.NET Core Web API للطبقة التقديمية، مع الت"],"case_study_ar":"إرسال 500 بريد عند الضغط على زر يجعل الصفحة تنتظر دقائق.","case_question_ar":"كيف تنقل ذلك لمهمة في الخلفية؟","challenge_ar":"أضف لوحة تعرض حالة المهام في الخلفية.","videos":[{"title_ar":"المحاضرة — المهام في الخلفية وAjax ومتطلبات المشروع","url":"https://youtu.be/pG-Z-T7sN94","description_ar":null}],"resources":[{"label":"Common web application architectures — Microsoft Learn","url":"https://learn.microsoft.com/dotnet/architecture/modern-web-apps-azure/common-web-application-architectures","kind":"website"}],"assignment":{"title_ar":"تكليف: المهام في الخلفية وAjax ومتطلبات المشروع","brief_ar":"أنشئ مشروعاً أو مجلداً باسم:\n\n📁 TM_MVC3TIER_L16_BackgroundJobsAjax\n\nالمطلوب:\n1️⃣ نفّذ مهمة في الخلفية (BackgroundService أو Hangfire) ترسل تقريراً دورياً.\n2️⃣ أضف تفاعلاً لحظياً بـ Ajax.\n3️⃣ سلّم المشروع النهائي بثلاث طبقات مع README ولقطات وفيديو قصير.\n\n📦 المطلوب تسليمه:\n🐙 رابط مستودع GitHub فيه الكود كاملاً.\n📝 README يشرح ما بنيته وكيف تشغّله.\n📸 صور واضحة لنتائج التشغيل داخل README.","required_evidence":["github"],"is_required":true}}]}]}$course$::jsonb);
